{
  "timeline": [
    {
      "headline": "Super Bowl XXXI Game",
      "text": "Super Bowl XXXI was played on January 26, 1997, at the Louisiana Superdome in New Orleans, Louisiana. The Green Bay Packers defeated the New England Patriots 35–21.",
      "date": "1997-01-26"
    },
    {
      "headline": "Green Bay Packers' Third Super Bowl Victory",
      "text": "The Green Bay Packers achieved their third Super Bowl victory by winning Super Bowl XXXI. This was their first Super Bowl win since Super Bowl II in 1968.",
      "date": "1997-01-26"
    },
    {
      "headline": "Packers Extend NFL Championship Record",
      "text": "With their victory in Super Bowl XXXI, the Green Bay Packers extended their league record for the most overall NFL championships to 12.",
      "date": "1997-01-26"
    },
    {
      "headline": "End of NFC's Super Bowl Winning Streak",
      "text": "Super Bowl XXXI marked the last in a run of 13 straight Super Bowl victories by the NFC over the AFC.",
      "date": "1997-01-26"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Beginning of the Haitian Revolution",
      "text": "The Haitian Revolution began on August 21, 1791, when enslaved Africans in the French colony of Saint-Domingue initiated a rebellion against their colonial masters.",
      "date": "1791-08-21"
    },
    {
      "headline": "Toussaint Louverture Emerges as Leader",
      "text": "In 1793, Toussaint Louverture, a former slave, emerged as a prominent leader of the revolution, organizing the enslaved people into a disciplined military force.",
      "date": "1793"
    },
    {
      "headline": "Abolition of Slavery in Saint-Domingue",
      "text": "On February 4, 1794, the French National Convention officially abolished slavery in all French colonies, including Saint-Domingue, in response to the ongoing revolution.",
      "date": "1794-02-04"
    },
    {
      "headline": "Louverture's Constitution",
      "text": "In 1801, Toussaint Louverture promulgated a new constitution for Saint-Domingue, which declared him governor for life and abolished slavery, though it maintained a nominal allegiance to France.",
      "date": "1801"
    },
    {
      "headline": "Napoleon's Invasion",
      "text": "In 1802, Napoleon Bonaparte sent a large expeditionary force to Saint-Domingue to restore French control and reinstate slavery, leading to renewed conflict.",
      "date": "1802"
    },
    {
      "headline": "Capture of Toussaint Louverture",
      "text": "On June 7, 1802, Toussaint Louverture was captured by French forces and deported to France, where he died in prison the following year.",
      "date": "1802-06-07"
    },
    {
      "headline": "Battle of Vertières",
      "text": "On November 18, 1803, the Battle of Vertières was fought, resulting in a decisive victory for the Haitian forces under Jean-Jacques Dessalines against the French, effectively ending the war.",
      "date": "1803-11-18"
    },
    {
      "headline": "Declaration of Independence",
      "text": "On January 1, 1804, Jean-Jacques Dessalines declared the independence of Haiti, making it the first post-colonial independent black-led nation in the world.",
      "date": "1804-01-01"
    },
    {
      "headline": "Dessalines Becomes Emperor",
      "text": "In October 1804, Jean-Jacques Dessalines declared himself Emperor of Haiti, taking the name Emperor Jacques I.",
      "date": "1804-10"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Mia Hamm",
      "text": "Mariel Margaret 'Mia' Hamm was born on March 17, 1972, in Selma, Alabama, USA.",
      "date": "1972-03-17"
    },
    {
      "headline": "Joins U.S. Women's National Team",
      "text": "In 1987, at the age of 15, Mia Hamm joined the United States women's national soccer team, becoming the youngest player ever to play for the team.",
      "date": "1987"
    },
    {
      "headline": "Wins First FIFA Women's World Cup",
      "text": "Mia Hamm was part of the U.S. team that won the inaugural FIFA Women's World Cup in 1991, held in China.",
      "date": "1991"
    },
    {
      "headline": "Wins Olympic Gold Medal",
      "text": "Hamm won her first Olympic gold medal with the U.S. women's soccer team at the 1996 Summer Olympics in Atlanta.",
      "date": "1996"
    },
    {
      "headline": "Wins Second FIFA Women's World Cup",
      "text": "Mia Hamm and the U.S. team won their second FIFA Women's World Cup in 1999, hosted in the United States.",
      "date": "1999"
    },
    {
      "headline": "Plays for Washington Freedom",
      "text": "From 2001 to 2003, Mia Hamm played for the Washington Freedom in the Women's United Soccer Association (WUSA), the first professional women's soccer league in the United States.",
      "date": "2001"
    },
    {
      "headline": "Wins Second Olympic Gold Medal",
      "text": "Hamm won her second Olympic gold medal at the 2004 Summer Olympics in Athens, Greece.",
      "date": "2004"
    },
    {
      "headline": "Retirement from Professional Soccer",
      "text": "Mia Hamm retired from professional soccer in 2004, concluding a remarkable career with the U.S. national team.",
      "date": "2004"
    },
    {
      "headline": "Inducted into National Soccer Hall of Fame",
      "text": "In 2007, Mia Hamm was inducted into the National Soccer Hall of Fame, recognizing her outstanding contributions to the sport.",
      "date": "2007"
    }
  ]
}

