{
  "timeline": [
    {
      "headline": "Birth of Paul Gauguin",
      "text": "Paul Gauguin was born on June 7, 1848, in Paris, France.",
      "date": "1848-06-07"
    },
    {
      "headline": "Gauguin's Early Life",
      "text": "In 1851, Gauguin's family moved to Peru, where they lived for four years. This experience influenced his later artistic style.",
      "date": "1851"
    },
    {
      "headline": "Return to France",
      "text": "Gauguin returned to France in 1855 after his family's stay in Peru.",
      "date": "1855"
    },
    {
      "headline": "Gauguin Joins the Navy",
      "text": "In 1865, Gauguin joined the merchant navy and later the French navy, serving until 1871.",
      "date": "1865"
    },
    {
      "headline": "Marriage to Mette-Sophie Gad",
      "text": "In 1873, Gauguin married Mette-Sophie Gad, a Danish woman, with whom he had five children.",
      "date": "1873"
    },
    {
      "headline": "Begins Painting",
      "text": "Gauguin began painting in his spare time in 1873, initially as a hobby.",
      "date": "1873"
    },
    {
      "headline": "First Exhibition with Impressionists",
      "text": "In 1881, Gauguin exhibited his work with the Impressionists for the first time.",
      "date": "1881"
    },
    {
      "headline": "Full-time Artist",
      "text": "In 1885, Gauguin decided to pursue painting full-time, leaving his family behind in Denmark.",
      "date": "1885"
    },
    {
      "headline": "Move to Tahiti",
      "text": "In 1891, Gauguin moved to Tahiti to escape European civilization and find inspiration for his art.",
      "date": "1891"
    },
    {
      "headline": "Publication of 'Noa Noa'",
      "text": "In 1893, Gauguin published 'Noa Noa', a travelogue of his experiences in Tahiti.",
      "date": "1893"
    },
    {
      "headline": "Return to Tahiti",
      "text": "Gauguin returned to Tahiti in 1895, where he continued to create some of his most famous works.",
      "date": "1895"
    },
    {
      "headline": "Move to the Marquesas Islands",
      "text": "In 1901, Gauguin moved to the Marquesas Islands, seeking further isolation.",
      "date": "1901"
    },
    {
      "headline": "Death of Paul Gauguin",
      "text": "Paul Gauguin died on May 8, 1903, in Atuona, Marquesas Islands, French Polynesia.",
      "date": "1903-05-08"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Stephen Chow",
      "text": "Stephen Chow was born on June 22, 1962, in Hong Kong.",
      "date": "1962-06-22"
    },
    {
      "headline": "Debut in Television",
      "text": "In 1982, Stephen Chow began his career in television by joining TVB, a Hong Kong television station, where he started as a temporary actor.",
      "date": "1982"
    },
    {
      "headline": "First Major Film Role",
      "text": "Stephen Chow's first major film role was in the movie 'Final Justice' in 1988, which earned him the Best Supporting Actor award at the Taiwan Golden Horse Awards.",
      "date": "1988"
    },
    {
      "headline": "Breakthrough with 'All for the Winner'",
      "text": "In 1990, Stephen Chow starred in 'All for the Winner', a film that became a massive hit and established him as a leading comedic actor in Hong Kong.",
      "date": "1990"
    },
    {
      "headline": "Directorial Debut",
      "text": "Stephen Chow made his directorial debut with the film 'From Beijing with Love' in 1994, which he also co-wrote and starred in.",
      "date": "1994"
    },
    {
      "headline": "International Success with 'Shaolin Soccer'",
      "text": "In 2001, Stephen Chow directed and starred in 'Shaolin Soccer', which became a major international success and won numerous awards.",
      "date": "2001"
    },
    {
      "headline": "Release of 'Kung Fu Hustle'",
      "text": "Stephen Chow released 'Kung Fu Hustle' in 2004, a film that received critical acclaim and won several awards, further cementing his reputation as a filmmaker.",
      "date": "2004"
    },
    {
      "headline": "Release of 'CJ7'",
      "text": "In 2008, Stephen Chow released 'CJ7', a science fiction comedy film that he directed, produced, and starred in.",
      "date": "2008"
    },
    {
      "headline": "Release of 'Journey to the West: Conquering the Demons'",
      "text": "Stephen Chow co-directed and produced 'Journey to the West: Conquering the Demons', which was released in 2013 and became a box office success.",
      "date": "2013"
    },
    {
      "headline": "Release of 'The Mermaid'",
      "text": "In 2016, Stephen Chow directed 'The Mermaid', which became the highest-grossing film of all time in China at the time of its release.",
      "date": "2016"
    }
  ]
}

