{
  "timeline": [
    {
      "headline": "Appearance of Aurochs",
      "text": "The aurochs first appeared during the late Pleistocene epoch, around 2 million years ago. It was one of the largest herbivores of its time, with bulls reaching a shoulder height of up to 180 cm.",
      "date": "-2000000"
    },
    {
      "headline": "Domestication of Cattle",
      "text": "Around 8,000 years ago, humans began domesticating aurochs in the Near East, leading to the development of modern domestic cattle.",
      "date": "-6000"
    },
    {
      "headline": "Extinction in the British Isles",
      "text": "Aurochs became extinct in the British Isles around 1,000 BCE due to hunting and habitat loss.",
      "date": "-1000"
    },
    {
      "headline": "Extinction in Europe",
      "text": "By the early Middle Ages, aurochs populations had significantly declined across Europe, surviving only in isolated areas.",
      "date": "0500"
    },
    {
      "headline": "Last Recorded Aurochs",
      "text": "The last recorded aurochs died in 1627 in the Jaktorów Forest, Poland. This marked the extinction of the species.",
      "date": "1627"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Origins of Goulash",
      "text": "Goulash originated in Hungary as a dish prepared by herdsmen. The name 'goulash' comes from the Hungarian word 'gulyás,' which means 'herdsman.' The dish was initially a simple stew made by herdsmen during cattle drives.",
      "date": "-0900"
    },
    {
      "headline": "Introduction of Paprika",
      "text": "Paprika, a key ingredient in modern goulash, was introduced to Hungary in the 16th century. It became a defining feature of the dish, giving it its distinctive flavor and color.",
      "date": "1500"
    },
    {
      "headline": "Goulash Becomes a National Dish",
      "text": "By the 19th century, goulash had become a symbol of Hungarian identity and a national dish. It was during this time that the dish gained popularity beyond Hungary's borders.",
      "date": "1800"
    },
    {
      "headline": "Spread Across Europe",
      "text": "In the late 19th and early 20th centuries, goulash spread across Central Europe and became a popular dish in countries such as Austria, Germany, and the Czech Republic.",
      "date": "1900"
    },
    {
      "headline": "Modern Variations",
      "text": "Today, goulash has numerous variations across Europe, with each region adding its own twist to the traditional recipe. It remains a beloved dish in Hungary and a staple in Central European cuisine.",
      "date": "2023"
    }
  ]
}

