{
  "timeline": [
    {
      "headline": "Founding of Nineveh",
      "text": "Nineveh was founded as an ancient Assyrian city in Upper Mesopotamia. Its origins date back to the 7th millennium BCE, making it one of the oldest cities in the world.",
      "date": "-07000"
    },
    {
      "headline": "Nineveh as a Religious Center",
      "text": "By the 3rd millennium BCE, Nineveh had become an important religious center dedicated to the goddess Ishtar.",
      "date": "-03000"
    },
    {
      "headline": "Nineveh Becomes Capital of Assyria",
      "text": "In 705 BCE, Nineveh became the capital of the Neo-Assyrian Empire under King Sennacherib, marking the beginning of its prominence.",
      "date": "-0705"
    },
    {
      "headline": "Construction of the Walls of Nineveh",
      "text": "During the reign of Sennacherib (705–681 BCE), the walls of Nineveh were constructed, encompassing an area of about 7 square kilometers.",
      "date": "-0705"
    },
    {
      "headline": "Sennacherib's Aqueduct",
      "text": "In 691 BCE, Sennacherib completed an aqueduct at Jerwan to bring water to Nineveh, showcasing advanced engineering skills.",
      "date": "-0691"
    },
    {
      "headline": "Nineveh at its Peak",
      "text": "Under the rule of Ashurbanipal (668–627 BCE), Nineveh reached its peak as the largest city in the world, known for its impressive library and cultural achievements.",
      "date": "-0668"
    },
    {
      "headline": "Fall of Nineveh",
      "text": "In 612 BCE, Nineveh fell to a coalition of Babylonians, Medes, and others, marking the end of the Neo-Assyrian Empire.",
      "date": "-0612"
    },
    {
      "headline": "Rediscovery of Nineveh",
      "text": "In the 19th century, Nineveh was rediscovered by archaeologists, with significant excavations beginning in the 1840s.",
      "date": "1840"
    }
  ]
}

{
