    {
      "headline": "Reign of Ptolemy III Euergetes",
      "text": "Ptolemy III Euergetes ruled from 246 BCE to 222 BCE. He expanded the empire and secured Egypt's wealth and power.",
      "date": "-0246"
    },
    {
      "headline": "Reign of Ptolemy IV Philopator",
      "text": "Ptolemy IV Philopator ruled from 222 BCE to 204 BCE. His reign saw the decline of the Ptolemaic Kingdom due to internal strife and external threats.",
      "date": "-0222"
    },
    {
      "headline": "Reign of Ptolemy V Epiphanes",
      "text": "Ptolemy V Epiphanes reigned from 204 BCE to 180 BCE. His rule was challenged by revolts and the loss of territories.",
      "date": "-0204"
    },
    {
      "headline": "Reign of Ptolemy VI Philometor",
      "text": "Ptolemy VI Philometor ruled from 180 BCE to 145 BCE. His reign was marked by conflicts with the Seleucid Empire and internal family disputes.",
      "date": "-0180"
    },
    {
      "headline": "Reign of Ptolemy VIII Physcon",
      "text": "Ptolemy VIII Physcon ruled intermittently between 170 BCE and 116 BCE. His reign was characterized by cruelty and political instability.",
      "date": "-0170"
    },
    {
      "headline": "Reign of Cleopatra VII",
      "text": "Cleopatra VII, the last active ruler of the Ptolemaic Kingdom, reigned from 51 BCE to 30 BCE. Her alliances with Julius Caesar and Mark Antony are notable.",
      "date": "-0051"
    },
    {
      "headline": "End of the Ptolemaic Dynasty",
      "text": "The Ptolemaic Dynasty ended in 30 BCE with the death of Cleopatra VII and the annexation of Egypt by the Roman Republic.",
      "date": "-0030"
    }
  ]
}

