{
  "timeline": [
    {
      "headline": "Birth of Roxelana",
      "text": "Roxelana, also known as Hürrem Sultan, was born around the year 1502. She was of Ruthenian origin, likely in the town of Rohatyn, which is now in modern-day Ukraine.",
      "date": "1502"
    },
    {
      "headline": "Arrival in the Ottoman Empire",
      "text": "Roxelana was captured during a Tatar slave raid and eventually entered the Ottoman Empire, where she became part of Sultan Suleiman the Magnificent's harem. This event likely occurred in the early 1520s.",
      "date": "1520"
    },
    {
      "headline": "Marriage to Sultan Suleiman",
      "text": "Roxelana married Sultan Suleiman the Magnificent, becoming his legal wife. This was a significant event as it broke the Ottoman tradition of sultans not marrying their concubines. The marriage took place around 1533 or 1534.",
      "date": "1533"
    },
    {
      "headline": "Became Haseki Sultan",
      "text": "Roxelana was given the title of Haseki Sultan, making her the chief consort and a powerful figure in the Ottoman court. This occurred after her marriage to Suleiman.",
      "date": "1533"
    },
    {
      "headline": "Influence in Politics",
      "text": "Throughout her life, Roxelana wielded significant political influence, advising Sultan Suleiman and engaging in state affairs. Her influence marked the beginning of the Sultanate of Women, a period where women of the Ottoman imperial harem had substantial political power.",
      "date": "1530s"
    },
    {
      "headline": "Construction of Charitable Complex",
      "text": "Roxelana commissioned the construction of the Haseki Sultan Complex in Istanbul, which included a mosque, a school, a hospital, and a soup kitchen. This complex was completed in 1539.",
      "date": "1539"
    },
    {
      "headline": "Death of Roxelana",
      "text": "Roxelana died on April 15, 1558, in Istanbul. She was buried in a mausoleum adjacent to the Süleymaniye Mosque.",
      "date": "1558-04-15"
    }
  ]
}

