{
  "timeline": [
    {
      "headline": "Creation of the Wooden Cow",
      "text": "Daedalus crafted a wooden cow for Queen Pasiphaë of Crete, which allowed her to mate with a bull, leading to the birth of the Minotaur. This event is a significant demonstration of Daedalus's skill and ingenuity.",
      "date": "-1300"  },
    {
      "headline": "Construction of the Labyrinth",
      "text": "Daedalus designed and built the Labyrinth on the island of Crete for King Minos. The Labyrinth was a complex maze intended to imprison the Minotaur, a creature that was half-man and half-bull.",
      "date": "-1300"
    },
    {
      "headline": "Imprisonment in Crete",
      "text": "After the construction of the Labyrinth, Daedalus and his son Icarus were imprisoned by King Minos to prevent the secret of the Labyrinth from spreading.",
      "date": "-1290"
    },
    {
      "headline": "Escape from Crete",
      "text": "Daedalus crafted wings made of feathers and wax for himself and his son Icarus to escape from Crete. He warned Icarus not to fly too close to the sun or too close to the sea.",
      "date": "-1280"
    },
    {
      "headline": "Death of Icarus",
      "text": "During their escape, Icarus flew too close to the sun, causing the wax in his wings to melt. He fell into the sea and drowned, a body of water now known as the Icarian Sea.",
      "date": "-1280"
    },
    {
      "headline": "Arrival in Sicily",
      "text": "After the tragic loss of his son, Daedalus arrived safely in Sicily, where he was welcomed by King Cocalus.",
      "date": "-1275"
    },
    {
      "headline": "Death of King Minos",
      "text": "King Minos pursued Daedalus to Sicily, but was killed by the daughters of King Cocalus, who poured boiling water over him while he was taking a bath.",
      "date": "-1270"
    }
  ]
}

