{
  "timeline": [
    {
      "headline": "First Appearance in Literature",
      "text": "Medea first appears in Hesiod's Theogony, which was composed around 700 BCE. This early mention establishes her as a significant figure in Greek mythology.",
      "date": "-0700"
    },
    {
      "headline": "Role in Jason and the Argonauts",
      "text": "Medea aids Jason in his quest for the Golden Fleece. As the daughter of King Aeëtes of Colchis, she uses her sorcery to help Jason overcome various challenges, including taming fire-breathing bulls and defeating the dragon guarding the fleece.",
      "date": "-1300"  },
    {
      "headline": "Marriage to Jason",
      "text": "After successfully obtaining the Golden Fleece, Medea marries Jason. Their marriage is marked by both love and betrayal, as Medea's actions to secure the fleece lead to her estrangement from her family.",
      "date": "-1300"
    },
    {
      "headline": "Medea's Revenge",
      "text": "In Euripides's tragedy 'Medea', written in 431 BCE, Medea takes revenge on Jason for his betrayal by killing their children and his new bride. This act of vengeance is one of the most famous aspects of her myth.",
      "date": "-0431"
    },
    {
      "headline": "Depiction in Apollonius of Rhodes's Argonautica",
      "text": "Medea is prominently featured in Apollonius of Rhodes's epic 'Argonautica', which was composed in the 3rd century BCE. This work further explores her role in the quest for the Golden Fleece and her relationship with Jason.",
      "date": "-0300"
    }
  ]
}

