{
  "timeline": [
    {
      "headline": "Formation of the Texas Rangers",
      "text": "In 1823, Stephen F. Austin, known as the 'Father of Texas,' called for the formation of a group of ten men to protect the newly settled families from Native American attacks. This group would later become known as the Texas Rangers.",
      "date": "1823"
    },
    {
      "headline": "Official Establishment",
      "text": "The Texas Rangers were officially established on August 10, 1835, by the provisional government of Texas. They were created to protect settlers from Native American raids and to enforce laws.",
      "date": "1835-08-10"
    },
    {
      "headline": "Role in the Texas Revolution",
      "text": "During the Texas Revolution (1835-1836), the Texas Rangers played a crucial role in the fight for independence from Mexico, serving as scouts and couriers.",
      "date": "1835"
    },
    {
      "headline": "Service in the Republic of Texas",
      "text": "From 1836 to 1846, the Texas Rangers served as a paramilitary force for the Republic of Texas, engaging in battles against Native American tribes and Mexican forces.",
      "date": "1836"
    },
    {
      "headline": "Annexation of Texas",
      "text": "In 1845, Texas was annexed by the United States, and the Texas Rangers continued their service under the new state government.",
      "date": "1845"
    },
    {
      "headline": "Mexican-American War",
      "text": "During the Mexican-American War (1846-1848), the Texas Rangers gained fame for their scouting and fighting skills, earning the nickname 'Los Diablos Tejanos' or 'The Texas Devils' from Mexican troops.",
      "date": "1846"
    },
    {
      "headline": "Reconstruction Era Challenges",
      "text": "After the Civil War, during the Reconstruction era, the Texas Rangers faced challenges as they were temporarily disbanded by the federal government but were later reformed to combat lawlessness in the state.",
      "date": "1870"
    },
    {
      "headline": "Modernization and Reforms",
      "text": "In the early 20th century, the Texas Rangers underwent modernization and reforms to address corruption and improve their effectiveness as a law enforcement agency.",
      "date": "1900"
    },
    {
      "headline": "Role in the 20th Century",
      "text": "Throughout the 20th century, the Texas Rangers played significant roles in various high-profile criminal investigations, including the pursuit of outlaws like Bonnie and Clyde.",
      "date": "1934"
    },
    {
      "headline": "21st Century Operations",
      "text": "In the 21st century, the Texas Rangers continue to serve as a major law enforcement agency in Texas, handling major criminal investigations and providing support to local law enforcement agencies.",
      "date": "2000"
    }
  ]
}

{
