    {
      "headline": "Founding of Santa Fe",
      "text": "Santa Fe was founded by Spanish colonists in 1610, making it the oldest state capital in the United States.",
      "date": "1610"
    },
    {
      "headline": "Santa Fe becomes the capital",
      "text": "In 1610, Santa Fe was designated as the capital of the province of Nuevo México in the Spanish Empire.",
      "date": "1610"
    },
    {
      "headline": "Pueblo Revolt",
      "text": "In 1680, the Pueblo Revolt occurred, during which Pueblo peoples expelled the Spanish settlers from Santa Fe.",
      "date": "1680"
    },
    {
      "headline": "Spanish Reconquest",
      "text": "In 1692, Spanish forces led by Diego de Vargas reconquered Santa Fe, re-establishing Spanish control.",
      "date": "1692"
    },
    {
      "headline": "Santa Fe Trail",
      "text": "The Santa Fe Trail was opened in 1821, establishing a trade route between Missouri and Santa Fe.",
      "date": "1821"
    },
    {
      "headline": "Mexican Independence",
      "text": "In 1821, Mexico gained independence from Spain, and Santa Fe became part of the Mexican territory.",
      "date": "1821"
    },
    {
      "headline": "American Occupation",
      "text": "In 1846, during the Mexican-American War, American forces occupied Santa Fe without resistance.",
      "date": "1846"
    },
    {
      "headline": "Treaty of Guadalupe Hidalgo",
      "text": "In 1848, the Treaty of Guadalupe Hidalgo ended the Mexican-American War, and Santa Fe became part of the United States.",
      "date": "1848"
    },
    {
      "headline": "New Mexico Statehood",
      "text": "In 1912, New Mexico was admitted as the 47th state of the United States, with Santa Fe as its capital.",
      "date": "1912"
    }
  ]
}

