      "headline": "Origin of Foot Binding",
      "text": "Foot binding is believed to have originated during the Five Dynasties and Ten Kingdoms period in China (907–960 AD). The practice began among dancers and courtesans and gradually spread to the upper classes.",
      "date": "0907"
    },
    {
      "headline": "Spread During the Song Dynasty",
      "text": "During the Song Dynasty (960–1279 AD), foot binding became more widespread among the elite and was considered a status symbol.",
      "date": "0960"
    },
    {
      "headline": "Foot Binding Becomes Widespread",
      "text": "By the Ming Dynasty (1368–1644 AD), foot binding had become a widespread practice across China, transcending social classes.",
      "date": "1368"
    },
    {
      "headline": "Criticism and Reform Attempts",
      "text": "In the late 19th century, reformers began to criticize foot binding as a barbaric practice. The first anti-foot binding society was formed in 1874.",
      "date": "1874"
    },
    {
      "headline": "Official Ban on Foot Binding",
      "text": "The practice of foot binding was officially banned in 1912 after the fall of the Qing Dynasty, as part of efforts to modernize China.",
      "date": "1912"
    },
    {
      "headline": "Foot Binding Persists in Rural Areas",
      "text": "Despite the ban, foot binding continued in some rural areas of China until the mid-20th century.",
      "date": "1950"
    }
  ]
}

