{
  "timeline": [
    {
      "headline": "Formation of the Indus River",
      "text": "The Indus River, one of the longest rivers in Asia, was formed millions of years ago due to tectonic activities and the uplift of the Himalayas.",
      "date": "-10000000"
    },
    {
      "headline": "Early Human Settlements",
      "text": "Around 3300 BCE, early human settlements began to form along the Indus River, leading to the development of the Indus Valley Civilization.",
      "date": "-03300"
    },
    {
      "headline": "Indus Valley Civilization",
      "text": "From approximately 2600 BCE to 1900 BCE, the Indus Valley Civilization thrived along the Indus River, known for its advanced urban planning, architecture, and social organization.",
      "date": "-02600"
    },
    {
      "headline": "Decline of the Indus Valley Civilization",
      "text": "Around 1900 BCE, the Indus Valley Civilization began to decline, possibly due to climate change, tectonic activity, or invasions.",
      "date": "-01900"
    },
    {
      "headline": "Vedic Period",
      "text": "During the Vedic period (approximately 1500 BCE to 500 BCE), the region around the Indus River was significant in the development of early Hindu culture and the composition of the Vedas.",
      "date": "-01500"
    },
    {
      "headline": "Achaemenid Empire",
      "text": "In the 6th century BCE, the Indus region became part of the Achaemenid Empire under Darius the Great.",
      "date": "-0520"
    },
    {
      "headline": "Alexander the Great's Invasion",
      "text": "In 326 BCE, Alexander the Great crossed the Indus River during his campaign to conquer the Indian subcontinent.",
      "date": "-0326"
    },
    {
      "headline": "Maurya Empire",
      "text": "After Alexander's departure, the region around the Indus River became part of the Maurya Empire under Chandragupta Maurya in the late 4th century BCE.",
      "date": "-0320"
    },
    {
      "headline": "Islamic Conquests",
      "text": "In the 7th and 8th centuries CE, the Indus region saw the arrival of Islamic forces, leading to significant cultural and religious changes.",
      "date": "0700"
    },
    {
      "headline": "British Colonial Rule",
      "text": "In the 19th century, the Indus River region came under British colonial rule, which lasted until the mid-20th century.",
      "date": "1800"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, the partition of India led to the Indus River becoming a significant geographical and political boundary between India and Pakistan.",
      "date": "1947"
    },
    {
      "headline": "Indus Waters Treaty",
      "text": "In 1960, India and Pakistan signed the Indus Waters Treaty, brokered by the World Bank, to manage the water resources of the Indus River.",
      "date": "1960"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Discovery of X-rays",
      "text": "X-rays were discovered by Wilhelm Conrad Röntgen on November 8, 1895. He was experimenting with cathode rays when he noticed a glow coming from a nearby chemically coated screen.",
      "date": "1895-11-08"
    },
    {
      "headline": "First X-ray Image",
      "text": "On December 22, 1895, Wilhelm Röntgen took the first X-ray photograph of his wife's hand, which clearly showed her bones and her wedding ring.",
      "date": "1895-12-22"
    },
    {
      "headline": "Röntgen's Nobel Prize",
      "text": "In 1901, Wilhelm Röntgen was awarded the first Nobel Prize in Physics for his discovery of X-rays.",
      "date": "1901"
    },
    {
      "headline": "Introduction of X-rays in Medicine",
      "text": "By the early 1900s, X-rays began to be used in medical diagnostics, revolutionizing the field by allowing doctors to see inside the human body without surgery.",
      "date": "1900"
    },
    {
      "headline": "Development of X-ray Tubes",
      "text": "In 1913, William D. Coolidge developed the Coolidge tube, an improved X-ray tube that allowed for more consistent and controllable X-ray production.",
      "date": "1913"
    },
    {
      "headline": "X-rays in World War I",
      "text": "During World War I (1914-1918), X-rays were extensively used to locate bullets and shrapnel in injured soldiers, significantly aiding in medical treatment.",
      "date": "1914"
    },
    {
      "headline": "Discovery of X-ray Crystallography",
      "text": "In 1912, Max von Laue discovered X-ray crystallography, a technique that uses X-ray diffraction to study the atomic structure of crystals.",
      "date": "1912"
    },
    {
      "headline": "Nobel Prize for X-ray Crystallography",
      "text": "In 1914, Max von Laue was awarded the Nobel Prize in Physics for his discovery of X-ray diffraction by crystals.",
      "date": "1914"
    },
    {
      "headline": "Development of Computed Tomography (CT)",
      "text": "In 1972, Godfrey Hounsfield and Allan Cormack developed computed tomography (CT), which uses X-rays to create detailed cross-sectional images of the body.",
      "date": "1972"
    },
    {
      "headline": "Nobel Prize for CT",
      "text": "In 1979, Godfrey Hounsfield and Allan Cormack were awarded the Nobel Prize in Physiology or Medicine for the development of computed tomography.",
      "date": "1979"
    }
  ]
}

