    {
      "headline": "Establishment of the Pahlavi Dynasty",
      "text": "Reza Shah Pahlavi was crowned as the Shah of Iran, marking the beginning of the Pahlavi dynasty on December 15, 1925.",
      "date": "1925-12-15"
    },
    {
      "headline": "Change of Country Name",
      "text": "In 1935, Reza Shah Pahlavi requested foreign delegates to use the term 'Iran' instead of 'Persia' to refer to the country.",
      "date": "1935"
    },
    {
      "headline": "Anglo-Soviet Invasion of Iran",
      "text": "In August 1941, British and Soviet forces invaded Iran to secure oil fields and ensure supply lines during World War II.",
      "date": "1941-08"
    },
    {
      "headline": "Abdication of Reza Shah",
      "text": "Reza Shah Pahlavi was forced to abdicate the throne in favor of his son, Mohammad Reza Pahlavi, on September 16, 1941, due to the Anglo-Soviet invasion.",
      "date": "1941-09-16"
    },
    {
      "headline": "Nationalization of the Iranian Oil Industry",
      "text": "In 1951, Prime Minister Mohammad Mosaddegh nationalized the Iranian oil industry, previously controlled by the British-owned Anglo-Iranian Oil Company.",
      "date": "1951"
    },
    {
      "headline": "1953 Iranian Coup d'état",
      "text": "On August 19, 1953, a coup d'état, orchestrated by the United States and the United Kingdom, overthrew Prime Minister Mohammad Mosaddegh and strengthened the rule of Mohammad Reza Pahlavi.",
      "date": "1953-08-19"
    },
    {
      "headline": "White Revolution",
      "text": "In 1963, Mohammad Reza Shah launched the White Revolution, a series of economic, social, and political reforms aimed at modernizing Iran.",
      "date": "1963"
    },
    {
      "headline": "Celebration of 2,500 Years of Persian Empire",
      "text": "In October 1971, Iran celebrated the 2,500th anniversary of the founding of the Persian Empire by Cyrus the Great with a grand event in Persepolis.",
      "date": "1971-10"
    },
    {
      "headline": "Iranian Revolution",
      "text": "The Iranian Revolution began in 1978 and culminated in the overthrow of the Pahlavi dynasty on February 11, 1979, leading to the establishment of the Islamic Republic of Iran.",
      "date": "1979-02-11"
    }
  ]
}

