{
  "timeline": [
    {
      "headline": "Origin of Gothic Architecture",
      "text": "Gothic architecture originated in the Île-de-France and Picardy regions of northern France in the late 12th century. It evolved from Romanesque architecture.",
      "date": "1180"
    },
    {
      "headline": "Construction of Basilica of Saint-Denis",
      "text": "The Basilica of Saint-Denis, often considered the first Gothic building, was reconstructed under the direction of Abbot Suger. The choir was completed in 1144, marking a significant development in Gothic architecture.",
      "date": "1144"
    },
    {
      "headline": "Notre-Dame de Paris Construction Begins",
      "text": "Construction of the Notre-Dame Cathedral in Paris began in 1163. It is one of the most famous examples of French Gothic architecture.",
      "date": "1163"
    },
    {
      "headline": "Chartres Cathedral Rebuilt",
      "text": "After a fire in 1194, Chartres Cathedral was rebuilt in the Gothic style. It is renowned for its architectural innovations and stained glass windows.",
      "date": "1194"
    },
    {
      "headline": "Gothic Architecture Spreads to England",
      "text": "Gothic architecture spread to England in the late 12th century, with the construction of Canterbury Cathedral's choir, completed in 1184.",
      "date": "1184"
    },
    {
      "headline": "Construction of Reims Cathedral",
      "text": "Construction of Reims Cathedral began in 1211. It is a masterpiece of High Gothic architecture and was the site of the coronation of French kings.",
      "date": "1211"
    },
    {
      "headline": "Sainte-Chapelle Completed",
      "text": "The Sainte-Chapelle in Paris was completed in 1248. It is known for its stunning stained glass windows and is a prime example of the Rayonnant Gothic style.",
      "date": "1248"
    },
    {
      "headline": "Gothic Architecture Reaches Germany",
      "text": "Gothic architecture reached Germany in the 13th century, with the construction of Cologne Cathedral beginning in 1248.",
      "date": "1248"
    },
    {
      "headline": "Florence Cathedral Construction Begins",
      "text": "Construction of the Florence Cathedral began in 1296. It is an example of Italian Gothic architecture, blending Gothic elements with Renaissance influences.",
      "date": "1296"
    },
    {
      "headline": "Gothic Architecture in Spain",
      "text": "Gothic architecture spread to Spain in the 13th century, with notable examples including the cathedrals of Burgos and León.",
      "date": "1200"
    },
    {
      "headline": "Gothic Architecture Declines",
      "text": "By the 16th century, Gothic architecture began to decline as the Renaissance style became more popular across Europe.",
      "date": "1500"
    }
  ]
}

