    {
      "headline": "Introduction of the Ketogenic Diet",
      "text": "The ketogenic diet was introduced in 1921 by Dr. Russell Wilder at the Mayo Clinic. He coined the term 'ketogenic diet' to describe a diet that produces a high level of ketone bodies in the blood through an excess of fat and lack of carbohydrates.",
      "date": "1921"
    },
    {
      "headline": "Early Use in Epilepsy Treatment",
      "text": "In the 1920s and 1930s, the ketogenic diet gained popularity as a treatment for epilepsy, particularly in children. It was found to reduce the frequency of seizures in many patients.",
      "date": "1920"
    },
    {
      "headline": "Decline in Popularity",
      "text": "The ketogenic diet's popularity declined in the late 1930s with the introduction of antiepileptic drugs, which were easier to administer and manage.",
      "date": "1938"
    },
    {
      "headline": "Renewed Interest in the 1990s",
      "text": "Interest in the ketogenic diet was renewed in the 1990s, largely due to the efforts of the Charlie Foundation, which was established in 1994 to promote the diet as a treatment for epilepsy after its success in treating Charlie Abrahams, the son of Hollywood producer Jim Abrahams.",
      "date": "1994"
    },
    {
      "headline": "Research and Expansion of Use",
      "text": "In the 2000s and 2010s, research expanded into the use of the ketogenic diet for other conditions, including weight loss, diabetes, and certain neurological disorders, although its primary use remains in the treatment of epilepsy.",
      "date": "2000"
    }
  ]
}

