    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Rudolf E. Kálmán",
      "text": "Rudolf E. Kálmán, the mathematician and electrical engineer after whom the Kalman filter is named, was born on May 19, 1930.",
      "date": "1930-05-19"
    },
    {
      "headline": "Development of the Kalman Filter",
      "text": "In 1960, Rudolf E. Kálmán published his seminal paper on the Kalman filter, which introduced the algorithm that would become fundamental in control theory and signal processing.",
      "date": "1960"
    },
    {
      "headline": "Application in the Apollo Program",
      "text": "During the 1960s, the Kalman filter was applied in the Apollo space program, helping to navigate the spacecraft by filtering out noise from the measurements.",
      "date": "1960s"
    },
    {
      "headline": "Widespread Adoption in Various Fields",
      "text": "By the 1970s, the Kalman filter had become widely adopted in various fields such as aerospace, robotics, and economics for its ability to provide accurate estimates from noisy data.",
      "date": "1970s"
    },
    {
      "headline": "Rudolf E. Kálmán Receives the National Medal of Science",
      "text": "In 2009, Rudolf E. Kálmán was awarded the National Medal of Science for his contributions to modern control theory, including the development of the Kalman filter.",
      "date": "2009"
    },
    {
      "headline": "Death of Rudolf E. Kálmán",
      "text": "Rudolf E. Kálmán passed away on July 2, 2016, leaving behind a legacy of significant contributions to control theory and signal processing.",
      "date": "2016-07-02"
    }
  ]
}

