{
  "timeline": [
    {
      "headline": "Beginning of Nazi Human Experimentation",
      "text": "Nazi human experimentation began in earnest in 1942, primarily conducted in concentration camps such as Auschwitz, Dachau, and Ravensbrück. These experiments were often cruel and inhumane, involving prisoners of various nationalities and age groups.",
      "date": "1942"
    },
    {
      "headline": "Experiments at Auschwitz",
      "text": "At Auschwitz, Dr. Josef Mengele conducted experiments on twins, attempting to change eye color by injecting chemicals into children's eyes, and performing surgeries without anesthesia. These experiments were part of a broader set of inhumane practices conducted at the camp.",
      "date": "1943"
    },
    {
      "headline": "Experiments at Dachau",
      "text": "At Dachau, experiments were conducted to test the limits of human endurance, including high-altitude experiments and hypothermia tests. These experiments were often fatal and were conducted without the consent of the prisoners.",
      "date": "1943"
    },
    {
      "headline": "Experiments at Ravensbrück",
      "text": "At Ravensbrück, experiments focused on bone, muscle, and nerve transplantation, as well as the effects of sulfonamide drugs. Many of these experiments resulted in severe injuries or death.",
      "date": "1943"
    },
    {
      "headline": "End of Nazi Human Experimentation",
      "text": "Nazi human experimentation largely ended with the fall of Nazi Germany in 1945. The experiments left many survivors with severe permanent injuries, and a significant number of victims were killed.",
      "date": "1945"
    },
    {
      "headline": "Nuremberg Doctors' Trial",
      "text": "In 1946-1947, the Nuremberg Doctors' Trial was held to prosecute those responsible for Nazi human experimentation. The trial resulted in several convictions and highlighted the atrocities committed during the experiments.",
      "date": "1946"
    }
  ]
}

