    {
      "headline": "Partitions of Poland",
      "text": "In 1793, during the Second Partition of Poland, Gdańsk was annexed by the Kingdom of Prussia.",
      "date": "1793"
    },
    {
      "headline": "Napoleonic Wars",
      "text": "Gdańsk was declared a Free City by Napoleon in 1807 but was returned to Prussia in 1815 after the Congress of Vienna.",
      "date": "1807"
    },
    {
      "headline": "Free City of Danzig",
      "text": "After World War I, the Treaty of Versailles in 1920 established Gdańsk as the Free City of Danzig under the League of Nations.",
      "date": "1920"
    },
    {
      "headline": "World War II Outbreak",
      "text": "The German invasion of Poland began with the attack on the Westerplatte peninsula in Gdańsk on September 1, 1939, marking the start of World War II.",
      "date": "1939-09-01"
    },
    {
      "headline": "Liberation and Return to Poland",
      "text": "In 1945, Gdańsk was liberated by Soviet and Polish forces and was reintegrated into Poland after World War II.",
      "date": "1945"
    },
    {
      "headline": "Solidarity Movement",
      "text": "In 1980, the Solidarity movement, led by Lech Wałęsa, began in the Gdańsk Shipyard, playing a crucial role in the fall of communism in Poland.",
      "date": "1980"
