  "timeline": [
    {
      "headline": "Earliest Known Use of Stone Tools",
      "text": "Around 3.3 million years ago, the earliest known use of stone tools by hominins occurred. This marks the beginning of the Paleolithic era.",
      "date": "-3300000"
    },
    {
      "headline": "Emergence of Homo habilis",
      "text": "Approximately 2.8 million years ago, Homo habilis, one of the earliest members of the genus Homo, emerged. They are believed to have used stone tools.",
      "date": "-2800000"
    },
    {
      "headline": "Appearance of Homo erectus",
      "text": "Around 1.9 million years ago, Homo erectus appeared. This species is known for its use of more advanced stone tools and is believed to have been the first to use fire.",
      "date": "-1900000"
    },
    {
      "headline": "Acheulean Tool Industry",
      "text": "Beginning about 1.76 million years ago, the Acheulean tool industry emerged, characterized by large bifacial tools such as handaxes.",
      "date": "-1760000"
    },
    {
      "headline": "Control of Fire",
      "text": "Evidence suggests that by around 1 million years ago, early humans had learned to control fire, which was crucial for cooking and protection.",
      "date": "-1000000"
    },
    {
      "headline": "Neanderthals Emerge",
      "text": "Approximately 400,000 years ago, Neanderthals emerged in Europe and parts of Asia. They are known for their robust build and sophisticated tool use.",
      "date": "-400000"
    },
    {
      "headline": "Mousterian Tool Culture",
      "text": "Around 160,000 years ago, the Mousterian tool culture developed, associated with Neanderthals and characterized by flake tools.",
      "date": "-160000"
    },
    {
      "headline": "Anatomically Modern Humans",
      "text": "Anatomically modern humans (Homo sapiens) appeared around 300,000 years ago in Africa, eventually spreading across the globe.",
      "date": "-300000"
    },
    {
      "headline": "Upper Paleolithic Revolution",
      "text": "Around 50,000 years ago, the Upper Paleolithic Revolution occurred, marked by a significant increase in the diversity and complexity of tools and art.",
      "date": "-50000"
    },
    {
      "headline": "End of the Paleolithic Era",
      "text": "The Paleolithic era ended around 11,650 years ago with the conclusion of the Pleistocene epoch and the beginning of the Holocene.",
      "date": "-11650"
    }
  ]
}

