{
  "timeline": [
    {
      "headline": "First Nations Settlement",
      "text": "The area now known as Manitoba was first inhabited by First Nations peoples, including the Cree, Ojibwe, Dene, and Sioux.",
      "date": "-10000"
    },
    {
      "headline": "Arrival of European Explorers",
      "text": "In the late 17th century, European explorers such as Henry Hudson and Pierre Gaultier de Varennes, sieur de La Vérendrye, began exploring the region.",
      "date": "1690"
    },
    {
      "headline": "Establishment of the Hudson's Bay Company",
      "text": "In 1670, the Hudson's Bay Company was established, claiming the Hudson Bay watershed, including present-day Manitoba, as Rupert's Land.",
      "date": "1670"
    },
    {
      "headline": "Selkirk Settlement",
      "text": "In 1812, the Selkirk Settlement was established by Thomas Douglas, 5th Earl of Selkirk, bringing Scottish settlers to the Red River area.",
      "date": "1812"
    },
    {
      "headline": "Red River Rebellion",
      "text": "In 1869-1870, the Red River Rebellion, led by Louis Riel, occurred in response to the transfer of Rupert's Land to Canada without consulting the Métis inhabitants.",
      "date": "1869"
    },
    {
      "headline": "Manitoba Act and Province Creation",
      "text": "On July 15, 1870, the Manitoba Act was passed, creating the province of Manitoba as part of Canada.",
      "date": "1870-07-15"
    },
    {
      "headline": "Expansion of Manitoba's Borders",
      "text": "In 1881, Manitoba's borders were expanded to include more territory to the west and north.",
      "date": "1881"
    },
    {
      "headline": "Winnipeg General Strike",
      "text": "In 1919, the Winnipeg General Strike took place, one of the most influential strikes in Canadian history, involving over 30,000 workers.",
      "date": "1919"
    },
    {
      "headline": "Flood of the Century",
      "text": "In 1997, Manitoba experienced the 'Flood of the Century,' which caused extensive damage, particularly in the Red River Valley.",
      "date": "1997"
    },
    {
      "headline": "Truth and Reconciliation Commission",
      "text": "In 2015, the Truth and Reconciliation Commission of Canada released its final report, which included significant findings and recommendations related to the treatment of Indigenous peoples in Manitoba and across Canada.",
      "date": "2015"
    }
  ]
}

