{
  "timeline": [
    {
      "headline": "Founding of Mogadishu",
      "text": "Mogadishu is believed to have been founded in the 10th century by Arab traders. It became an important port city in the Indian Ocean trade network.",
      "date": "0900"
    },
    {
      "headline": "Sultanate of Mogadishu",
      "text": "By the 12th century, Mogadishu had become the capital of the Sultanate of Mogadishu, a powerful and wealthy city-state that controlled trade in the region.",
      "date": "1100"
    },
    {
      "headline": "Visit by Ibn Battuta",
      "text": "In 1331, the famous Moroccan traveler Ibn Battuta visited Mogadishu and described it as an exceptionally large city with many rich merchants.",
      "date": "1331"
    },
    {
      "headline": "Portuguese Attack",
      "text": "In 1499, the Portuguese explorer Vasco da Gama attacked Mogadishu during his second voyage to India.",
      "date": "1499"
    },
    {
      "headline": "Omani Influence",
      "text": "In the late 17th century, Mogadishu came under the influence of the Omani Empire, which controlled much of the East African coast.",
      "date": "1698"
    },
    {
      "headline": "Italian Colonial Rule",
      "text": "In 1889, Mogadishu became part of Italian Somaliland, marking the beginning of Italian colonial rule.",
      "date": "1889"
    },
    {
      "headline": "Independence of Somalia",
      "text": "On July 1, 1960, Mogadishu became the capital of the newly independent Republic of Somalia.",
      "date": "1960-07-01"
    },
    {
      "headline": "Somali Civil War",
      "text": "In 1991, the Somali Civil War broke out, leading to significant destruction and instability in Mogadishu.",
      "date": "1991"
    },
    {
      "headline": "Battle of Mogadishu",
      "text": "On October 3-4, 1993, the Battle of Mogadishu occurred, involving U.S. forces and Somali militia, which became widely known through the book and film 'Black Hawk Down'.",
      "date": "1993-10-03"
    },
    {
      "headline": "Transitional Federal Government",
      "text": "In 2004, the Transitional Federal Government was established in Somalia, with Mogadishu as its capital.",
      "date": "2004"
    },
    {
      "headline": "AMISOM Deployment",
      "text": "In 2007, the African Union Mission in Somalia (AMISOM) was deployed to Mogadishu to help stabilize the city and support the Somali government.",
      "date": "2007"
    },
    {
      "headline": "Al-Shabaab Withdrawal",
      "text": "In August 2011, the militant group Al-Shabaab withdrew from Mogadishu, marking a significant turning point in the city's security situation.",
      "date": "2011-08"
    }
  ]
}

