{
  "timeline": [
    {
      "headline": "Palm Sunday",
      "text": "Palm Sunday marks the beginning of Holy Week, commemorating Jesus Christ's triumphant entry into Jerusalem. This event is celebrated on the Sunday before Easter.",
      "date": "0000-04-02"
    },
    {
      "headline": "Holy Monday",
      "text": "Holy Monday is the second day of Holy Week. In Western Christianity, it is associated with the anointing of Jesus at Bethany. In Eastern Christianity, it commemorates the cursing of the fig tree.",
      "date": "0000-04-03"
    },
    {
      "headline": "Holy Tuesday",
      "text": "Holy Tuesday is the third day of Holy Week. In Western Christianity, it is often associated with Jesus' predictions of his own death. In Eastern Christianity, it commemorates the Parable of the Ten Virgins.",
      "date": "0000-04-04"
    },
    {
      "headline": "Holy Wednesday",
      "text": "Holy Wednesday, also known as Spy Wednesday, marks the day Judas Iscariot conspired to betray Jesus. In Eastern Christianity, it is also known as Great and Holy Wednesday.",
      "date": "0000-04-05"
    },
    {
      "headline": "Maundy Thursday",
      "text": "Maundy Thursday commemorates the Last Supper of Jesus Christ with the Apostles. It is observed on the Thursday before Easter and includes the institution of the Eucharist.",
      "date": "0000-04-06"
    },
    {
      "headline": "Good Friday",
      "text": "Good Friday is observed on the Friday before Easter Sunday. It commemorates the crucifixion of Jesus Christ and his death at Calvary.",
      "date": "0000-04-07"
    },
    {
      "headline": "Holy Saturday",
      "text": "Holy Saturday is the day before Easter Sunday. It commemorates the day Jesus' body lay in the tomb and marks the end of Holy Week.",
      "date": "0000-04-08"
    }
  ]
}

