{
  "timeline": [
    {
      "headline": "Formation of the Kingdom of Judah",
      "text": "The Kingdom of Judah was established around 930 BCE following the split of the United Monarchy of Israel into two separate kingdoms: Israel in the north and Judah in the south.",
      "date": "-0930"
    },
    {
      "headline": "Reign of King Rehoboam",
      "text": "Rehoboam, the son of Solomon, became the first king of Judah after the division of the United Monarchy. His reign began around 930 BCE.",
      "date": "-0930"
    },
    {
      "headline": "Reign of King Asa",
      "text": "King Asa ruled Judah from approximately 913 BCE to 873 BCE. He was known for religious reforms and efforts to strengthen the kingdom.",
      "date": "-0913"
    },
    {
      "headline": "Reign of King Jehoshaphat",
      "text": "Jehoshaphat, the son of Asa, reigned from around 870 BCE to 849 BCE. He is noted for his judicial reforms and alliances with the Kingdom of Israel.",
      "date": "-0870"
    },
    {
      "headline": "Reign of King Hezekiah",
      "text": "Hezekiah ruled from approximately 715 BCE to 686 BCE. He is known for religious reforms and for fortifying Jerusalem against Assyrian invasion.",
      "date": "-0715"
    },
    {
      "headline": "Assyrian Siege of Jerusalem",
      "text": "In 701 BCE, the Assyrian king Sennacherib laid siege to Jerusalem during the reign of Hezekiah, but the city was not captured.",
      "date": "-0701"
    },
    {
      "headline": "Reign of King Josiah",
      "text": "Josiah reigned from 640 BCE to 609 BCE. He is remembered for major religious reforms and centralizing worship in Jerusalem.",
      "date": "-0640"
    },
    {
      "headline": "Battle of Megiddo",
      "text": "In 609 BCE, King Josiah was killed at the Battle of Megiddo while attempting to stop the Egyptian Pharaoh Necho II from aiding the Assyrians.",
      "date": "-0609"
    },
    {
      "headline": "Babylonian Conquest and Destruction of Jerusalem",
      "text": "In 586 BCE, the Babylonians, led by Nebuchadnezzar II, captured Jerusalem, destroyed the First Temple, and exiled many inhabitants to Babylon.",
      "date": "-0586"
    },
    {
      "headline": "End of the Kingdom of Judah",
      "text": "The Kingdom of Judah effectively ended in 586 BCE with the Babylonian conquest and the destruction of Jerusalem.",
      "date": "-0586"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Beginning of the Revolution",
      "text": "The Hungarian Revolution of 1956 began on October 23, 1956, with a peaceful student demonstration in Budapest. The protestors demanded political reform and the withdrawal of Soviet troops from Hungary.",
      "date": "1956-10-23"
    },
    {
      "headline": "Protests Turn Violent",
      "text": "On October 23, 1956, the peaceful protests turned violent when the demonstrators attempted to broadcast their demands over the radio, leading to clashes with the State Security Police (ÁVH).",
      "date": "1956-10-23"
    },
    {
      "headline": "Imre Nagy Becomes Prime Minister",
      "text": "On October 24, 1956, Imre Nagy was appointed as the Prime Minister of Hungary, in an attempt to appease the revolutionaries.",
      "date": "1956-10-24"
    },
    {
      "headline": "Soviet Troops Enter Budapest",
      "text": "On October 24, 1956, Soviet troops entered Budapest to suppress the uprising, leading to intense fighting between Hungarian freedom fighters and Soviet forces.",
      "date": "1956-10-24"
    },
    {
      "headline": "Ceasefire and Soviet Withdrawal",
      "text": "On October 28, 1956, a ceasefire was declared, and Soviet troops began to withdraw from Budapest, as the Hungarian government promised reforms.",
      "date": "1956-10-28"
    },
    {
      "headline": "Hungary Declares Neutrality",
      "text": "On November 1, 1956, Imre Nagy declared Hungary's neutrality and announced its withdrawal from the Warsaw Pact, seeking support from the United Nations.",
      "date": "1956-11-01"
    },
    {
      "headline": "Soviet Invasion",
      "text": "On November 4, 1956, Soviet forces launched a major offensive to crush the revolution, re-entering Budapest with overwhelming military force.",
      "date": "1956-11-04"
    },
    {
      "headline": "End of the Revolution",
      "text": "By November 10, 1956, the Soviet military had effectively crushed the Hungarian Revolution, resulting in thousands of deaths and the arrest of many revolutionaries.",
      "date": "1956-11-10"
    },
    {
      "headline": "Imre Nagy Arrested",
      "text": "On November 22, 1956, Imre Nagy was arrested after seeking asylum in the Yugoslav Embassy. He was later executed in 1958.",
      "date": "1956-11-22"
    },
    {
      "headline": "Mass Exodus",
      "text": "In the aftermath of the revolution, nearly a quarter of a million Hungarians fled the country to escape repression.",
      "date": "1956-11"
    }
  ]
}

