{
  "timeline": [
    {
      "headline": "Development of Unix Begins",
      "text": "In 1969, Ken Thompson, Dennis Ritchie, and others at Bell Labs began the development of Unix, a new operating system.",
      "date": "1969"
    },
    {
      "headline": "First Edition of Unix Released",
      "text": "The first edition of Unix was released in November 1971. It was a multi-tasking, multi-user operating system.",
      "date": "1971-11"
    },
    {
      "headline": "Unix Version 4 Released",
      "text": "In 1973, Unix Version 4 was released, marking the first version written in the C programming language, which made it portable across different machines.",
      "date": "1973"
    },
    {
      "headline": "Unix Version 6 Released",
      "text": "In 1975, Unix Version 6 was released, and it became widely distributed to educational institutions, which helped to spread its popularity.",
      "date": "1975"
    },
    {
      "headline": "BSD Unix Developed",
      "text": "In 1977, the University of California, Berkeley, began developing the Berkeley Software Distribution (BSD), a Unix derivative that introduced many new features.",
      "date": "1977"
    },
    {
      "headline": "AT&T Begins Licensing Unix",
      "text": "In 1979, AT&T began licensing Unix to outside parties, which led to the development of various commercial Unix systems.",
      "date": "1979"
    },
    {
      "headline": "Release of System V",
      "text": "In 1983, AT&T released System V, one of the most significant versions of Unix, which became a standard for commercial Unix systems.",
      "date": "1983"
    },
    {
      "headline": "Introduction of POSIX Standard",
      "text": "In 1988, the Portable Operating System Interface (POSIX) standard was introduced to ensure compatibility between different Unix systems.",
      "date": "1988"
    },
    {
      "headline": "Launch of Linux",
      "text": "In 1991, Linus Torvalds released the Linux kernel, which was inspired by Unix and became the foundation for many Unix-like operating systems.",
      "date": "1991"
    },
    {
      "headline": "Open Group Forms Single UNIX Specification",
      "text": "In 1994, the Open Group was formed, and it developed the Single UNIX Specification to maintain the standardization of Unix systems.",
      "date": "1994"
    }
  ]
}

