{
  "timeline": [
    {
      "headline": "Birth of Sacagawea",
      "text": "Sacagawea was born around 1788 into the Lemhi Shoshone tribe in what is now Idaho.",
      "date": "1788"
    },
    {
      "headline": "Capture by the Hidatsa",
      "text": "Around 1800, Sacagawea was captured by a group of Hidatsa during a raid and taken to their village near present-day Washburn, North Dakota.",
      "date": "1800"
    },
    {
      "headline": "Marriage to Toussaint Charbonneau",
      "text": "Sacagawea was sold or given as a wife to Toussaint Charbonneau, a French-Canadian fur trader, around 1804.",
      "date": "1804"
    },
    {
      "headline": "Birth of Jean Baptiste Charbonneau",
      "text": "On February 11, 1805, Sacagawea gave birth to her son, Jean Baptiste Charbonneau, at Fort Mandan.",
      "date": "1805-02-11"
    },
    {
      "headline": "Joining the Lewis and Clark Expedition",
      "text": "In April 1805, Sacagawea joined the Lewis and Clark Expedition as an interpreter and guide, traveling with her husband and infant son.",
      "date": "1805-04"
    },
    {
      "headline": "Reunion with the Shoshone",
      "text": "In August 1805, Sacagawea helped the expedition by negotiating with the Shoshone for horses and supplies, reuniting with her brother, Cameahwait, who was the Shoshone chief.",
      "date": "1805-08"
    },
    {
      "headline": "Reaching the Pacific Ocean",
      "text": "Sacagawea and the expedition reached the Pacific Ocean in November 1805, marking a significant milestone in their journey.",
      "date": "1805-11"
    },
    {
      "headline": "Return to the Mandan Villages",
      "text": "In August 1806, Sacagawea and her family returned to the Mandan villages after the completion of the Lewis and Clark Expedition.",
      "date": "1806-08"
    },
    {
      "headline": "Death of Sacagawea",
      "text": "Sacagawea is believed to have died on December 20, 1812, at Fort Lisa, in present-day North Dakota, possibly from an illness.",
      "date": "1812-12-20"
    }
  ]
}

