    },
    {
      "headline": "First Published Work",
      "text": "In 1978, Alan Moore began publishing his first comic strip, 'Maxwell the Magic Cat', under the pseudonym Jill de Ray in the Northants Post.",
      "date": "1978"
    },
    {
      "headline": "Begins Writing for 2000 AD",
      "text": "In 1980, Moore started writing for the British comic anthology 2000 AD, contributing to series such as 'Skizz', 'D.R. and Quinch', and 'The Ballad of Halo Jones'.",
      "date": "1980"
    },
    {
      "headline": "Swamp Thing",
      "text": "In 1983, Moore began writing 'Swamp Thing' for DC Comics, which became a critical success and helped establish his reputation in the American comic book industry.",
      "date": "1983"
    },
    {
      "headline": "Watchmen Publication",
      "text": "In 1986, Moore's seminal work 'Watchmen' was published by DC Comics, co-created with artist Dave Gibbons. It is considered one of the greatest graphic novels of all time.",
      "date": "1986"
    },
    {
      "headline": "V for Vendetta",
      "text": "In 1988, 'V for Vendetta', originally serialized in Warrior magazine, was published as a complete graphic novel by DC Comics.",
      "date": "1988"
    },
    {
      "headline": "From Hell",
      "text": "In 1991, Moore began publishing 'From Hell', a graphic novel about Jack the Ripper, illustrated by Eddie Campbell. It was completed in 1996.",
      "date": "1991"
    },
    {
      "headline": "League of Extraordinary Gentlemen",
      "text": "In 1999, Moore launched 'The League of Extraordinary Gentlemen' with artist Kevin O'Neill, published by America's Best Comics.",
      "date": "1999"
    },
    {
      "headline": "Jerusalem Publication",
      "text": "In 2016, Moore published 'Jerusalem', a novel that explores the history and mythology of his hometown, Northampton.",
      "date": "2016"
    },
    {
      "headline": "Retirement from Comics",
      "text": "In 2019, Alan Moore announced his retirement from the comic book industry, stating that he would focus on other forms of writing.",
      "date": "2019"
    }
