{
  "timeline": [
    {
      "headline": "Emergence of Cells",
      "text": "Cells are believed to have emerged on Earth about 4 billion years ago. This marks the beginning of cellular life, which is the basic structural and functional unit of all forms of life.",
      "date": "-4000000000"
    },
    {
      "headline": "Discovery of Cells",
      "text": "The term 'cell' was coined by Robert Hooke in 1665 when he observed the structure of cork under a microscope and described the small compartments he saw as 'cells'.",
      "date": "1665"
    },
    {
      "headline": "Development of Cell Theory",
      "text": "In 1839, Matthias Schleiden and Theodor Schwann developed the cell theory, which states that all living organisms are composed of cells and that the cell is the basic unit of life.",
      "date": "1839"
    },
    {
      "headline": "Discovery of Organelles",
      "text": "Throughout the 19th and 20th centuries, scientists discovered various organelles within cells, each with specific functions, such as the nucleus, mitochondria, and chloroplasts.",
      "date": "1800-1900"
    },
    {
      "headline": "Advancements in Microscopy",
      "text": "The development of electron microscopy in the 20th century allowed scientists to observe cells and their organelles in much greater detail, leading to significant advancements in cell biology.",
      "date": "1930"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Sukarno",
      "text": "Sukarno was born on June 6, 1901, in Surabaya, Dutch East Indies.",
      "date": "1901-06-06"
    },
    {
      "headline": "Education in Surabaya",
      "text": "In 1916, Sukarno moved to Surabaya to attend a Dutch high school, where he became involved in nationalist activities.",
      "date": "1916"
    },
    {
      "headline": "Graduation from Technische Hoogeschool",
      "text": "Sukarno graduated from the Technische Hoogeschool (now Bandung Institute of Technology) in Bandung with a degree in civil engineering in 1926.",
      "date": "1926"
    },
    {
      "headline": "Founding of the Indonesian National Party",
      "text": "In 1927, Sukarno co-founded the Indonesian National Party (PNI) to promote independence from Dutch colonial rule.",
      "date": "1927"
    },
    {
      "headline": "Imprisonment by Dutch Authorities",
      "text": "Sukarno was arrested by Dutch colonial authorities in 1929 for his political activities and sentenced to four years in prison.",
      "date": "1929"
    },
    {
      "headline": "Release from Prison",
      "text": "Sukarno was released from prison in December 1931 after serving two years of his sentence.",
      "date": "1931-12"
    },
    {
      "headline": "Exile to Flores and Bengkulu",
      "text": "In 1933, Sukarno was exiled by the Dutch to Flores and later to Bengkulu, where he remained until the Japanese invasion in 1942.",
      "date": "1933"
    },
    {
      "headline": "Proclamation of Indonesian Independence",
      "text": "On August 17, 1945, Sukarno, along with Mohammad Hatta, proclaimed Indonesia's independence from Dutch rule.",
      "date": "1945-08-17"
    },
    {
      "headline": "First President of Indonesia",
      "text": "Sukarno became the first President of Indonesia on August 18, 1945, following the country's declaration of independence.",
      "date": "1945-08-18"
    },
    {
      "headline": "Recognition of Indonesian Independence",
      "text": "In December 1949, the Dutch formally recognized Indonesian independence following the Dutch-Indonesian Round Table Conference.",
      "date": "1949-12"
    },
    {
      "headline": "Guided Democracy Era",
      "text": "In 1959, Sukarno established 'Guided Democracy' in Indonesia, dissolving the parliamentary system and assuming greater control.",
      "date": "1959"
    },
    {
      "headline": "Overthrown from Power",
      "text": "Sukarno was effectively removed from power in 1967 following a failed coup attempt in 1965 and the rise of Suharto.",
      "date": "1967"
    },
    {
      "headline": "Death of Sukarno",
      "text": "Sukarno died on June 21, 1970, in Jakarta, Indonesia.",
      "date": "1970-06-21"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Design of .45 ACP",
      "text": "The .45 ACP (Automatic Colt Pistol) was designed by John Moses Browning in 1904. It was created for use in his prototype Colt semi-automatic pistol.",
      "date": "1904"
    },
    {
      "headline": "Thompson–LaGarde Tests",
      "text": "In 1904, the Thompson–LaGarde Tests were conducted, which influenced the decision to adopt a minimum of .45 caliber for a new handgun cartridge due to its stopping power.",
      "date": "1904"
    },
    {
      "headline": "Adoption by the U.S. Military",
      "text": "After successful military trials, the .45 ACP was adopted as the standard chambering for Colt's M1911 pistol.",
      "date": "1911"
    },
    {
      "headline": "Moro Rebellion Influence",
      "text": "The development of the .45 ACP was partly motivated by the lack of stopping power experienced during the Moro Rebellion, where the .38 Long Colt proved inadequate.",
      "date": "1904"
    }
  ]
}

