      "headline": "Initial Development",
      "text": "The development of the Minuteman missile began in the late 1950s as part of the United States' efforts to create a solid-fueled intercontinental ballistic missile (ICBM).",
      "date": "1958"
    },
    {
      "headline": "First Test Launch",
      "text": "The first test launch of the Minuteman I missile took place on February 1, 1961, at Cape Canaveral, Florida.",
      "date": "1961-02-01"
    },
    {
      "headline": "Deployment of Minuteman I",
      "text": "The Minuteman I entered service with the United States Air Force in 1962, marking the first deployment of a solid-fueled ICBM.",
      "date": "1962"
    },
    {
      "headline": "Introduction of Minuteman II",
      "text": "The Minuteman II, an improved version of the missile with greater range and accuracy, was first deployed in 1965.",
      "date": "1965"
    },
    {
      "headline": "Deployment of Minuteman III",
      "text": "The Minuteman III, featuring multiple independently targetable reentry vehicles (MIRVs), was first deployed in 1970, enhancing the missile's capability.",
      "date": "1970"
    },
    {
      "headline": "Completion of Minuteman III Deployment",
      "text": "By 1975, the deployment of the Minuteman III was completed, solidifying its role in the U.S. nuclear arsenal.",
      "date": "1975"
    },
    {
      "headline": "Start of Minuteman III Modernization",
      "text": "In the 1990s, the Minuteman III underwent significant modernization to extend its service life and improve its capabilities.",
      "date": "1990"
    },
    {
      "headline": "End of Minuteman II Service",
      "text": "The Minuteman II was officially retired from service in 1994, leaving the Minuteman III as the sole land-based ICBM in the U.S. arsenal.",
      "date": "1994"
    },
    {
      "headline": "Ongoing Minuteman III Service",
      "text": "As of 2024, the Minuteman III remains in service as the only land-based ICBM in the United States, representing a critical component of the U.S. nuclear triad.",
      "date": "2024"
    }
  ]
