{
  "timeline": [
    {
      "headline": "Indus Valley Civilization",
      "text": "The region of Punjab was part of the Indus Valley Civilization, one of the world's earliest urban cultures, which flourished around 3300 BCE to 1300 BCE.",
      "date": "-3300"
    },
    {
      "headline": "Vedic Period",
      "text": "During the Vedic period (circa 1500 BCE to 500 BCE), the Punjab region was known as Sapta Sindhu, the land of seven rivers.",
      "date": "-1500"
    },
    {
      "headline": "Achaemenid Empire",
      "text": "In 518 BCE, the Achaemenid Empire under Darius the Great annexed the Punjab region, making it part of the empire's easternmost territories.",
      "date": "-0518"
    },
    {
      "headline": "Alexander the Great's Invasion",
      "text": "In 326 BCE, Alexander the Great invaded Punjab, defeating King Porus in the Battle of the Hydaspes.",
      "date": "-0326"
    },
    {
      "headline": "Maurya Empire",
      "text": "Following Alexander's departure, the region became part of the Maurya Empire under Chandragupta Maurya around 322 BCE.",
      "date": "-0322"
    },
    {
      "headline": "Gupta Empire",
      "text": "During the 4th and 5th centuries CE, Punjab was part of the Gupta Empire, known for its cultural and scientific advancements.",
      "date": "0320"
    },
    {
      "headline": "Arrival of Islam",
      "text": "In the 8th century, Islam began to spread in Punjab with the arrival of Muslim traders and the Umayyad Caliphate's expansion.",
      "date": "0700"
    },
    {
      "headline": "Delhi Sultanate",
      "text": "Punjab became part of the Delhi Sultanate in the 13th century, marking the beginning of Muslim rule in the region.",
      "date": "1206"
    },
    {
      "headline": "Mughal Empire",
      "text": "In 1526, the Mughal Empire was established, and Punjab became an important region under Mughal rule.",
      "date": "1526"
    },
    {
      "headline": "Sikh Empire",
      "text": "In the early 19th century, Maharaja Ranjit Singh established the Sikh Empire, with Lahore as its capital, which lasted until 1849.",
      "date": "1801"
    },
    {
      "headline": "British Colonial Rule",
      "text": "After the defeat of the Sikh Empire in 1849, Punjab was annexed by the British East India Company and later became part of British India.",
      "date": "1849"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, the partition of India led to the division of Punjab between India and Pakistan, causing massive displacement and violence.",
      "date": "1947"
    },
    {
      "headline": "Creation of Punjab States",
      "text": "In 1966, the Indian state of Punjab was reorganized, leading to the creation of Haryana and Himachal Pradesh.",
      "date": "1966"
    }
  ]
}

