{
  "timeline": [
    {
      "headline": "Discovery of the Galilean Moons",
      "text": "In 1610, Galileo Galilei and Simon Marius independently discovered the four largest moons of Jupiter: Io, Europa, Ganymede, and Callisto. These were the first objects found to orbit a body that was neither Earth nor the Sun.",
      "date": "1610"
    },
    {
      "headline": "Discovery of Amalthea",
      "text": "In 1892, the fifth moon of Jupiter, Amalthea, was discovered by Edward Emerson Barnard. It was the first Jovian moon discovered since the Galilean moons.",
      "date": "1892"
    },
    {
      "headline": "Discovery of Himalia",
      "text": "In 1904, Charles Dillon Perrine discovered Himalia, the largest irregular moon of Jupiter.",
      "date": "1904"
    },
    {
      "headline": "Discovery of Elara",
      "text": "Elara, another of Jupiter's moons, was discovered by Charles Dillon Perrine in 1905.",
      "date": "1905"
    },
    {
      "headline": "Discovery of Pasiphae",
      "text": "In 1908, Philibert Jacques Melotte discovered Pasiphae, one of the outer moons of Jupiter.",
      "date": "1908"
    },
    {
      "headline": "Discovery of Sinope",
      "text": "Sinope was discovered by Seth Barnes Nicholson in 1914, adding to the list of Jupiter's moons.",
      "date": "1914"
    },
    {
      "headline": "Discovery of Lysithea and Carme",
      "text": "In 1938, Seth Barnes Nicholson discovered two more moons of Jupiter, Lysithea and Carme.",
      "date": "1938"
    },
    {
      "headline": "Discovery of Ananke",
      "text": "Ananke, another moon of Jupiter, was discovered by Seth Barnes Nicholson in 1951.",
      "date": "1951"
    },
    {
      "headline": "Discovery of Leda",
      "text": "In 1974, Charles Thomas Kowal discovered Leda, one of Jupiter's smaller moons.",
      "date": "1974"
    },
    {
      "headline": "Discovery of Themisto",
      "text": "Themisto was discovered in 1975 by Charles Thomas Kowal and Elizabeth Roemer, but was lost and then rediscovered in 2000.",
      "date": "1975"
    },
    {
      "headline": "Discovery of Callirrhoe and Other Moons",
      "text": "In 1999, Callirrhoe was discovered, marking the beginning of a new era of discoveries of small outer moons of Jupiter.",
      "date": "1999"
    },
    {
      "headline": "Discovery of 23 New Moons",
      "text": "In 2003, a significant number of new moons were discovered, adding 23 new moons to Jupiter's known satellite system.",
      "date": "2003"
    },
    {
      "headline": "Discovery of Valetudo",
      "text": "In 2018, Valetudo was discovered, a small moon of Jupiter that orbits in a prograde direction.",
      "date": "2018"
    },
    {
      "headline": "95 Confirmed Moons",
      "text": "As of February 5, 2024, there are 95 moons of Jupiter with confirmed orbits, not including a number of meter-sized moonlets and possible kilometer-sized outer irregular moons.",
      "date": "2024-02-05"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Earliest Chinese Characters",
      "text": "The earliest confirmed evidence of Chinese characters dates back to the Shang dynasty, with oracle bone script used for divination. These inscriptions are from around 1250 BCE.",
      "date": "-1250"
    },
    {
      "headline": "Development of Seal Script",
      "text": "During the Zhou dynasty, particularly the late Western Zhou period, seal script began to develop. This script was more standardized and used for official inscriptions.",
      "date": "-1046"
    },
    {
      "headline": "Qin Dynasty Standardization",
      "text": "In 221 BCE, the first emperor of China, Qin Shi Huang, standardized the script across the empire, leading to the creation of the small seal script.",
      "date": "-0221"
    },
    {
      "headline": "Emergence of Clerical Script",
      "text": "The clerical script emerged during the Han dynasty (206 BCE – 220 CE) as a more practical and simplified form of writing compared to the seal script.",
      "date": "-0206"
    },
    {
      "headline": "Development of Regular Script",
      "text": "The regular script, which is the basis for modern Chinese writing, began to develop during the late Han dynasty and was fully developed by the Wei and Jin periods (220–420 CE).",
      "date": "0220"
    },
    {
      "headline": "Spread to Other Cultures",
      "text": "Chinese characters spread to other East Asian countries, influencing the development of scripts in Japan (kanji), Korea (hanja), and Vietnam (chữ Nôm) over the centuries.",
      "date": "0500"
    },
    {
      "headline": "Simplification in the People's Republic of China",
      "text": "In the 1950s and 1960s, the People's Republic of China introduced simplified Chinese characters to increase literacy by reducing the number of strokes in traditional characters.",
      "date": "1950"
    },
    {
      "headline": "Modern Use and Digitalization",
      "text": "In the 21st century, Chinese characters are used in digital formats, with Unicode providing a standardized encoding for characters across different platforms.",
      "date": "2000"
    }
  ]
}

