    },
    {
      "headline": "First Use of the Term 'Reggae'",
      "text": "The term 'reggae' was first popularized by the 1968 single 'Do the Reggay' by Toots and the Maytals. This song effectively named the genre and introduced it to a global audience.",
      "date": "1968"
    },
    {
      "headline": "Reggae's Global Influence",
      "text": "Throughout the 1970s, reggae music gained international popularity, influencing musicians worldwide and becoming a voice for social and political commentary.",
      "date": "1970s"
    },
    {
      "headline": "Bob Marley's Impact",
      "text": "Bob Marley, one of the most famous reggae artists, helped bring reggae to a global audience with his music and messages of peace and unity. His career spanned from the late 1960s until his death in 1981.",
      "date": "1960s-1981"
    },
    {
      "headline": "Reggae's Recognition",
      "text": "In 2018, UNESCO recognized reggae music as an intangible cultural heritage, highlighting its contributions to international discourse on issues of injustice, resistance, love, and humanity.",
      "date": "2018"
    }
  ]
}

