    },
    {
      "headline": "Bodhidharma's Influence",
      "text": "Bodhidharma, an Indian monk, is traditionally credited with transmitting Chan Buddhism to China in the 5th or 6th century, laying the foundation for Zen.",
      "date": "0520"
    },
    {
      "headline": "Spread to Vietnam",
      "text": "From China, Chan spread south to Vietnam, where it became known as Vietnamese Thiền.",
      "date": "0600"
    },
    {
      "headline": "Spread to Korea",
      "text": "Chan Buddhism spread northeast to Korea, where it became known as Seon Buddhism.",
      "date": "0700"
    },
    {
      "headline": "Spread to Japan",
      "text": "Chan Buddhism spread east to Japan, where it became known as Japanese Zen.",
      "date": "1191"
    },
    {
      "headline": "Development of Rinzai School",
      "text": "The Rinzai school of Zen was established in Japan by the monk Myōan Eisai, emphasizing koan practice.",
      "date": "1191"
    },
    {
      "headline": "Development of Sōtō School",
      "text": "The Sōtō school of Zen was established in Japan by the monk Dōgen, emphasizing zazen or seated meditation.",
      "date": "1227"
    },
    {
      "headline": "Zen's Influence on Japanese Culture",
      "text": "Zen Buddhism significantly influenced Japanese culture, including the arts, tea ceremony, and martial arts, during the Kamakura and Muromachi periods.",
      "date": "1336"
    }
  ]
}

