    {
      "headline": "Foundation of Tyre",
      "text": "Tyre is believed to have been founded around 2750 BCE as a Phoenician city. It became one of the most important cities in the ancient Mediterranean world.",
      "date": "-2750"
    },
    {
      "headline": "Tyre's Role in Phoenician Expansion",
      "text": "During the 10th century BCE, Tyre played a crucial role in the Phoenician expansion across the Mediterranean, establishing colonies such as Carthage.",
      "date": "-1000"
    },
    {
      "headline": "Siege of Tyre by Nebuchadnezzar II",
      "text": "From 586 to 573 BCE, Tyre was besieged by Babylonian king Nebuchadnezzar II. The city withstood the siege, but eventually agreed to pay tribute.",
      "date": "-0586"
    },
    {
      "headline": "Conquest by Alexander the Great",
      "text": "In 332 BCE, Tyre was conquered by Alexander the Great after a famous seven-month siege, during which he built a causeway to reach the island city.",
      "date": "-0332"
    },
    {
      "headline": "Roman Rule",
      "text": "Tyre became part of the Roman Empire in 64 BCE and flourished as a major center of trade and culture.",
      "date": "-0064"
    },
    {
      "headline": "Destruction by Earthquake",
      "text": "In 551 CE, Tyre was severely damaged by a major earthquake, which led to significant rebuilding efforts.",
      "date": "0551"
    },
    {
      "headline": "Muslim Conquest",
      "text": "In 638 CE, Tyre was conquered by Muslim forces, marking the beginning of Islamic rule in the region.",
      "date": "0638"
    },
    {
      "headline": "Crusader Control",
      "text": "In 1124, Tyre was captured by the Crusaders and became part of the Kingdom of Jerusalem.",
      "date": "1124"
    },
    {
      "headline": "Return to Muslim Rule",
      "text": "In 1291, Tyre was recaptured by the Mamluks, ending Crusader control in the region.",
      "date": "1291"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Tyre became part of the Ottoman Empire in 1516 and remained under Ottoman control until the end of World War I.",
      "date": "1516"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1984, Tyre was designated as a UNESCO World Heritage Site due to its rich history and archaeological significance.",
      "date": "1984"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Terri Schiavo's Collapse",
      "text": "On February 25, 1990, Terri Schiavo collapsed in her home in St. Petersburg, Florida, due to cardiac arrest caused by a potassium imbalance, leading to severe brain damage and a persistent vegetative state.",
      "date": "1990-02-25"
    },
    {
      "headline": "Michael Schiavo's Petition",
      "text": "In 1998, Michael Schiavo, Terri's husband and legal guardian, petitioned the Sixth Circuit Court of Florida to remove Terri's feeding tube, arguing that she would not have wanted prolonged artificial life support.",
      "date": "1998"
    },
    {
      "headline": "Court Orders Removal of Feeding Tube",
      "text": "On February 11, 2000, Judge George Greer of the Sixth Circuit Court of Florida ruled in favor of Michael Schiavo, ordering the removal of Terri Schiavo's feeding tube.",
      "date": "2000-02-11"
    },
    {
      "headline": "Feeding Tube Removed and Reinserted",
      "text": "On April 24, 2001, Terri Schiavo's feeding tube was removed for the first time, but it was reinserted two days later on April 26, 2001, after her parents, Bob and Mary Schindler, filed an appeal.",
      "date": "2001-04-24"
    },
    {
      "headline": "Florida Governor's Intervention",
      "text": "On October 21, 2003, Florida Governor Jeb Bush signed 'Terri's Law,' which allowed the state to intervene and order the reinsertion of Terri Schiavo's feeding tube six days after it had been removed.",
      "date": "2003-10-21"
    },
    {
      "headline": "Florida Supreme Court Strikes Down 'Terri's Law'",
      "text": "On September 23, 2004, the Florida Supreme Court unanimously ruled that 'Terri's Law' was unconstitutional, leading to the removal of the feeding tube again.",
      "date": "2004-09-23"
    },
    {
      "headline": "Federal Intervention",
      "text": "In March 2005, the U.S. Congress passed a bill allowing federal courts to review the case, which was signed by President George W. Bush on March 21, 2005.",
      "date": "2005-03-21"
    },
    {
      "headline": "Final Removal of Feeding Tube",
      "text": "On March 18, 2005, Terri Schiavo's feeding tube was removed for the final time following a court order.",
      "date": "2005-03-18"
    },
    {
      "headline": "Death of Terri Schiavo",
      "text": "Terri Schiavo died on March 31, 2005, at the age of 41, nearly two weeks after her feeding tube was removed.",
      "date": "2005-03-31"
    }
  ]
}

