    {
      "headline": "Conception of the Constituent Assembly",
      "text": "The idea of a Constituent Assembly for India was first proposed by M.N. Roy in 1934. It was later enshrined as a demand by the Indian National Congress in 1935.",
      "date": "1934"
    },
    {
      "headline": "Demand for Constituent Assembly",
      "text": "The Indian National Congress officially demanded a Constituent Assembly in 1935, emphasizing the need for a body to draft a constitution for India.",
      "date": "1935"
    },
    {
      "headline": "Elections for Constituent Assembly",
      "text": "Elections for the Constituent Assembly were held in July 1946. The assembly was partly elected by the Provincial Assemblies of British India and partly nominated by the princely states.",
      "date": "1946-07"
    },
    {
      "headline": "First Meeting of the Constituent Assembly",
      "text": "The Constituent Assembly of India held its first meeting on December 9, 1946.",
      "date": "1946-12-09"
    },
    {
      "headline": "Adoption of the Objectives Resolution",
      "text": "On January 22, 1947, the Constituent Assembly adopted the Objectives Resolution, which laid down the fundamental principles of the constitution.",
      "date": "1947-01-22"
    },
    {
      "headline": "India's Independence and Role of the Assembly",
      "text": "After India gained independence on August 15, 1947, the Constituent Assembly also served as the nation's Provisional Parliament.",
      "date": "1947-08-15"
    },
    {
      "headline": "Draft Constitution Prepared",
      "text": "The first draft of the Constitution of India was prepared by the Drafting Committee and submitted to the Constituent Assembly on November 4, 1947.",
      "date": "1947-11-04"
    },
    {
      "headline": "Adoption of the Constitution",
      "text": "The Constitution of India was adopted by the Constituent Assembly on November 26, 1949.",
      "date": "1949-11-26"
    },
    {
      "headline": "Constitution Comes into Effect",
      "text": "The Constitution of India came into effect on January 26, 1950, marking the end of the Constituent Assembly's role.",
      "date": "1950-01-26"
    }
  ]
}

