{
  "timeline": [
    {
      "headline": "Soviet Invasion of Poland",
      "text": "On September 17, 1939, the Soviet Union invaded Poland from the east, following the German invasion from the west. This led to the capture of thousands of Polish military officers and intelligentsia.",
      "date": "1939-09-17"
    },
    {
      "headline": "Decision to Execute Polish Prisoners",
      "text": "On March 5, 1940, the Soviet Politburo, including Joseph Stalin, signed an order to execute Polish prisoners of war, which included military officers, police officers, and members of the Polish intelligentsia.",
      "date": "1940-03-05"
    },
    {
      "headline": "Katyn Massacre Executions Begin",
      "text": "In April 1940, the NKVD began executing Polish prisoners in the Katyn Forest, as well as in other locations such as Kalinin and Kharkiv.",
      "date": "1940-04"
    },
    {
      "headline": "Katyn Massacre Executions End",
      "text": "By May 1940, the mass executions of approximately 22,000 Polish prisoners were completed.",
      "date": "1940-05"
    },
    {
      "headline": "Discovery of Mass Graves",
      "text": "In April 1943, Nazi German forces discovered the mass graves in the Katyn Forest and announced the findings to the world, blaming the Soviet Union for the massacre.",
      "date": "1943-04"
    },
    {
      "headline": "Soviet Denial and Blame on Nazis",
      "text": "The Soviet Union denied responsibility for the massacre and claimed that the Nazis were responsible for the killings, a stance they maintained for decades.",
      "date": "1943"
    },
    {
      "headline": "Soviet Admission of Guilt",
      "text": "On April 13, 1990, the Soviet Union officially admitted responsibility for the Katyn massacre, acknowledging that the executions were carried out by the NKVD.",
      "date": "1990-04-13"
    },
    {
      "headline": "Polish-Russian Reconciliation Efforts",
      "text": "In 2010, efforts were made to reconcile Polish-Russian relations, including a joint commemoration of the 70th anniversary of the massacre.",
      "date": "2010"
    }
  ]
}

