    {
      "headline": "Development of Santería",
      "text": "Santería, also known as Regla de Ocha or Lucumí, developed in Cuba during the late 19th century. It arose through a process of syncretism between the traditional Yoruba religion of West Africa, Catholicism, and Spiritism.",
      "date": "1800-1899"
    },
    {
      "headline": "Syncretism with Catholicism",
      "text": "Santería incorporates elements of Catholicism, with many of its deities, known as orishas, being associated with Catholic saints. This syncretism allowed enslaved Africans to continue practicing their religion under the guise of Catholic worship.",
      "date": "1800-1899"
    },
    {
      "headline": "Influence of Spiritism",
      "text": "Spiritism, a belief system that emphasizes communication with spirits, also influenced Santería. This influence is evident in the practices of divination and communication with ancestors within the religion.",
      "date": "1800-1899"
    },
    {
      "headline": "Spread to the United States",
      "text": "In the 20th century, Santería spread to the United States, particularly in areas with large Cuban immigrant populations, such as Miami and New York City.",
      "date": "1900-1999"
    },
    {
      "headline": "Diversity among Practitioners",
      "text": "Santería is characterized by a lack of central authority and significant diversity among its practitioners, known as creyentes ('believers'). This diversity is reflected in the various practices and interpretations of the religion.",
      "date": "1900-1999"
    }
  ]
}

