    {
      "headline": "Formation of the Russian Social Democratic Labour Party",
      "text": "The Communist Party of the Soviet Union traces its origins to the Russian Social Democratic Labour Party (RSDLP), which was founded in 1898.",
      "date": "1898"
    },
    {
      "headline": "Bolshevik-Menshevik Split",
      "text": "The RSDLP split into two factions, the Bolsheviks and the Mensheviks, at the Second Party Congress in 1903.",
      "date": "1903"
