    {
      "headline": "October Revolution",
      "text": "The Bolsheviks, led by Vladimir Lenin, seized power in Russia during the October Revolution in 1917.",
      "date": "1917-10"
    },
    {
      "headline": "Formation of the Russian Communist Party (Bolsheviks)",
      "text": "The Bolsheviks formally became the Russian Communist Party (Bolsheviks) in March 1918.",
      "date": "1918-03"
    },
    {
      "headline": "Formation of the Communist Party of the Soviet Union",
      "text": "The Russian Communist Party (Bolsheviks) was renamed the All-Union Communist Party (Bolsheviks) in 1925, and later became the Communist Party of the Soviet Union in 1952.",
      "date": "1925"
    },
    {
      "headline": "Stalin's Leadership",
      "text": "Joseph Stalin became the leader of the Soviet Union and the Communist Party, consolidating power by the late 1920s.",
      "date": "1929"
    },
    {
      "headline": "Great Purge",
      "text": "The Great Purge, a campaign of political repression in the Soviet Union, took place from 1936 to 1938 under Stalin's leadership.",
      "date": "1936"
    },
    {
      "headline": "World War II and Soviet Expansion",
      "text": "During and after World War II, the Soviet Union expanded its influence across Eastern Europe, establishing communist governments in several countries.",
      "date": "1945"
    },
    {
      "headline": "Nikita Khrushchev's Leadership",
      "text": "Nikita Khrushchev led the Soviet Union from 1953 to 1964, initiating de-Stalinization and significant reforms.",
      "date": "1953"
    },
    {
      "headline": "Brezhnev Era",
      "text": "Leonid Brezhnev led the Soviet Union from 1964 to 1982, a period marked by economic stagnation and political stability.",
      "date": "1964"
    },
    {
      "headline": "Gorbachev's Reforms",
      "text": "Mikhail Gorbachev became the leader of the Soviet Union in 1985, introducing reforms such as glasnost and perestroika.",
      "date": "1985"
    },
    {
      "headline": "End of CPSU's Monopoly",
      "text": "In 1990, the Congress of People's Deputies modified Article 6 of the 1977 Soviet Constitution, ending the CPSU's monopoly over the political system.",
      "date": "1990"
    },
    {
      "headline": "Coup Attempt and Party Ban",
      "text": "Following the 1991 Soviet coup attempt, Russian President Boris Yeltsin outlawed the Communist Party of the Soviet Union on 6 November 1991.",
      "date": "1991-11-06"
    }
  ]
}

