{
  "timeline": [
    {
      "headline": "Faraday's Law of Induction",
      "text": "In 1831, Michael Faraday discovered the principle of electromagnetic induction, which is the fundamental operating principle of transformers. This law describes how a changing magnetic field within a coil of wire induces an electromotive force (EMF) in the wire.",
      "date": "1831"
    },
    {
      "headline": "First Transformer Prototype",
      "text": "In 1836, Reverend Nicholas Callan of Maynooth College, Ireland, invented an early form of the induction coil, which is considered a precursor to the modern transformer.",
      "date": "1836"
    },
    {
      "headline": "Development of the Induction Coil",
      "text": "Between 1851 and 1853, Heinrich Daniel Ruhmkorff developed the Ruhmkorff coil, an early type of induction coil that could produce high voltages, further advancing the technology leading to transformers.",
      "date": "1851"
    },
    {
      "headline": "First Practical Transformer",
      "text": "In 1885, Hungarian engineers Károly Zipernowsky, Ottó Bláthy, and Miksa Déri created the first practical transformer, known as the ZBD model, which was used in the Ganz factory in Budapest.",
      "date": "1885"
    },
    {
      "headline": "Introduction of the Alternating Current Transformer",
      "text": "In 1886, William Stanley, working for Westinghouse, built the first practical alternating current (AC) transformer in Great Barrington, Massachusetts, which was used to demonstrate the advantages of AC power distribution.",
      "date": "1886"
    },
    {
      "headline": "Adoption of Transformers in Power Grids",
      "text": "By the late 1880s, transformers became a key component in the widespread adoption of AC power systems, allowing for efficient long-distance transmission of electricity.",
      "date": "1880"
    },
    {
      "headline": "Standardization of Transformer Design",
      "text": "In the early 20th century, the design and construction of transformers were standardized, leading to improvements in efficiency and reliability, and facilitating their widespread use in electrical grids worldwide.",
      "date": "1900"
    }
  ]
}

