      "date": "1876-06-25"
    },
    {
      "headline": "Surrender of Crazy Horse",
      "text": "On May 6, 1877, Crazy Horse surrendered to United States troops at Fort Robinson in Nebraska, after months of evading capture.",
      "date": "1877-05-06"
    },
    {
