{
  "timeline": [
    {
      "headline": "Dutch Cape Colony Established",
      "text": "In 1652, the Dutch East India Company established a refreshment station at the Cape of Good Hope, marking the beginning of European settlement in South Africa. This led to the initial interactions and unions between Dutch settlers and the indigenous Khoi Khoi people.",
      "date": "1652"
    },
    {
      "headline": "Interracial Unions Begin",
      "text": "Throughout the late 17th century, Dutch settlers began forming unions with Khoi Khoi women, as well as with enslaved women brought from other parts of Africa and Asia, leading to the birth of mixed-race children.",
      "date": "Late 1600s"
    },
    {
      "headline": "British Occupation of the Cape",
      "text": "In 1795, the British took control of the Cape Colony from the Dutch, leading to further European settlement and increased interracial unions, contributing to the growth of the Coloured population.",
      "date": "1795"
    },
    {
      "headline": "Abolition of Slavery",
      "text": "In 1834, slavery was abolished in the British Empire, including the Cape Colony. This event significantly impacted the social dynamics and demographics of the region, affecting the Coloured community.",
      "date": "1834"
    },
    {
      "headline": "Union of South Africa",
      "text": "In 1910, the Union of South Africa was established, uniting the Cape Colony, Natal, Transvaal, and the Orange Free State. The Coloured community was subjected to various forms of discrimination under the new government.",
      "date": "1910"
    },
    {
      "headline": "Apartheid Legislation Enacted",
      "text": "In 1948, the National Party came to power in South Africa and began implementing apartheid, a system of institutionalized racial segregation and discrimination. Coloured people were officially classified as a separate racial group and faced numerous restrictions.",
      "date": "1948"
    },
    {
      "headline": "Coloureds Removed from Voter Rolls",
      "text": "In 1956, the South African government removed Coloured people from the common voters' roll, further disenfranchising them under apartheid.",
      "date": "1956"
    },
    {
      "headline": "End of Apartheid",
      "text": "In 1994, apartheid officially ended with the first democratic elections in South Africa, in which people of all races, including Coloureds, could vote. This marked a significant turning point for the Coloured community in terms of political and social rights.",
      "date": "1994"
    }
  ]
}

