{
  "timeline": [
    {
      "headline": "IEEE 802.11 Standard Published",
      "text": "The original IEEE 802.11 standard was published in 1997. It provided 1 or 2 Mbps transmission speeds in the 2.4 GHz band using either frequency-hopping spread spectrum (FHSS) or direct-sequence spread spectrum (DSSS).",
      "date": "1997"
    },
    {
      "headline": "IEEE 802.11a Amendment",
      "text": "In 1999, the IEEE 802.11a amendment was ratified. It operated in the 5 GHz band and offered data rates up to 54 Mbps using orthogonal frequency-division multiplexing (OFDM).",
      "date": "1999"
    },
    {
      "headline": "IEEE 802.11b Amendment",
      "text": "Also in 1999, the IEEE 802.11b amendment was ratified. It operated in the 2.4 GHz band and increased data rates up to 11 Mbps using DSSS.",
      "date": "1999"
    },
    {
      "headline": "IEEE 802.11g Amendment",
      "text": "The IEEE 802.11g amendment was ratified in 2003. It operated in the 2.4 GHz band and offered data rates up to 54 Mbps, combining the best of 802.11a and 802.11b.",
      "date": "2003"
    },
    {
      "headline": "IEEE 802.11n Amendment",
      "text": "Ratified in 2009, the IEEE 802.11n amendment introduced MIMO (multiple-input multiple-output) technology, allowing data rates up to 600 Mbps in both the 2.4 GHz and 5 GHz bands.",
      "date": "2009"
    },
    {
      "headline": "IEEE 802.11ac Amendment",
      "text": "The IEEE 802.11ac amendment was ratified in 2013. It operated in the 5 GHz band and introduced wider channels, more spatial streams, and higher data rates up to 1 Gbps and beyond.",
      "date": "2013"
    },
    {
      "headline": "IEEE 802.11ad Amendment",
      "text": "Ratified in 2012, the IEEE 802.11ad amendment introduced the 60 GHz band, allowing for very high data rates up to 7 Gbps over short distances.",
      "date": "2012"
    },
    {
