{
  "timeline": [
    {
      "headline": "Beginning of Mycenaean Greece",
      "text": "The Mycenaean civilization began around 1750 BC, marking the last phase of the Bronze Age in ancient Greece. This period is characterized by the emergence of palatial states, urban organization, and a distinctively Greek civilization.",
      "date": "-1750"
    },
    {
      "headline": "Development of Mycenaean Palatial Centers",
      "text": "During the 16th century BC, major Mycenaean centers such as Mycenae, Pylos, Tiryns, and Midea in the Peloponnese, as well as Orchomenos, Thebes, and Athens in Central Greece, began to emerge.",
      "date": "-1600"
    },
    {
      "headline": "Mycenaean Expansion",
      "text": "By the 15th century BC, Mycenaean settlements had expanded to Epirus, Macedonia, islands in the Aegean Sea, the south-west coast of Asia Minor, and Cyprus. Mycenaean-influenced settlements also appeared in the Levant and Italy.",
      "date": "-1500"
    },
    {
      "headline": "Height of Mycenaean Civilization",
      "text": "The Mycenaean civilization reached its peak during the 14th and 13th centuries BC, with a highly developed sociopolitical culture, advanced art, and the use of the Linear B writing system.",
      "date": "-1400"
    },
    {
      "headline": "Destruction of Mycenaean Palaces",
      "text": "Around 1200 BC, many Mycenaean palaces were destroyed, marking the beginning of the decline of Mycenaean civilization.",
      "date": "-1200"
    },
    {
      "headline": "End of Mycenaean Greece",
      "text": "By approximately 1050 BC, the Mycenaean civilization had collapsed, leading to the Greek Dark Ages. This period was characterized by a significant decline in population and the loss of writing.",
      "date": "-1050"
    }
  ]
}

