    {
      "headline": "Development of EMDR",
      "text": "In 1987, Francine Shapiro developed Eye Movement Desensitization and Reprocessing (EMDR) as a form of psychotherapy aimed at alleviating the distress associated with traumatic memories, such as those experienced in post-traumatic stress disorder (PTSD).",
      "date": "1987"
    },
    {
      "headline": "First Controlled Study",
      "text": "In 1989, Francine Shapiro published the first controlled study of EMDR, demonstrating its effectiveness in treating PTSD.",
      "date": "1989"
    },
    {
      "headline": "EMDR Gains Recognition",
      "text": "In the 1990s, EMDR gained recognition as a viable treatment for PTSD, with various studies supporting its efficacy.",
      "date": "1990"
    },
    {
      "headline": "EMDR International Association Founded",
      "text": "In 1995, the EMDR International Association (EMDRIA) was founded to promote the use and research of EMDR therapy.",
      "date": "1995"
    },
    {
      "headline": "EMDR Included in Treatment Guidelines",
      "text": "By the late 1990s and early 2000s, EMDR was included in various treatment guidelines for PTSD, including those by the American Psychological Association and the Department of Veterans Affairs.",
      "date": "2000"
    },
    {
      "headline": "EMDR Controversy",
      "text": "Despite its inclusion in treatment guidelines, EMDR remains controversial within the psychological community, with debates over its mechanisms and efficacy continuing into the 21st century.",
      "date": "2000"
    }
  ]
}

