    {
      "headline": "AMF Acquisition",
      "text": "In 1969, American Machine and Foundry (AMF) acquired Harley-Davidson, leading to a period of mixed success and quality control issues.",
      "date": "1969"
    },
    {
      "headline": "Buyback from AMF",
      "text": "In 1981, a group of 13 investors, led by Vaughn Beals and Willie G. Davidson, purchased Harley-Davidson from AMF, marking the beginning of a turnaround for the company.",
      "date": "1981"
