    },
    {
      "headline": "Hambach Festival",
      "text": "The Hambach Festival took place in May 1832. It was a significant event in the history of the German Confederation, where around 30,000 people gathered to demand national unity, freedom, and democracy.",
      "date": "1832-05"
    },
    {
      "headline": "Frankfurt Parliament",
      "text": "In 1848, the Frankfurt Parliament was convened as part of the revolutionary movements across Europe. It was the first freely elected parliament for all of Germany, aiming to create a unified German state.",
      "date": "1848"
    },
    {
      "headline": "Dissolution of the German Confederation",
      "text": "The German Confederation was dissolved on August 23, 1866, following the Austro-Prussian War. The war resulted in the establishment of the North German Confederation under Prussian leadership.",
      "date": "1866-08-23"
    }
  ]
}

