{
  "timeline": [
    {
      "headline": "First Japanese Invasion of Korea",
      "text": "The first Japanese invasion of Korea, led by Toyotomi Hideyoshi, began in 1592. Japanese forces landed at Busan and quickly advanced northward, capturing Seoul and Pyongyang.",
      "date": "1592"
    },
    {
      "headline": "Battle of Hansan Island",
      "text": "In August 1592, the Korean navy, under the command of Admiral Yi Sun-sin, won a decisive victory against the Japanese fleet at the Battle of Hansan Island, which significantly disrupted Japanese supply lines.",
      "date": "1592-08"
    },
    {
      "headline": "Recapture of Pyongyang",
      "text": "In January 1593, allied Korean and Ming Chinese forces recaptured Pyongyang from the Japanese, marking a turning point in the first invasion.",
      "date": "1593-01"
    },
    {
      "headline": "Siege of Jinju",
      "text": "The first Siege of Jinju occurred in 1592, where Korean forces successfully defended the fortress against the Japanese.",
      "date": "1592"
    },
    {
      "headline": "Truce Negotiations",
      "text": "In 1596, after several years of stalemate and negotiations, a temporary truce was established between Japan and the Ming dynasty, although it ultimately failed to bring lasting peace.",
      "date": "1596"
    },
    {
      "headline": "Second Japanese Invasion of Korea",
      "text": "The second invasion began in 1597, as Japanese forces launched a renewed offensive, capturing several fortresses in southern Korea.",
      "date": "1597"
    },
    {
      "headline": "Battle of Myeongnyang",
      "text": "In October 1597, Admiral Yi Sun-sin achieved a significant victory at the Battle of Myeongnyang, where his fleet defeated a much larger Japanese force, further hindering Japanese operations.",
      "date": "1597-10"
    },
    {
      "headline": "Battle of Noryang",
      "text": "The Battle of Noryang took place in December 1598, where combined Korean and Ming naval forces defeated the Japanese fleet. This battle marked the last major military engagement of the war.",
      "date": "1598-12"
    },
    {
      "headline": "Withdrawal of Japanese Forces",
      "text": "By the end of 1598, Japanese forces withdrew from Korea, effectively ending the conflict. The withdrawal was prompted by the death of Toyotomi Hideyoshi and the lack of resources to continue the war.",
      "date": "1598"
    }
  ]
}

