{
  "timeline": [
    {
      "headline": "Hijacking of Air France Flight 139",
      "text": "On June 27, 1976, Air France Flight 139, traveling from Tel Aviv to Paris, was hijacked by two members of the Popular Front for the Liberation of Palestine - External Operations (PFLP-EO) and two members of the German Revolutionary Cells (RZ) during a stopover in Athens.",
      "date": "1976-06-27"
    },
    {
      "headline": "Flight Diverted to Libya",
      "text": "After the hijacking, the aircraft was diverted to Benghazi, Libya, where it landed for refueling and stayed for several hours.",
      "date": "1976-06-27"
    },
    {
      "headline": "Arrival at Entebbe, Uganda",
      "text": "On June 28, 1976, the hijacked plane landed at Entebbe International Airport in Uganda. The hijackers were joined by additional terrorists and received support from Ugandan dictator Idi Amin.",
      "date": "1976-06-28"
    },
    {
      "headline": "Hostage Situation at Entebbe",
      "text": "The hijackers held 248 passengers and crew hostage at the old terminal of Entebbe Airport, demanding the release of 40 Palestinians held in Israel and 13 other detainees imprisoned in Kenya, France, Switzerland, and Germany.",
      "date": "1976-06-28"
    },
    {
      "headline": "Operation Thunderbolt Planned",
      "text": "In response to the hijacking, the Israeli government began planning a rescue operation, codenamed Operation Thunderbolt, to free the hostages held at Entebbe Airport.",
      "date": "1976-06-29"
    },
    {
      "headline": "Rescue Operation Launched",
      "text": "On July 3, 1976, Israeli commandos flew over 2,500 miles to Uganda to execute the rescue mission. The operation was meticulously planned and involved a surprise attack on the airport.",
      "date": "1976-07-03"
    },
    {
      "headline": "Operation Entebbe Executed",
      "text": "On July 4, 1976, the Israeli commandos successfully stormed the airport, killing all the hijackers and 45 Ugandan soldiers. Three hostages were killed during the raid, and one Israeli soldier, Yonatan Netanyahu, was also killed.",
      "date": "1976-07-04"
    },
    {
      "headline": "Hostages Rescued",
      "text": "The operation resulted in the rescue of 102 hostages, who were flown back to Israel. The mission was hailed as a success and demonstrated Israel's commitment to protecting its citizens.",
      "date": "1976-07-04"
    }
  ]
}

