    {
      "headline": "First Identification of Chronic Wasting Disease",
      "text": "Chronic wasting disease (CWD) was first identified in captive mule deer at a wildlife research facility in Fort Collins, Colorado, United States, in 1967.",
      "date": "1967"
    },
    {
      "headline": "Recognition as a Transmissible Spongiform Encephalopathy",
      "text": "In 1978, CWD was recognized as a transmissible spongiform encephalopathy (TSE), a family of diseases caused by prions.",
      "date": "1978"
    },
    {
      "headline": "First Case in Free-Ranging Deer",
      "text": "The first case of CWD in free-ranging deer was identified in Colorado in 1981.",
      "date": "1981"
    },
    {
      "headline": "Spread to Other States",
      "text": "By the late 1990s, CWD had spread to wild deer and elk populations in several other states, including Wyoming, Nebraska, and South Dakota.",
      "date": "1990"
    },
    {
      "headline": "First Detection in Canada",
      "text": "CWD was first detected in Canada in 1996 in farmed elk in Saskatchewan.",
      "date": "1996"
    },
    {
      "headline": "First Detection in Europe",
      "text": "In 2016, CWD was detected for the first time in Europe, in a wild reindeer in Norway.",
      "date": "2016"
    },
    {
      "headline": "Ongoing Monitoring and Research",
      "text": "As of 2023, CWD continues to be monitored and researched extensively due to its potential impact on wildlife populations and concerns about possible transmission to humans.",
      "date": "2023"
    }
  ]
}

