    {
      "headline": "Study Begins",
      "text": "The Tuskegee Study of Untreated Syphilis in the Negro Male began in 1932. It was conducted by the United States Public Health Service (PHS) and involved nearly 400 African American men with syphilis.",
      "date": "1932"
    },
    {
      "headline": "Penicillin Becomes Standard Treatment",
      "text": "In 1947, penicillin became the standard treatment for syphilis. However, the men in the study were not treated with penicillin, as the study continued to observe the effects of untreated syphilis.",
      "date": "1947"
    },
    {
      "headline": "Study Exposed",
      "text": "In 1972, the study was exposed to the public, leading to widespread outrage. The unethical nature of the study, including the lack of informed consent and the withholding of treatment, was heavily criticized.",
      "date": "1972"
    },
    {
      "headline": "Study Ends",
      "text": "Following the public outcry, the Tuskegee Syphilis Study was officially ended in 1972.",
      "date": "1972"
    },
    {
      "headline": "U.S. Government Settlement",
      "text": "In 1974, the U.S. government reached a $10 million settlement with the study participants and their families.",
      "date": "1974"
    },
    {
      "headline": "Presidential Apology",
      "text": "On May 16, 1997, President Bill Clinton formally apologized to the surviving participants of the study and their families on behalf of the United States government.",
      "date": "1997-05-16"
    }
  ]
}

