{
  "timeline": [
    {
      "headline": "Formation of the 82nd Division",
      "text": "The 82nd Division was constituted in the National Army on August 5, 1917, and organized on August 25, 1917, at Camp Gordon, Georgia.",
      "date": "1917-08-25"
    },
    {
      "headline": "World War I Deployment",
      "text": "The 82nd Division was deployed to France in 1918, where it participated in the St. Mihiel and Meuse-Argonne offensives.",
      "date": "1918"
    },
    {
      "headline": "Reconstitution as 82nd Airborne Division",
      "text": "On August 15, 1942, the 82nd Division was reconstituted as the 82nd Airborne Division, becoming the first airborne division in the U.S. Army.",
      "date": "1942-08-15"
    },
    {
      "headline": "Sicily Invasion",
      "text": "The 82nd Airborne Division participated in Operation Husky, the invasion of Sicily, in July 1943.",
      "date": "1943-07"
    },
    {
      "headline": "Operation Overlord",
      "text": "The division took part in Operation Overlord, the D-Day landings in Normandy, on June 6, 1944.",
      "date": "1944-06-06"
    },
    {
      "headline": "Operation Market Garden",
      "text": "In September 1944, the 82nd Airborne Division participated in Operation Market Garden in the Netherlands.",
      "date": "1944-09"
    },
    {
      "headline": "Battle of the Bulge",
      "text": "The division played a crucial role in the Battle of the Bulge, which began in December 1944.",
      "date": "1944-12"
    },
    {
      "headline": "Occupation Duty in Berlin",
      "text": "After World War II, the 82nd Airborne Division was stationed in Berlin as part of the occupation forces in 1945.",
      "date": "1945"
    },
    {
      "headline": "Deployment to the Dominican Republic",
      "text": "In April 1965, the division was deployed to the Dominican Republic as part of Operation Power Pack.",
      "date": "1965-04"
    },
    {
      "headline": "Vietnam War Deployment",
      "text": "Elements of the 82nd Airborne Division were deployed to Vietnam in 1968 during the Tet Offensive.",
      "date": "1968"
    },
    {
      "headline": "Operation Urgent Fury",
      "text": "The division participated in Operation Urgent Fury, the invasion of Grenada, in October 1983.",
      "date": "1983-10"
    },
    {
      "headline": "Operation Just Cause",
      "text": "In December 1989, the 82nd Airborne Division took part in Operation Just Cause in Panama.",
      "date": "1989-12"
    },
    {
      "headline": "Operation Desert Storm",
      "text": "The division was deployed to the Persian Gulf for Operation Desert Storm in 1991.",
      "date": "1991"
    },
    {
      "headline": "Operation Enduring Freedom",
      "text": "In 2002, the 82nd Airborne Division was deployed to Afghanistan as part of Operation Enduring Freedom.",
      "date": "2002"
    },
    {
      "headline": "Operation Iraqi Freedom",
      "text": "The division was deployed to Iraq in 2003 as part of Operation Iraqi Freedom.",
      "date": "2003"
    }
  ]
}

