    },
    {
      "headline": "Reign of Ish-bosheth",
      "text": "After Saul's death, his son Ish-bosheth was made king over Israel, while David was king over Judah. Ish-bosheth's reign is traditionally dated to around 1010 BCE.",
      "date": "-1010"
    },
    {
      "headline": "Reign of David",
      "text": "David became king of Judah around 1010 BCE and later became king of the United Kingdom of Israel after Ish-bosheth's death. His reign is traditionally dated from 1010 to 970 BCE.",
      "date": "-1010"
    },
    {
      "headline": "Capture of Jerusalem",
      "text": "David captured Jerusalem and established it as the capital of the United Kingdom of Israel. This event is traditionally dated to around 1003 BCE.",
      "date": "-1003"
    },
    {
      "headline": "Reign of Solomon",
      "text": "Solomon, son of David, became king after David's death. His reign is traditionally dated from 970 to 931 BCE. Solomon is known for building the First Temple in Jerusalem.",
      "date": "-0970"
    },
    {
      "headline": "Construction of the First Temple",
      "text": "Solomon built the First Temple in Jerusalem, a significant religious and cultural achievement. The construction is traditionally dated to around 957 BCE.",
      "date": "-0957"
    },
    {
      "headline": "Division of the Kingdom",
      "text": "After Solomon's death in 931 BCE, the United Kingdom of Israel split into two separate kingdoms: the Kingdom of Israel in the north and the Kingdom of Judah in the south.",
      "date": "-0931"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of John Bowlby",
      "text": "John Bowlby, the psychiatrist and psychoanalyst who developed attachment theory, was born on February 26, 1907.",
      "date": "1907-02-26"
    },
    {
      "headline": "Bowlby's Early Career",
      "text": "In the 1930s, John Bowlby began his career in psychiatry and psychoanalysis, focusing on child development and the impact of early family relationships.",
      "date": "1930"
    },
    {
      "headline": "Bowlby's Research on Maternal Deprivation",
      "text": "During World War II, Bowlby conducted research on children who had been separated from their families, leading to his interest in maternal deprivation and its effects on child development.",
      "date": "1940"
    },
    {
      "headline": "Publication of 'Maternal Care and Mental Health'",
      "text": "In 1951, John Bowlby published 'Maternal Care and Mental Health,' a report for the World Health Organization, emphasizing the importance of a child's relationship with their mother in mental health development.",
      "date": "1951"
    },
    {
      "headline": "Development of Attachment Theory",
      "text": "Throughout the 1950s and 1960s, Bowlby developed attachment theory, integrating concepts from ethology, cybernetics, information processing, and developmental psychology.",
      "date": "1950"
    },
    {
      "headline": "Publication of 'Attachment and Loss' Series",
      "text": "Between 1969 and 1980, Bowlby published the 'Attachment and Loss' trilogy, which laid the foundation for attachment theory and explored the nature of attachment, separation, and loss.",
      "date": "1969"
    },
    {
      "headline": "Mary Ainsworth's Strange Situation Procedure",
      "text": "In 1970, Mary Ainsworth, a colleague of Bowlby, developed the Strange Situation Procedure, an observational study that identified different attachment styles in children.",
      "date": "1970"
    },
    {
      "headline": "Bowlby's Death",
      "text": "John Bowlby passed away on September 2, 1990, leaving a significant legacy in the field of psychology with his development of attachment theory.",
      "date": "1990-09-02"
    }
  ]
}

