{
  "timeline": [
    {
      "headline": "Beginning of the Cretaceous Period",
      "text": "The Cretaceous Period began approximately 145 million years ago, marking the start of the third and final period of the Mesozoic Era.",
      "date": "-0145000000"
    },
    {
      "headline": "Early Cretaceous Climate",
      "text": "During the Early Cretaceous, the climate was generally warm, with high sea levels and the absence of polar ice caps. This period saw the diversification of dinosaurs and the rise of flowering plants.",
      "date": "-0145000000"
    },
    {
      "headline": "Aptian Stage",
      "text": "The Aptian stage occurred around 125 to 113 million years ago, characterized by significant volcanic activity and the deposition of large chalk deposits.",
      "date": "-0125000000"
    },
    {
      "headline": "Rise of Flowering Plants",
      "text": "Flowering plants (angiosperms) began to diversify and spread during the Early Cretaceous, around 125 million years ago, significantly altering ecosystems.",
      "date": "-0125000000"
    },
    {
      "headline": "Late Cretaceous Climate",
      "text": "The Late Cretaceous, starting around 100 million years ago, was marked by a warm climate, high sea levels, and the proliferation of dinosaurs such as Tyrannosaurus and Triceratops.",
      "date": "-0100000000"
    },
    {
      "headline": "Cenomanian-Turonian Oceanic Anoxic Event",
      "text": "Around 93 million years ago, a major oceanic anoxic event occurred, leading to widespread marine extinctions and the deposition of black shales.",
      "date": "-0093000000"
    },
    {
      "headline": "K-Pg Extinction Event",
      "text": "The Cretaceous-Paleogene (K-Pg) extinction event occurred approximately 66 million years ago, marking the end of the Cretaceous Period and resulting in the extinction of about 75% of Earth's species, including most dinosaurs.",
      "date": "-0066000000"
    },
    {
      "headline": "End of the Cretaceous Period",
      "text": "The Cretaceous Period ended around 66 million years ago, transitioning into the Paleogene Period of the Cenozoic Era.",
      "date": "-0066000000"
    }
  ]
}

