{
  "timeline": [
    {
      "headline": "Pre-European Contact",
      "text": "Before European contact, the Cherokee people lived in the Southeastern Woodlands of the United States. They were concentrated in their homelands, in towns along river valleys of what is now southwestern North Carolina, southeastern Tennessee, southwestern Virginia, edges of western South Carolina, northern Georgia, and northeastern Alabama.",
      "date": "-1500"
    },
    {
      "headline": "First European Contact",
      "text": "The Cherokee first encountered Europeans in 1540 when Spanish explorer Hernando de Soto led an expedition through their territory.",
      "date": "1540"
    },
    {
      "headline": "Cherokee Alliance with the British",
      "text": "During the 18th century, the Cherokee formed an alliance with the British in the hopes of gaining protection from other tribes and European settlers.",
      "date": "1700"
    },
    {
      "headline": "Treaty of Hopewell",
      "text": "In 1785, the Cherokee signed the Treaty of Hopewell, which was intended to establish boundaries between the United States and Cherokee lands.",
      "date": "1785"
    },
    {
      "headline": "Adoption of a Written Constitution",
      "text": "In 1827, the Cherokee Nation adopted a written constitution, modeling it after the United States Constitution, in an effort to assert their sovereignty.",
      "date": "1827"
    },
    {
      "headline": "Trail of Tears",
      "text": "In 1838-1839, the Cherokee were forcibly removed from their ancestral lands in the Southeastern United States and relocated to Indian Territory (present-day Oklahoma) in an event known as the Trail of Tears.",
      "date": "1838"
    },
    {
      "headline": "Establishment of the Cherokee Nation in Indian Territory",
      "text": "Following their removal, the Cherokee established a new government in Indian Territory and rebuilt their society.",
      "date": "1839"
    },
    {
      "headline": "Cherokee Nation v. Georgia",
      "text": "In 1831, the Cherokee Nation sought a federal injunction against laws passed by the state of Georgia depriving them of rights within its boundaries, but the Supreme Court ruled that it had no original jurisdiction in the matter, as the Cherokee Nation was a dependent nation.",
      "date": "1831"
    },
    {
      "headline": "Worcester v. Georgia",
      "text": "In 1832, the U.S. Supreme Court ruled in Worcester v. Georgia that the Cherokee Nation was a distinct community in which the laws of Georgia had no force, establishing the principle of tribal sovereignty.",
      "date": "1832"
    }
  ]
}

