{
  "timeline": [
    {
      "headline": "First European Settlement",
      "text": "In 1614, the first European settlement was established in what is now Albany, New York, by Dutch traders who built Fort Nassau.",
      "date": "1614"
    },
    {
      "headline": "Establishment of Fort Orange",
      "text": "In 1624, the Dutch established Fort Orange, which became a permanent trading post and the foundation for the city of Albany.",
      "date": "1624"
    },
    {
      "headline": "Charter of Beverwijck",
      "text": "In 1652, the settlement around Fort Orange was officially chartered as the village of Beverwijck by the Dutch.",
      "date": "1652"
    },
    {
      "headline": "English Takeover",
      "text": "In 1664, the English took control of the Dutch territories in America, including Beverwijck, and renamed it Albany after the Duke of Albany.",
      "date": "1664"
    },
    {
      "headline": "Albany Receives City Charter",
      "text": "In 1686, Albany was officially chartered as a city by Governor Thomas Dongan, making it one of the oldest surviving European settlements from the original thirteen colonies.",
      "date": "1686"
    },
    {
      "headline": "Albany Congress",
      "text": "In 1754, the Albany Congress was held, where representatives from seven colonies met to discuss better relations with Native American tribes and defense against the French.",
      "date": "1754"
    },
    {
      "headline": "State Capital Designation",
      "text": "In 1797, Albany was designated as the capital of New York State, a status it retains to this day.",
      "date": "1797"
    },
    {
      "headline": "Erie Canal Completion",
      "text": "In 1825, the Erie Canal was completed, connecting the Hudson River at Albany to Lake Erie, significantly boosting trade and transportation.",
      "date": "1825"
    },
    {
      "headline": "Incorporation of the City of Albany",
      "text": "In 1848, the city of Albany was incorporated, further solidifying its status as a major urban center in New York.",
      "date": "1848"
    },
    {
      "headline": "Albany Plan of Union",
      "text": "In 1754, Benjamin Franklin proposed the Albany Plan of Union at the Albany Congress, which was an early attempt to form a union of the colonies.",
      "date": "1754"
    },
    {
      "headline": "Construction of the New York State Capitol",
      "text": "Construction of the New York State Capitol building in Albany began in 1867 and was completed in 1899, becoming a prominent architectural landmark.",
      "date": "1867"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of the House of Stuart",
      "text": "The House of Stuart, originally spelled Stewart, was founded by Walter fitz Alan, who held the office of High Steward of Scotland. The family name comes from this office.",
      "date": "-1100"
    },
    {
      "headline": "First Monarch of the Stewart Line",
      "text": "Robert II became the first monarch of the Stewart line in Scotland in 1371.",
      "date": "1371"
    },
    {
      "headline": "Union of the Crowns",
      "text": "In 1603, James VI of Scotland became James I of England and Ireland, uniting the crowns of Scotland, England, and Ireland under the House of Stuart.",
      "date": "1603"
    },
    {
      "headline": "Reign of Mary, Queen of Scots",
      "text": "Mary, Queen of Scots, reigned over Scotland from 1542 until her forced abdication in 1567. She was brought up in France and adopted the French spelling of the name Stuart.",
      "date": "1542"
    },
    {
      "headline": "Execution of Mary, Queen of Scots",
      "text": "Mary, Queen of Scots, was executed on February 8, 1587, after being implicated in a plot to assassinate Queen Elizabeth I of England.",
      "date": "1587-02-08"
    },
    {
      "headline": "English Civil War",
      "text": "The English Civil War (1642–1651) was a series of armed conflicts and political machinations between Parliamentarians and Royalists, largely over the manner of England's governance and issues of religious freedom. The Royalists supported King Charles I, a Stuart monarch.",
      "date": "1642"
    },
    {
      "headline": "Execution of Charles I",
      "text": "King Charles I was executed on January 30, 1649, following the English Civil War.",
      "date": "1649-01-30"
    },
    {
      "headline": "Restoration of the Monarchy",
      "text": "The monarchy was restored in 1660 with Charles II, son of Charles I, ascending to the throne.",
      "date": "1660"
    },
    {
      "headline": "Glorious Revolution",
      "text": "The Glorious Revolution in 1688 resulted in the overthrow of King James II of England, a Stuart monarch, and the ascension of William III and Mary II to the English throne.",
      "date": "1688"
    },
    {
      "headline": "End of the Stuart Dynasty",
      "text": "The Stuart dynasty ended in 1714 with the death of Queen Anne, after which the throne passed to the House of Hanover.",
      "date": "1714"
    }
  ]
}

