{
  "timeline": [
    {
      "headline": "Development of HTTP",
      "text": "The development of the Hypertext Transfer Protocol (HTTP) began in 1989 when Tim Berners-Lee proposed a new project at CERN to facilitate information sharing among researchers. This led to the creation of the World Wide Web.",
      "date": "1989"
    },
    {
      "headline": "Release of HTTP/0.9",
      "text": "HTTP/0.9, the first version of the protocol, was released in 1991. It was a simple protocol for raw data transfer across the Internet.",
      "date": "1991"
    },
    {
      "headline": "Introduction of HTTP/1.0",
      "text": "HTTP/1.0 was introduced in 1996. This version included metadata in the form of HTTP headers, allowing for more complex interactions.",
      "date": "1996"
    },
    {
      "headline": "Standardization of HTTP/1.1",
      "text": "HTTP/1.1 was standardized in 1997. It brought significant improvements, including persistent connections, chunked transfer encoding, and additional cache control mechanisms.",
      "date": "1997"
    },
    {
      "headline": "Publication of RFC 2616",
      "text": "In June 1999, HTTP/1.1 was further refined and published as RFC 2616 by the Internet Engineering Task Force (IETF).",
      "date": "1999-06"
    },
    {
      "headline": "Introduction of HTTP/2",
      "text": "HTTP/2 was developed to improve performance and was published as RFC 7540 in May 2015. It introduced features like multiplexing, header compression, and server push.",
      "date": "2015-05"
    },
    {
      "headline": "Release of HTTP/3",
      "text": "HTTP/3, based on the QUIC protocol, was published as a proposed standard in June 2022. It aims to reduce latency and improve security.",
      "date": "2022-06"
    }
  ]
}

