{
  "timeline": [
    {
      "headline": "Proto-Turkic Language",
      "text": "Proto-Turkic is the reconstructed common ancestor of the Turkic languages. It is believed to have been spoken in a region of East Asia spanning from Mongolia to Northwest China. The exact date of its existence is not precisely known, but it is thought to have been spoken before the first millennium.",
      "date": "-1000"
    },
    {
      "headline": "Expansion of Turkic Languages",
      "text": "During the first millennium, the Turkic languages began to expand from their original region in East Asia to Central Asia and farther west. This expansion was likely facilitated by the movements of Turkic peoples across Eurasia.",
      "date": "0500"
    },
    {
      "headline": "Old Turkic Script",
      "text": "The Old Turkic script, also known as the Göktürk script, was used by the Göktürks and other early Turkic peoples. The earliest known inscriptions date back to the 8th century.",
      "date": "0700"
    },
    {
      "headline": "Karakhanid Language",
      "text": "The Karakhanid language, a member of the Turkic language family, was used in the Karakhanid Khanate, which existed from the 9th to the 13th century. It is one of the earliest recorded Turkic languages.",
      "date": "0900"
    },
    {
      "headline": "Codex Cumanicus",
      "text": "The Codex Cumanicus is a linguistic manual of the Cuman language, a Turkic language, compiled in the late 13th century. It serves as an important source for the study of Turkic languages during this period.",
      "date": "1294"
    },
    {
      "headline": "Chagatai Language",
      "text": "The Chagatai language, a member of the Turkic language family, was widely used in Central Asia from the 15th to the early 20th century. It served as a literary language for many Turkic peoples.",
      "date": "1400"
    },
    {
      "headline": "Modern Turkic Languages",
      "text": "Today, the Turkic languages are spoken by Turkic peoples across a vast region from Eastern Europe and Southern Europe to Central Asia, East Asia, North Asia (Siberia), and West Asia. There are more than 35 documented Turkic languages.",
      "date": "2023"
    }
  ]
}

