{
  "timeline": [
    {
      "headline": "Congress of Vienna",
      "text": "The Congress of Vienna in 1815 established a new political order in Europe after the defeat of Napoleon. It restored many of the old regimes and divided the Italian peninsula into several states.",
      "date": "1815"
    },
    {
      "headline": "Rebellions Inspired by Congress of Vienna",
      "text": "In the 1820s and 1830s, various rebellions occurred across the Italian peninsula, inspired by dissatisfaction with the outcomes of the Congress of Vienna.",
      "date": "1820"
    },
    {
      "headline": "Revolutions of 1848",
      "text": "The Revolutions of 1848 were a series of political upheavals throughout Europe. In Italy, they were a catalyst for the unification movement, leading to increased nationalist sentiment.",
      "date": "1848"
    },
    {
      "headline": "First Italian War of Independence",
      "text": "The First Italian War of Independence was fought between the Kingdom of Sardinia and the Austrian Empire from 1848 to 1849. It was an early attempt to unify Italy, although it ended in failure.",
      "date": "1848"
    },
    {
      "headline": "Second Italian War of Independence",
      "text": "The Second Italian War of Independence in 1859 was a conflict between the Kingdom of Sardinia, allied with France, and the Austrian Empire. It resulted in the annexation of Lombardy to Sardinia.",
      "date": "1859"
    },
    {
      "headline": "Expedition of the Thousand",
      "text": "In 1860, Giuseppe Garibaldi led the Expedition of the Thousand, a campaign to conquer the Kingdom of the Two Sicilies. This was a significant step towards unification.",
      "date": "1860"
    },
    {
      "headline": "Proclamation of the Kingdom of Italy",
      "text": "On March 17, 1861, the Kingdom of Italy was officially proclaimed, with Victor Emmanuel II as its first king. This marked a major milestone in the unification process.",
      "date": "1861-03-17"
    },
    {
      "headline": "Third Italian War of Independence",
      "text": "The Third Italian War of Independence in 1866 was fought between the Kingdom of Italy and the Austrian Empire. It resulted in the annexation of Venetia to Italy.",
      "date": "1866"
    },
    {
      "headline": "Capture of Rome",
      "text": "On September 20, 1870, Italian troops captured Rome, which was then part of the Papal States. This event marked the final act of the unification of Italy.",
      "date": "1870-09-20"
    },
    {
      "headline": "Rome Becomes Capital of Italy",
      "text": "In 1871, Rome was declared the capital of the Kingdom of Italy, completing the unification process.",
      "date": "1871"
    }
  ]
}

