{
  "timeline": [
    {
      "headline": "Roman Era",
      "text": "Trieste became a Roman colony in 33 BCE, known as Tergeste.",
      "date": "-0033"
    },
    {
      "headline": "Middle Ages",
      "text": "In the 9th century, Trieste became part of the Frankish Empire.",
      "date": "0800"
    },
    {
      "headline": "Habsburg Rule",
      "text": "In 1382, Trieste placed itself under the protection of the Habsburgs, becoming part of the Holy Roman Empire.",
      "date": "1382"
    },
    {
      "headline": "Free Port Status",
      "text": "In 1719, Charles VI declared Trieste a free port, significantly boosting its economic development.",
      "date": "1719"
    },
    {
      "headline": "Napoleonic Wars",
      "text": "Trieste was occupied by French troops in 1809 and became part of the Illyrian Provinces.",
      "date": "1809"
    },
    {
      "headline": "Return to Austrian Control",
      "text": "After the Congress of Vienna in 1815, Trieste was returned to Austrian control.",
      "date": "1815"
    },
    {
      "headline": "Annexation to Italy",
      "text": "Following World War I, Trieste was annexed to Italy in 1920 under the Treaty of Rapallo.",
      "date": "1920"
    },
    {
      "headline": "World War II and Aftermath",
      "text": "During World War II, Trieste was occupied by German forces in 1943 and later liberated by Yugoslav Partisans in 1945.",
      "date": "1943"
    },
    {
      "headline": "Free Territory of Trieste",
      "text": "In 1947, the Free Territory of Trieste was established, divided into two zones, with Zone A administered by the Allies and Zone B by Yugoslavia.",
      "date": "1947"
    },
    {
      "headline": "Return to Italy",
      "text": "In 1954, the London Memorandum returned Zone A, including Trieste, to Italian administration.",
      "date": "1954"
    },
    {
      "headline": "Official Annexation",
      "text": "The Treaty of Osimo in 1975 officially annexed Trieste to Italy, resolving territorial disputes with Yugoslavia.",
      "date": "1975"
    }
  ]
}

