    {
      "headline": "Foundation of the City of Rhodes",
      "text": "The city of Rhodes was founded in 408 BCE. It was designed by the architect Hippodamus of Miletus, known for his grid plan.",
      "date": "-0408"
    },
    {
      "headline": "Construction of the Colossus of Rhodes",
      "text": "The Colossus of Rhodes, one of the Seven Wonders of the Ancient World, was constructed between 292 and 280 BCE. It was a statue of the sun god Helios, erected to celebrate Rhodes' victory over Cyprus.",
      "date": "-0280"
    },
    {
      "headline": "Destruction of the Colossus of Rhodes",
      "text": "In 226 BCE, the Colossus of Rhodes was destroyed by an earthquake. The statue broke at the knees and fell over onto the land.",
      "date": "-0226"
    },
    {
      "headline": "Rhodes under Roman Control",
      "text": "In 164 BCE, Rhodes became a Roman ally and later a part of the Roman Empire. The island retained a degree of autonomy and continued to be a center of commerce and culture.",
      "date": "-0164"
    },
    {
      "headline": "Byzantine Period",
      "text": "After the division of the Roman Empire in 395 CE, Rhodes became part of the Byzantine Empire. It remained under Byzantine control for several centuries.",
      "date": "0395"
    },
    {
      "headline": "Conquest by the Knights of Saint John",
      "text": "In 1309, the Knights of Saint John of Jerusalem conquered Rhodes. They fortified the city and ruled the island until 1522.",
      "date": "1309"
    },
    {
      "headline": "Ottoman Conquest",
      "text": "In 1522, after a long siege, the Ottoman Empire captured Rhodes. The Knights of Saint John were forced to leave the island.",
      "date": "1522"
    },
    {
      "headline": "Italian Rule",
      "text": "In 1912, during the Italo-Turkish War, Italy seized Rhodes from the Ottoman Empire. The island remained under Italian control until World War II.",
      "date": "1912"
    },
    {
      "headline": "Incorporation into Greece",
      "text": "After World War II, in 1947, Rhodes was formally integrated into Greece as part of the Dodecanese islands.",
      "date": "1947"
    }
  ]
}

