{
  "timeline": [
    {
      "headline": "Appointment of General Mikhail Kutuzov",
      "text": "On 29 August [O.S. 17 August] 1812, General Mikhail Kutuzov was appointed by Emperor Alexander I of Russia to replace Barclay de Tolly after the Battle of Smolensk.",
      "date": "1812-08-29"
    },
    {
      "headline": "Battle of Borodino",
      "text": "The Battle of Borodino took place on 7 September [O.S. 26 August] 1812 near the village of Borodino during Napoleon's invasion of Russia. The Grande Armée won the battle against the Imperial Russian Army but failed to gain a decisive victory and suffered tremendous losses.",
      "date": "1812-09-07"
    },
    {
      "headline": "Russian Retreat",
      "text": "After the Battle of Borodino, the Imperial Russian forces retreated in an orderly fashion southwards, allowing the French occupation of Moscow.",
      "date": "1812-09"
    },
    {
      "headline": "French Occupation of Moscow",
      "text": "Following the Battle of Borodino, the French occupied Moscow. The Imperial Russian army used scorched earth tactics to trap Napoleon and his men in the city.",
      "date": "1812-09"
    },
    {
      "headline": "Criticism of Napoleon's Strategy",
      "text": "Napoleon's reluctance to deploy his Imperial Guard and his desire to negotiate with Alexander I to join against the British were widely criticized as a strategic blunder, allowing the Imperial Russian army to continue its retreat.",
      "date": "1812-09"
    }
  ]
}

