    },
    {
      "headline": "Completion of Mullaperiyar Dam",
      "text": "The Mullaperiyar Dam was completed in 1895. It is a masonry gravity dam on the Periyar River, located in the Idukki district of Kerala, India.",
      "date": "1895"
    },
    {
      "headline": "Water Level Reaches 142 Feet",
      "text": "On 21 November 2014, the water level of the Mullaperiyar Dam hit 142 feet for the first time in 35 years.",
      "date": "2014-11-21"
    },
    {
      "headline": "Water Level Reaches Maximum Limit Again",
      "text": "On 15 August 2018, following incessant rains in Kerala, the reservoir of the Mullaperiyar Dam again hit the maximum limit of 142 feet.",
      "date": "2018-08-15"
    },
    {
      "headline": "UNU-INWEH Report on Ageing Dams",
      "text": "In 2021, a UNU-INWEH report highlighted that the Mullaperiyar Dam is situated in a seismically active area with significant structural flaws, posing a risk to 3.5 million people if the dam were to fail.",
      "date": "2021"
    }
  ]
}

