{
  "timeline": [
    {
      "headline": "Hero's Aeolipile",
      "text": "Around 10-70 AD, Hero of Alexandria described the aeolipile, a simple steam-powered device, in his work Pneumatica. It is considered one of the earliest known steam engines.",
      "date": "-0060"
    },
    {
      "headline": "Thomas Savery's Steam Pump",
      "text": "In 1698, Thomas Savery patented a steam-powered pump, which was used to remove water from mines. It was one of the first practical applications of steam power.",
      "date": "1698"
    },
    {
      "headline": "Newcomen Atmospheric Engine",
      "text": "In 1712, Thomas Newcomen developed the atmospheric engine, which improved upon Savery's design and became widely used for pumping water out of mines.",
      "date": "1712"
    },
    {
      "headline": "James Watt's Improvements",
      "text": "In 1765, James Watt made significant improvements to the steam engine, including the separate condenser, which greatly increased efficiency.",
      "date": "1765"
    },
    {
      "headline": "Watt's Patent",
      "text": "In 1769, James Watt patented his improved steam engine design, which laid the foundation for the Industrial Revolution.",
      "date": "1769"
    },
    {
      "headline": "First Commercial Steam Engine",
      "text": "In 1776, the first commercial steam engine built by James Watt and Matthew Boulton was installed, marking the beginning of widespread industrial use.",
      "date": "1776"
    },
    {
      "headline": "High-Pressure Steam Engines",
      "text": "In the early 1800s, Richard Trevithick and Oliver Evans developed high-pressure steam engines, which were more powerful and efficient than previous designs.",
      "date": "1800"
    },
    {
      "headline": "Steam Locomotive Invention",
      "text": "In 1804, Richard Trevithick built the first full-scale working railway steam locomotive.",
      "date": "1804"
    },
    {
      "headline": "Stephenson's Rocket",
      "text": "In 1829, George Stephenson's Rocket won the Rainhill Trials, demonstrating the potential of steam locomotives for railway transport.",
      "date": "1829"
    },
    {
      "headline": "Steam Turbine Development",
      "text": "In 1884, Charles Parsons invented the steam turbine, which would eventually replace reciprocating steam engines in many applications.",
      "date": "1884"
    }
  ]
}

