    },
    {
      "headline": "Introduction of Markov Chains",
      "text": "In 1906, Andrey Markov introduced the concept of Markov chains, a stochastic process that describes a sequence of possible events where the probability of each event depends only on the state attained in the previous event.",
      "date": "1906"
    },
    {
      "headline": "Publication of Markov's Paper",
      "text": "In 1907, Andrey Markov published a paper that laid the foundation for the theory of Markov chains, demonstrating their application in probability theory.",
      "date": "1907"
    },
    {
      "headline": "Development of Continuous-Time Markov Chains",
      "text": "In the 1930s, the concept of continuous-time Markov chains (CTMC) was developed, expanding the application of Markov processes to continuous time.",
      "date": "1930"
    },
    {
      "headline": "Death of Andrey Markov",
      "text": "Andrey Markov passed away on July 20, 1922, leaving behind a significant legacy in the field of probability theory and statistics.",
      "date": "1922-07-20"
    }
  ]
}

