{
  "timeline": [
    {
      "headline": "Creation of the Thousand Character Classic",
      "text": "The Thousand Character Classic was created during the Liang Dynasty (502–557 AD) by Zhou Xingsi. It was commissioned by Emperor Wu of Liang to teach his son, the crown prince, how to read and write.",
      "date": "0502"
    },
    {
      "headline": "Compilation and Arrangement",
      "text": "Zhou Xingsi compiled and arranged the Thousand Character Classic using exactly one thousand unique Chinese characters, each used only once, into 250 lines of four characters each.",
      "date": "0502"
    },
    {
      "headline": "Adoption as Educational Primer",
      "text": "The Thousand Character Classic became widely adopted as a primer for teaching Chinese characters to children, forming a fundamental part of traditional literacy training in the Sinosphere.",
      "date": "0502"
    },
    {
      "headline": "Integration with Other Educational Texts",
