    {
      "headline": "Discussion of Quantum Entanglement",
      "text": "In 1935, Schrödinger coined the term 'quantum entanglement' and discussed its implications in quantum mechanics.",
      "date": "1935"
    },
    {
      "headline": "Move to Ireland",
      "text": "In 1939, Schrödinger moved to Ireland to escape the political climate in Austria and took a position at the Dublin Institute for Advanced Studies.",
      "date": "1939"
    },
    {
      "headline": "Publication of 'What is Life?'",
      "text": "In 1944, Schrödinger published his influential book 'What is Life?', which explored the relationship between quantum physics and genetics.",
      "date": "1944"
    },
    {
      "headline": "Return to Vienna",
      "text": "In 1956, Schrödinger returned to Vienna, where he spent the remainder of his career.",
      "date": "1956"
    },
    {
      "headline": "Death of Erwin Schrödinger",
      "text": "Erwin Schrödinger passed away on January 4, 1961, in Vienna, Austria.",
      "date": "1961-01-04"
    }
  ]
}

