      "headline": "Origin of the House of Hanover",
      "text": "The House of Hanover originated as a cadet branch of the House of Welf in 1635, also known then as the House of Brunswick-Lüneburg.",
      "date": "1635"
    },
    {
      "headline": "Elevation to Electorate",
      "text": "In 1692, Hanover was elevated to an Electorate, increasing its political significance within the Holy Roman Empire.",
      "date": "1692"
    },
    {
      "headline": "George I becomes King of Great Britain and Ireland",
      "text": "In 1714, George I, prince-elector of Hanover and a descendant of King James VI and I, assumed the throne of Great Britain and Ireland, marking the beginning of Hanoverian rule over the British Empire.",
      "date": "1714"
    },
    {
      "headline": "End of Hanoverian Rule in the United Kingdom",
      "text": "With Queen Victoria's death in 1901, the throne of the United Kingdom passed to her eldest son Edward VII, a member of the House of Saxe-Coburg and Gotha, through his father Albert, Prince Consort.",
      "date": "1901"
    },
    {
      "headline": "Loss of the Duchy of Brunswick",
      "text": "The last reigning members of the House of Hanover lost the Duchy of Brunswick in 1918 when Germany became a republic and abolished royalty and nobility.",
      "date": "1918"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Enactment of Title IX",
      "text": "Title IX was enacted as part of the Education Amendments of 1972, signed into law by President Richard Nixon on June 23, 1972. It prohibits sex-based discrimination in any school or any other education program that receives funding from the federal government.",
      "date": "1972-06-23"
    },
    {
      "headline": "Title IX Regulations Issued",
      "text": "The U.S. Department of Health, Education, and Welfare issued regulations for Title IX on June 4, 1975, providing guidelines for compliance with the law.",
      "date": "1975-06-04"
    },
    {
      "headline": "Grove City College v. Bell",
      "text": "In 1984, the Supreme Court ruled in Grove City College v. Bell that Title IX applied only to specific programs receiving federal funds, not entire institutions.",
      "date": "1984"
    },
    {
      "headline": "Civil Rights Restoration Act",
      "text": "In 1988, Congress passed the Civil Rights Restoration Act, which overturned the Grove City College v. Bell decision, mandating that Title IX applies to entire institutions if any part receives federal funding.",
      "date": "1988"
    },
    {
      "headline": "Clarification on Athletics",
      "text": "In 1996, the Department of Education issued a clarification on Title IX, emphasizing that schools must provide equal athletic opportunities for both sexes.",
      "date": "1996"
    },
    {
      "headline": "Dear Colleague Letter",
      "text": "On April 4, 2011, the Department of Education's Office for Civil Rights issued a 'Dear Colleague' letter, providing guidance on how schools should handle sexual violence and harassment under Title IX.",
      "date": "2011-04-04"
    },
    {
      "headline": "Title IX Regulations on Sexual Misconduct",
      "text": "In May 2020, the Department of Education under Secretary Betsy DeVos issued new Title IX regulations, which included changes to how schools must handle cases of sexual misconduct.",
      "date": "2020-05"
    }
  ]
}

