    },
    {
      "headline": "End of Presidential Term",
      "text": "Batista's term as elected president ended on October 10, 1944, after which he left Cuba for the United States.",
      "date": "1944-10-10"
    },
    {
      "headline": "Coup d'état",
      "text": "On March 10, 1952, Batista led a successful coup d'état, overthrowing President Carlos Prío Socarrás and seizing power as a military dictator.",
      "date": "1952-03-10"
    },
    {
      "headline": "Cuban Revolution",
      "text": "The Cuban Revolution, led by Fidel Castro, began in 1953 and culminated in Batista's overthrow on January 1, 1959.",
      "date": "1959-01-01"
    },
    {
      "headline": "Exile and Death",
      "text": "After being overthrown, Batista fled to the Dominican Republic and later settled in Portugal, where he died on August 6, 1973.",
      "date": "1973-08-06"
