      "date": "-0060"
    },
    {
      "headline": "Second Consulship",
      "text": "Crassus served as consul for the second time in 55 BC, again with Pompey.",
      "date": "-0055"
    },
    {
      "headline": "Campaign in Parthia",
      "text": "In 53 BC, Crassus led a military campaign against the Parthian Empire, seeking military glory and wealth.",
      "date": "-0053"
    },
    {
      "headline": "Battle of Carrhae and Death",
      "text": "Crassus was defeated and killed at the Battle of Carrhae in 53 BC, marking a significant loss for Rome against the Parthians.",
      "date": "-0053"
    }
  ]
}

