{
  "timeline": [
    {
      "headline": "Early Insurance Practices",
      "text": "The earliest known insurance practices date back to the 3rd millennium BCE in China and Babylon, where merchants would redistribute their goods across multiple vessels to limit loss due to shipwreck.",
      "date": "-3000"
    },
    {
      "headline": "Code of Hammurabi",
      "text": "Around 1750 BCE, the Code of Hammurabi in Babylon included a form of insurance where a debtor did not have to repay a loan if personal misfortune made it impossible.",
      "date": "-1750"
    },
    {
      "headline": "Greek and Roman Insurance",
      "text": "In the 4th century BCE, the Greeks and Romans introduced the concept of 'benevolent societies' that provided financial support to families of deceased members.",
      "date": "-0400"
    },
    {
      "headline": "Medieval Guilds",
      "text": "During the Middle Ages, guilds in Europe provided insurance-like benefits to their members, including support in times of illness or death.",
      "date": "1000"
    },
    {
      "headline": "Lloyd's of London",
      "text": "In 1688, Lloyd's of London was established as a coffee house where merchants, ship owners, and underwriters met to discuss and arrange marine insurance.",
      "date": "1688"
    },
    {
      "headline": "First Life Insurance Company",
      "text": "The Amicable Society for a Perpetual Assurance Office, the world's first life insurance company, was founded in London in 1706.",
      "date": "1706"
    },
    {
      "headline": "Fire Insurance in the United States",
      "text": "In 1752, Benjamin Franklin helped to establish the Philadelphia Contributionship, the first mutual fire insurance company in the United States.",
      "date": "1752"
    },
    {
      "headline": "Modern Insurance Regulation",
      "text": "The first modern insurance regulatory law was passed in New Hampshire in 1851, establishing a state insurance commissioner to oversee insurance practices.",
      "date": "1851"
    },
    {
      "headline": "Social Insurance Programs",
      "text": "In 1889, Germany introduced the first social insurance program, providing health, accident, and old-age insurance to workers.",
      "date": "1889"
    },
    {
      "headline": "National Health Insurance",
      "text": "In 1911, the United Kingdom introduced the National Insurance Act, which provided health insurance for workers.",
      "date": "1911"
    },
    {
      "headline": "Formation of the FDIC",
      "text": "The Federal Deposit Insurance Corporation (FDIC) was created in 1933 in the United States to insure bank deposits and restore trust in the American banking system during the Great Depression.",
      "date": "1933"
    },
    {
      "headline": "Introduction of Medicare and Medicaid",
      "text": "In 1965, the United States introduced Medicare and Medicaid, providing health insurance to the elderly and low-income individuals.",
      "date": "1965"
    },
    {
      "headline": "Affordable Care Act",
      "text": "The Affordable Care Act, aimed at expanding health insurance coverage in the United States, was signed into law in 2010.",
      "date": "2010"
    }
  ]
}

