{
  "timeline": [
    {
      "headline": "Composition of the Deuterocanonical Books",
      "text": "The Deuterocanonical books were composed over a period of time, primarily between the 3rd century BCE and the 1st century CE. These books include Tobit, Judith, Wisdom, Sirach, Baruch, and 1 and 2 Maccabees, among others.",
      "date": "-0300"
    },
    {
      "headline": "Inclusion in the Septuagint",
      "text": "The Deuterocanonical books were included in the Septuagint, the Greek translation of the Hebrew Bible, which was completed by the 2nd century BCE.",
      "date": "-0200"
    },
    {
      "headline": "Council of Rome",
      "text": "In 382 CE, the Council of Rome, under Pope Damasus I, affirmed the inclusion of the Deuterocanonical books in the canon of Scripture.",
      "date": "0382"
    },
    {
      "headline": "Council of Hippo",
      "text": "The Council of Hippo in 393 CE confirmed the canon of the Bible, including the Deuterocanonical books.",
      "date": "0393"
    },
    {
      "headline": "Council of Carthage",
      "text": "In 397 CE, the Council of Carthage reaffirmed the inclusion of the Deuterocanonical books in the Christian biblical canon.",
      "date": "0397"
    },
    {
      "headline": "Council of Florence",
      "text": "The Council of Florence (1431-1449) reaffirmed the inclusion of the Deuterocanonical books in the canon of the Catholic Church.",
      "date": "1431"
    },
    {
      "headline": "Council of Trent",
      "text": "In 1546, the Council of Trent officially declared the Deuterocanonical books as part of the canon of the Catholic Church, in response to the Protestant Reformation.",
      "date": "1546"
    },
    {
      "headline": "Rejection by Protestant Reformers",
      "text": "During the 16th century, Protestant reformers, including Martin Luther, rejected the Deuterocanonical books as part of the biblical canon, referring to them as 'Apocrypha'.",
      "date": "1500"
    }
  ]
