{
  "timeline": [
    {
      "headline": "First Launch of Saturn V",
      "text": "The first launch of the Saturn V rocket, known as Apollo 4, took place on November 9, 1967. This was an uncrewed test flight to demonstrate the capabilities of the rocket.",
      "date": "1967-11-09"
    },
    {
      "headline": "First Crewed Launch - Apollo 8",
      "text": "Apollo 8, the first crewed mission to use the Saturn V, launched on December 21, 1968. It was the first human spaceflight to leave Earth's orbit, reach the Moon, orbit it, and return safely to Earth.",
      "date": "1968-12-21"
    },
    {
      "headline": "Apollo 11 - First Moon Landing",
      "text": "On July 16, 1969, the Saturn V launched Apollo 11, which carried astronauts Neil Armstrong, Buzz Aldrin, and Michael Collins. This mission resulted in the first human landing on the Moon on July 20, 1969.",
      "date": "1969-07-16"
    },
    {
      "headline": "Apollo 12 Mission",
      "text": "Apollo 12, the sixth crewed flight in the Apollo program and the second to land on the Moon, was launched on November 14, 1969, using the Saturn V.",
      "date": "1969-11-14"
    },
    {
      "headline": "Apollo 13 Launch",
      "text": "The Saturn V launched Apollo 13 on April 11, 1970. Although the mission did not land on the Moon due to an in-flight technical failure, it is famous for the successful return of its crew.",
      "date": "1970-04-11"
    },
    {
      "headline": "Apollo 14 Mission",
      "text": "Apollo 14 was launched on January 31, 1971, with the Saturn V, marking the third successful Moon landing mission.",
      "date": "1971-01-31"
    },
    {
      "headline": "Apollo 15 Mission",
      "text": "Apollo 15, launched on July 26, 1971, was the fourth mission to land on the Moon and the first to use the Lunar Roving Vehicle.",
      "date": "1971-07-26"
    },
    {
      "headline": "Apollo 16 Mission",
      "text": "The Saturn V launched Apollo 16 on April 16, 1972. This mission was the fifth to land on the Moon.",
      "date": "1972-04-16"
    },
    {
      "headline": "Apollo 17 - Final Moon Landing",
      "text": "Apollo 17, launched on December 7, 1972, was the last Apollo mission to land humans on the Moon, marking the end of the Apollo lunar missions.",
      "date": "1972-12-07"
    },
    {
      "headline": "Launch of Skylab",
      "text": "On May 14, 1973, the Saturn V launched Skylab, the first American space station, into orbit. This was the final launch of the Saturn V rocket.",
      "date": "1973-05-14"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Initial Proposal of HSTS",
      "text": "The concept of HTTP Strict Transport Security (HSTS) was initially proposed by Jeff Hodges, Collin Jackson, and Adam Barth in 2010 as a way to enhance web security by enforcing the use of HTTPS connections.",
      "date": "2010"
    },
    {
      "headline": "Publication of RFC 6797",
      "text": "HSTS was officially specified as an IETF standards track protocol in RFC 6797, which was published in November 2012. This document outlines the implementation and functioning of HSTS to protect websites from certain types of attacks.",
      "date": "2012-11"
    },
    {
      "headline": "Adoption by Major Browsers",
      "text": "By 2014, major web browsers such as Google Chrome, Mozilla Firefox, and Internet Explorer had implemented support for HSTS, allowing websites to declare that browsers should only interact with them using secure HTTPS connections.",
      "date": "2014"
    },
    {
      "headline": "HSTS Preloading",
      "text": "The concept of HSTS preloading was introduced, allowing websites to be included in a list maintained by browser vendors that enforces HSTS even before the first connection. This further enhances security by preventing initial connection vulnerabilities.",
      "date": "2015"
    }
  ]
}

