{
  "timeline": [
    {
      "headline": "Inception of Databases",
      "text": "The concept of databases began to take shape in the 1960s with the development of the first database management systems.",
      "date": "1960"
    },
    {
      "headline": "Introduction of Hierarchical Database Model",
      "text": "In 1968, IBM introduced the Information Management System (IMS), which was based on the hierarchical database model.",
      "date": "1968"
    },
    {
      "headline": "Network Database Model",
      "text": "The Conference on Data Systems Languages (CODASYL) developed the network database model in the late 1960s, which was standardized in 1971.",
      "date": "1971"
    },
    {
      "headline": "Relational Database Model",
      "text": "Edgar F. Codd proposed the relational database model in a seminal paper published in 1970, which laid the foundation for relational databases.",
      "date": "1970"
    },
    {
      "headline": "Development of SQL",
      "text": "Structured Query Language (SQL) was developed in the early 1970s at IBM by Donald D. Chamberlin and Raymond F. Boyce.",
      "date": "1970"
    },
    {
      "headline": "Oracle Corporation Founded",
      "text": "In 1977, Larry Ellison, Bob Miner, and Ed Oates founded Oracle Corporation, which became a major player in the database industry.",
      "date": "1977"
    },
    {
      "headline": "Introduction of Object-Oriented Databases",
      "text": "In the 1980s, object-oriented databases emerged, integrating object-oriented programming with database technology.",
      "date": "1980"
    },
    {
      "headline": "NoSQL Databases",
      "text": "The term NoSQL was coined in the early 2000s to describe databases that diverged from traditional relational database structures, focusing on scalability and flexibility.",
      "date": "2000"
    },
    {
      "headline": "Introduction of NewSQL",
      "text": "Around 2010, NewSQL databases emerged, aiming to provide the scalability of NoSQL systems while maintaining the ACID properties of traditional databases.",
      "date": "2010"
    }
  ]
}

