{
  "timeline": [
    {
      "headline": "Invention of the MOSFET",
      "text": "The metal–oxide–semiconductor field-effect transistor (MOSFET) was invented by Mohamed M. Atalla and Dawon Kahng at Bell Labs in 1959. This invention marked a significant advancement in semiconductor technology.",
      "date": "1959"
    },
    {
      "headline": "First Working MOSFET",
      "text": "The first working MOSFET was demonstrated by Mohamed M. Atalla and Dawon Kahng in 1960. This demonstration showed the potential of MOSFETs in electronic circuits.",
      "date": "1960"
    },
    {
      "headline": "MOSFET Commercialization",
      "text": "The commercialization of MOSFET technology began in the 1960s, leading to its widespread use in electronic devices.",
      "date": "1960s"
    },
    {
      "headline": "Introduction of CMOS Technology",
      "text": "Complementary MOS (CMOS) technology, which uses both p-type and n-type MOSFETs, was developed in the 1960s. CMOS technology became the standard for digital integrated circuits.",
      "date": "1960s"
    },
    {
      "headline": "MOSFET in Integrated Circuits",
      "text": "By the 1970s, MOSFETs had become the most common type of transistor in integrated circuits, due to their efficiency and scalability.",
      "date": "1970s"
    },
    {
      "headline": "Scaling of MOSFETs",
      "text": "Throughout the 1980s and 1990s, MOSFETs were continually scaled down in size, leading to increased performance and lower power consumption in electronic devices.",
      "date": "1980s-1990s"
    },
    {
      "headline": "Advancements in MOSFET Technology",
      "text": "In the 2000s, advancements in MOSFET technology continued, with the development of high-k dielectrics and metal gates to further improve performance.",
      "date": "2000s"
    },
    {
      "headline": "MOSFETs in Modern Electronics",
      "text": "Today, MOSFETs are a fundamental component in modern electronics, used in everything from microprocessors to power management systems.",
      "date": "2023"
    }
  ]
}

{
  "timeline": [
