    },
    {
      "headline": "Disquisitiones Arithmeticae Published",
      "text": "In 1801, Gauss published 'Disquisitiones Arithmeticae', a landmark work in the field of number theory.",
      "date": "1801"
    },
    {
      "headline": "Predicts Orbit of Ceres",
      "text": "Gauss successfully predicted the orbit of the dwarf planet Ceres in 1801, after it was lost following its discovery.",
      "date": "1801"
