      "headline": "Arrival of Missionaries",
      "text": "In 1830, John Williams, a missionary from the London Missionary Society, arrived in Samoa, marking the beginning of significant European influence.",
      "date": "1830"
    },
    {
      "headline": "Partition of the Samoan Islands",
      "text": "In 1899, the Tripartite Convention divided the Samoan Islands between Germany and the United States, with Germany taking control of Western Samoa and the United States taking control of Eastern Samoa.",
      "date": "1899"
    },
    {
      "headline": "New Zealand Administration",
      "text": "Following World War I, Western Samoa was placed under New Zealand administration as a League of Nations mandate in 1914.",
      "date": "1914"
    },
    {
      "headline": "Independence of Western Samoa",
      "text": "Western Samoa became the first Pacific Island nation to gain independence on January 1, 1962.",
      "date": "1962-01-01"
    },
    {
      "headline": "American Samoa's Political Status",
      "text": "In 1977, American Samoa's political status was solidified as an unincorporated territory of the United States, allowing for self-governance under a locally elected governor.",
      "date": "1977"
    }
  ]
