{
  "timeline": [
    {
      "headline": "Identification of Phytophthora infestans",
      "text": "Phytophthora infestans was first identified as the cause of late blight in the mid-19th century. This organism is responsible for the devastating potato blight that led to the Irish Potato Famine.",
      "date": "1840"
    },
    {
      "headline": "Irish Potato Famine",
      "text": "The Irish Potato Famine, caused by Phytophthora infestans, occurred between 1845 and 1852. It led to the death of approximately one million people and caused mass emigration from Ireland.",
      "date": "1845"
    },
    {
      "headline": "Highland Potato Famine",
      "text": "The Highland Potato Famine in Scotland, also caused by Phytophthora infestans, occurred in 1846. It resulted in severe food shortages and hardship.",
      "date": "1846"
    },
    {
      "headline": "Spread to Europe",
      "text": "Phytophthora infestans spread across Europe in the 1840s, causing widespread crop failures and contributing to food shortages.",
      "date": "1840"
    },
    {
      "headline": "Scientific Advances in Understanding",
      "text": "Throughout the 20th century, scientific research advanced the understanding of Phytophthora infestans, including its lifecycle, environmental conditions favoring its spread, and methods for controlling its impact on crops.",
      "date": "1900"
    }
  ]
}

{
  "timeline": [
