  "timeline": [
    {
      "headline": "Murders of Aarushi Talwar and Hemraj Banjade",
      "text": "On the night of 15–16 May 2008, 13-year-old Aarushi Talwar and 45-year-old Hemraj Banjade were murdered at Aarushi's home in Noida, India.",
      "date": "2008-05-15"
    },
    {
      "headline": "Discovery of Aarushi's Body",
      "text": "On 16 May 2008, Aarushi Talwar's body was discovered in her bedroom by her parents.",
      "date": "2008-05-16"
    },
    {
      "headline": "Discovery of Hemraj's Body",
      "text": "On 17 May 2008, Hemraj Banjade's body was discovered on the terrace of the Talwar residence.",
      "date": "2008-05-17"
    },
    {
      "headline": "Initial Investigation and Media Coverage",
      "text": "The case received sensational media coverage, with various theories and allegations being made against Aarushi and the suspects.",
      "date": "2008-05"
    },
    {
      "headline": "Arrest of Rajesh Talwar",
      "text": "On 23 May 2008, Aarushi's father, Rajesh Talwar, was arrested by the police as a suspect in the murders.",
      "date": "2008-05-23"
    },
    {
      "headline": "Release of Rajesh Talwar",
      "text": "Rajesh Talwar was released on bail on 11 July 2008 due to lack of evidence.",
      "date": "2008-07-11"
    },
    {
      "headline": "CBI Takes Over the Case",
      "text": "The Central Bureau of Investigation (CBI) took over the investigation from the local police on 1 June 2008.",
      "date": "2008-06-01"
    },
    {
      "headline": "Closure Report Filed by CBI",
      "text": "On 29 December 2010, the CBI filed a closure report, citing insufficient evidence to charge anyone with the murders.",
      "date": "2010-12-29"
    },
    {
      "headline": "Court Orders Trial",
      "text": "On 9 February 2011, a special CBI court rejected the closure report and ordered the trial of Rajesh and Nupur Talwar.",
      "date": "2011-02-09"
    },
    {
      "headline": "Conviction of Rajesh and Nupur Talwar",
      "text": "On 25 November 2013, Rajesh and Nupur Talwar were convicted of the murders and sentenced to life imprisonment.",
      "date": "2013-11-25"
    },
    {
      "headline": "Acquittal by Allahabad High Court",
      "text": "On 12 October 2017, the Allahabad High Court acquitted Rajesh and Nupur Talwar, citing lack of evidence.",
      "date": "2017-10-12"
    }
  ]
}

