    {
      "headline": "Earliest Inhabitants",
      "text": "Corfu was inhabited by the Phaeacians, a mythical people mentioned in Homer's Odyssey.",
      "date": "-1200"
    },
    {
      "headline": "Corinthian Colonization",
      "text": "In 734 BC, Corfu was colonized by settlers from Corinth, marking the beginning of its historical record.",
      "date": "-0734"
    },
    {
      "headline": "Battle of Sybota",
      "text": "In 433 BC, Corfu was involved in the Battle of Sybota against Corinth, which was one of the catalysts for the Peloponnesian War.",
      "date": "-0433"
    },
    {
      "headline": "Roman Conquest",
      "text": "In 229 BC, Corfu came under Roman control after the Illyrian Wars.",
      "date": "-0229"
    },
    {
      "headline": "Byzantine Era",
      "text": "Following the division of the Roman Empire in 395 AD, Corfu became part of the Eastern Roman Empire, also known as the Byzantine Empire.",
      "date": "0395"
    },
    {
      "headline": "Venetian Rule",
      "text": "In 1386, Corfu came under the control of the Republic of Venice, which lasted until 1797.",
      "date": "1386"
    },
    {
      "headline": "French Occupation",
      "text": "In 1797, Corfu was occupied by French forces following the Treaty of Campo Formio.",
      "date": "1797"
    },
    {
      "headline": "British Protectorate",
      "text": "In 1815, Corfu became a British protectorate as part of the United States of the Ionian Islands.",
      "date": "1815"
    },
    {
      "headline": "Union with Greece",
      "text": "On May 21, 1864, Corfu and the other Ionian Islands were ceded to Greece by the British.",
      "date": "1864-05-21"
    },
    {
      "headline": "World War II Occupation",
      "text": "During World War II, Corfu was occupied by Italian and later German forces from 1941 to 1944.",
      "date": "1941"
    },
    {
      "headline": "Establishment of Ionian University",
      "text": "In 1984, the Ionian University was established in Corfu, enhancing its educational and cultural landscape.",
      "date": "1984"
    }
  ]
}

