{
  "timeline": [
    {
      "headline": "Early Preclassic Period Begins",
      "text": "The Early Preclassic period in Mesoamerica begins around 2000 BCE, marking the start of agricultural communities and the development of pottery.",
      "date": "-2000"
    },
    {
      "headline": "Olmec Civilization Flourishes",
      "text": "The Olmec civilization, known for its colossal head sculptures and as one of the earliest Mesoamerican cultures, flourishes from around 1500 BCE to 400 BCE.",
      "date": "-1500"
    },
    {
      "headline": "San Lorenzo Olmec Site",
      "text": "San Lorenzo, one of the major Olmec sites, reaches its peak around 1200 BCE, becoming a prominent center of Olmec culture.",
      "date": "-1200"
    },
    {
      "headline": "La Venta Becomes Prominent",
      "text": "La Venta becomes the primary Olmec center around 900 BCE, known for its ceremonial complexes and monumental architecture.",
      "date": "-0900"
    },
    {
      "headline": "Olmec Decline",
      "text": "The decline of the Olmec civilization occurs around 400 BCE, leading to the rise of other Mesoamerican cultures.",
      "date": "-0400"
    },
    {
      "headline": "Zapotec Civilization Develops",
      "text": "The Zapotec civilization begins to develop in the Oaxaca Valley around 500 BCE, known for its writing system and urban centers like Monte Albán.",
      "date": "-0500"
    },
    {
      "headline": "Monte Albán Founded",
      "text": "Monte Albán, a major Zapotec city, is founded around 500 BCE and becomes a significant cultural and political center.",
      "date": "-0500"
    },
    {
      "headline": "Teotihuacan Emerges",
      "text": "The city of Teotihuacan begins to emerge around 100 BCE, eventually becoming one of the largest cities in the ancient world.",
      "date": "-0100"
    },
    {
      "headline": "Classic Period Begins",
      "text": "The Classic period in Mesoamerica begins around 250 CE, characterized by the rise of major cities like Teotihuacan and the Maya city-states.",
      "date": "0250"
    },
    {
      "headline": "Teotihuacan at its Peak",
      "text": "Teotihuacan reaches its peak around 450 CE, known for its massive pyramids and influence across Mesoamerica.",
      "date": "0450"
    },
    {
      "headline": "Maya Civilization Flourishes",
      "text": "The Maya civilization flourishes during the Classic period, with major city-states like Tikal, Palenque, and Copán reaching their zenith.",
      "date": "0600"
    },
    {
      "headline": "Teotihuacan Decline",
      "text": "The decline of Teotihuacan occurs around 550 CE, leading to shifts in power dynamics across Mesoamerica.",
      "date": "0550"
    },
    {
      "headline": "Postclassic Period Begins",
      "text": "The Postclassic period begins around 900 CE, marked by the rise of new powers such as the Toltecs and later the Aztecs.",
      "date": "0900"
    },
    {
      "headline": "Toltec Civilization",
      "text": "The Toltec civilization rises around 900 CE, with Tula as its capital, influencing later cultures including the Aztecs.",
      "date": "0900"
    },
    {
      "headline": "Aztec Empire Established",
      "text": "The Aztec Empire is established in the early 15th century, with Tenochtitlan as its capital, becoming a dominant force in Mesoamerica.",
      "date": "1428"
    },
    {
      "headline": "Spanish Conquest of the Aztec Empire",
      "text": "The Spanish, led by Hernán Cortés, conquer the Aztec Empire in 1521, marking the end of major indigenous rule in Mesoamerica.",
      "date": "1521"
    }
  ]
}

