{
  "timeline": [
    {
      "headline": "Emergence of Indo-Aryan Languages",
      "text": "The Indo-Aryan languages began to emerge as a distinct group within the Indo-Iranian branch of the Indo-European language family. This development is believed to have occurred around the early 2nd millennium BCE.",
      "date": "-2000"
    },
    {
      "headline": "Vedic Sanskrit",
      "text": "Vedic Sanskrit, the earliest form of the Indo-Aryan languages, was used in the composition of the Vedas, the oldest sacred texts of Hinduism, around 1500 BCE.",
      "date": "-1500"
    },
    {
      "headline": "Classical Sanskrit",
      "text": "Classical Sanskrit, a refined version of Vedic Sanskrit, became prominent around 500 BCE. It was standardized by the grammarian Pāṇini in his work, the Ashtadhyayi.",
      "date": "-0500"
    },
    {
      "headline": "Prakrit Languages",
      "text": "By around 300 BCE, the Prakrit languages, which were vernacular forms of Sanskrit, began to be used in literature and inscriptions across the Indian subcontinent.",
      "date": "-0300"
    },
    {
      "headline": "Pali Canon",
      "text": "The Pali Canon, the scriptures of Theravada Buddhism, was composed in the Pali language, a Prakrit, around the 1st century BCE.",
      "date": "-0100"
    },
    {
      "headline": "Apabhraṃśa Stage",
      "text": "The Apabhraṃśa stage of the Indo-Aryan languages, which represents the transition from Middle Indo-Aryan to Modern Indo-Aryan, occurred around the 6th century CE.",
      "date": "0600"
    },
    {
      "headline": "Development of Modern Indo-Aryan Languages",
      "text": "By the 10th century CE, the modern Indo-Aryan languages began to emerge from the Apabhraṃśa languages, leading to the development of languages such as Hindi, Bengali, Marathi, and others.",
      "date": "1000"
    },
    {
      "headline": "Colonial Influence and Language Standardization",
      "text": "During the British colonial period in the 19th century, several Indo-Aryan languages underwent processes of standardization and modernization, influenced by colonial administrative needs.",
      "date": "1800"
    },
    {
      "headline": "Post-Independence Language Policies",
      "text": "Following the independence of India and Pakistan in 1947, language policies were implemented to promote and standardize various Indo-Aryan languages as official languages in different regions.",
      "date": "1947"
    },
    {
      "headline": "Contemporary Status",
      "text": "As of the early 21st century, Indo-Aryan languages have over 800 million speakers worldwide, with significant communities in South Asia and diaspora populations globally.",
      "date": "2000"
    }
  ]
}

