{
  "timeline": [
    {
      "headline": "Formation of the Whigs",
      "text": "The Whigs emerged in the late 1670s as a political faction opposing the succession of James, Duke of York, a Catholic, to the English throne. They were initially formed to support the Exclusion Bill, which sought to exclude James from the line of succession.",
      "date": "1670"
    },
    {
      "headline": "Glorious Revolution",
      "text": "The Whigs played a significant role in the Glorious Revolution of 1688, which resulted in the overthrow of King James II and the ascension of William III and Mary II to the English throne.",
      "date": "1688"
    },
    {
      "headline": "Act of Settlement 1701",
      "text": "The Whigs supported the Act of Settlement 1701, which ensured that only Protestants could ascend to the English throne, further solidifying their influence in British politics.",
      "date": "1701"
    },
    {
      "headline": "Rise to Power",
      "text": "The Whigs dominated British politics during the early 18th century, particularly under the leadership of Sir Robert Walpole, who is often regarded as the first de facto Prime Minister of Great Britain.",
      "date": "1721"
    },
    {
      "headline": "American Revolution",
      "text": "During the American Revolution, the Whigs were generally more sympathetic to the American colonies' grievances and were critical of the British government's policies.",
      "date": "1775"
    },
    {
      "headline": "Reform Act 1832",
      "text": "The Whigs were instrumental in the passage of the Reform Act 1832, which reformed the British electoral system by redistributing seats in the House of Commons and extending the franchise.",
      "date": "1832"
    },
    {
      "headline": "Formation of the Liberal Party",
      "text": "In the 1850s, the Whigs merged with the Peelites and Radicals to form the Liberal Party, marking the end of the Whigs as a distinct political entity.",
      "date": "1859"
    },
    {
      "headline": "Irish Home Rule Crisis",
      "text": "In 1886, many former Whigs left the Liberal Party over the issue of Irish Home Rule, forming the Liberal Unionist Party.",
      "date": "1886"
    },
    {
      "headline": "Merger into the Conservative Party",
      "text": "The Liberal Unionist Party, formed by former Whigs, merged with the Conservative Party in 1912, further integrating the Whig legacy into British political history.",
      "date": "1912"
    }
