    {
      "headline": "Inclusion in Indian Constitution",
      "text": "The concept of a Uniform Civil Code (UCC) was included in the Directive Principles of State Policy in the Indian Constitution under Article 44, which states that the State shall endeavor to secure for the citizens a uniform civil code throughout the territory of India.",
      "date": "1949"
    },
    {
      "headline": "Shah Bano Case",
      "text": "In 1985, the Supreme Court of India ruled in favor of Shah Bano, a Muslim woman who sought maintenance from her husband after divorce. The case highlighted the need for a Uniform Civil Code as it dealt with the conflict between personal laws and the rights of women.",
      "date": "1985"
    },
    {
      "headline": "BJP's Advocacy for UCC",
      "text": "The Bharatiya Janata Party (BJP) has been a strong advocate for the implementation of a Uniform Civil Code in India, consistently including it in their election manifestos since the 1990s.",
      "date": "1990"
    },
    {
      "headline": "Law Commission Report",
      "text": "In 2018, the Law Commission of India released a consultation paper stating that a Uniform Civil Code is neither necessary nor desirable at this stage, suggesting instead that reforms should be made to existing personal laws to ensure equality.",
      "date": "2018"
    },
    {
      "headline": "Supreme Court's Observations",
      "text": "In 2020, the Supreme Court of India observed that there is a need for a Uniform Civil Code in the country, urging the government to consider its implementation.",
      "date": "2020"
    }
  ]
}

