      "headline": "Foundation of Riga",
      "text": "Riga was officially founded in 1201 by Albert of Buxhoeveden, a German bishop who established it as a base for the Christianization of the Baltic region.",
      "date": "1201"
    },
    {
      "headline": "Riga Joins the Hanseatic League",
      "text": "In 1282, Riga became a member of the Hanseatic League, a powerful economic and defensive alliance of merchant guilds and market towns in Northwestern and Central Europe.",
      "date": "1282"
    },
    {
      "headline": "Swedish Rule Begins",
      "text": "In 1621, during the Polish-Swedish War, Riga was captured by the Swedish Empire and became one of its most important cities.",
      "date": "1621"
    },
    {
      "headline": "Great Northern War and Russian Control",
      "text": "In 1710, during the Great Northern War, Riga was taken by Russian forces and subsequently became part of the Russian Empire under the Treaty of Nystad in 1721.",
      "date": "1710"
    },
    {
      "headline": "Industrialization and Growth",
      "text": "In the 19th century, Riga experienced significant industrialization and population growth, becoming a major industrial and commercial center in the Russian Empire.",
      "date": "1800-1900"
    },
    {
      "headline": "Independence and Interwar Period",
      "text": "Following World War I, Riga became the capital of independent Latvia in 1918, after the country declared independence from Russia.",
      "date": "1918"
    },
    {
      "headline": "Soviet Occupation Begins",
      "text": "In 1940, Riga was occupied by the Soviet Union as part of the Molotov-Ribbentrop Pact, marking the beginning of Soviet control.",
      "date": "1940"
    },
    {
      "headline": "Nazi Occupation",
      "text": "During World War II, Riga was occupied by Nazi Germany from 1941 to 1944, before being retaken by Soviet forces.",
      "date": "1941"
    },
    {
      "headline": "Restoration of Independence",
      "text": "In 1991, following the collapse of the Soviet Union, Riga once again became the capital of an independent Latvia.",
      "date": "1991"
    },
    {
      "headline": "Riga Joins the European Union",
      "text": "In 2004, Riga became part of the European Union when Latvia joined the organization, marking a significant step in its integration into Western Europe.",
      "date": "2004"
    }
  ]
}

