{
  "timeline": [
    {
      "headline": "Emergence of Catharism",
      "text": "Catharism began to emerge as a distinct movement in the 12th century, primarily in the Languedoc region of southern France and parts of northern Italy.",
      "date": "1100"
    },
    {
      "headline": "Cathar Council of Saint-Félix",
      "text": "In 1167, the Cathars held a council at Saint-Félix-Lauragais, near Toulouse, which helped to organize and consolidate their beliefs and practices.",
      "date": "1167"
    },
    {
      "headline": "Pope Innocent III's Call for Action",
      "text": "In 1208, Pope Innocent III called for a crusade against the Cathars, marking the beginning of the Albigensian Crusade.",
      "date": "1208"
    },
    {
      "headline": "Start of the Albigensian Crusade",
      "text": "The Albigensian Crusade began in 1209, initiated by the Catholic Church to eliminate Catharism in southern France.",
      "date": "1209"
    },
    {
      "headline": "Massacre at Béziers",
      "text": "On July 22, 1209, the city of Béziers was sacked, and thousands of Cathars and Catholics alike were killed by the crusaders.",
      "date": "1209-07-22"
    },
    {
      "headline": "Siege of Carcassonne",
      "text": "In August 1209, the crusaders captured Carcassonne, a major Cathar stronghold, forcing many Cathars to flee or convert.",
      "date": "1209-08"
    },
    {
      "headline": "Battle of Muret",
      "text": "On September 12, 1213, the Battle of Muret took place, resulting in a decisive victory for the crusaders and weakening Cathar resistance.",
      "date": "1213-09-12"
    },
    {
      "headline": "Fourth Lateran Council",
      "text": "In 1215, the Fourth Lateran Council officially condemned Catharism and reinforced measures against heresy.",
      "date": "1215"
    },
    {
      "headline": "Fall of Montségur",
      "text": "On March 16, 1244, the Cathar stronghold of Montségur fell to the crusaders, and over 200 Cathars were burned at the stake.",
      "date": "1244-03-16"
    },
    {
      "headline": "Establishment of the Medieval Inquisition",
      "text": "In 1233, the Catholic Church established the Medieval Inquisition to systematically root out heresy, including Catharism.",
      "date": "1233"
    },
    {
      "headline": "End of Catharism",
      "text": "By 1350, Catharism had been largely eradicated due to the efforts of the Albigensian Crusade and the Inquisition.",
      "date": "1350"
    }
  ]
}

