{
  "timeline": [
    {
      "headline": "Earliest Recorded Use of Crucifixion",
      "text": "The earliest recorded use of crucifixion as a method of execution dates back to the 6th century BCE by the Persians.",
      "date": "-0600"
    },
    {
      "headline": "Crucifixion in Carthage",
      "text": "Carthaginians adopted crucifixion as a method of punishment, particularly for military leaders who failed in battle, around the 3rd century BCE.",
      "date": "-0300"
    },
    {
      "headline": "Roman Adoption of Crucifixion",
      "text": "The Romans began using crucifixion as a method of execution for slaves, rebels, and enemies of the state around the 3rd century BCE.",
      "date": "-0300"
    },
    {
      "headline": "Crucifixion of Spartacus' Followers",
      "text": "In 71 BCE, following the defeat of Spartacus' slave rebellion, the Roman general Crassus crucified 6,000 of Spartacus' followers along the Appian Way.",
      "date": "-0071"
    },
    {
      "headline": "Crucifixion of Jesus of Nazareth",
      "text": "Jesus of Nazareth was crucified by the Romans around 30-33 CE, an event that became central to Christian theology.",
      "date": "0030"
    },
    {
      "headline": "End of Crucifixion in the Roman Empire",
      "text": "Crucifixion was abolished as a form of capital punishment in the Roman Empire by Emperor Constantine I in the 4th century CE.",
      "date": "0337"
    },
    {
      "headline": "Modern Instances of Crucifixion",
      "text": "There have been reports of crucifixion being used as a method of execution in some countries as recently as the 21st century, although these reports are often difficult to verify.",
      "date": "2000"
    }
  ]
}

