    {
      "headline": "Origins of Haitian Vodou",
      "text": "Haitian Vodou originated between the 16th and 19th centuries as a syncretic religion combining elements of West and Central African traditional religions with Roman Catholicism. This development occurred among enslaved Africans in the French colony of Saint-Domingue, now Haiti.",
      "date": "1600"
    },
    {
      "headline": "Haitian Revolution",
      "text": "The Haitian Revolution (1791-1804) was a successful anti-slavery and anti-colonial insurrection by self-liberated slaves against French colonial rule in Saint-Domingue. Vodou played a significant role in uniting the enslaved Africans and was integral to the revolution's success.",
      "date": "1791"
    },
    {
      "headline": "Haiti Gains Independence",
      "text": "On January 1, 1804, Haiti declared its independence from France, becoming the first independent nation of Latin America and the Caribbean, the first post-colonial independent black-led nation in the world, and the only nation whose independence was gained as part of a successful slave rebellion.",
      "date": "1804-01-01"
    },
    {
      "headline": "Vodou Recognized as a Religion",
      "text": "In 2003, the Haitian government officially recognized Vodou as a religion, granting Vodou priests the authority to perform civil ceremonies such as marriages.",
      "date": "2003"
    }
  ]
}

