{
  "timeline": [
    {
      "headline": "Emergence of Rococo Style",
      "text": "The Rococo style began to emerge in France in the early 18th century, around the 1730s, as a reaction against the grandeur, symmetry, and strict regulations of the Baroque style.",
      "date": "1730"
    },
    {
      "headline": "Rococo in Architecture",
      "text": "Rococo architecture is characterized by elaborate ornamentation, asymmetrical values, pastel color palette, and curved or serpentine lines. It became prominent in the 1730s, particularly in Paris.",
      "date": "1730"
    },
    {
      "headline": "Spread of Rococo",
      "text": "The Rococo style spread throughout Europe, influencing the arts and architecture in countries such as Germany, Austria, and Italy during the mid-18th century.",
      "date": "1750"
    },
    {
      "headline": "Rococo in Painting",
      "text": "Rococo painting is known for its lightness, elegance, and use of curving natural forms in ornamentation. Artists like Antoine Watteau and François Boucher were prominent figures in Rococo painting.",
      "date": "1750"
    },
    {
      "headline": "Decline of Rococo",
      "text": "By the late 18th century, around the 1770s, the Rococo style began to decline as the Neoclassical style gained popularity, emphasizing simplicity and symmetry.",
      "date": "1770"
    },
    {
      "headline": "Rococo Revival",
      "text": "In the 19th century, there was a revival of interest in the Rococo style, particularly in interior design and decorative arts.",
      "date": "1800"
    }
  ]
}

