{
  "timeline": [
    {
      "headline": "Start of the Battle of Passchendaele",
      "text": "The Third Battle of Ypres, also known as the Battle of Passchendaele, began on July 31, 1917. The battle was part of a strategy decided by the Allies at conferences in November 1916 and May 1917.",
      "date": "1917-07-31"
    },
    {
      "headline": "Battle of Langemarck",
      "text": "The Battle of Langemarck took place from August 16 to August 18, 1917, as part of the larger Battle of Passchendaele. It was an attempt by the Allies to capture the village of Langemarck.",
      "date": "1917-08-16"
    },
    {
      "headline": "Battle of Menin Road Ridge",
      "text": "The Battle of Menin Road Ridge occurred from September 20 to September 25, 1917. It was a successful operation by the British forces to capture the Menin Road Ridge.",
      "date": "1917-09-20"
    },
    {
      "headline": "Battle of Polygon Wood",
      "text": "The Battle of Polygon Wood took place from September 26 to October 3, 1917. It was another phase of the Third Battle of Ypres, where the Allies aimed to capture the Polygon Wood area.",
      "date": "1917-09-26"
    },
    {
      "headline": "Battle of Broodseinde",
      "text": "The Battle of Broodseinde occurred on October 4, 1917. It was a significant Allied attack aimed at capturing the Broodseinde Ridge.",
      "date": "1917-10-04"
    },
    {
      "headline": "Battle of Poelcappelle",
      "text": "The Battle of Poelcappelle took place on October 9, 1917. It was part of the ongoing efforts by the Allies to advance in the Ypres Salient.",
      "date": "1917-10-09"
    },
    {
      "headline": "First Battle of Passchendaele",
      "text": "The First Battle of Passchendaele occurred on October 12, 1917. The Allies attempted to capture the village of Passchendaele but faced strong German resistance.",
      "date": "1917-10-12"
    },
    {
      "headline": "Second Battle of Passchendaele",
      "text": "The Second Battle of Passchendaele took place from October 26 to November 10, 1917. The Canadian Corps played a crucial role in finally capturing the village of Passchendaele.",
      "date": "1917-10-26"
    },
    {
      "headline": "End of the Battle of Passchendaele",
      "text": "The Battle of Passchendaele officially ended on November 10, 1917, with the capture of the village by the Allies. The battle resulted in significant casualties on both sides and is remembered for its harsh conditions and muddy terrain.",
      "date": "1917-11-10"
    }
  ]
}

