      "headline": "Earliest Mention of Sanaa",
      "text": "Sanaa is believed to have been founded at least 2,500 years ago. It is mentioned in ancient texts and has a rich history as a center of trade and culture.",
      "date": "-0500"
    },
    {
      "headline": "Sanaa Becomes a Major Islamic Center",
      "text": "In the 7th century, Sanaa became an important center for the spread of Islam after the arrival of the Prophet Muhammad's followers.",
      "date": "0630"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Sanaa came under Ottoman control in the 16th century, marking a significant period of administration and architectural development.",
      "date": "1538"
    },
    {
      "headline": "First Ottoman Withdrawal",
      "text": "The Ottomans withdrew from Sanaa in 1635, leading to a period of local rule.",
      "date": "1635"
    },
    {
      "headline": "Second Ottoman Occupation",
      "text": "The Ottomans reoccupied Sanaa in the 19th century, reasserting their control over the region.",
      "date": "1872"
    },
    {
      "headline": "End of Ottoman Rule",
      "text": "The Ottoman Empire's control over Sanaa ended in 1918 following World War I.",
      "date": "1918"
    },
    {
      "headline": "North Yemen Civil War",
      "text": "Sanaa was a focal point during the North Yemen Civil War from 1962 to 1970, which resulted in the establishment of the Yemen Arab Republic.",
      "date": "1962"
    },
    {
      "headline": "Unification of Yemen",
      "text": "In 1990, North Yemen and South Yemen unified to form the Republic of Yemen, with Sanaa as the capital.",
      "date": "1990"
    },
    {
      "headline": "Houthi Occupation",
      "text": "In September 2014, Houthi forces took control of Sanaa, leading to significant political upheaval.",
      "date": "2014-09"
    },
    {
      "headline": "Aden Declared Temporary Capital",
      "text": "In March 2015, then-president Abdrabbuh Mansur Hadi declared Aden as the temporary capital of Yemen due to the Houthi occupation of Sanaa.",
      "date": "2015-03"
    }
  ]
}

