    },
    {
      "headline": "Tomb of the Unknown Soldier",
      "text": "The Tomb of the Unknown Soldier was dedicated on November 11, 1921, as a monument to American service members who have died without their remains being identified.",
      "date": "1921-11-11"
    },
    {
      "headline": "Addition of the Eternal Flame",
      "text": "The Eternal Flame was added to the grave of President John F. Kennedy on November 25, 1963, following his assassination.",
      "date": "1963-11-25"
