{
  "timeline": [
    {
      "headline": "Emergence of Blaxploitation",
      "text": "The blaxploitation genre emerged in the early 1970s, influenced by the cultural momentum of the Black civil rights movement, the black power movement, and the Black Panther Party.",
      "date": "1970"
    },
    {
      "headline": "Release of 'Sweet Sweetback's Baadasssss Song'",
      "text": "In 1971, Melvin Van Peebles released 'Sweet Sweetback's Baadasssss Song', a film that is often credited with sparking the blaxploitation genre. It was notable for its portrayal of a Black protagonist who defies authority.",
      "date": "1971"
    },
    {
      "headline": "Release of 'Shaft'",
      "text": "In 1971, 'Shaft', directed by Gordon Parks, was released. The film became a major success and is one of the most iconic films of the blaxploitation genre.",
      "date": "1971"
    },
    {
      "headline": "Coining of the Term 'Blaxploitation'",
      "text": "In 1972, Junius Griffin, president of the Beverly Hills–Hollywood branch of the NAACP, coined the term 'blaxploitation' to describe the genre. He criticized it for perpetuating racist stereotypes.",
      "date": "1972"
    },
    {
      "headline": "Release of 'Super Fly'",
      "text": "In 1972, 'Super Fly', directed by Gordon Parks Jr., was released. The film was another major success and further solidified the blaxploitation genre.",
      "date": "1972"
    },
    {
      "headline": "Criticism and Decline",
      "text": "By the mid-1970s, the blaxploitation genre faced criticism from civil rights groups for perpetuating negative stereotypes. This led to a decline in the production of such films.",
      "date": "1975"
    },
    {
      "headline": "Legacy and Influence",
      "text": "Despite its decline, the blaxploitation genre left a lasting impact on cinema and popular culture, influencing future filmmakers and genres.",
      "date": "1980"
    }
  ]
}

