{
  "timeline": [
    {
      "headline": "Ancient Conscription Practices",
      "text": "Conscription dates back to antiquity, with various ancient civilizations implementing forms of compulsory military service.",
      "date": "-2000"
    },
    {
      "headline": "Conscription in Ancient Greece",
      "text": "In ancient Greece, city-states like Athens and Sparta practiced forms of conscription to maintain their military forces.",
      "date": "-0500"
    },
    {
      "headline": "Conscription in Ancient Rome",
      "text": "The Roman Republic and later the Roman Empire utilized conscription to build and maintain their legions.",
      "date": "-0300"
    },
    {
      "headline": "The Levée en Masse",
      "text": "In 1793, during the French Revolution, the levée en masse was decreed, marking the start of modern conscription. It required all able-bodied men to defend the nation.",
      "date": "1793"
    },
    {
      "headline": "Conscription in Napoleonic Wars",
      "text": "Napoleon Bonaparte expanded the French conscription system to build his Grand Armée, which played a crucial role in the Napoleonic Wars.",
      "date": "1803"
    },
    {
      "headline": "Conscription Act in the United Kingdom",
      "text": "The United Kingdom introduced conscription for the first time during World War I with the Military Service Act of 1916.",
      "date": "1916"
    },
    {
      "headline": "Selective Service Act in the United States",
      "text": "The United States implemented conscription with the Selective Service Act of 1917 during World War I.",
      "date": "1917"
    },
    {
      "headline": "Conscription in World War II",
      "text": "Many countries, including the United States, United Kingdom, and Soviet Union, expanded conscription during World War II to meet military needs.",
      "date": "1939"
    },
    {
      "headline": "End of Conscription in the United States",
      "text": "The United States ended conscription in 1973, transitioning to an all-volunteer military force.",
      "date": "1973"
    },
    {
      "headline": "Conscription in Modern Times",
      "text": "As of the 21st century, conscription remains in practice in several countries, including South Korea, Israel, and Switzerland, among others.",
      "date": "2000"
    }
  ]
}

