      "headline": "Founding of Amman as Rabbath Ammon",
      "text": "Amman was originally founded as Rabbath Ammon, the capital of the Ammonites, around the 13th century BCE.",
      "date": "-1300"
    },
    {
      "headline": "Conquest by the Assyrian Empire",
      "text": "In the 8th century BCE, Rabbath Ammon was conquered by the Assyrian Empire.",
      "date": "-0800"
    },
    {
      "headline": "Control by the Neo-Babylonian Empire",
      "text": "In the 6th century BCE, the city came under the control of the Neo-Babylonian Empire.",
      "date": "-0600"
    },
    {
      "headline": "Incorporation into the Persian Empire",
      "text": "In the 5th century BCE, Rabbath Ammon became part of the Persian Empire.",
      "date": "-0500"
    },
    {
      "headline": "Hellenistic Period and Renaming to Philadelphia",
      "text": "After the conquest by Alexander the Great in the 4th century BCE, the city was renamed Philadelphia and became part of the Hellenistic world.",
      "date": "-0331"
    },
    {
      "headline": "Roman Rule",
      "text": "In 106 CE, Philadelphia became part of the Roman Empire and was included in the Decapolis, a group of ten cities on the eastern frontier of the Roman Empire.",
      "date": "0106"
    },
    {
      "headline": "Byzantine Period",
      "text": "During the Byzantine period, Philadelphia was a center for Christianity and saw the construction of several churches.",
      "date": "0324"
    },
    {
      "headline": "Islamic Conquest",
      "text": "In 635 CE, the city was conquered by the Rashidun Caliphate and became part of the Islamic world.",
      "date": "0635"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Amman came under Ottoman rule in the 16th century and remained a small village until the late 19th century.",
      "date": "1516"
    },
    {
      "headline": "Resettlement and Growth",
      "text": "In 1878, Circassian refugees settled in Amman, marking the beginning of its modern growth.",
      "date": "1878"
    },
    {
      "headline": "Establishment as Capital of Transjordan",
      "text": "In 1921, Amman was declared the capital of the Emirate of Transjordan by Emir Abdullah I.",
      "date": "1921"
    },
    {
      "headline": "Independence and Capital of Jordan",
      "text": "In 1946, Jordan gained independence, and Amman became the capital of the newly independent Hashemite Kingdom of Jordan.",
      "date": "1946"
    },
    {
      "headline": "Rapid Urbanization",
      "text": "From the 1950s onwards, Amman experienced rapid urbanization and population growth, becoming the economic and cultural center of Jordan.",
      "date": "1950"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Introduction of VHS",
      "text": "The VHS (Video Home System) was introduced by the Victor Company of Japan (JVC) in 1976. It was developed as a standard for consumer-level analog video recording on tape cassettes.",
      "date": "1976"
    },
    {
      "headline": "VHS Launch in the United States",
      "text": "VHS was launched in the United States in 1977, marking the beginning of its competition with Sony's Betamax format.",
      "date": "1977"
    },
    {
      "headline": "VHS Gains Market Dominance",
      "text": "By the early 1980s, VHS had gained significant market dominance over Betamax, largely due to longer recording times and a wider selection of available movies.",
      "date": "1980"
    },
    {
      "headline": "Introduction of VHS-C",
      "text": "In 1982, JVC introduced VHS-C, a more compact version of VHS designed for camcorders, which became popular for home video recording.",
      "date": "1982"
    },
    {
      "headline": "Peak Popularity of VHS",
      "text": "VHS reached its peak popularity in the late 1980s and early 1990s, becoming the standard for home video entertainment.",
      "date": "1990"
    },
    {
      "headline": "Introduction of S-VHS",
      "text": "In 1987, JVC introduced S-VHS (Super VHS), an improved version of VHS with better video quality, aimed at professional and high-end consumer markets.",
      "date": "1987"
    },
    {
      "headline": "Decline of VHS",
      "text": "The decline of VHS began in the late 1990s with the introduction of DVD, which offered better video quality and more convenience.",
      "date": "1997"
    },
    {
      "headline": "End of VHS Production",
      "text": "The last standalone JVC VHS-only VCR was produced in 2008, marking the end of an era for VHS as a dominant video format.",
      "date": "2008"
    }
  ]
}

