{
  "timeline": [
    {
      "headline": "Occupation of Constantinople",
      "text": "On March 16, 1920, the Allied forces occupied Constantinople, the capital of the Ottoman Empire, which intensified the Turkish National Movement's resolve to resist partition and occupation.",
      "date": "1920-03-16"
    },
    {
      "headline": "Establishment of the Grand National Assembly",
      "text": "On April 23, 1920, the Grand National Assembly of Turkey was established in Ankara, marking the beginning of the Turkish National Movement's formal political and military resistance against the occupying forces.",
      "date": "1920-04-23"
    },
    {
      "headline": "Treaty of Sèvres",
      "text": "Signed on August 10, 1920, the Treaty of Sèvres sought to dismantle the Ottoman Empire, ceding large territories to the Allied powers and their allies, which was rejected by the Turkish Nationalists.",
      "date": "1920-08-10"
    },
    {
      "headline": "Battle of Sakarya",
      "text": "From August 23 to September 13, 1921, the Battle of Sakarya was fought between Turkish Nationalist forces and Greek forces. The Turkish victory was a turning point in the war.",
      "date": "1921-08-23"
    },
    {
      "headline": "Treaty of Kars",
      "text": "On October 13, 1921, the Treaty of Kars was signed between Turkey and the Soviet states of Armenia, Azerbaijan, and Georgia, establishing the eastern borders of Turkey.",
      "date": "1921-10-13"
    },
    {
      "headline": "Battle of Dumlupınar",
      "text": "The Battle of Dumlupınar, fought from August 26 to August 30, 1922, was the final battle of the Greco-Turkish War, resulting in a decisive victory for the Turkish forces.",
      "date": "1922-08-26"
    },
    {
      "headline": "Armistice of Mudanya",
      "text": "Signed on October 11, 1922, the Armistice of Mudanya ended the hostilities between Turkey and the Allied powers, leading to the withdrawal of Greek forces from Anatolia.",
      "date": "1922-10-11"
    },
    {
      "headline": "Abolition of the Ottoman Sultanate",
      "text": "On November 1, 1922, the Grand National Assembly of Turkey formally abolished the Ottoman Sultanate, ending over 600 years of Ottoman rule.",
      "date": "1922-11-01"
    },
    {
      "headline": "Treaty of Lausanne",
      "text": "The Treaty of Lausanne was signed on July 24, 1923, recognizing the sovereignty of the newly established Republic of Turkey and setting its modern borders.",
      "date": "1923-07-24"
    },
    {
      "headline": "Proclamation of the Republic of Turkey",
      "text": "On October 29, 1923, the Republic of Turkey was officially proclaimed, with Mustafa Kemal Atatürk as its first president, marking the end of the Turkish War of Independence.",
      "date": "1923-10-29"
    }
  ]
}

