  "timeline": [
    {
      "headline": "Birth of Hypatia",
      "text": "Hypatia was born around 360 CE in Alexandria, Egypt, then part of the Eastern Roman Empire.",
      "date": "0360"
    },
    {
      "headline": "Hypatia's Education",
      "text": "Hypatia was educated in Athens, where she studied mathematics and philosophy, likely under the guidance of her father, Theon of Alexandria.",
      "date": "0370"
    },
    {
      "headline": "Hypatia Becomes a Teacher",
      "text": "By the late 4th century, Hypatia became a prominent teacher of philosophy and astronomy in Alexandria, attracting many students from across the Mediterranean.",
      "date": "0385"
    },
    {
      "headline": "Hypatia's Commentary on Diophantus's Arithmetica",
      "text": "Hypatia wrote a commentary on Diophantus's thirteen-volume Arithmetica, which may survive in part, having been interpolated into Diophantus's original text.",
      "date": "0390"
    },
    {
      "headline": "Hypatia's Commentary on Apollonius's Conics",
      "text": "Hypatia wrote a commentary on Apollonius of Perga's treatise on conic sections, although this work has not survived.",
      "date": "0395"
    },
    {
      "headline": "Hypatia's Influence in Alexandria",
      "text": "Hypatia became renowned in her own lifetime as a great teacher and a wise counselor, influencing many students and scholars in Alexandria.",
      "date": "0400"
    },
    {
      "headline": "Hypatia's Possible Editing of Ptolemy's Almagest",
      "text": "Many modern scholars believe that Hypatia may have edited the surviving text of Ptolemy's Almagest, based on the title of her father Theon's commentary on Book III of the Almagest.",
      "date": "0405"
    },
    {
      "headline": "Death of Hypatia",
      "text": "Hypatia was murdered by a Christian mob in March 415 CE in Alexandria, amid political and religious turmoil.",
      "date": "0415-03"
    }
  ]
}

