    },
    {
      "headline": "Casanova's Imprisonment in the Leads",
      "text": "On July 26, 1755, Casanova was arrested and imprisoned in the Doge's Palace in Venice, known as 'The Leads', on charges of affront to religion and common decency.",
      "date": "1755-07-26"
    },
    {
      "headline": "Casanova's Escape from Prison",
      "text": "On October 31, 1756, Casanova famously escaped from The Leads, a feat that contributed to his legendary status.",
      "date": "1756-10-31"
    },
    {
      "headline": "Casanova's Travels Across Europe",
      "text": "After his escape, Casanova traveled extensively across Europe, visiting cities such as Paris, Prague, and London, engaging in various occupations and adventures.",
      "date": "1757"
    },
    {
      "headline": "Casanova's Memoirs",
      "text": "In 1789, Casanova began writing his autobiography, 'Histoire de ma vie', which provides a detailed account of his life and the social customs of 18th-century Europe.",
      "date": "1789"
    },
    {
      "headline": "Casanova's Death",
      "text": "Giacomo Casanova died on June 4, 1798, at the age of 73, in Dux, Bohemia, now Duchcov in the Czech Republic.",
