{
  "timeline": [
    {
      "headline": "Formation of the Lakota",
      "text": "The Lakota people, also known as the Teton Sioux, are one of the three prominent subcultures of the Sioux people. They are part of the larger Sioux Nation, which historically inhabited the Great Plains region of North America.",
      "date": "-1500"
    },
    {
      "headline": "Migration to the Great Plains",
      "text": "The Lakota migrated westward from the Great Lakes region to the Great Plains, where they adapted to a nomadic lifestyle centered around the buffalo. This migration occurred over several centuries, with significant movement taking place in the 17th and 18th centuries.",
      "date": "1700"
    },
    {
      "headline": "Introduction of the Horse",
      "text": "The Lakota acquired horses in the early 18th century, which transformed their culture and way of life, enhancing their ability to hunt buffalo and engage in warfare.",
      "date": "1730"
    },
    {
      "headline": "Battle of Little Bighorn",
      "text": "On June 25-26, 1876, the Lakota, along with the Northern Cheyenne and Arapaho, defeated the 7th Cavalry Regiment of the United States Army, led by Lieutenant Colonel George Armstrong Custer, at the Battle of Little Bighorn.",
      "date": "1876-06-25"
    },
    {
      "headline": "Wounded Knee Massacre",
      "text": "On December 29, 1890, the U.S. Army's 7th Cavalry Regiment killed approximately 150-300 Lakota men, women, and children at Wounded Knee Creek in South Dakota, marking a tragic event in Lakota history.",
      "date": "1890-12-29"
    },
    {
      "headline": "Establishment of Reservations",
      "text": "Following the Indian Wars, the Lakota were confined to reservations in North and South Dakota, drastically altering their traditional way of life.",
      "date": "1890"
    },
    {
      "headline": "Revival of Lakota Culture",
      "text": "In the late 20th and early 21st centuries, there has been a resurgence in the preservation and revitalization of Lakota language and culture, with efforts to teach the language and maintain traditional practices.",
      "date": "2000"
    }
  ]
}

