    {
      "headline": "Coronation of Charlemagne",
      "text": "On December 25, 800, Charlemagne was crowned as Emperor of the Romans by Pope Leo III. This event contributed to tensions between the Eastern and Western Churches, as it challenged the Byzantine Emperor's authority.",
      "date": "0800-12-25"
    },
    {
      "headline": "Iconoclasm Controversy",
      "text": "The Iconoclasm Controversy, which began in the Byzantine Empire in the 8th century, involved disputes over the use of religious images. It was a significant theological disagreement between the Eastern and Western Churches.",
      "date": "0726"
    },
    {
      "headline": "Filioque Controversy",
      "text": "The Filioque Controversy arose from the Western Church's addition of the phrase 'and the Son' to the Nicene Creed, which was not accepted by the Eastern Church. This theological dispute was a major factor leading to the schism.",
      "date": "0800"
    },
    {
      "headline": "Papal Claims of Universal Jurisdiction",
      "text": "The Pope's claim to universal jurisdiction over the entire Christian Church was a point of contention with the Eastern Church, which favored a more conciliar approach.",
      "date": "0900"
    },
    {
      "headline": "Dispute Over Eucharistic Bread",
      "text": "Differences over whether leavened or unleavened bread should be used in the Eucharist became a point of contention between the Eastern and Western Churches.",
      "date": "1000"
    },
    {
      "headline": "Mutual Excommunications of 1054",
      "text": "On July 16, 1054, Cardinal Humbert, representing Pope Leo IX, excommunicated Patriarch Michael I Cerularius of Constantinople. In response, Cerularius excommunicated Humbert and his associates. This event marked the formal beginning of the East–West Schism.",
      "date": "1054-07-16"
    },
    {
      "headline": "Attempts at Reconciliation",
      "text": "Throughout the centuries following the schism, there were various attempts at reconciliation between the Eastern Orthodox and Roman Catholic Churches, including the Council of Florence in 1439, but these efforts were largely unsuccessful.",
      "date": "1439"
    }
  ]
}

