{
  "timeline": [
    {
      "headline": "Early Origins of Isekai",
      "text": "The concept of Isekai can be traced back to ancient literature and folklore, where characters are transported to other worlds or realms. Examples include the Japanese folktale 'Urashima Tarō' and the classical Chinese novel 'Journey to the West'.",
      "date": "-0700"
    },
    {
      "headline": "Modern Isekai Emergence",
      "text": "The modern form of Isekai began to take shape in the late 20th century with the rise of light novels and anime. Works like 'Fushigi Yûgi' (1991) and 'The Vision of Escaflowne' (1996) helped popularize the genre.",
      "date": "1991"
    },
    {
      "headline": "Influential Isekai Series: 'Sword Art Online'",
      "text": "The release of 'Sword Art Online' in 2009 marked a significant moment for the Isekai genre. This light novel series, which was later adapted into an anime, became a major influence on the genre's popularity.",
      "date": "2009"
    },
    {
      "headline": "Isekai Boom in Anime",
      "text": "The 2010s saw a massive boom in Isekai anime, with numerous series being produced each year. Popular titles include 'Re:Zero - Starting Life in Another World' (2016) and 'That Time I Got Reincarnated as a Slime' (2018).",
      "date": "2016"
    },
    {
      "headline": "Isekai in Video Games",
      "text": "Isekai themes have also become prevalent in video games, with titles like 'Final Fantasy' and 'The Legend of Zelda' incorporating elements of being transported to another world.",
      "date": "2018"
    },
    {
      "headline": "Isekai's Continued Popularity",
      "text": "As of the 2020s, Isekai remains one of the most popular genres in anime and manga, with new series and adaptations continuing to captivate audiences worldwide.",
      "date": "2020"
    }
  ]
}

