    {
      "headline": "Migration of Indo-Aryan Peoples",
      "text": "The Indo-Aryan peoples began migrating from Central Asia into South Asia, introducing the Proto-Indo-Aryan language. This migration is believed to have occurred around 1500 BCE.",
      "date": "-1500"
    },
    {
      "headline": "Vedic Period",
      "text": "The Vedic Period, marked by the composition of the Vedas, the oldest scriptures of Hinduism, began around 1500 BCE and lasted until about 500 BCE. This era saw the establishment of early Indo-Aryan culture and society in the Indian subcontinent.",
      "date": "-1500"
    },
    {
      "headline": "Formation of Mahajanapadas",
      "text": "By around 600 BCE, the Indo-Aryan peoples had established several large kingdoms and republics known as Mahajanapadas across northern India.",
      "date": "-0600"
    },
    {
      "headline": "Rise of the Maurya Empire",
      "text": "The Maurya Empire, founded by Chandragupta Maurya in 322 BCE, became one of the largest empires in the Indian subcontinent, unifying much of the Indo-Aryan speaking regions.",
      "date": "-0322"
    },
    {
      "headline": "Spread of Indo-Aryan Languages",
      "text": "Over centuries, Indo-Aryan languages spread across South Asia, becoming the predominant languages in regions such as northern India, Pakistan, Bangladesh, Nepal, and Sri Lanka.",
      "date": "0000"
    },
    {
      "headline": "Modern Distribution of Indo-Aryan Peoples",
      "text": "Today, Indo-Aryan speakers are found across South Asia, including regions such as Bangladesh, Nepal, eastern Pakistan, Sri Lanka, Maldives, and northern India.",
      "date": "2023"
    }
  ]
}

