    {
      "headline": "Formation of the Joplin Tornado",
      "text": "On May 22, 2011, a large and devastating multiple-vortex tornado formed just west of Joplin, Missouri. It was part of a larger late-May tornado outbreak.",
      "date": "2011-05-22"
    },
    {
      "headline": "Tornado Strikes Joplin",
      "text": "The EF5 tornado struck Joplin, Missouri, on the evening of May 22, 2011. It intensified very quickly, reaching a maximum width of nearly one mile (1.6 km) during its path through the southern part of the city.",
      "date": "2011-05-22"
    },
    {
      "headline": "Path Through Joplin",
      "text": "The tornado tracked eastward through Joplin, causing catastrophic damage. It destroyed homes, businesses, and infrastructure, leading to significant loss of life and injuries.",
      "date": "2011-05-22"
    },
    {
      "headline": "Crossing Interstate 44",
      "text": "After devastating Joplin, the tornado continued across Interstate 44 into rural portions of Jasper and Newton counties.",
      "date": "2011-05-22"
    },
    {
      "headline": "Dissipation of the Tornado",
      "text": "The tornado weakened before it dissipated in the rural areas after causing extensive damage in Joplin and surrounding regions.",
      "date": "2011-05-22"
    },
    {
      "headline": "Aftermath and Recovery Efforts",
      "text": "In the aftermath of the tornado, emergency response teams and volunteers began recovery efforts. The community faced a long process of rebuilding and healing.",
      "date": "2011-05-23"
    },
    {
      "headline": "Impact and Legacy",
      "text": "The 2011 Joplin tornado resulted in 158 fatalities and over 1,000 injuries, making it one of the deadliest tornadoes in U.S. history. It left a lasting impact on the community and led to changes in emergency preparedness and response strategies.",
      "date": "2011"
    }
  ]
}

