  "timeline": [
    {
      "headline": "First Mention of Saxons",
      "text": "The Saxons are first mentioned by the Greek geographer Ptolemy in his work 'Geographia', written around 150 AD, where he refers to them as a tribe located in the area of modern-day northern Germany.",
      "date": "0150"
    },
    {
      "headline": "Saxon Raids on Roman Britain",
      "text": "In the late 3rd century, Saxons began raiding the coasts of Roman Britain, as well as the coasts of Gaul, contributing to the instability of the Roman Empire during this period.",
      "date": "0280"
    },
    {
      "headline": "Saxon Settlement in Britain",
      "text": "By the 5th century, Saxons, along with other Germanic tribes such as the Angles and Jutes, began to settle in Britain following the Roman withdrawal, leading to the formation of several Anglo-Saxon kingdoms.",
      "date": "0400"
    },
    {
      "headline": "Saxon Wars with Charlemagne",
      "text": "From 772 to 804, the Saxons were engaged in a series of conflicts with Charlemagne, the King of the Franks, known as the Saxon Wars. These wars resulted in the eventual subjugation and Christianization of the Saxons.",
      "date": "0772"
    },
    {
      "headline": "Creation of the Duchy of Saxony",
      "text": "In 804, following the conclusion of the Saxon Wars, the region of Saxony was incorporated into the Carolingian Empire as a duchy, marking the end of Saxon independence.",
      "date": "0804"
    },
    {
      "headline": "Saxon Influence in the Holy Roman Empire",
      "text": "During the 10th and 11th centuries, the Duchy of Saxony became one of the most powerful duchies in the Holy Roman Empire, with the Saxon dynasty producing several emperors, including Otto I, who was crowned Holy Roman Emperor in 962.",
      "date": "0962"
    }
  ]
}

