{
  "timeline": [
    {
      "headline": "Spanish Armada Sets Sail",
      "text": "The Spanish Armada, commanded by Alonso de Guzmán, Duke of Medina Sidonia, set sail from Lisbon in late May 1588. The fleet's mission was to sail up the English Channel, join with the Duke of Parma in Flanders, and escort an invasion force to England.",
      "date": "1588-05"
    },
    {
      "headline": "Battle of Gravelines",
      "text": "On July 29, 1588, the Spanish Armada was engaged by the English fleet in the Battle of Gravelines. The English forces, using more maneuverable ships and superior tactics, inflicted significant damage on the Spanish fleet.",
      "date": "1588-07-29"
    },
    {
      "headline": "Armada Attempts to Regroup",
      "text": "Following the Battle of Gravelines, the Spanish Armada attempted to regroup and return to Spain by sailing around the north of Scotland and Ireland. However, they encountered severe storms that scattered the fleet.",
      "date": "1588-08"
    },
    {
      "headline": "Spanish Armada Defeated",
      "text": "By September 1588, the Spanish Armada was effectively defeated. Many ships were lost to storms and shipwrecks along the coasts of Scotland and Ireland. The remnants of the fleet eventually returned to Spain.",
      "date": "1588-09"
    },
    {
      "headline": "Aftermath and Impact",
      "text": "The defeat of the Spanish Armada marked a turning point in naval warfare and established England as a dominant sea power. It also prevented the Spanish from reinstating Catholicism in England and ended the immediate threat of invasion.",
      "date": "1588"
    }
  ]
}

