{
  "timeline": [
    {
      "headline": "Construction Begins",
      "text": "Construction of Persepolis began under the reign of Darius I in 518 BCE. It was intended to serve as the ceremonial capital of the Achaemenid Empire.",
      "date": "-0518"
    },
    {
      "headline": "Expansion by Xerxes I",
      "text": "Xerxes I, the successor of Darius I, continued the expansion of Persepolis, adding several new structures including the Gate of All Nations and the Hall of a Hundred Columns around 486 BCE.",
      "date": "-0486"
    },
    {
      "headline": "Completion of Major Structures",
      "text": "By the reign of Artaxerxes I (465-424 BCE), many of the major structures of Persepolis, including the Apadana Palace and the Throne Hall, were completed.",
      "date": "-0465"
    },
    {
      "headline": "Destruction by Alexander the Great",
      "text": "In 330 BCE, Persepolis was looted and burned by the armies of Alexander the Great, marking the decline of the Achaemenid Empire.",
      "date": "-0330"
    },
    {
      "headline": "Rediscovery and Excavation",
      "text": "The ruins of Persepolis were rediscovered and excavated in the 1930s, revealing the grandeur of the ancient city.",
      "date": "1930"
    },
