    {
      "headline": "Bombing of the World Trade Center",
      "text": "On February 26, 1993, a van bomb detonated below the North Tower of the World Trade Center complex in Manhattan, New York City. The 1,336 lb (606 kg) urea nitrate–hydrogen gas enhanced device was intended to make the North Tower collapse onto the South Tower, taking down both skyscrapers and killing tens of thousands of people. While it failed to do so, it killed six people, including a pregnant woman, and caused over a thousand injuries. About 50,000 people were evacuated from the buildings that day.",
      "date": "1993-02-26"
    },
    {
      "headline": "Arrest of Mohammad Salameh",
      "text": "Mohammad Salameh, one of the conspirators, was arrested on March 4, 1993, after he tried to reclaim the deposit on the rental van used in the bombing.",
      "date": "1993-03-04"
    },
    {
      "headline": "Arrest of Nidal Ayyad",
      "text": "Nidal Ayyad, another conspirator, was arrested on March 10, 1993. He was linked to the bombing through a letter claiming responsibility for the attack.",
      "date": "1993-03-10"
    },
    {
      "headline": "Arrest of Mahmud Abouhalima",
      "text": "Mahmud Abouhalima was arrested on March 24, 1993, in Egypt and extradited to the United States.",
      "date": "1993-03-24"
    },
    {
      "headline": "Arrest of Ahmad Ajaj",
      "text": "Ahmad Ajaj was arrested on March 29, 1993. He was already in custody for passport fraud at the time of the bombing.",
      "date": "1993-03-29"
    },
    {
      "headline": "Arrest of Ramzi Yousef",
      "text": "Ramzi Yousef, the mastermind behind the bombing, was arrested on February 7, 1995, in Islamabad, Pakistan, and extradited to the United States.",
      "date": "1995-02-07"
    },
