      "headline": "Attack on Pearl Harbor",
      "text": "On December 7, 1941, the Empire of Japan attacked Pearl Harbor, leading to the United States' entry into World War II.",
      "date": "1941-12-07"
    },
    {
      "headline": "Executive Order 9066 Issued",
      "text": "On February 19, 1942, President Franklin D. Roosevelt signed Executive Order 9066, authorizing the forced relocation and internment of Japanese Americans.",
      "date": "1942-02-19"
    },
    {
      "headline": "First Forced Relocations Begin",
      "text": "In March 1942, the first forced relocations of Japanese Americans began, with individuals being moved to temporary assembly centers.",
      "date": "1942-03"
    },
    {
      "headline": "War Relocation Authority Established",
      "text": "On March 18, 1942, the War Relocation Authority (WRA) was established to oversee the internment process.",
      "date": "1942-03-18"
    },
    {
      "headline": "First Internment Camp Opens",
      "text": "On May 27, 1942, the first internment camp, Manzanar, officially opened in California.",
      "date": "1942-05-27"
    },
    {
      "headline": "Peak of Internment",
      "text": "By the end of 1942, approximately 120,000 Japanese Americans were interned in ten camps across the United States.",
      "date": "1942"
    },
    {
      "headline": "End of Internment",
      "text": "In January 1945, the internment camps began to close, following a Supreme Court decision and the decline of wartime hysteria.",
      "date": "1945-01"
    },
    {
      "headline": "Last Camp Closes",
      "text": "On March 20, 1946, the last internment camp, Tule Lake, officially closed.",
      "date": "1946-03-20"
    },
    {
      "headline": "Civil Liberties Act of 1988",
      "text": "On August 10, 1988, President Ronald Reagan signed the Civil Liberties Act, which formally apologized and provided reparations to surviving Japanese Americans who were interned.",
      "date": "1988-08-10"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Escape Attempt from Alcatraz",
      "text": "Late on the night of June 11 or early morning of June 12, 1962, inmates Clarence Anglin, John Anglin, and Frank Morris escaped from Alcatraz Federal Penitentiary. They placed papier-mâché model heads resembling their own likenesses in their beds, broke out of the main prison building via ventilation ducts and an unguarded utility corridor, and departed the island aboard an improvised inflatable raft.",
      "date": "1962-06-11"
    },
    {
      "headline": "Discovery of the Escape",
      "text": "On the morning of June 12, 1962, prison officials discovered the escape when guards attempted to wake the inmates for their daily headcount and found the dummy heads in their beds.",
      "date": "1962-06-12"
    },
    {
      "headline": "Fate of the Escapees",
      "text": "The fate of Clarence Anglin, John Anglin, and Frank Morris remains unknown. Despite extensive investigations, no conclusive evidence has been found to determine whether they survived the escape or perished in the waters of San Francisco Bay.",
      "date": "1962-06-12"
    },
    {
      "headline": "Allen West's Failed Escape",
      "text": "Allen West, a fourth conspirator in the escape plan, was unable to escape with the others. He was left behind on the island after failing to remove the ventilation grill in his cell in time.",
      "date": "1962-06-11"
    }
  ]
}

