    {
      "headline": "Operation Yewtree Launched",
      "text": "In October 2012, the Metropolitan Police launched Operation Yewtree, an investigation into the allegations against Savile and others. The operation was divided into three strands: allegations against Savile, allegations against 'Savile and others', and allegations against others.",
      "date": "2012-10"
    },
    {
      "headline": "BBC's Internal Investigation",
      "text": "In October 2012, the BBC announced an internal investigation into the allegations, focusing on why a Newsnight investigation into Savile was dropped in 2011.",
      "date": "2012-10"
    },
    {
      "headline": "Publication of the Dame Janet Smith Review",
      "text": "On February 25, 2016, the Dame Janet Smith Review was published. It examined the culture and practices at the BBC during the years Savile worked there and concluded that the BBC had missed opportunities to stop Savile's abuse.",
      "date": "2016-02-25"
    },
    {
      "headline": "Operation Yewtree Report",
      "text": "On January 11, 2013, the Metropolitan Police and NSPCC published a joint report titled 'Giving Victims a Voice', which detailed the extent of Savile's abuse, identifying 450 victims.",
      "date": "2013-01-11"
    }
  ]
}

