{
  "timeline": [
    {
      "headline": "Foundation of the Shakers",
      "text": "The Shakers, originally known as the 'Shaking Quakers' due to their ecstatic worship practices, were founded around 1747 in England. They emerged from a branch of the Quakers.",
      "date": "1747"
    },
    {
      "headline": "Ann Lee Joins the Shakers",
      "text": "Ann Lee, who would become the leader of the Shakers, joined the sect in 1758. Her leadership would later be pivotal in the establishment and spread of the Shakers in America.",
      "date": "1758"
    },
    {
      "headline": "Ann Lee's Vision and Leadership",
      "text": "In 1770, Ann Lee had a vision that she was the female embodiment of Christ, which led to her becoming the leader of the Shakers.",
      "date": "1770"
    },
    {
      "headline": "Migration to America",
      "text": "In 1774, Ann Lee and a small group of followers emigrated from England to America, seeking religious freedom and the opportunity to establish their community.",
      "date": "1774"
    },
    {
      "headline": "Establishment of the First Shaker Community in America",
      "text": "The first Shaker community in America was established in Watervliet, New York, in 1776. This marked the beginning of the Shaker movement in the United States.",
      "date": "1776"
    },
    {
      "headline": "Ann Lee's Death",
      "text": "Ann Lee, the charismatic leader of the Shakers, died on September 8, 1784. Her death marked the end of an era but her teachings continued to guide the Shaker communities.",
      "date": "1784-09-08"
    },
    {
      "headline": "Peak of Shaker Influence",
      "text": "The Shakers reached their peak influence in the mid-19th century, with about 6,000 members spread across numerous communities in the United States.",
      "date": "1850"
    },
    {
      "headline": "Decline in Shaker Membership",
      "text": "By the late 19th century, Shaker membership began to decline due to various factors, including the celibate lifestyle and societal changes.",
      "date": "1880"
    },
    {
      "headline": "Closure of Most Shaker Communities",
      "text": "Throughout the 20th century, most Shaker communities closed due to dwindling membership and changing societal norms.",
      "date": "1900"
    },
    {
      "headline": "Last Active Shaker Community",
      "text": "As of the early 21st century, the last active Shaker community is located in Sabbathday Lake, Maine, continuing to uphold the traditions of the Shaker faith.",
      "date": "2000"
    }
  ]
}

