{
  "timeline": [
    {
      "headline": "Formation of the Democratic Current",
      "text": "In 1986, the Democratic Current was formed as a political faction within the Institutional Revolutionary Party (PRI) in Mexico. This faction was critical of the PRI's authoritarian practices and sought democratic reforms.",
      "date": "1986"
    },
    {
      "headline": "Contested General Election",
      "text": "In 1988, the National Democratic Front, the immediate predecessor of the Party of the Democratic Revolution (PRD), participated in the Mexican general election. The election was widely believed to have been rigged by the PRI, leading to significant political unrest.",
      "date": "1988"
    },
    {
      "headline": "Founding of the Party of the Democratic Revolution",
      "text": "On May 5, 1989, the Party of the Democratic Revolution (PRD) was officially founded. It emerged from the National Democratic Front and was established as a response to the perceived electoral fraud in the 1988 general election.",
      "date": "1989-05-05"
    },
    {
      "headline": "First Major Electoral Success",
      "text": "In 1997, the PRD achieved its first major electoral success when Cuauhtémoc Cárdenas was elected as the Head of Government of Mexico City, marking a significant political shift in the capital.",
      "date": "1997"
    },
    {
      "headline": "Presidential Election Participation",
      "text": "The PRD participated in the 2000 Mexican presidential election, with Cuauhtémoc Cárdenas as its candidate. Although Cárdenas did not win, the election marked the end of the PRI's 71-year rule.",
      "date": "2000"
    },
    {
      "headline": "Andrés Manuel López Obrador's Candidacy",
      "text": "In 2006, Andrés Manuel López Obrador ran as the PRD's candidate in the Mexican presidential election. The election was highly contested, and López Obrador narrowly lost, leading to widespread protests.",
      "date": "2006"
    },
    {
      "headline": "Split and Decline",
      "text": "In 2012, the PRD faced internal divisions and a decline in influence as Andrés Manuel López Obrador left the party to form the National Regeneration Movement (MORENA).",
      "date": "2012"
    }
  ]
}

