{
  "timeline": [
    {
      "headline": "Permian–Triassic Extinction Event",
      "text": "Approximately 251.9 million years ago, the Permian–Triassic extinction event occurred, marking the boundary between the Permian and Triassic geologic periods, and with them the Paleozoic and Mesozoic eras. It is Earth's most severe known extinction event, with the extinction of 57% of biological families, 83% of genera, 81% of marine species, and 70% of terrestrial vertebrate species. It is also the greatest known mass extinction of insects.",
      "date": "-251900000"
    },
    {
      "headline": "First Pulse of Extinction",
      "text": "Evidence suggests that the Permian–Triassic extinction event may have occurred in one to three distinct pulses. The first pulse is believed to have been caused by massive volcanic eruptions in the Siberian Traps, leading to significant environmental changes.",
      "date": "-251900000"
    },
    {
      "headline": "Second Pulse of Extinction",
      "text": "The second pulse of extinction may have been driven by further environmental stressors, including ocean anoxia and acidification, which severely impacted marine life.",
      "date": "-251900000"
    },
    {
      "headline": "Third Pulse of Extinction",
      "text": "A potential third pulse of extinction could have been exacerbated by additional volcanic activity and climate changes, further contributing to the massive loss of biodiversity.",
      "date": "-251900000"
    }
  ]
}

