{
  "timeline": [
    {
      "headline": "Discovery by Captain James Cook",
      "text": "Norfolk Island was discovered by Captain James Cook on 10 October 1774 during his second voyage to the South Pacific.",
      "date": "1774-10-10"
    },
    {
      "headline": "First Settlement",
      "text": "The first European settlement on Norfolk Island was established on 6 March 1788 by Lieutenant Philip Gidley King and a party of 22 people, including 15 convicts.",
      "date": "1788-03-06"
    },
    {
      "headline": "Abandonment of First Settlement",
      "text": "The first settlement was abandoned in 1814, with the last settlers leaving the island on 15 February 1814.",
      "date": "1814-02-15"
    },
    {
      "headline": "Second Penal Settlement",
      "text": "A second penal settlement was established on Norfolk Island in 1825, which became notorious for its harsh conditions.",
      "date": "1825"
    },
    {
      "headline": "Closure of Second Penal Settlement",
      "text": "The second penal settlement was closed in 1855, and the last convicts were removed from the island.",
      "date": "1855"
    },
    {
      "headline": "Arrival of Pitcairn Islanders",
      "text": "In 1856, descendants of the Bounty mutineers from Pitcairn Island were resettled on Norfolk Island, arriving on 8 June 1856.",
      "date": "1856-06-08"
    },
    {
      "headline": "Norfolk Island Act",
      "text": "The Norfolk Island Act was passed in 1979, granting the island limited self-government as an external territory of Australia.",
      "date": "1979"
    },
    {
      "headline": "Revocation of Self-Government",
      "text": "In 2015, the Australian government revoked Norfolk Island's self-government, making it a regional council under New South Wales law.",
      "date": "2015"
    }
  ]
}

