{
  "timeline": [
    {
      "headline": "Founding of ResearchGate",
      "text": "ResearchGate was founded in 2008 by Ijad Madisch, Sören Hofmayer, and Horst Fickenscher. The platform was created to facilitate collaboration and sharing among scientists and researchers.",
      "date": "2008"
    },
    {
      "headline": "First Funding Round",
      "text": "In 2010, ResearchGate secured its first round of funding, which was led by Benchmark Capital. This funding helped the platform to expand its operations and user base.",
      "date": "2010"
    },
    {
      "headline": "Significant User Growth",
      "text": "By 2012, ResearchGate had grown significantly, reaching 2 million users. This marked a major milestone in the platform's development as a leading academic social network.",
      "date": "2012"
    },
    {
      "headline": "Series B Funding",
      "text": "In 2013, ResearchGate raised $35 million in a Series B funding round. The investment was led by Bill Gates and Tenaya Capital, further boosting the platform's growth and development.",
      "date": "2013"
    },
    {
      "headline": "Largest Academic Social Network",
      "text": "By 2014, ResearchGate was recognized as the largest academic social network in terms of active users, according to a study by Nature.",
      "date": "2014"
    },
    {
      "headline": "Continued Growth and Development",
      "text": "ResearchGate continued to grow and develop, with a 2015-2016 survey indicating that a significant number of academics had profiles on the platform, rivaling those on Google Scholar.",
      "date": "2015"
    },
    {
      "headline": "Legal Challenges",
      "text": "In 2017, ResearchGate faced legal challenges from several academic publishers over copyright infringement issues related to the sharing of published papers on the platform.",
      "date": "2017"
    },
    {
      "headline": "Partnership with Wiley",
      "text": "In 2019, ResearchGate announced a partnership with Wiley, a major academic publisher, to facilitate the sharing of research articles and improve access to scientific content.",
      "date": "2019"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Invention of Parkesine",
      "text": "In 1856, Alexander Parkes invented Parkesine, the first man-made plastic, which was derived from cellulose.",
      "date": "1856"
    },
    {
      "headline": "Introduction of Bakelite",
      "text": "In 1907, Leo Baekeland invented Bakelite, the first fully synthetic plastic, marking the beginning of the modern plastics industry.",
      "date": "1907"
    },
    {
      "headline": "Development of Polyvinyl Chloride (PVC)",
      "text": "PVC was first polymerized between 1838-1872, but it was not until 1926 that Waldo Semon and the B.F. Goodrich Company developed a method to make it more flexible and easier to process.",
      "date": "1926"
    },
    {
      "headline": "Invention of Nylon",
      "text": "In 1935, Wallace Carothers and his team at DuPont invented nylon, the first synthetic fiber, which was introduced to the public in 1939.",
      "date": "1935"
    },
    {
      "headline": "Introduction of Polyethylene Terephthalate (PET)",
      "text": "In 1941, John Rex Whinfield and James Tennant Dickson, employees of the Calico Printers' Association of Manchester, patented the first polyester fiber, which became known as PET.",
      "date": "1941"
    },
    {
      "headline": "Development of High-Density Polyethylene (HDPE)",
      "text": "In 1953, Karl Ziegler and Erhard Holzkamp developed HDPE, which was later commercialized by the Phillips Petroleum Company.",
      "date": "1953"
    },
    {
      "headline": "Introduction of Polypropylene",
      "text": "In 1954, Giulio Natta and his assistant Paolo Chini developed isotactic polypropylene, which was later commercialized by the Montecatini company.",
      "date": "1954"
    },
    {
      "headline": "Invention of Kevlar",
      "text": "In 1965, Stephanie Kwolek, a chemist at DuPont, invented Kevlar, a high-strength material used in bulletproof vests and other applications.",
      "date": "1965"
    },
    {
      "headline": "Development of Bioplastics",
      "text": "In the early 21st century, the development of bioplastics began to gain momentum, with materials derived from renewable sources such as corn starch and sugarcane.",
      "date": "2000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Development of Student's t-test",
      "text": "The Student's t-test was developed by William Sealy Gosset, a chemist working for the Guinness Brewery in Dublin. He published the test under the pseudonym 'Student' in 1908.",
      "date": "1908"
    },
    {
      "headline": "Publication of 'The Probable Error of a Mean'",
      "text": "In 1908, William Sealy Gosset published his paper 'The Probable Error of a Mean' in the journal Biometrika. This paper introduced the t-test and the t-distribution.",
      "date": "1908"
    },
    {
      "headline": "Adoption in Statistical Analysis",
      "text": "Over the years following its publication, the Student's t-test became widely adopted in statistical analysis, particularly in fields such as psychology, medicine, and social sciences, where it is used to determine if there are significant differences between groups.",
      "date": "1920"
    },
    {
      "headline": "Integration into Statistical Software",
      "text": "With the advent of computers and statistical software in the mid-20th century, the Student's t-test was integrated into many statistical analysis programs, making it more accessible to researchers and analysts.",
      "date": "1950"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Joshua",
      "text": "Joshua, originally named Hoshea, son of Nun, from the tribe of Ephraim, was born in Egypt prior to the Exodus.",
      "date": "-1500"
    },
