    {
      "headline": "Succeeding Moses",
      "text": "After Moses' death, Joshua became the leader of the Israelite tribes and led them into the Promised Land.",
      "date": "-1406"
    },
    {
      "headline": "Battle of Jericho",
      "text": "Joshua led the Israelites in the Battle of Jericho, where the walls of the city fell after the Israelites marched around them for seven days.",
      "date": "-1406"
    },
    {
      "headline": "Conquest of Canaan",
      "text": "Joshua led the Israelites in a series of military campaigns to conquer the land of Canaan, as detailed in the Book of Joshua.",
      "date": "-1406 to -1399"
    },
    {
      "headline": "Division of the Land",
      "text": "Joshua oversaw the division of the conquered land among the twelve tribes of Israel.",
      "date": "-1399"
    },
    {
      "headline": "Death of Joshua",
      "text": "Joshua died at the age of 110 and was buried in Timnath-serah in the hill country of Ephraim.",
      "date": "-1390"
    }
  ]
}

