{
  "timeline": [
    {
      "headline": "Origin of Rum",
      "text": "Rum originated in the Caribbean in the 17th century. It was first distilled on the sugarcane plantations of the Caribbean islands.",
      "date": "1600"
    },
    {
      "headline": "First Recorded Distillation",
      "text": "The first recorded distillation of rum took place on the sugarcane plantations of the Caribbean in the 1620s.",
      "date": "1620"
    },
    {
      "headline": "Rum in Colonial America",
      "text": "By the 1650s, rum had become a popular drink in Colonial America, with the first rum distillery established on Staten Island in 1664.",
      "date": "1664"
    },
    {
      "headline": "Rum and the Slave Trade",
      "text": "Rum played a significant role in the triangular trade of the 17th and 18th centuries, where it was traded for slaves in Africa, who were then sold in the Caribbean.",
      "date": "1700"
    },
    {
      "headline": "Rum in the British Navy",
      "text": "In 1731, the British Navy adopted rum as part of the sailors' daily ration, replacing French brandy.",
      "date": "1731"
    },
    {
      "headline": "Abolition of the Rum Ration",
      "text": "The British Navy abolished the daily rum ration, known as the 'tot', on July 31, 1970, a day known as Black Tot Day.",
      "date": "1970-07-31"
    },
    {
      "headline": "Modern Rum Production",
      "text": "Today, rum is produced in nearly every major sugar-producing region of the world, with a wide variety of styles and flavors.",
      "date": "2023"
    }
  ]
}

