  "timeline": [
    {
      "headline": "Tongva and Tataviam Native American Tribes",
      "text": "Before European settlement, the San Fernando Valley was inhabited by the Tongva and Tataviam Native American tribes.",
      "date": "-0001"
    },
    {
      "headline": "Spanish Exploration",
      "text": "In 1769, the Spanish Portolá expedition, the first European land entry and exploration of the present-day state of California, entered the San Fernando Valley.",
      "date": "1769"
    },
    {
      "headline": "Mission San Fernando Rey de España",
      "text": "On September 8, 1797, the Mission San Fernando Rey de España was founded by the Spanish in the San Fernando Valley.",
      "date": "1797-09-08"
    },
    {
      "headline": "Mexican Secularization Act",
      "text": "In 1833, the Mexican government passed the Secularization Act, which led to the redistribution of mission lands, including those in the San Fernando Valley.",
      "date": "1833"
    },
    {
      "headline": "Treaty of Cahuenga",
      "text": "On January 13, 1847, the Treaty of Cahuenga was signed, ending hostilities in California during the Mexican-American War. This event took place in the San Fernando Valley.",
      "date": "1847-01-13"
    },
    {
      "headline": "California Statehood",
      "text": "California became a state of the United States on September 9, 1850, which included the San Fernando Valley.",
      "date": "1850-09-09"
    },
    {
      "headline": "Los Angeles Aqueduct",
      "text": "In 1913, the Los Angeles Aqueduct was completed, bringing water from the Owens Valley to Los Angeles and facilitating the development of the San Fernando Valley.",
      "date": "1913"
    },
    {
      "headline": "Annexation by Los Angeles",
      "text": "In 1915, parts of the San Fernando Valley were annexed by the city of Los Angeles, allowing for further urban development.",
      "date": "1915"
    },
    {
      "headline": "Warner Bros. Studios",
      "text": "In 1926, Warner Bros. Studios was established in Burbank, a city within the San Fernando Valley.",
      "date": "1926"
    },
    {
      "headline": "Walt Disney Studios",
      "text": "In 1939, Walt Disney Studios moved to its current location in Burbank, within the San Fernando Valley.",
      "date": "1939"
    },
    {
      "headline": "Universal Studios Hollywood",
      "text": "In 1964, Universal Studios Hollywood theme park opened in the San Fernando Valley, becoming a major tourist attraction.",
      "date": "1964"
    },
    {
      "headline": "Northridge Earthquake",
      "text": "On January 17, 1994, the Northridge earthquake struck the San Fernando Valley, causing widespread damage and loss of life.",
      "date": "1994-01-17"
    }
  ]
}

