  "timeline": [
    {
      "headline": "Earliest Records of Acupuncture",
      "text": "The earliest records of acupuncture date back to the Han dynasty in China, around 100 BCE. These records describe the use of needles to stimulate specific points on the body.",
      "date": "-0100"
    },
    {
      "headline": "The Huangdi Neijing",
      "text": "The Huangdi Neijing, also known as the Yellow Emperor's Inner Canon, is one of the earliest and most important texts in Chinese medicine. It was compiled around the 2nd century BCE and includes references to acupuncture.",
      "date": "-0200"
    },
    {
      "headline": "Acupuncture in the Tang Dynasty",
      "text": "During the Tang dynasty (618–907 CE), acupuncture became more systematized and widely practiced. The government established medical schools that included acupuncture in their curriculum.",
      "date": "0618"
    },
    {
      "headline": "Acupuncture in the Ming Dynasty",
      "text": "In the Ming dynasty (1368–1644), acupuncture reached new heights of popularity. The publication of the 'Great Compendium of Acupuncture and Moxibustion' by Yang Jizhou in 1601 was a significant milestone.",
      "date": "1601"
    },
    {
      "headline": "Decline in Popularity",
      "text": "During the Qing dynasty (1644–1912), acupuncture began to decline in popularity as Western medicine was introduced to China.",
      "date": "1644"
    },
    {
      "headline": "Revival in the 20th Century",
      "text": "In the 20th century, particularly after the establishment of the People's Republic of China in 1949, acupuncture experienced a revival as part of the government's promotion of traditional Chinese medicine.",
      "date": "1949"
    },
    {
      "headline": "Introduction to the West",
      "text": "Acupuncture was introduced to the Western world in the 1970s, gaining attention after U.S. President Richard Nixon's visit to China in 1972.",
      "date": "1972"
    },
    {
      "headline": "World Health Organization Recognition",
      "text": "In 1979, the World Health Organization recognized acupuncture as a valid treatment for certain conditions, further boosting its popularity worldwide.",
      "date": "1979"
    }
  ]
}

