{
  "timeline": [
    {
      "headline": "Formation of Thuringia",
      "text": "The region of Thuringia was first mentioned in historical records as a distinct area in the 6th century, inhabited by the Thuringii tribe.",
      "date": "-0500"
    },
    {
      "headline": "Thuringian Kingdom",
      "text": "The Thuringian Kingdom was established around the 5th century and lasted until it was conquered by the Franks in 531.",
      "date": "0531"
    },
    {
      "headline": "Frankish Conquest",
      "text": "In 531, the Thuringian Kingdom was conquered by the Franks, leading to its integration into the Frankish Empire.",
      "date": "0531"
    },
    {
      "headline": "Creation of the Landgraviate of Thuringia",
      "text": "The Landgraviate of Thuringia was established in 1130, becoming a significant principality within the Holy Roman Empire.",
      "date": "1130"
    },
    {
      "headline": "Thuringian War of Succession",
      "text": "The Thuringian War of Succession took place from 1247 to 1264, following the death of the last Ludowingian landgrave, leading to a division of territories.",
      "date": "1247"
    },
    {
      "headline": "Incorporation into the Electorate of Saxony",
      "text": "In 1485, Thuringia was divided between the Ernestine and Albertine branches of the Wettin dynasty, with much of it becoming part of the Electorate of Saxony.",
      "date": "1485"
    },
    {
      "headline": "Formation of the Duchy of Saxe-Weimar",
      "text": "In 1572, the Duchy of Saxe-Weimar was formed as part of the Ernestine duchies, marking a significant political restructuring in Thuringia.",
      "date": "1572"
    },
    {
      "headline": "Weimar Republic Era",
      "text": "After World War I, Thuringia became part of the newly formed Weimar Republic in 1919, marking a shift to a republican form of government.",
      "date": "1919"
    },
    {
      "headline": "Establishment of the Free State of Thuringia",
      "text": "The Free State of Thuringia was officially established on May 1, 1920, as part of the Weimar Republic.",
      "date": "1920-05-01"
    },
    {
      "headline": "Thuringia in Nazi Germany",
      "text": "During the Nazi regime, Thuringia was reorganized as part of the administrative changes in Germany, losing its status as a free state.",
      "date": "1933"
    },
    {
      "headline": "Reestablishment after World War II",
      "text": "After World War II, Thuringia was reestablished as a state within the Soviet occupation zone in 1945.",
      "date": "1945"
    },
    {
      "headline": "Dissolution into East Germany",
      "text": "In 1952, Thuringia was dissolved as part of the administrative reorganization in East Germany, being divided into several districts.",
      "date": "1952"
    },
    {
      "headline": "Reformation of Thuringia",
      "text": "Following German reunification, Thuringia was reformed as a federal state of Germany on October 3, 1990.",
      "date": "1990-10-03"
    }
  ]
}

