    {
      "headline": "Beginning of the Golden Age of Piracy",
      "text": "The Golden Age of Piracy is commonly considered to have begun in the 1650s, when maritime piracy became a significant factor in the histories of the North Atlantic and Indian Oceans.",
      "date": "1650"
    },
    {
      "headline": "Henry Morgan's Raid on Panama",
      "text": "In 1671, the pirate Henry Morgan led a successful raid on Panama City, one of the most significant and lucrative pirate attacks of the era.",
      "date": "1671"
    },
    {
      "headline": "Pirate Haven of Nassau",
      "text": "By 1713, Nassau in the Bahamas had become a notorious pirate haven, attracting many of the most famous pirates of the era.",
      "date": "1713"
    },
    {
      "headline": "Blackbeard's Blockade of Charleston",
      "text": "In May 1718, the infamous pirate Blackbeard blockaded the port of Charleston, South Carolina, demanding and receiving a chest of medicine.",
      "date": "1718-05"
    },
    {
      "headline": "Capture and Death of Blackbeard",
      "text": "On November 22, 1718, Blackbeard was killed in a battle with British naval forces off the coast of Ocracoke Island, North Carolina.",
      "date": "1718-11-22"
    },
    {
      "headline": "Trial and Execution of Pirates in London",
      "text": "In 1723, a large number of pirates were tried and executed in London, marking a significant crackdown on piracy.",
      "date": "1723"
    },
    {
      "headline": "End of the Golden Age of Piracy",
      "text": "The Golden Age of Piracy is generally considered to have ended in the 1730s, as increased naval patrols and anti-piracy laws led to the decline of piracy.",
      "date": "1730"
    }
  ]
}

