      "headline": "Outbreak of the First Indochina War",
      "text": "The First Indochina War began on 19 December 1946, when Việt Minh forces launched attacks against French positions in Hanoi, marking the start of the conflict.",
      "date": "1946-12-19"
    },
    {
      "headline": "Battle of Hòa Bình",
      "text": "The Battle of Hòa Bình took place from 10 November 1951 to 25 February 1952. It was a significant confrontation between French forces and the Việt Minh, resulting in a strategic withdrawal by the French.",
      "date": "1951-11"
    },
    {
      "headline": "Operation Castor",
      "text": "On 20 November 1953, the French launched Operation Castor, an airborne operation to establish a fortified airhead at Điện Biên Phủ.",
      "date": "1953-11-20"
    },
    {
      "headline": "Battle of Điện Biên Phủ",
      "text": "The Battle of Điện Biên Phủ occurred from 13 March to 7 May 1954. It was a decisive engagement that ended with a Việt Minh victory, leading to the end of French colonial rule in Indochina.",
      "date": "1954-03-13"
    },
    {
      "headline": "Geneva Conference",
      "text": "The Geneva Conference took place from 26 April to 21 July 1954, resulting in the Geneva Accords, which temporarily divided Vietnam at the 17th parallel and marked the end of the First Indochina War.",
      "date": "1954-07-21"
    }
  ]
}

