    {
      "headline": "Reign of Ulugh Beg",
      "text": "Ulugh Beg, a grandson of Timur, ruled from 1447 to 1449 and was known for his contributions to astronomy and science.",
      "date": "1447"
    },
    {
      "headline": "Assassination of Ulugh Beg",
      "text": "Ulugh Beg was assassinated in 1449, which further weakened the Timurid Empire.",
      "date": "1449"
