{
  "timeline": [
    {
      "headline": "Initiation of COINTELPRO",
      "text": "COINTELPRO was initiated by the FBI in 1956 to monitor and disrupt the activities of the Communist Party USA and other organizations deemed subversive.",
      "date": "1956"
    },
    {
      "headline": "Expansion to Civil Rights Movement",
      "text": "In the early 1960s, COINTELPRO expanded its focus to include civil rights organizations, notably targeting leaders like Martin Luther King Jr. and groups such as the Southern Christian Leadership Conference (SCLC).",
      "date": "1960"
    },
    {
      "headline": "Targeting of Black Power Movement",
      "text": "By the late 1960s, COINTELPRO intensified its efforts against the Black Power movement, including groups like the Black Panther Party, using tactics such as infiltration, surveillance, and the spread of misinformation.",
      "date": "1967"
    },
    {
      "headline": "Focus on Anti-Vietnam War Activists",
      "text": "COINTELPRO also targeted anti-Vietnam War activists, aiming to disrupt and discredit organizations and individuals opposing the war.",
      "date": "1968"
    },
    {
      "headline": "Exposure of COINTELPRO",
      "text": "In March 1971, a group of activists known as the Citizens' Commission to Investigate the FBI broke into an FBI office in Media, Pennsylvania, and discovered documents revealing the existence of COINTELPRO, leading to public outcry and increased scrutiny.",
      "date": "1971-03"
    },
    {
      "headline": "Termination of COINTELPRO",
      "text": "Following the exposure and subsequent investigations, COINTELPRO was officially terminated by the FBI in 1971.",
      "date": "1971"
    },
    {
      "headline": "Senate Church Committee Investigation",
      "text": "In 1975, the Church Committee, a U.S. Senate committee, conducted an investigation into COINTELPRO and other intelligence abuses, leading to significant reforms in the oversight of intelligence activities.",
      "date": "1975"
    }
  ]
}

