  "timeline": [
    {
      "headline": "Citizens United Produces Documentary",
      "text": "In 2008, Citizens United, a nonprofit corporation, produced a documentary critical of then-Senator Hillary Clinton, who was a candidate in the Democratic Party's 2008 presidential primary elections.",
      "date": "2008"
    },
    {
      "headline": "Federal Election Commission Blocks Documentary",
      "text": "In 2008, the Federal Election Commission (FEC) blocked the broadcast of the documentary, citing the Bipartisan Campaign Reform Act (BCRA), which prohibited corporations and unions from using their general treasury funds for 'electioneering communications' or for speech that expressly advocated the election or defeat of a candidate.",
      "date": "2008"
    },
    {
      "headline": "Citizens United Files Lawsuit",
      "text": "Citizens United filed a lawsuit against the FEC in the United States District Court for the District of Columbia, seeking an injunction against the application of the BCRA to its documentary.",
      "date": "2008"
    },
    {
      "headline": "Supreme Court Hears Oral Arguments",
      "text": "On March 24, 2009, the Supreme Court heard oral arguments in the case of Citizens United v. Federal Election Commission.",
      "date": "2009-03-24"
    },
    {
      "headline": "Reargument Ordered by Supreme Court",
      "text": "On June 29, 2009, the Supreme Court ordered reargument of the case, asking the parties to address whether it should overrule its earlier decisions in Austin v. Michigan Chamber of Commerce and portions of McConnell v. FEC.",
      "date": "2009-06-29"
    },
    {
      "headline": "Reargument Takes Place",
      "text": "The reargument took place on September 9, 2009, focusing on the broader constitutional questions regarding the First Amendment and campaign finance laws.",
      "date": "2009-09-09"
    },
    {
      "headline": "Supreme Court Decision Announced",
      "text": "On January 21, 2010, the Supreme Court issued its decision in Citizens United v. FEC, ruling 5-4 that the First Amendment prohibits the government from restricting independent expenditures for political campaigns by corporations, nonprofit organizations, labor unions, and other associations.",
      "date": "2010-01-21"
    },
    {
      "headline": "Impact on Campaign Finance",
      "text": "The decision led to the creation of super PACs and a significant increase in the amount of money spent on political campaigns, as it allowed corporations and unions to spend unlimited amounts on political advocacy.",
      "date": "2010"
    }
  ]
}

