{
  "timeline": [
    {
      "headline": "Conrad Waddington Coins 'Epigenetics'",
      "text": "In 1942, British developmental biologist Conrad Waddington coined the term 'epigenetics' to describe the interactions between genes and their environment that bring the phenotype into being.",
      "date": "1942"
    },
    {
      "headline": "Discovery of DNA Methylation",
      "text": "In the 1950s, researchers discovered DNA methylation, a key epigenetic mechanism, which involves the addition of a methyl group to DNA, affecting gene expression.",
      "date": "1950"
    },
    {
      "headline": "Histone Modification Identified",
      "text": "In the 1960s, scientists identified histone modification as another epigenetic mechanism. Histones are proteins that DNA wraps around, and their modification can influence gene expression.",
      "date": "1960"
    },
    {
      "headline": "Imprinting and Epigenetic Inheritance",
      "text": "In the 1980s, the concept of genomic imprinting was discovered, showing that some genes are expressed in a parent-of-origin-specific manner, an important aspect of epigenetic inheritance.",
      "date": "1980"
    },
    {
      "headline": "Epigenome Mapping Begins",
      "text": "In the early 2000s, projects to map the human epigenome began, aiming to catalog all the chemical changes to DNA and histone proteins that regulate gene expression.",
      "date": "2000"
    },
    {
      "headline": "Epigenetics and Cancer Research",
      "text": "In the 2000s, significant research emerged linking epigenetic changes to cancer, showing how alterations in DNA methylation and histone modification can lead to tumorigenesis.",
      "date": "2000"
    },
    {
      "headline": "CRISPR and Epigenetic Editing",
      "text": "In the 2010s, advancements in CRISPR technology allowed for precise editing of epigenetic marks, opening new avenues for research and potential therapies.",
      "date": "2010"
    }
  ]
}

