{
  "timeline": [
    {
      "headline": "Origin of the Term 'Lynching'",
      "text": "The term 'lynching' is believed to have originated during the American Revolutionary War. It is often attributed to Charles Lynch, a Virginia planter and justice of the peace, who led an irregular court to punish Loyalists. The term 'Lynch Law' was used to describe these extrajudicial punishments.",
      "date": "1776"
    },
    {
      "headline": "Peak of Lynching in the United States",
      "text": "Lynching reached its peak in the United States during the late 19th and early 20th centuries. It was most prevalent in the Southern United States, where it was used as a tool of racial control and intimidation against African Americans.",
      "date": "1890"
    },
    {
      "headline": "NAACP Anti-Lynching Campaign",
      "text": "In the early 20th century, the National Association for the Advancement of Colored People (NAACP) began a campaign against lynching. They published reports and statistics to raise awareness and lobbied for federal anti-lynching legislation.",
      "date": "1910"
    },
    {
      "headline": "Dyer Anti-Lynching Bill",
      "text": "The Dyer Anti-Lynching Bill was introduced in the United States Congress in 1918 by Congressman Leonidas C. Dyer. It aimed to establish lynching as a federal crime. The bill passed the House of Representatives in 1922 but was filibustered in the Senate.",
      "date": "1922"
    },
    {
      "headline": "Decline of Lynching in the United States",
      "text": "Lynching began to decline in the United States after the 1930s due to increased awareness, activism, and changes in social attitudes. The Great Migration of African Americans from the rural South to urban areas in the North also contributed to the decline.",
      "date": "1930"
    },
    {
      "headline": "Emmett Till Lynching",
      "text": "In 1955, the lynching of 14-year-old Emmett Till in Mississippi became a catalyst for the Civil Rights Movement. His murder and the subsequent trial, where the accused were acquitted, drew national and international attention to racial violence in the United States.",
      "date": "1955-08-28"
    },
    {
      "headline": "Federal Anti-Lynching Legislation",
      "text": "Despite numerous attempts, federal anti-lynching legislation was not passed until the 21st century. In 2020, the Emmett Till Antilynching Act was passed by the U.S. House of Representatives, making lynching a federal hate crime.",
      "date": "2020"
    }
  ]
}

