{
  "timeline": [
    {
      "headline": "Partition of British India",
      "text": "The partition of British India led to the creation of the dominions of India and Pakistan on August 15, 1947. This event marked the beginning of the complex and often hostile relationship between the two nations.",
      "date": "1947-08-15"
    },
    {
      "headline": "First Indo-Pakistani War",
      "text": "The First Indo-Pakistani War, also known as the First Kashmir War, began in October 1947 and ended in December 1948. It was fought over the princely state of Jammu and Kashmir.",
      "date": "1947-10"
    },
    {
      "headline": "Indo-Pakistani War of 1965",
      "text": "The Indo-Pakistani War of 1965 was a culmination of skirmishes that took place between April 1965 and September 1965 between India and Pakistan. The conflict began following Pakistan's Operation Gibraltar, which was designed to infiltrate forces into Jammu and Kashmir to cause insurgency against Indian rule.",
      "date": "1965-04"
    },
    {
      "headline": "Indo-Pakistani War of 1971",
      "text": "The Indo-Pakistani War of 1971 was a military confrontation between India and Pakistan that occurred during the Bangladesh Liberation War in East Pakistan. It lasted from December 3, 1971, to December 16, 1971, and resulted in the creation of Bangladesh.",
      "date": "1971-12-03"
    },
    {
      "headline": "Siachen Conflict",
      "text": "The Siachen Conflict began in 1984 when India launched Operation Meghdoot to capture the Siachen Glacier in the disputed Kashmir region. The conflict is ongoing, with both countries maintaining a military presence in the region.",
      "date": "1984"
    },
    {
      "headline": "Kargil War",
      "text": "The Kargil War was fought between India and Pakistan from May to July 1999 in the Kargil district of Kashmir and elsewhere along the Line of Control (LoC). The conflict was initiated by the infiltration of Pakistani soldiers and militants into positions on the Indian side of the LoC.",
      "date": "1999-05"
    },
    {
      "headline": "2001–2002 India–Pakistan Standoff",
      "text": "The 2001–2002 India–Pakistan standoff was a military standoff between India and Pakistan that was initiated in the aftermath of the Indian Parliament attack on December 13, 2001. The standoff lasted until October 2002.",
      "date": "2001-12-13"
    },
    {
      "headline": "Mumbai Attacks",
      "text": "The 2008 Mumbai attacks were a series of terrorist attacks that took place in November 2008, when 10 members of Lashkar-e-Taiba, an Islamist terrorist organization based in Pakistan, carried out 12 coordinated shooting and bombing attacks lasting four days across Mumbai.",
      "date": "2008-11-26"
    },
    {
      "headline": "2016 Uri Attack",
      "text": "The Uri attack was a terrorist attack by four heavily armed militants on September 18, 2016, near the town of Uri in the Indian-administered state of Jammu and Kashmir. It resulted in the death of 19 Indian soldiers.",
      "date": "2016-09-18"
    },
    {
      "headline": "2019 Pulwama Attack",
      "text": "The Pulwama attack occurred on February 14, 2019, when a convoy of vehicles carrying Indian security personnel on the Jammu Srinagar National Highway was attacked by a vehicle-borne suicide bomber in the Pulwama district of Jammu and Kashmir, leading to heightened tensions between India and Pakistan.",
      "date": "2019-02-14"
    }
  ]
}

