    },
    {
      "headline": "Spanish Discovery",
      "text": "In 1499, Bonaire was discovered by Alonso de Ojeda and Amerigo Vespucci, who claimed it for Spain.",
      "date": "1499"
    },
    {
      "headline": "Dutch Control",
      "text": "In 1636, the Dutch West India Company took control of Bonaire, establishing it as a plantation island.",
      "date": "1636"
    },
    {
      "headline": "British Occupation",
      "text": "During the Napoleonic Wars, Bonaire was occupied by the British from 1800 to 1803 and again from 1807 to 1816.",
      "date": "1800"
    },
    {
      "headline": "Return to Dutch Rule",
      "text": "In 1816, Bonaire was returned to Dutch control following the end of the Napoleonic Wars.",
      "date": "1816"
    },
    {
      "headline": "Abolition of Slavery",
      "text": "Slavery was abolished in Bonaire on July 1, 1863, as part of the Dutch abolition of slavery in its colonies.",
      "date": "1863-07-01"
    },
    {
      "headline": "World War II",
      "text": "During World War II, Bonaire was used as a military base by the Allies.",
      "date": "1940"
    },
    {
      "headline": "Becoming a Special Municipality",
      "text": "On October 10, 2010, Bonaire became a special municipality of the Netherlands following the dissolution of the Netherlands Antilles.",
      "date": "2010-10-10"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Isma'il ibn Jafar",
      "text": "Isma'il ibn Jafar, the sixth Imam of the Isma'ili Shia Muslims, was born in 719 CE.",
      "date": "0719"
    },
    {
      "headline": "Death of Isma'il ibn Jafar",
      "text": "Isma'il ibn Jafar died in 755 CE, leading to a split among his followers and the formation of the Isma'ili sect.",
      "date": "0755"
    },
    {
      "headline": "Establishment of the Fatimid Caliphate",
      "text": "In 909 CE, the Fatimid Caliphate was established in North Africa by the Isma'ili Imam Abdullah al-Mahdi Billah, marking a significant political and religious achievement for the Isma'ili community.",
      "date": "0909"
    },
    {
      "headline": "Conquest of Egypt by the Fatimids",
      "text": "In 969 CE, the Fatimid Caliphate conquered Egypt, establishing Cairo as their capital and further expanding Isma'ili influence.",
      "date": "0969"
    },
    {
      "headline": "Construction of Al-Azhar University",
      "text": "In 970 CE, the Fatimids founded Al-Azhar University in Cairo, which became a major center of learning and Isma'ili scholarship.",
      "date": "0970"
    },
    {
      "headline": "Death of Al-Hakim bi-Amr Allah",
      "text": "In 1021 CE, the Fatimid Caliph Al-Hakim bi-Amr Allah disappeared under mysterious circumstances, leading to significant changes within the Isma'ili community.",
      "date": "1021"
    },
    {
      "headline": "Nizari-Musta'li Schism",
      "text": "In 1094 CE, a major schism occurred within the Isma'ili community between the Nizari and Musta'li factions following the death of the Fatimid Caliph al-Mustansir Billah.",
      "date": "1094"
    },
    {
      "headline": "Assassination of Nizam al-Mulk",
      "text": "In 1092 CE, the Nizari Isma'ilis, led by Hassan-i Sabbah, assassinated the Seljuk vizier Nizam al-Mulk, marking the beginning of the Nizari Isma'ili's use of assassination as a political tool.",
      "date": "1092"
    },
    {
      "headline": "Fall of Alamut Castle",
      "text": "In 1256 CE, the Mongols captured and destroyed Alamut Castle, the stronghold of the Nizari Isma'ilis, significantly weakening their power.",
      "date": "1256"
    },
    {
      "headline": "Aga Khan I becomes Imam",
      "text": "In 1817 CE, Hasan Ali Shah, known as Aga Khan I, became the 46th Imam of the Nizari Isma'ilis, marking the beginning of the modern period of Isma'ili leadership.",
      "date": "1817"
    }
  ]
}

