{
  "timeline": [
    {
      "headline": "Birth of Kwame Nkrumah",
      "text": "Kwame Nkrumah was born on September 21, 1909, in Nkroful, Gold Coast (now Ghana).",
      "date": "1909-09-21"
    },
    {
      "headline": "Education in the United States",
      "text": "In 1935, Nkrumah traveled to the United States to pursue higher education. He attended Lincoln University in Pennsylvania and later the University of Pennsylvania, where he studied theology and philosophy.",
      "date": "1935"
    },
    {
      "headline": "Move to the United Kingdom",
      "text": "In 1945, Nkrumah moved to London, where he became involved in the Pan-African movement and helped organize the Fifth Pan-African Congress in Manchester.",
      "date": "1945"
    },
    {
      "headline": "Return to Gold Coast and Political Involvement",
      "text": "Nkrumah returned to the Gold Coast in 1947 and became the General Secretary of the United Gold Coast Convention (UGCC), a political party advocating for self-governance.",
      "date": "1947"
    },
    {
      "headline": "Formation of the Convention People's Party",
      "text": "In 1949, Nkrumah founded the Convention People's Party (CPP), which called for 'self-government now'.",
      "date": "1949"
    },
    {
      "headline": "Arrest and Imprisonment",
      "text": "In 1950, Nkrumah was arrested and imprisoned by the colonial authorities for leading a series of strikes and protests.",
      "date": "1950"
    },
    {
      "headline": "Election as Prime Minister of the Gold Coast",
      "text": "In 1952, while still imprisoned, Nkrumah's CPP won the general elections, and he was released to become the first Prime Minister of the Gold Coast.",
      "date": "1952"
    },
    {
      "headline": "Independence of Ghana",
      "text": "On March 6, 1957, the Gold Coast gained independence from Britain and was renamed Ghana. Nkrumah became the first Prime Minister of the newly independent nation.",
      "date": "1957-03-06"
    },
    {
      "headline": "Becoming the First President of Ghana",
      "text": "In 1960, Ghana became a republic, and Nkrumah was elected as the first President of Ghana.",
      "date": "1960"
    },
    {
      "headline": "Founding Member of the Organization of African Unity",
      "text": "In 1963, Nkrumah was a founding member of the Organization of African Unity (OAU), which aimed to promote unity and cooperation among African states.",
      "date": "1963"
    },
    {
      "headline": "Awarded the Lenin Peace Prize",
      "text": "In 1962, Nkrumah was awarded the Lenin Peace Prize by the Soviet Union for his efforts in promoting peace and anti-colonialism.",
      "date": "1962"
    },
    {
      "headline": "Overthrown in a Coup",
      "text": "On February 24, 1966, while Nkrumah was on a state visit to North Vietnam and China, his government was overthrown in a military coup.",
      "date": "1966-02-24"
    },
    {
      "headline": "Death of Kwame Nkrumah",
      "text": "Kwame Nkrumah died on April 27, 1972, in Bucharest, Romania, where he was receiving medical treatment for cancer.",
      "date": "1972-04-27"
    }
  ]
}

