{
  "timeline": [
    {
      "headline": "Publication of 'The Call of Cthulhu'",
      "text": "'The Call of Cthulhu', the short story by H. P. Lovecraft that introduced the creature Cthulhu and laid the foundation for the Cthulhu Mythos, was first published in the pulp magazine Weird Tales in February 1928.",
      "date": "1928-02"
    },
    {
      "headline": "Coining of the Term 'Cthulhu Mythos'",
      "text": "August Derleth, a contemporary correspondent and protégé of Lovecraft, coined the term 'Cthulhu Mythos' to identify the settings, tropes, and lore that were employed by Lovecraft and his literary successors. This occurred after Lovecraft's death in 1937, as Derleth worked to organize and expand Lovecraft's fictional universe.",
      "date": "1937"
    },
    {
      "headline": "Posthumous Expansion by August Derleth",
      "text": "Following Lovecraft's death in 1937, August Derleth began to expand the Cthulhu Mythos by writing new stories and organizing Lovecraft's works into a coherent mythological framework. Derleth's contributions included the introduction of the 'Elder Gods' and a more structured cosmic battle between good and evil.",
      "date": "1937"
    },
    {
      "headline": "Publication of 'The Outsider and Others'",
      "text": "In 1939, Arkham House, a publishing company founded by August Derleth and Donald Wandrei, published 'The Outsider and Others', the first collection of Lovecraft's works. This marked the beginning of the wider dissemination of the Cthulhu Mythos.",
      "date": "1939"
    },
    {
      "headline": "Influence on Popular Culture",
      "text": "Throughout the 20th century and into the 21st, the Cthulhu Mythos has had a significant influence on popular culture, inspiring a wide range of adaptations and references in literature, film, games, and other media.",
      "date": "2000"
    }
  ]
}

