{
  "timeline": [
    {
      "headline": "Start of the Age of Discovery",
      "text": "The Age of Discovery began in the late 15th century, marked by European exploration and expansion across the globe.",
      "date": "1492"
    },
    {
      "headline": "Christopher Columbus's First Voyage",
      "text": "On August 3, 1492, Christopher Columbus set sail from Spain in an attempt to find a new route to Asia. He reached the Americas on October 12, 1492.",
      "date": "1492-08-03"
    },
    {
      "headline": "Vasco da Gama Reaches India",
      "text": "In 1498, Vasco da Gama reached Calicut on the Malabar Coast of India, establishing a sea route from Europe to Asia.",
      "date": "1498"
    },
    {
      "headline": "Treaty of Tordesillas",
      "text": "Signed on June 7, 1494, the Treaty of Tordesillas divided the newly discovered lands outside Europe between Portugal and Spain along a meridian 370 leagues west of the Cape Verde islands.",
      "date": "1494-06-07"
    },
    {
      "headline": "Ferdinand Magellan's Expedition",
      "text": "In 1519, Ferdinand Magellan led the first expedition to circumnavigate the globe, although he was killed in the Philippines in 1521. The expedition was completed by Juan Sebastián Elcano in 1522.",
      "date": "1519"
    },
    {
      "headline": "Hernán Cortés Conquers the Aztec Empire",
      "text": "In 1521, Hernán Cortés completed the conquest of the Aztec Empire, marking a significant expansion of Spanish influence in the Americas.",
      "date": "1521"
    },
    {
      "headline": "Francisco Pizarro Conquers the Inca Empire",
      "text": "In 1533, Francisco Pizarro captured the Inca capital of Cusco, leading to the fall of the Inca Empire.",
      "date": "1533"
    },
    {
      "headline": "Establishment of the First English Colony in America",
      "text": "In 1607, the English established their first permanent colony in America at Jamestown, Virginia.",
      "date": "1607"
    },
    {
      "headline": "Dutch East India Company Founded",
      "text": "In 1602, the Dutch East India Company was established, becoming a major force in the spice trade and colonial expansion in Asia.",
      "date": "1602"
    },
    {
      "headline": "End of the Age of Discovery",
      "text": "The Age of Discovery is generally considered to have ended in the early 17th century as European powers established colonies and trade networks worldwide.",
      "date": "1600"
    }
  ]
}

