    },
    {
      "headline": "Introduction of Nonavalent HPV Vaccine",
      "text": "The nonavalent HPV vaccine was introduced, providing additional protection against HPV types 31, 33, 45, 52, and 58, further expanding the prevention of HPV-related cancers.",
      "date": "2014"
    },
    {
      "headline": "WHO Recommendations for HPV Vaccination",
      "text": "The World Health Organization (WHO) recommends a one or two-dose schedule for girls aged 9–14 years, the same for girls and women aged 15–20 years, and two doses with a 6-month interval for women older than 21 years.",
      "date": "2017"
    }
  ]
