      "headline": "Confederate Offensive into Missouri",
      "text": "Earlier in 1862, Confederate Major General Thomas C. Hindman made an abortive offensive into southwestern Missouri from Arkansas.",
      "date": "1862"
    },
    {
      "headline": "Union Pursuit into Arkansas",
      "text": "Union troops under Brigadier General James G. Blunt followed Hindman into northwestern Arkansas.",
      "date": "1862"
    },
    {
      "headline": "Skirmish at Cane Hill",
      "text": "In early November 1862, a detachment of Blunt's command led by Colonel William F. Cloud defeated a small Confederate force commanded by Colonel Emmett MacDonald in the Cane Hill area.",
      "date": "1862-11"
    },
    {
      "headline": "Hindman's Plan to Attack Blunt",
      "text": "Confederate General Hindman saw an opportunity to attack Blunt while his division was separated from the rest of the Union Army of the Frontier.",
      "date": "1862"
    },
    {
      "headline": "Marmaduke Sent to Cane Hill",
      "text": "Hindman sent a force under Brigadier General John S. Marmaduke to Cane Hill, also known as Boonsboro, to collect supplies.",
      "date": "1862"
    },
    {
      "headline": "Battle of Cane Hill",
      "text": "The Battle of Cane Hill was fought on November 28, 1862, between Union and Confederate forces in northwestern Arkansas, near the town of Cane Hill.",
      "date": "1862-11-28"
    }
  ]
}

