    {
      "headline": "Formation of the Syrian Democratic Forces",
      "text": "The Syrian Democratic Forces (SDF) were founded on 10 October 2015. The SDF is a Kurdish-led coalition of U.S.-backed left-wing ethnic militias and rebel groups, serving as the official military wing of the Autonomous Administration of North and East Syria.",
      "date": "2015-10-10"
    },
    {
      "headline": "Battle of al-Hawl",
      "text": "In late 2015, the SDF launched the Battle of al-Hawl against ISIL, capturing the town of al-Hawl in northeastern Syria by November 13, 2015.",
      "date": "2015-11-13"
    },
    {
      "headline": "Capture of Tishrin Dam",
      "text": "On December 26, 2015, the SDF captured the Tishrin Dam from ISIL, a strategic victory that allowed them to cross the Euphrates River.",
      "date": "2015-12-26"
    },
    {
      "headline": "Manbij Offensive",
      "text": "The SDF launched the Manbij offensive on May 31, 2016, to capture the city of Manbij from ISIL. The city was fully captured by August 12, 2016.",
      "date": "2016-08-12"
    },
    {
      "headline": "Raqqa Campaign",
      "text": "The SDF began the Raqqa campaign on November 6, 2016, to liberate Raqqa, the de facto capital of ISIL in Syria. The city was fully captured on October 17, 2017.",
      "date": "2017-10-17"
    },
    {
      "headline": "Deir ez-Zor Campaign",
      "text": "The SDF launched the Deir ez-Zor campaign on September 9, 2017, to capture ISIL-held areas in the Deir ez-Zor Governorate. The campaign resulted in significant territorial gains.",
      "date": "2017-09-09"
    },
    {
      "headline": "Capture of Hajin",
      "text": "On December 14, 2018, the SDF captured the town of Hajin, one of the last significant ISIL strongholds in Syria.",
      "date": "2018-12-14"
    },
    {
      "headline": "Battle of Baghuz Fawqani",
      "text": "The SDF launched the Battle of Baghuz Fawqani in early 2019, capturing the last ISIL-held territory in Syria on March 23, 2019, marking the territorial defeat of ISIL.",
      "date": "2019-03-23"
    },
    {
      "headline": "Turkish Offensive in Northeast Syria",
      "text": "In October 2019, Turkey launched a military offensive against the SDF in northeastern Syria, leading to significant territorial and strategic changes in the region.",
      "date": "2019-10"
    }
  ]
}

