{
  "timeline": [
    {
      "headline": "Beginning of the Heian Period",
      "text": "In 794, the Heian period began when Emperor Kammu moved the capital of Japan to Heian-kyō, which is present-day Kyoto. This marked the start of a new era in Japanese history.",
      "date": "0794"
    },
    {
      "headline": "Development of Kana Scripts",
      "text": "During the early Heian period, two syllabaries unique to Japan, katakana and hiragana, were developed. These scripts allowed for the creation of a distinct Japanese literature.",
      "date": "0800"
    },
    {
      "headline": "Rise of the Fujiwara Clan",
      "text": "The Fujiwara clan rose to power during the Heian period, exerting significant influence over the imperial court by marrying their daughters into the imperial family.",
      "date": "0850"
    },
    {
      "headline": "Publication of the Kokin Wakashū",
      "text": "Around 905, the Kokin Wakashū, an anthology of waka poetry, was compiled by order of Emperor Daigo. It is one of the most important collections of Japanese poetry.",
      "date": "0905"
    },
    {
      "headline": "The Tale of Genji",
      "text": "In the early 11th century, Murasaki Shikibu wrote 'The Tale of Genji,' considered the world's first novel. This work is a masterpiece of Japanese literature and provides insight into the Heian court life.",
      "date": "1008"
    },
    {
      "headline": "The Pillow Book",
      "text": "Sei Shōnagon, a court lady, wrote 'The Pillow Book' around the year 1002. It is a collection of essays, lists, and anecdotes that depict court life during the Heian period.",
      "date": "1002"
    },
    {
      "headline": "Decline of the Fujiwara Clan",
      "text": "By the late 11th century, the power of the Fujiwara clan began to decline as other clans, such as the Taira and Minamoto, gained influence.",
      "date": "1086"
    },
    {
      "headline": "Genpei War",
      "text": "The Genpei War, a conflict between the Taira and Minamoto clans, took place from 1180 to 1185. This war led to the end of the Heian period and the rise of the Kamakura shogunate.",
      "date": "1180"
    },
    {
      "headline": "End of the Heian Period",
      "text": "The Heian period officially ended in 1185 with the defeat of the Taira clan by the Minamoto clan at the Battle of Dan-no-ura, marking the beginning of the Kamakura period.",
      "date": "1185"
    }
  ]
}

