  "timeline": [
    {
      "headline": "Extraction from Kollur Mine",
      "text": "The Hope Diamond was extracted in the 17th century from the Kollur Mine in Guntur, India. It is a blue diamond known for its exceptional size.",
      "date": "1600"
    },
    {
      "headline": "Acquisition by Jean-Baptiste Tavernier",
      "text": "In 1666, the French gem merchant Jean-Baptiste Tavernier acquired the diamond, which was then known as the Tavernier Blue.",
      "date": "1666"
    },
    {
      "headline": "Sale to King Louis XIV",
      "text": "In 1668, Tavernier sold the diamond to King Louis XIV of France, who had it recut into the French Blue.",
      "date": "1668"
    },
    {
      "headline": "Disappearance during French Revolution",
      "text": "The diamond disappeared in 1792 during the French Revolution when the French Crown Jewels were looted.",
      "date": "1792"
    },
    {
      "headline": "Reappearance in London",
      "text": "The diamond reappeared in London in 1812, twenty years after its theft, and was recut into what is now known as the Hope Diamond.",
      "date": "1812"
    },
    {
      "headline": "Acquisition by Henry Philip Hope",
      "text": "In 1839, the diamond was cataloged in the gem collection of Henry Philip Hope, from whom it gets its name.",
      "date": "1839"
    },
    {
      "headline": "Ownership by Lord Francis Hope",
      "text": "The diamond was inherited by Lord Francis Hope in 1887, who later sold it due to financial difficulties.",
      "date": "1887"
    },
    {
      "headline": "Purchase by Pierre Cartier",
      "text": "In 1910, Pierre Cartier purchased the diamond and later sold it to Evalyn Walsh McLean.",
      "date": "1910"
    },
    {
      "headline": "Acquisition by Harry Winston",
      "text": "In 1949, the diamond was purchased by New York jeweler Harry Winston, who later donated it to the Smithsonian Institution.",
      "date": "1949"
    },
    {
      "headline": "Donation to the Smithsonian Institution",
      "text": "In 1958, Harry Winston donated the Hope Diamond to the Smithsonian Institution, where it remains on display.",
      "date": "1958"
    }
  ]
}

