{
  "timeline": [
    {
      "headline": "Early SaaS Concepts",
      "text": "The concept of Software as a Service (SaaS) can be traced back to the 1960s with the idea of time-sharing, which allowed multiple users to access a mainframe computer simultaneously.",
      "date": "1960"
    },
    {
      "headline": "Application Service Providers (ASPs)",
      "text": "In the 1990s, Application Service Providers (ASPs) emerged, offering a precursor to SaaS by providing software applications over the internet.",
      "date": "1990"
    },
    {
      "headline": "Salesforce.com Launch",
      "text": "Salesforce.com was founded in 1999 and became one of the first companies to deliver enterprise applications via a web-based platform, marking a significant milestone in the development of SaaS.",
      "date": "1999"
    },
    {
      "headline": "SaaS Gains Popularity",
      "text": "By the early 2000s, SaaS began to gain popularity as internet speeds increased and businesses sought more cost-effective software solutions.",
      "date": "2000"
    },
    {
      "headline": "Introduction of Google Apps",
      "text": "In 2006, Google launched Google Apps, a suite of productivity applications delivered as SaaS, further popularizing the model.",
      "date": "2006"
    },
    {
      "headline": "Microsoft Office 365 Launch",
      "text": "Microsoft launched Office 365 in 2011, offering its popular Office suite as a subscription-based SaaS, marking a major shift for traditional software vendors.",
      "date": "2011"
    },
    {
      "headline": "SaaS Becomes Mainstream",
      "text": "By 2020, SaaS had become the dominant model for software deployment, with businesses of all sizes adopting SaaS solutions for a wide range of applications.",
      "date": "2020"
    },
    {
      "headline": "SaaS in 2023",
      "text": "By 2023, SaaS was the main form of software application deployment, with continued growth and innovation in the sector.",
      "date": "2023"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Construction Begins",
      "text": "The construction of Florence Cathedral commenced in 1296 in the Gothic style to a design by Arnolfo di Cambio.",
      "date": "1296"
    },
    {
      "headline": "Arnolfo di Cambio's Death",
      "text": "Arnolfo di Cambio, the original architect of the cathedral, passed away in 1302, leaving the project incomplete.",
      "date": "1302"
    },
    {
      "headline": "Giotto's Campanile",
      "text": "In 1334, Giotto di Bondone took over the construction and began work on the campanile (bell tower).",
      "date": "1334"
    },
    {
      "headline": "Giotto's Death",
      "text": "Giotto di Bondone died in 1337, leaving the campanile unfinished.",
      "date": "1337"
    },
    {
      "headline": "Completion of Campanile",
      "text": "The campanile was completed in 1359 by Francesco Talenti and others after Giotto's death.",
      "date": "1359"
    },
    {
      "headline": "Brunelleschi's Dome",
      "text": "Filippo Brunelleschi was commissioned to design and construct the dome of the cathedral, which began in 1420.",
      "date": "1420"
    },
    {
      "headline": "Completion of the Dome",
      "text": "Brunelleschi's dome was completed in 1436, marking the structural completion of the cathedral.",
      "date": "1436"
    },
    {
      "headline": "Consecration of the Cathedral",
      "text": "The cathedral was consecrated by Pope Eugene IV on March 25, 1436.",
      "date": "1436-03-25"
    },
    {
      "headline": "Completion of the Façade",
      "text": "The elaborate Gothic Revival façade, designed by Emilio De Fabris, was completed in 1887.",
      "date": "1887"
    }
  ]
}

