{
  "timeline": [
    {
      "headline": "Birth of Antonio López de Santa Anna",
      "text": "Antonio López de Santa Anna was born on February 21, 1794, in Xalapa, Veracruz, Mexico.",
      "date": "1794-02-21"
    },
    {
      "headline": "Joined the Spanish Army",
      "text": "In 1810, Santa Anna joined the Spanish colonial army as a cadet.",
      "date": "1810"
    },
    {
      "headline": "Battle of Medina",
      "text": "Santa Anna participated in the Battle of Medina on August 18, 1813, fighting against the Mexican insurgents.",
      "date": "1813-08-18"
    },
    {
      "headline": "Switch to Mexican Independence",
      "text": "In 1821, Santa Anna switched allegiance to the Mexican independence movement, supporting Agustín de Iturbide's Plan of Iguala.",
      "date": "1821"
    },
    {
      "headline": "Role in the Overthrow of Iturbide",
      "text": "In 1823, Santa Anna played a role in the overthrow of Emperor Agustín de Iturbide, supporting the establishment of a republic.",
      "date": "1823"
    },
    {
      "headline": "First Presidency",
      "text": "Santa Anna first became President of Mexico on May 16, 1833.",
      "date": "1833-05-16"
    },
    {
      "headline": "Battle of the Alamo",
      "text": "Santa Anna led Mexican forces in the Battle of the Alamo, which took place from February 23 to March 6, 1836.",
      "date": "1836-02-23"
    },
    {
      "headline": "Capture at the Battle of San Jacinto",
      "text": "Santa Anna was captured by Texan forces on April 21, 1836, after the Battle of San Jacinto.",
      "date": "1836-04-21"
    },
    {
      "headline": "Return to Power",
      "text": "Santa Anna returned to power as President of Mexico in 1839, after several interim presidencies.",
      "date": "1839"
    },
    {
      "headline": "Pastry War",
      "text": "In 1838-1839, Santa Anna led Mexican forces during the Pastry War against France.",
      "date": "1838"
    },
    {
      "headline": "Loss of a Leg",
      "text": "Santa Anna lost his leg in 1838 during the Pastry War, which became a symbol of his military service.",
      "date": "1838"
    },
    {
      "headline": "Exile to Cuba",
      "text": "In 1845, Santa Anna went into exile in Cuba after being deposed.",
      "date": "1845"
    },
    {
      "headline": "Return and Mexican-American War",
      "text": "Santa Anna returned to Mexico in 1846 to lead the Mexican army during the Mexican-American War.",
      "date": "1846"
    },
    {
      "headline": "Gadsden Purchase",
      "text": "In 1853, Santa Anna sold a portion of Mexican territory to the United States in the Gadsden Purchase.",
      "date": "1853"
    },
