{
  "timeline": [
    {
      "headline": "First Dialysis Experiment",
      "text": "In 1854, Scottish chemist Thomas Graham conducted the first experiment that laid the groundwork for dialysis by demonstrating the process of osmosis and diffusion through a semipermeable membrane.",
      "date": "1854"
    },
    {
      "headline": "Development of the First Dialysis Machine",
      "text": "In 1943, Dutch physician Willem Kolff constructed the first working dialysis machine, known as the 'artificial kidney'.",
      "date": "1943"
    },
    {
      "headline": "First Successful Dialysis Treatment",
      "text": "In 1945, Willem Kolff successfully treated a patient with acute kidney failure using his dialysis machine.",
      "date": "1945"
    },
    {
      "headline": "Introduction of Chronic Dialysis",
      "text": "In the 1960s, Belding Scribner and his team developed the Scribner shunt, which allowed for long-term dialysis treatment for patients with chronic kidney failure.",
      "date": "1960"
    },
    {
      "headline": "Medicare Coverage for Dialysis",
      "text": "In 1972, the United States Congress passed legislation to extend Medicare coverage to patients with end-stage renal disease, significantly increasing access to dialysis treatment.",
      "date": "1972"
    },
    {
      "headline": "Development of Continuous Ambulatory Peritoneal Dialysis (CAPD)",
      "text": "In 1976, the technique of Continuous Ambulatory Peritoneal Dialysis (CAPD) was developed, providing patients with a portable and flexible dialysis option.",
      "date": "1976"
    },
    {
      "headline": "Introduction of High-Flux Dialysis",
      "text": "In the 1980s, high-flux dialysis membranes were introduced, allowing for more efficient removal of larger toxins from the blood.",
      "date": "1980"
    },
    {
      "headline": "Advancements in Home Hemodialysis",
      "text": "In the 2000s, advancements in technology and equipment made home hemodialysis more accessible and practical for patients.",
      "date": "2000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Introduction of the Byte",
      "text": "The term 'byte' was coined by Werner Buchholz in July 1956 during the early design phase for the IBM Stretch computer. It was originally used to describe a variable-length field that could hold a single character.",
      "date": "1956-07"
    },
    {
      "headline": "Standardization of the 8-bit Byte",
      "text": "By the late 1960s, the 8-bit byte became the standard size for a byte, as it was adopted by most computer architectures. This standardization allowed for a consistent way to encode characters and data.",
      "date": "1960s"
    },
    {
      "headline": "Introduction of the Octet",
      "text": "In network protocol documents, such as the Internet Protocol, the term 'octet' was introduced to refer specifically to an 8-bit byte, to avoid ambiguity with systems that might use different byte sizes.",
      "date": "1970s"
    },
    {
      "headline": "Widespread Adoption in Computing",
      "text": "Throughout the 1970s and 1980s, the 8-bit byte became the smallest addressable unit of memory in most computer architectures, solidifying its role in computing.",
      "date": "1970s-1980s"
    }
  ]
}

