      "text": "In 209 BC, Modu Chanyu became the supreme leader of the Xiongnu, marking the beginning of the Xiongnu Empire.",
      "date": "-0209"
    },
    {
      "headline": "Xiongnu Empire established",
      "text": "Under Modu Chanyu's leadership, the Xiongnu Empire was established, unifying various nomadic tribes in the eastern Eurasian Steppe.",
      "date": "-0209"
    },
    {
      "headline": "Battle of Baideng",
      "text": "In 200 BC, the Xiongnu, under Modu Chanyu, defeated the Han dynasty forces at the Battle of Baideng, establishing their dominance over the region.",
      "date": "-0200"
    },
    {
      "headline": "Heqin policy with Han dynasty",
      "text": "In 198 BC, the Han dynasty and the Xiongnu entered into a heqin agreement, a marriage alliance and peace treaty, to maintain peace between the two powers.",
      "date": "-0198"
    },
    {
      "headline": "Expansion under Modu Chanyu",
      "text": "Throughout his reign, Modu Chanyu expanded the Xiongnu Empire, consolidating control over the steppes and extending influence over neighboring tribes.",
      "date": "-0209 to -0174"
    },
    {
      "headline": "Death of Modu Chanyu",
      "text": "Modu Chanyu died in 174 BC, leaving behind a powerful and expansive Xiongnu Empire.",
      "date": "-0174"
    },
    {
      "headline": "Reign of Laoshang Chanyu",
      "text": "Following Modu Chanyu's death, his son Laoshang Chanyu took over leadership and continued to expand the empire's influence.",
      "date": "-0174"
    },
    {
      "headline": "Xiongnu raids on Han dynasty",
      "text": "During the 2nd century BC, the Xiongnu frequently raided Han dynasty territories, leading to ongoing conflicts and negotiations.",
      "date": "-0200 to -0100"
    },
    {
      "headline": "Decline of Xiongnu power",
      "text": "By the 1st century AD, the Xiongnu Empire began to decline due to internal strife, pressure from the Han dynasty, and the rise of other nomadic groups.",
      "date": "0000 to 0100"
    },
    {
      "headline": "Collapse of the Xiongnu Empire",
      "text": "By the late 1st century AD, the Xiongnu Empire had largely disintegrated, with remnants assimilating into other cultures or migrating to new regions.",
      "date": "0100"
    }
  ]
}

