{
  "timeline": [
    {
      "headline": "Ancient Origins of Shorthand",
      "text": "Shorthand systems have been in use since ancient times, with early examples found in Ancient Greece and Rome. The earliest known shorthand system was developed by the Greeks in the 4th century BCE.",
      "date": "-0400"
    },
    {
      "headline": "Tironian Notes",
      "text": "In the 1st century BCE, Marcus Tullius Tiro, a slave and later a freedman of Cicero, developed the Tironian Notes, a shorthand system used in Ancient Rome.",
      "date": "-0063"
    },
    {
      "headline": "Revival in the Middle Ages",
      "text": "During the Middle Ages, shorthand saw a revival in monasteries, where it was used to transcribe religious texts.",
      "date": "1100"
    },
    {
      "headline": "Timothy Bright's System",
      "text": "In 1588, English physician Timothy Bright published 'Characterie: An Arte of Shorte, Swifte, and Secrete Writing by Character', one of the first modern shorthand systems.",
      "date": "1588"
    },
    {
      "headline": "John Willis's Art of Stenography",
      "text": "In 1602, John Willis published 'The Art of Stenography', which became one of the most popular shorthand systems in England.",
      "date": "1602"
    },
    {
      "headline": "Thomas Shelton's Tachygraphy",
      "text": "In 1626, Thomas Shelton published 'Tachygraphy', a shorthand system that became widely used in England and was even used by Samuel Pepys in his famous diaries.",
      "date": "1626"
    },
    {
      "headline": "Samuel Taylor's System",
      "text": "In 1786, Samuel Taylor published a shorthand system that was adopted by the British government for official use.",
      "date": "1786"
    },
    {
      "headline": "Isaac Pitman's Phonography",
      "text": "In 1837, Isaac Pitman introduced 'Phonography', a system of shorthand based on phonetic principles, which became one of the most popular systems in the English-speaking world.",
      "date": "1837"
    },
    {
      "headline": "Gregg Shorthand",
      "text": "In 1888, John Robert Gregg introduced 'Gregg Shorthand', a system that became widely used in the United States and other English-speaking countries.",
      "date": "1888"
    },
    {
      "headline": "Decline of Shorthand",
      "text": "With the advent of recording devices and computers in the late 20th century, the use of shorthand began to decline.",
      "date": "1980"
    }
  ]
}

