    {
      "headline": "Establishment of the Kingdom of Kush",
      "text": "The Kingdom of Kush was established around 1070 BCE after the collapse of the New Kingdom of Egypt. It was centered at Napata in what is now northern Sudan.",
      "date": "-1070"
    },
    {
      "headline": "Rise of the Napatan Dynasty",
      "text": "Around 750 BCE, the Napatan Dynasty began to rise in power, eventually leading to the Kushite control over Egypt.",
      "date": "-0750"
    },
    {
      "headline": "Kushite Conquest of Egypt",
      "text": "In 747 BCE, Piye, the king of Kush, began the conquest of Egypt, eventually establishing the 25th Dynasty of Egypt.",
      "date": "-0747"
    },
    {
      "headline": "Reign of Taharqa",
      "text": "Taharqa, one of the most prominent Kushite pharaohs, reigned from 690 BCE to 664 BCE, during which he undertook extensive building projects in Egypt and Kush.",
      "date": "-0690"
    },
    {
      "headline": "Assyrian Invasion",
      "text": "In 671 BCE, the Assyrians invaded Egypt, leading to the decline of Kushite power in Egypt.",
      "date": "-0671"
    },
    {
      "headline": "Move to Meroë",
      "text": "Around 591 BCE, the capital of the Kingdom of Kush was moved from Napata to Meroë, marking the beginning of the Meroitic period.",
      "date": "-0591"
    },
    {
      "headline": "Meroitic Period",
      "text": "The Meroitic period, lasting from around 300 BCE to 350 CE, was characterized by a distinct culture and script, with Meroë becoming a major center of iron production.",
      "date": "-0300"
    },
    {
      "headline": "Decline of the Kingdom of Kush",
      "text": "The Kingdom of Kush began to decline in the 4th century CE, facing pressures from the Roman Empire and internal strife.",
      "date": "0300"
    },
    {
      "headline": "Fall of Meroë",
      "text": "Around 350 CE, the Kingdom of Kush fell to the Kingdom of Aksum, marking the end of the Kushite civilization.",
      "date": "0350"
    }
  ]
}

