      "headline": "Birth of Norman Rockwell",
      "text": "Norman Percevel Rockwell was born on February 3, 1894, in New York City, United States.",
      "date": "1894-02-03"
    },
    {
      "headline": "First Commissioned Work",
      "text": "In 1912, at the age of 18, Rockwell received his first commission for four Christmas cards.",
      "date": "1912"
    },
    {
      "headline": "Art Editor for Boys' Life",
      "text": "In 1913, Rockwell became the art editor for Boys' Life, the official publication of the Boy Scouts of America, a position he held for three years.",
      "date": "1913"
    },
    {
      "headline": "First Cover for The Saturday Evening Post",
      "text": "On May 20, 1916, Rockwell's first cover for The Saturday Evening Post was published, marking the beginning of a long and successful relationship with the magazine.",
      "date": "1916-05-20"
    },
    {
      "headline": "Marriage to Irene O'Connor",
      "text": "In 1916, Rockwell married Irene O'Connor, a schoolteacher, but they divorced in 1930.",
      "date": "1916"
    },
    {
      "headline": "Marriage to Mary Barstow",
      "text": "In 1930, Rockwell married Mary Barstow, with whom he had three children.",
      "date": "1930"
    },
    {
      "headline": "Creation of the Willie Gillis Series",
      "text": "In 1941, Rockwell began the Willie Gillis series, depicting the life of a fictional American soldier during World War II.",
      "date": "1941"
    },
    {
      "headline": "The Four Freedoms Series",
      "text": "In 1943, Rockwell created the Four Freedoms series, inspired by President Franklin D. Roosevelt's 1941 State of the Union Address.",
      "date": "1943"
    },
    {
      "headline": "Death of Mary Barstow",
      "text": "Mary Barstow Rockwell passed away unexpectedly in 1959.",
      "date": "1959"
    },
    {
      "headline": "Marriage to Molly Punderson",
      "text": "In 1961, Rockwell married Molly Punderson, a retired schoolteacher.",
      "date": "1961"
    },
    {
      "headline": "The Problem We All Live With",
      "text": "In 1964, Rockwell painted The Problem We All Live With, depicting Ruby Bridges, an African American girl, walking to an all-white public school during desegregation.",
      "date": "1964"
    },
    {
      "headline": "Presidential Medal of Freedom",
      "text": "In 1977, Rockwell was awarded the Presidential Medal of Freedom, the United States' highest civilian honor, for his 'vivid and affectionate portraits of our country.'",
      "date": "1977"
    },
    {
      "headline": "Death of Norman Rockwell",
      "text": "Norman Rockwell passed away on November 8, 1978, in Stockbridge, Massachusetts, United States.",
      "date": "1978-11-08"
    }
  ]
}

