{
  "timeline": [
    {
      "headline": "First SSD Concept",
      "text": "The concept of a solid-state drive (SSD) was first introduced in the 1950s and 1960s with the development of semiconductor storage devices.",
      "date": "1950"
    },
    {
      "headline": "First Commercial SSDs",
      "text": "The first commercial SSDs were introduced in the late 1970s and early 1980s, primarily used in high-end supercomputers and military applications.",
      "date": "1978"
    },
    {
      "headline": "IBM 3380",
      "text": "In 1986, IBM introduced the 3380, one of the first SSDs used in a mainframe computer, which used DRAM for storage.",
      "date": "1986"
    },
    {
      "headline": "Flash-based SSDs",
      "text": "In 1991, SanDisk introduced the first flash-based SSD, which was a 20 MB drive for IBM's ThinkPad.",
      "date": "1991"
    },
    {
      "headline": "Consumer SSDs",
      "text": "In the mid-2000s, SSDs began to be used in consumer electronics, such as laptops and personal computers, due to advancements in flash memory technology.",
      "date": "2005"
    },
    {
      "headline": "Introduction of SATA SSDs",
      "text": "In 2007, the first SATA-based SSDs were introduced, offering improved performance and compatibility with existing computer systems.",
      "date": "2007"
    },
    {
      "headline": "PCIe SSDs",
      "text": "In 2010, PCIe SSDs were introduced, providing even faster data transfer rates by connecting directly to the motherboard.",
      "date": "2010"
    },
    {
      "headline": "NVMe SSDs",
      "text": "In 2013, the NVMe protocol was introduced, optimizing SSD performance by reducing latency and increasing data throughput.",
      "date": "2013"
    },
    {
      "headline": "Widespread Adoption",
      "text": "By the late 2010s, SSDs had become widely adopted in both consumer and enterprise markets, largely replacing traditional hard disk drives in many applications.",
      "date": "2018"
    }
  ]
}

