{
  "timeline": [
    {
      "headline": "First Recorded Attempt to Find the Northwest Passage",
      "text": "In 1497, John Cabot, an Italian explorer sailing under the English flag, made the first recorded attempt to find a Northwest Passage to Asia.",
      "date": "1497"
    },
    {
      "headline": "Martin Frobisher's Expeditions",
      "text": "Between 1576 and 1578, English explorer Martin Frobisher led three expeditions in search of the Northwest Passage, reaching what is now known as Frobisher Bay on Baffin Island.",
      "date": "1576"
    },
    {
      "headline": "Henry Hudson's Exploration",
      "text": "In 1610, Henry Hudson sailed into what is now known as Hudson Bay, believing he had found the Northwest Passage. His voyage ended in mutiny.",
      "date": "1610"
    },
    {
      "headline": "James Cook's Exploration",
      "text": "In 1776, Captain James Cook was commissioned by the British Admiralty to search for the Northwest Passage from the Pacific side. He explored the west coast of North America up to the Bering Strait.",
      "date": "1776"
    },
    {
      "headline": "Sir John Franklin's Lost Expedition",
      "text": "In 1845, Sir John Franklin led an expedition to chart and navigate the Northwest Passage. The expedition ended in tragedy, with both ships and all 129 men lost.",
      "date": "1845"
    },
    {
      "headline": "Roald Amundsen's Successful Navigation",
      "text": "In 1903-1906, Norwegian explorer Roald Amundsen became the first to successfully navigate the entire Northwest Passage, completing the journey in a small fishing vessel named Gjøa.",
      "date": "1903"
    },
    {
      "headline": "SS Manhattan's Transit",
      "text": "In 1969, the SS Manhattan, an ice-strengthened oil tanker, became the first commercial vessel to navigate the Northwest Passage, demonstrating its potential for shipping.",
      "date": "1969"
    },
    {
      "headline": "Canadian Sovereignty Assertion",
      "text": "In 1985, the United States Coast Guard icebreaker Polar Sea traversed the Northwest Passage without seeking Canadian permission, prompting Canada to assert its sovereignty over the waters.",
      "date": "1985"
    },
    {
      "headline": "First Commercial Passenger Ship",
      "text": "In 2016, the Crystal Serenity became the first large-scale commercial passenger ship to navigate the Northwest Passage, marking a new era in Arctic tourism.",
      "date": "2016"
    }
  ]
}

