    {
      "headline": "Onset of the Younger Dryas",
      "text": "Around 12,900 years Before Present (BP), the Younger Dryas period began. This was marked by a sudden and significant cooling in the Northern Hemisphere, with the North Atlantic Ocean cooling and annual air temperatures decreasing by approximately 3°C over North America, 2–6°C in Europe, and up to 10°C in Greenland.",
      "date": "-10950"
    },
    {
      "headline": "Rapid Cooling in Greenland",
      "text": "During the onset of the Younger Dryas, Greenland experienced particularly rapid cooling, with temperatures dropping significantly over just 3 years or less.",
      "date": "-10950"
    },
    {
      "headline": "Warming in the Southern Hemisphere",
      "text": "While the Northern Hemisphere experienced cooling, the Southern Hemisphere underwent warming during the Younger Dryas period.",
      "date": "-10950"
    },
    {
      "headline": "End of the Younger Dryas",
      "text": "The Younger Dryas period ended around 11,700 years Before Present (BP) with a dramatic warming over approximately 50 years. This transition marked the end of the glacial Pleistocene epoch and the beginning of the current Holocene epoch.",
      "date": "-09750"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Stepan Bandera",
      "text": "Stepan Andriyovych Bandera was born on January 1, 1909, in the village of Staryi Uhryniv, which was then part of the Austro-Hungarian Empire.",
      "date": "1909-01-01"
    },
    {
      "headline": "Joining the Organization of Ukrainian Nationalists (OUN)",
      "text": "In 1929, Stepan Bandera joined the Organization of Ukrainian Nationalists, a political organization that sought to establish an independent Ukrainian state.",
      "date": "1929"
    },
    {
      "headline": "Imprisonment for Political Activities",
      "text": "In 1934, Bandera was arrested by Polish authorities for his involvement in the assassination of Polish Interior Minister Bronisław Pieracki and was sentenced to death, which was later commuted to life imprisonment.",
      "date": "1934"
    },
    {
      "headline": "Release from Prison",
      "text": "In September 1939, following the invasion of Poland by Germany and the Soviet Union, Bandera was released from prison.",
      "date": "1939-09"
    },
    {
      "headline": "Proclamation of Ukrainian Statehood",
      "text": "On June 30, 1941, Bandera's faction of the OUN proclaimed an independent Ukrainian state in Lviv, which was not recognized by Nazi Germany.",
      "date": "1941-06-30"
    },
    {
      "headline": "Arrest by Nazi Germany",
      "text": "In July 1941, Bandera was arrested by the Gestapo and later imprisoned in Sachsenhausen concentration camp due to his refusal to retract the declaration of Ukrainian independence.",
      "date": "1941-07"
    },
    {
      "headline": "Release from Sachsenhausen",
      "text": "In September 1944, Bandera was released from Sachsenhausen concentration camp by the Nazis in an attempt to gain Ukrainian support against the advancing Soviet forces.",
      "date": "1944-09"
    },
    {
      "headline": "Assassination in Munich",
      "text": "On October 15, 1959, Stepan Bandera was assassinated in Munich, West Germany, by KGB agent Bohdan Stashynsky using a cyanide spray gun.",
      "date": "1959-10-15"
    }
  ]
}

