    {
      "headline": "Birth of John J. Pershing",
      "text": "John Joseph Pershing was born on September 13, 1860, in Laclede, Missouri.",
      "date": "1860-09-13"
    },
    {
      "headline": "Graduation from West Point",
      "text": "Pershing graduated from the United States Military Academy at West Point in 1886.",
      "date": "1886"
    },
    {
      "headline": "Service in the Spanish-American War",
      "text": "Pershing served in the Spanish-American War in 1898, where he was involved in the Santiago campaign in Cuba.",
      "date": "1898"
    },
    {
      "headline": "Promotion to Brigadier General",
      "text": "In 1906, Pershing was promoted to the rank of Brigadier General by President Theodore Roosevelt.",
      "date": "1906"
    },
    {
      "headline": "Mexican Expedition",
      "text": "In 1916, Pershing led the Punitive Expedition into Mexico in pursuit of Pancho Villa.",
      "date": "1916"
    },
    {
      "headline": "Commander of the American Expeditionary Forces",
      "text": "In 1917, Pershing was appointed as the commander of the American Expeditionary Forces in World War I.",
      "date": "1917"
    },
    {
      "headline": "Victory in World War I",
      "text": "Under Pershing's leadership, the American Expeditionary Forces played a crucial role in the Allied victory in World War I, culminating in the Armistice on November 11, 1918.",
      "date": "1918-11-11"
    },
    {
      "headline": "Promotion to General of the Armies",
      "text": "In 1919, Pershing was promoted to General of the Armies, the highest rank in the United States Army.",
      "date": "1919"
    },
    {
      "headline": "Retirement from the Army",
      "text": "Pershing retired from active military service in 1924.",
      "date": "1924"
    },
    {
      "headline": "Publication of Memoirs",
      "text": "In 1931, Pershing published his memoirs, 'My Experiences in the World War', which won the Pulitzer Prize for History.",
      "date": "1931"
    },
    {
      "headline": "Death of John J. Pershing",
      "text": "John J. Pershing passed away on July 15, 1948, in Washington, D.C.",
      "date": "1948-07-15"
    }
  ]
}

