    {
      "headline": "The Provisions of Oxford",
      "text": "In 1258, the Provisions of Oxford are issued, marking the first time English was used for official government documents since the Norman Conquest.",
      "date": "1258"
    },
    {
      "headline": "The Ormulum",
      "text": "The 'Ormulum', a biblical commentary written in Middle English, is completed around 1200. It is notable for its unique orthographic system.",
      "date": "1200"
    },
    {
      "headline": "The Black Death",
      "text": "The Black Death strikes England in 1348-1350, leading to significant social and linguistic changes, including the increased use of English in place of Latin and French.",
      "date": "1348"
    },
    {
      "headline": "Chaucer's 'The Canterbury Tales'",
      "text": "Geoffrey Chaucer begins writing 'The Canterbury Tales' in the late 14th century, around 1387. It is one of the most famous works of Middle English literature.",
      "date": "1387"
    },
    {
      "headline": "The Statute of Pleading",
      "text": "In 1362, the Statute of Pleading is enacted, making English the official language of the courts in England, reflecting the growing dominance of English over French.",
      "date": "1362"
    },
    {
      "headline": "End of Middle English Period",
      "text": "The Middle English period is generally considered to have ended around 1500, transitioning into Early Modern English.",
