    {
      "headline": "Royal Navy Expedition",
      "text": "In June 1840, the Royal Navy launched an expedition against China, marking the beginning of military engagements in the First Opium War.",
      "date": "1840-06"
    },
    {
      "headline": "Defeat of the Qing Dynasty",
      "text": "By August 1842, the British forces, using technologically superior ships and weapons, defeated the Qing dynasty.",
      "date": "1842-08"
    },
    {
      "headline": "Treaty of Nanking",
      "text": "The Treaty of Nanking was imposed by the British in 1842, forcing China to increase foreign trade, give compensation, and cede Hong Kong Island to the British.",
      "date": "1842"
    },
    {
      "headline": "Continuation of Opium Trade",
      "text": "Following the Treaty of Nanking, the opium trade continued in China despite the previous ban.",
      "date": "1842"
    }
  ]
}

