      "headline": "Immigration to the United States",
      "text": "Mary Mallon immigrated to the United States in 1883, where she later became known as Typhoid Mary.",
      "date": "1883"
    },
    {
      "headline": "First Identified as a Typhoid Carrier",
      "text": "In 1906, Mary Mallon was identified as the source of a typhoid fever outbreak in Oyster Bay, Long Island, after infecting several people while working as a cook.",
      "date": "1906"
    },
    {
      "headline": "First Quarantine",
      "text": "Mary Mallon was forcibly quarantined for the first time in 1907 after being identified as an asymptomatic carrier of typhoid fever. She was held at a hospital on North Brother Island in New York City.",
      "date": "1907"
    },
    {
      "headline": "Release from Quarantine",
      "text": "In 1910, Mary Mallon was released from quarantine under the condition that she would no longer work as a cook.",
      "date": "1910"
    },
    {
      "headline": "Return to Cooking and Second Quarantine",
      "text": "Mary Mallon returned to working as a cook under an alias, leading to another typhoid outbreak. She was quarantined again in 1915, this time for the remainder of her life.",
      "date": "1915"
    },
    {
      "headline": "Death of Mary Mallon",
      "text": "Mary Mallon died on November 11, 1938, after nearly 30 years in quarantine on North Brother Island.",
      "date": "1938-11-11"
    }
  ]
}

