    {
      "headline": "Birth of Johannes Gutenberg",
      "text": "Johannes Gutenberg was born around 1400 in Mainz, Holy Roman Empire.",
      "date": "1400"
    },
    {
      "headline": "Gutenberg's Early Life",
      "text": "Gutenberg grew up in Mainz, where he likely learned the trade of goldsmithing and metalworking.",
      "date": "1400"
    },
    {
      "headline": "Move to Strasbourg",
      "text": "Around 1430, Gutenberg moved to Strasbourg, where he lived for several years and began experimenting with printing.",
      "date": "1430"
    },
    {
      "headline": "Development of Movable Type",
      "text": "By the early 1440s, Gutenberg had developed a system of movable type printing, which he continued to refine over the next decade.",
      "date": "1440"
    },
    {
      "headline": "Return to Mainz",
      "text": "Gutenberg returned to Mainz in 1448, where he continued his work on the printing press.",
      "date": "1448"
    },
    {
      "headline": "Printing of the Gutenberg Bible",
      "text": "In 1455, Gutenberg completed the printing of the Gutenberg Bible, the first major book printed using movable type in the West.",
      "date": "1455"
    },
    {
      "headline": "Lawsuit with Johann Fust",
      "text": "In 1455, Gutenberg was sued by Johann Fust, his financial backer, which resulted in Gutenberg losing control of his printing workshop.",
      "date": "1455"
    },
    {
      "headline": "Later Life and Recognition",
      "text": "In 1465, Gutenberg was recognized by the Archbishop of Mainz, who granted him a pension and other privileges.",
      "date": "1465"
    },
    {
      "headline": "Death of Johannes Gutenberg",
      "text": "Johannes Gutenberg died on February 3, 1468, in Mainz, Holy Roman Empire.",
      "date": "1468-02-03"
    }
  ]
}

