      "headline": "Start of the Boshin War",
      "text": "The Boshin War began on January 27, 1868, with the Battle of Toba–Fushimi, where the forces of the ruling Tokugawa shogunate clashed with those of the Imperial Court.",
      "date": "1868-01-27"
    },
    {
      "headline": "Battle of Toba–Fushimi",
      "text": "From January 27 to January 31, 1868, the Battle of Toba–Fushimi took place, resulting in a decisive victory for the Imperial forces.",
      "date": "1868-01-31"
    },
    {
      "headline": "Capture of Edo",
      "text": "On May 3, 1868, Edo (modern-day Tokyo) was captured by Imperial forces, marking a significant turning point in the war.",
      "date": "1868-05-03"
    },
    {
      "headline": "Battle of Ueno",
      "text": "The Battle of Ueno occurred on July 4, 1868, where the Imperial forces defeated the Shogunate's last major resistance in Edo.",
      "date": "1868-07-04"
    },
    {
      "headline": "Battle of Aizu",
      "text": "From October 6 to November 6, 1868, the Battle of Aizu took place, resulting in the surrender of the Aizu domain to Imperial forces.",
      "date": "1868-11-06"
    },
    {
      "headline": "Battle of Hakodate",
      "text": "The Battle of Hakodate began in December 1868 and continued until May 1869, marking the final battle of the Boshin War.",
      "date": "1868-12"
    },
    {
      "headline": "End of the Boshin War",
      "text": "The Boshin War officially ended on June 27, 1869, with the surrender of the last Shogunate forces at Hakodate.",
      "date": "1869-06-27"
    }
  ]
}

