      "headline": "Foundation of Königsberg",
      "text": "Königsberg was founded in 1255 by the Teutonic Knights during the Baltic Crusades. It was established on the site of the Old Prussian settlement Twangste and named in honor of King Ottokar II of Bohemia.",
      "date": "1255"
    },
    {
      "headline": "Königsberg Becomes a Member of the Hanseatic League",
      "text": "In 1340, Königsberg joined the Hanseatic League, a powerful economic and defensive alliance of merchant guilds and market towns in Northwestern and Central Europe.",
      "date": "1340"
    },
    {
      "headline": "University of Königsberg Founded",
      "text": "The University of Königsberg, also known as the Albertina, was founded in 1544 by Duke Albert of Prussia. It became a significant center of learning and culture in the region.",
      "date": "1544"
    },
    {
      "headline": "Königsberg Becomes Capital of Ducal Prussia",
      "text": "In 1525, after the secularization of the Teutonic Order's Prussian territories, Königsberg became the capital of the newly established Duchy of Prussia.",
      "date": "1525"
    },
    {
      "headline": "Königsberg Under Swedish Control",
      "text": "During the Thirty Years' War, Königsberg came under Swedish control from 1626 to 1635.",
      "date": "1626"
    },
    {
      "headline": "Königsberg Becomes Part of the Kingdom of Prussia",
      "text": "In 1701, the Duchy of Prussia was elevated to the Kingdom of Prussia, and Königsberg became one of its major cities.",
      "date": "1701"
    },
    {
      "headline": "Immanuel Kant Born in Königsberg",
      "text": "The philosopher Immanuel Kant, one of the most influential figures in Western philosophy, was born in Königsberg on April 22, 1724.",
      "date": "1724-04-22"
    },
    {
      "headline": "Königsberg During World War II",
      "text": "Königsberg was heavily damaged during World War II, particularly by British bombing raids in 1944 and the subsequent Soviet assault in 1945.",
      "date": "1944"
    },
    {
      "headline": "Königsberg Becomes Kaliningrad",
      "text": "After World War II, in 1945, Königsberg was annexed by the Soviet Union and renamed Kaliningrad. It became part of the Russian Soviet Federative Socialist Republic.",
      "date": "1945"
    }
  ]
}

