{
  "timeline": [
    {
      "headline": "Origin of the Phrase",
      "text": "The phrase 'laissez-faire, laissez-passer' is generally attributed to the French economist Vincent de Gournay, who lived in the 18th century. The phrase translates to 'let do, let pass,' advocating for minimal government intervention in economic affairs.",
      "date": "1700s"
    },
    {
      "headline": "Influence of Physiocrats",
      "text": "In the mid-18th century, the Physiocrats, a group of French economists, adopted laissez-faire principles. They believed that the wealth of nations was derived from the value of 'land agriculture' and that agricultural products should be highly priced.",
      "date": "1750s"
    },
    {
      "headline": "Adam Smith's 'The Wealth of Nations'",
      "text": "In 1776, Adam Smith published 'The Wealth of Nations,' which argued for economic freedom and is often associated with the principles of laissez-faire. Smith's work laid the foundation for classical economics.",
      "date": "1776"
    },
    {
      "headline": "19th Century Industrial Revolution",
      "text": "During the 19th century, the Industrial Revolution in Europe and the United States saw the widespread application of laissez-faire principles, with minimal government interference in business and industry.",
      "date": "1800s"
    },
    {
      "headline": "Criticism and Regulation",
      "text": "By the late 19th and early 20th centuries, laissez-faire policies faced criticism for contributing to economic inequalities and poor working conditions, leading to increased government regulation and the development of welfare states.",
      "date": "1900s"
    },
    {
      "headline": "Modern Economic Policies",
      "text": "In the late 20th and early 21st centuries, laissez-faire principles have influenced neoliberal economic policies, advocating for free markets, deregulation, and privatization.",
      "date": "2000s"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of Erebuni Fortress",
      "text": "Yerevan's history dates back to the founding of the Erebuni Fortress by King Argishti I of Urartu in 782 BCE. This event marks the establishment of one of the world's oldest continuously inhabited cities.",
      "date": "-0782"
    },
    {
      "headline": "Yerevan under Persian Rule",
      "text": "In the 6th century BCE, Yerevan came under the rule of the Achaemenid Empire, marking a significant period of Persian influence in the region.",
      "date": "-0600"
    },
    {
      "headline": "Yerevan under Roman Control",
      "text": "In 58 BCE, Yerevan was captured by the Roman general Pompey during his campaign against the Kingdom of Armenia.",
      "date": "-0058"
    },
    {
      "headline": "Arab Conquest of Yerevan",
      "text": "In 658, Yerevan was conquered by the Arab Caliphate, becoming part of the Umayyad and later the Abbasid Caliphates.",
      "date": "0658"
    },
    {
      "headline": "Seljuk Turks Capture Yerevan",
      "text": "In the 11th century, Yerevan fell under the control of the Seljuk Turks, marking another shift in the city's political landscape.",
      "date": "1064"
    },
    {
      "headline": "Yerevan under Safavid Rule",
      "text": "In 1502, Yerevan became part of the Safavid Empire, serving as a key administrative center in the region.",
      "date": "1502"
    },
    {
      "headline": "Ottoman-Safavid Wars",
      "text": "Throughout the 16th and 17th centuries, Yerevan was a focal point of conflict between the Ottoman Empire and the Safavid Empire, changing hands multiple times.",
      "date": "1604"
    },
    {
      "headline": "Russian Conquest of Yerevan",
      "text": "In 1827, Yerevan was captured by Russian forces during the Russo-Persian War, leading to its incorporation into the Russian Empire.",
      "date": "1827"
    },
    {
      "headline": "Yerevan Becomes Capital of First Republic of Armenia",
      "text": "On May 28, 1918, Yerevan was declared the capital of the First Republic of Armenia, marking a significant moment in Armenian history.",
      "date": "1918-05-28"
    },
    {
      "headline": "Soviet Era Begins in Yerevan",
      "text": "In 1920, Yerevan became part of the Soviet Union as the capital of the Armenian Soviet Socialist Republic.",
      "date": "1920"
    },
    {
      "headline": "Independence of Armenia",
      "text": "On September 21, 1991, Armenia declared its independence from the Soviet Union, with Yerevan continuing as the capital of the newly independent Republic of Armenia.",
      "date": "1991-09-21"
    }
  ]
}

