{
  "timeline": [
    {
      "headline": "Zeno of Elea's Birth",
      "text": "Zeno of Elea was born around 490 BCE in Elea, a Greek colony in southern Italy.",
      "date": "-0490"
    },
    {
      "headline": "Zeno's Association with Parmenides",
      "text": "Zeno became a disciple of Parmenides, a pre-Socratic philosopher known for his doctrine of monism, which posits that reality is one unchanging substance.",
      "date": "-0460"
    },
    {
      "headline": "Creation of Zeno's Paradoxes",
      "text": "Zeno devised a series of paradoxes to support Parmenides's philosophy, challenging the notions of plurality and motion. These paradoxes include the Dichotomy Paradox, Achilles and the Tortoise, the Arrow Paradox, and the Stadium Paradox.",
      "date": "-0450"
    },
    {
      "headline": "Zeno's Paradoxes Discussed by Plato",
      "text": "Plato discusses Zeno's paradoxes in his dialogue 'Parmenides,' where Zeno is portrayed as defending Parmenides's ideas against critics.",
      "date": "-0360"
    },
    {
      "headline": "Aristotle's Analysis of Zeno's Paradoxes",
      "text": "Aristotle examines Zeno's paradoxes in his works, particularly in 'Physics,' where he attempts to resolve them by introducing the concept of potential infinity.",
      "date": "-0330"
    },
    {
      "headline": "Simplicius of Cilicia's Commentary",
      "text": "Simplicius, a 6th-century philosopher, provides extensive commentary on Zeno's paradoxes, preserving much of the original content and interpretations.",
      "date": "0530"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Construction Begins",
      "text": "Construction of the Panthéon began in 1758, initiated by King Louis XV of France. The design was created by architect Jacques-Germain Soufflot.",
      "date": "1758"
    },
    {
      "headline": "Death of Jacques-Germain Soufflot",
      "text": "Jacques-Germain Soufflot, the architect of the Panthéon, passed away in 1780 before the completion of the building.",
      "date": "1780"
    },
    {
      "headline": "Completion of the Panthéon",
      "text": "The Panthéon was completed in 1790. Originally intended as a church dedicated to Saint Genevieve, it was completed after the deaths of both King Louis XV and architect Jacques-Germain Soufflot.",
      "date": "1790"
    },
    {
      "headline": "Conversion to a Mausoleum",
      "text": "In 1791, during the French Revolution, the National Constituent Assembly decided to transform the Panthéon into a mausoleum to house the remains of distinguished French citizens.",
      "date": "1791"
    },
    {
      "headline": "First Interment",
      "text": "The first person to be interred in the Panthéon was Honoré Gabriel Riqueti, comte de Mirabeau, in 1791, although his remains were later removed.",
      "date": "1791"
    },
    {
      "headline": "Return to Religious Use",
      "text": "In 1806, under Napoleon Bonaparte, the Panthéon was returned to its original function as a church.",
      "date": "1806"
    },
