{
  "timeline": [
    {
      "headline": "Pequot War",
      "text": "The Pequot War was an armed conflict that took place between 1636 and 1638 in New England between the Pequot tribe and an alliance of the English colonists of the Massachusetts Bay, Plymouth, and Saybrook colonies and their Native American allies.",
      "date": "1636"
    },
    {
      "headline": "King Philip's War",
      "text": "King Philip's War (1675–1678), also known as Metacom's War or the First Indian War, was an armed conflict in 1675–1678 between indigenous inhabitants of New England and New England colonists and their indigenous allies.",
      "date": "1675"
    },
    {
      "headline": "Yamasee War",
      "text": "The Yamasee War (1715–1717) was a conflict between British settlers of colonial South Carolina and various Native American tribes, including the Yamasee, Muscogee, Cherokee, and others.",
      "date": "1715"
    },
    {
      "headline": "Pontiac's War",
      "text": "Pontiac's War (1763–1766) was launched by a loose confederation of Native American tribes, primarily from the Great Lakes region, the Illinois Country, and Ohio Country, who were dissatisfied with British postwar policies after the British victory in the French and Indian War.",
      "date": "1763"
    },
    {
      "headline": "Tecumseh's War",
      "text": "Tecumseh's War (1811) was a conflict between the United States and an American Indian confederation led by the Shawnee leader Tecumseh in the Indiana Territory.",
      "date": "1811"
    },
    {
      "headline": "First Seminole War",
      "text": "The First Seminole War (1816–1819) was a conflict in Florida between the United States and the Seminole, a Native American tribe that formed in Florida.",
      "date": "1816"
    },
    {
      "headline": "Black Hawk War",
      "text": "The Black Hawk War was a brief conflict in 1832 between the United States and Native Americans led by Black Hawk, a Sauk leader.",
      "date": "1832"
    },
    {
      "headline": "Second Seminole War",
      "text": "The Second Seminole War (1835–1842), also known as the Florida War, was a conflict from 1835 to 1842 in Florida between various groups of Native Americans collectively known as Seminoles and the United States.",
      "date": "1835"
    },
    {
      "headline": "Third Seminole War",
      "text": "The Third Seminole War (1855–1858) was the final conflict in a series of wars between the United States and the Seminole Indians of Florida.",
      "date": "1855"
    },
    {
      "headline": "Dakota War of 1862",
      "text": "The Dakota War of 1862, also known as the Sioux Uprising, was an armed conflict between the United States and several bands of Dakota (also known as the eastern 'Sioux').",
      "date": "1862"
    },
    {
      "headline": "Sand Creek Massacre",
      "text": "The Sand Creek Massacre was an atrocity in the American Indian Wars that occurred on November 29, 1864, when a 675-man force of Colorado U.S. Volunteer Cavalry attacked and destroyed a village of Cheyenne and Arapaho in southeastern Colorado Territory.",
      "date": "1864-11-29"
    },
    {
      "headline": "Red Cloud's War",
      "text": "Red Cloud's War (1866–1868) was an armed conflict between the Lakota, Northern Cheyenne, and Northern Arapaho on one side and the United States in the Wyoming and Montana territories from 1866 to 1868.",
      "date": "1866"
    },
    {
      "headline": "Battle of the Little Bighorn",
      "text": "The Battle of the Little Bighorn, also known as Custer's Last Stand, was an armed engagement between combined forces of the Lakota, Northern Cheyenne, and Arapaho tribes and the 7th Cavalry Regiment of the United States Army. It occurred on June 25–26, 1876.",
      "date": "1876-06-25"
    },
    {
      "headline": "Nez Perce War",
      "text": "The Nez Perce War was an armed conflict that took place between June and October 1877 between the Nez Perce tribe and the United States Army.",
      "date": "1877"
    },
    {
      "headline": "Wounded Knee Massacre",
      "text": "The Wounded Knee Massacre occurred on December 29, 1890, near Wounded Knee Creek on the Lakota Pine Ridge Indian Reservation in the U.S. state of South Dakota.",
      "date": "1890-12-29"
    }
  ]
}

