    {
      "headline": "Start of the First Sino-Japanese War",
      "text": "The First Sino-Japanese War began on July 25, 1894, as a conflict between the Qing dynasty of China and the Empire of Japan primarily over influence in Korea.",
      "date": "1894-07-25"
    },
    {
      "headline": "Battle of Pungdo",
      "text": "The Battle of Pungdo occurred on July 25, 1894, marking the first naval engagement of the war.",
      "date": "1894-07-25"
    },
    {
      "headline": "Battle of Seonghwan",
      "text": "The Battle of Seonghwan took place on July 29, 1894, where Japanese forces defeated the Chinese troops.",
      "date": "1894-07-29"
    },
    {
      "headline": "Battle of Pyongyang",
      "text": "On September 15, 1894, Japanese forces won a decisive victory at the Battle of Pyongyang, forcing Chinese troops to retreat.",
      "date": "1894-09-15"
    },
    {
      "headline": "Battle of the Yalu River",
      "text": "The Battle of the Yalu River occurred on September 17, 1894, resulting in a significant Japanese naval victory.",
      "date": "1894-09-17"
    },
    {
      "headline": "Capture of Port Arthur",
      "text": "Japanese forces captured the strategic port of Lüshunkou (Port Arthur) on November 21, 1894.",
      "date": "1894-11-21"
    },
    {
      "headline": "Battle of Weihaiwei",
      "text": "The Battle of Weihaiwei took place from January 20 to February 12, 1895, resulting in a Japanese victory and the capture of the Chinese Beiyang Fleet.",
      "date": "1895-02-12"
    },
    {
      "headline": "Qing Government Sues for Peace",
      "text": "In February 1895, after a series of defeats, the Qing government sued for peace with Japan.",
      "date": "1895-02"
    },
    {
      "headline": "Treaty of Shimonoseki",
      "text": "The Treaty of Shimonoseki was signed on April 17, 1895, officially ending the First Sino-Japanese War. The treaty ceded Taiwan, the Pescadores Islands, and the Liaodong Peninsula to Japan.",
      "date": "1895-04-17"
    }
  ]
}

