    {
      "headline": "Rudolf Steiner's Birth",
      "text": "Rudolf Steiner, the founder of Waldorf education, was born on February 27, 1861, in Murakirály, Austria-Hungary (now Donji Kraljevec, Croatia).",
      "date": "1861-02-27"
    },
    {
      "headline": "Foundation of Anthroposophy",
      "text": "In the early 20th century, Rudolf Steiner developed the spiritual philosophy known as anthroposophy, which would later influence the creation of Waldorf education.",
      "date": "1900"
    },
    {
      "headline": "First Waldorf School Opens",
      "text": "The first Waldorf school was established in Stuttgart, Germany, in 1919. It was founded by Rudolf Steiner at the request of Emil Molt, the owner of the Waldorf-Astoria cigarette factory, for the children of the factory's employees.",
      "date": "1919"
    },
    {
      "headline": "Expansion of Waldorf Schools",
      "text": "Throughout the 1920s and 1930s, Waldorf schools began to spread across Europe, with new schools opening in the Netherlands, Switzerland, and the United Kingdom.",
      "date": "1920"
    },
    {
      "headline": "Rudolf Steiner's Death",
      "text": "Rudolf Steiner passed away on March 30, 1925, in Dornach, Switzerland. His educational philosophy continued to influence the development of Waldorf schools worldwide.",
      "date": "1925-03-30"
    },
    {
      "headline": "Waldorf Education in North America",
      "text": "The first Waldorf school in North America, the Rudolf Steiner School, was established in New York City in 1928.",
      "date": "1928"
    },
    {
      "headline": "Post-War Growth",
      "text": "After World War II, Waldorf education experienced significant growth, with many new schools opening in Europe, North America, and other parts of the world.",
      "date": "1945"
    },
    {
      "headline": "Global Expansion",
      "text": "By the late 20th century, Waldorf education had expanded globally, with schools established in Africa, Asia, and South America.",
      "date": "1980"
    },
    {
      "headline": "Centennial of Waldorf Education",
      "text": "In 2019, Waldorf education celebrated its 100th anniversary, marking a century since the founding of the first Waldorf school in Stuttgart.",
      "date": "2019"
    }
  ]
}

