{
  "timeline": [
    {
      "headline": "Enactment of the Alien and Sedition Acts",
      "text": "In 1798, the United States Congress passed the Alien and Sedition Acts, a series of four laws aimed at strengthening national security but criticized for infringing on individual rights.",
      "date": "1798"
    },
    {
      "headline": "Naturalization Act of 1798",
      "text": "The Naturalization Act, enacted on June 18, 1798, increased the residency requirement for American citizenship from 5 to 14 years.",
      "date": "1798-06-18"
    },
    {
      "headline": "Alien Friends Act of 1798",
      "text": "The Alien Friends Act, enacted on June 25, 1798, authorized the president to deport any non-citizen suspected of plotting against the government during peacetime.",
      "date": "1798-06-25"
    },
    {
      "headline": "Alien Enemies Act of 1798",
      "text": "The Alien Enemies Act, enacted on July 6, 1798, allowed the president to detain and deport non-citizens from hostile nations during times of war.",
      "date": "1798-07-06"
    },
    {
      "headline": "Sedition Act of 1798",
      "text": "The Sedition Act, enacted on July 14, 1798, made it a crime to publish 'false, scandalous, and malicious writing' against the government or its officials.",
      "date": "1798-07-14"
    },
    {
      "headline": "Expiration of the Alien Friends Act",
      "text": "The Alien Friends Act expired on June 25, 1800, as it was originally set to last for two years.",
      "date": "1800-06-25"
    },
    {
      "headline": "Expiration of the Sedition Act",
      "text": "The Sedition Act expired on March 3, 1801, the day before Thomas Jefferson's inauguration as President.",
      "date": "1801-03-03"
    },
    {
      "headline": "Repeal of the Naturalization Act",
      "text": "The Naturalization Act was repealed in 1802, reducing the residency requirement for citizenship back to 5 years.",
      "date": "1802"
    },
    {
      "headline": "Alien Enemies Act remains in effect",
      "text": "The Alien Enemies Act, as amended, remains in effect and is codified as 50 U.S.C. ch. 3.",
      "date": "Present"
    }
  ]
}

