{
  "timeline": [
    {
      "headline": "Birth of Dmitri Shostakovich",
      "text": "Dmitri Dmitriyevich Shostakovich was born on September 25, 1906, in Saint Petersburg, Russia.",
      "date": "1906-09-25"
    },
    {
      "headline": "Premiere of First Symphony",
      "text": "Shostakovich's First Symphony premiered in 1926, marking his international recognition as a major composer.",
      "date": "1926"
