    {
      "headline": "Completion of Second Symphony",
      "text": "In 1927, Shostakovich completed his Second Symphony, which was subtitled 'To October' in celebration of the 10th anniversary of the October Revolution.",
      "date": "1927"
    },
    {
      "headline": "Premiere of Lady Macbeth of the Mtsensk District",
      "text": "The opera 'Lady Macbeth of the Mtsensk District' premiered on January 22, 1934, and was initially successful before being criticized by Soviet authorities.",
      "date": "1934-01-22"
    },
    {
      "headline": "Publication of Pravda Article",
      "text": "On January 28, 1936, the Soviet newspaper Pravda published an article titled 'Muddle Instead of Music,' criticizing Shostakovich's opera 'Lady Macbeth of the Mtsensk District.'",
      "date": "1936-01-28"
    },
    {
      "headline": "Fifth Symphony Premiere",
      "text": "Shostakovich's Fifth Symphony premiered on November 21, 1937, and was well-received, restoring his standing with Soviet authorities.",
      "date": "1937-11-21"
    },
    {
      "headline": "Seventh Symphony Premiere",
      "text": "The Seventh Symphony, also known as the 'Leningrad Symphony,' premiered on March 5, 1942, during World War II.",
      "date": "1942-03-05"
    },
    {
      "headline": "Eighth Symphony Premiere",
      "text": "Shostakovich's Eighth Symphony premiered on November 4, 1943, and was seen as a reflection on the hardships of war.",
      "date": "1943-11-04"
    },
    {
      "headline": "Ninth Symphony Premiere",
      "text": "The Ninth Symphony premiered on November 3, 1945, and was unexpectedly light-hearted, contrasting with the expectations for a grand victory symphony.",
      "date": "1945-11-03"
    },
    {
      "headline": "Tenth Symphony Premiere",
      "text": "The Tenth Symphony premiered on December 17, 1953, shortly after the death of Joseph Stalin, and is considered one of Shostakovich's major works.",
      "date": "1953-12-17"
    },
    {
      "headline": "Eleventh Symphony Premiere",
      "text": "The Eleventh Symphony, subtitled 'The Year 1905,' premiered on October 30, 1957, and commemorated the events of the Russian Revolution of 1905.",
      "date": "1957-10-30"
    },
    {
      "headline": "Twelfth Symphony Premiere",
      "text": "The Twelfth Symphony, subtitled 'The Year 1917,' premiered on October 1, 1961, and was dedicated to the memory of Lenin.",
      "date": "1961-10-01"
    },
    {
      "headline": "Thirteenth Symphony Premiere",
      "text": "The Thirteenth Symphony, subtitled 'Babi Yar,' premiered on December 18, 1962, and was based on the poem by Yevgeny Yevtushenko, addressing anti-Semitism and other social issues.",
      "date": "1962-12-18"
    },
    {
      "headline": "Death of Dmitri Shostakovich",
      "text": "Dmitri Shostakovich passed away on August 9, 1975, in Moscow, Russia.",
      "date": "1975-08-09"
    }
  ]
}

