      "date": "1985-12-28"
    },
    {
      "headline": "Meredith Kercher's Murder",
      "text": "On November 1, 2007, Meredith Kercher was murdered in Perugia, Italy. Her body was discovered on November 2, 2007.",
      "date": "2007-11-01"
    },
    {
      "headline": "Arrest of Amanda Knox and Raffaele Sollecito",
      "text": "Amanda Knox and her boyfriend Raffaele Sollecito were arrested on November 6, 2007, in connection with the murder of Meredith Kercher.",
      "date": "2007-11-06"
    },
    {
      "headline": "Arrest of Rudy Guede",
      "text": "Rudy Guede was arrested in Germany on November 20, 2007, and extradited to Italy to face charges related to the murder of Meredith Kercher.",
      "date": "2007-11-20"
    },
    {
      "headline": "Rudy Guede's Conviction",
      "text": "On October 28, 2008, Rudy Guede was convicted of the sexual assault and murder of Meredith Kercher and sentenced to 30 years in prison, later reduced to 16 years on appeal.",
      "date": "2008-10-28"
    },
    {
      "headline": "Initial Conviction of Knox and Sollecito",
      "text": "On December 4, 2009, Amanda Knox and Raffaele Sollecito were found guilty of the murder of Meredith Kercher and sentenced to 26 and 25 years in prison, respectively.",
      "date": "2009-12-04"
    },
    {
      "headline": "Acquittal of Knox and Sollecito",
      "text": "On October 3, 2011, Amanda Knox and Raffaele Sollecito were acquitted of the murder charges on appeal and released from prison.",
      "date": "2011-10-03"
    },
    {
      "headline": "Supreme Court Overturns Acquittal",
      "text": "On March 26, 2013, Italy's Supreme Court overturned the acquittal of Amanda Knox and Raffaele Sollecito, ordering a retrial.",
      "date": "2013-03-26"
    },
    {
      "headline": "Retrial Conviction of Knox and Sollecito",
      "text": "On January 30, 2014, Amanda Knox and Raffaele Sollecito were found guilty again in a retrial and sentenced to 28.5 and 25 years in prison, respectively.",
      "date": "2014-01-30"
    },
    {
      "headline": "Final Acquittal by Supreme Court",
      "text": "On March 27, 2015, Italy's Supreme Court definitively acquitted Amanda Knox and Raffaele Sollecito of the murder of Meredith Kercher.",
      "date": "2015-03-27"
    }
  ]
}

