{
  "timeline": [
    {
      "headline": "Choctaw Origins",
      "text": "The Choctaw people originally inhabited the Southeastern Woodlands, in what is now Mississippi and Alabama. Their language is a Western Muskogean language.",
      "date": "-1500"
    },
    {
      "headline": "Choctaw-European Contact",
      "text": "The Choctaw first encountered European explorers in the 16th century, including Hernando de Soto in 1540.",
      "date": "1540"
    },
    {
      "headline": "Treaty of Hopewell",
      "text": "In 1786, the Choctaw signed the Treaty of Hopewell with the United States, establishing boundaries and peaceful relations.",
      "date": "1786"
    },
    {
      "headline": "Treaty of Dancing Rabbit Creek",
      "text": "On September 27, 1830, the Choctaw signed the Treaty of Dancing Rabbit Creek, ceding their lands east of the Mississippi River to the United States and agreeing to relocate to Indian Territory (present-day Oklahoma).",
      "date": "1830-09-27"
    },
    {
      "headline": "Choctaw Trail of Tears",
      "text": "The Choctaw were the first of the Five Civilized Tribes to be forcibly removed from their ancestral lands in the southeastern United States to Indian Territory in the 1830s, a journey known as the Trail of Tears.",
      "date": "1831"
    },
    {
      "headline": "Choctaw Nation of Oklahoma",
      "text": "Following their relocation, the Choctaw established the Choctaw Nation in Indian Territory, which later became part of the state of Oklahoma.",
      "date": "1834"
    },
    {
      "headline": "Choctaw Code Talkers",
      "text": "During World War I, Choctaw soldiers served as code talkers, using their language to transmit secure military communications.",
      "date": "1918"
    },
    {
      "headline": "Federal Recognition",
      "text": "Today, Choctaw people are enrolled in four federally recognized tribes: the Choctaw Nation of Oklahoma, Mississippi Band of Choctaw Indians, Jena Band of Choctaw Indians in Louisiana, and the Yowani Choctaws enrolled under the confederacy of the Caddo Nation.",
      "date": "1970"
    }
  ]
}

