{
  "timeline": [
    {
      "headline": "Siege of Yorktown Begins",
      "text": "The Siege of Yorktown, also known as the Battle of Yorktown, began on September 28, 1781. It was a decisive engagement during the American Revolutionary War, where American and French forces laid siege to the British Army in Yorktown, Virginia.",
      "date": "1781-09-28"
    },
    {
      "headline": "French and American Forces Establish Siege Lines",
      "text": "By early October 1781, the combined American and French forces had established siege lines around Yorktown, effectively trapping the British forces led by General Charles Cornwallis.",
      "date": "1781-10"
    },
    {
      "headline": "First Parallel Completed",
      "text": "On October 6, 1781, the first parallel, a trench line used to besiege the British forces, was completed by the American and French troops.",
      "date": "1781-10-06"
    },
    {
      "headline": "Second Parallel Completed",
      "text": "The second parallel was completed on October 11, 1781, bringing the American and French forces closer to the British defenses.",
      "date": "1781-10-11"
    },
    {
      "headline": "British Counterattack Fails",
      "text": "On October 15, 1781, a British counterattack on the American and French siege lines failed, further weakening the British position.",
      "date": "1781-10-15"
    },
    {
      "headline": "British Surrender at Yorktown",
      "text": "On October 19, 1781, at 10:30 am, British Lieutenant General Charles Cornwallis formally surrendered to General George Washington, marking a decisive victory for the American and French forces and effectively ending major combat operations in the American Revolutionary War.",
      "date": "1781-10-19"
    }
  ]
}

