{
  "timeline": [
    {
      "headline": "Third Battle of Panipat",
      "text": "The Third Battle of Panipat took place on 14 January 1761 between the Maratha Confederacy and the invading army of the Durrani Empire. The battle occurred in and around the city of Panipat, approximately 97 kilometres north of Delhi.",
      "date": "1761-01-14"
    },
    {
      "headline": "Alliances and Support",
      "text": "The Afghans were supported by three key allies in India: Najib ad-Dawlah, who persuaded the support of the Rohilla chiefs, elements of the declining Mughal Empire, and the Oudh State under Shuja-ud-Daula.",
      "date": "1761-01-14"
    },
    {
      "headline": "Leadership of the Maratha Army",
      "text": "The Maratha army was led by Sadashivrao Bhau, who was the third-highest authority of the Maratha Confederacy after the Chhatrapati and the Peshwa.",
      "date": "1761-01-14"
    },
    {
      "headline": "Maratha Army Stationed",
      "text": "The bulk of the Maratha army was stationed in the Deccan Plateau with the Peshwa.",
      "date": "1761-01-14"
    }
  ]
}

