{
  "timeline": [
    {
      "headline": "Introduction of SD Card",
      "text": "The SD card was introduced in August 1999 as a joint effort between SanDisk, Panasonic (Matsushita Electric), and Toshiba to create a new standard for flash memory cards.",
      "date": "1999-08"
    },
    {
      "headline": "Formation of SD Association",
      "text": "In January 2000, the SD Association (SDA) was formed to promote and create standards for SD cards. The association was founded by Matsushita, SanDisk, and Toshiba.",
      "date": "2000-01"
    },
    {
      "headline": "Introduction of miniSD",
      "text": "The miniSD card was introduced in 2003 as a smaller form factor of the original SD card, designed for mobile phones.",
      "date": "2003"
    },
    {
      "headline": "Introduction of microSD",
      "text": "The microSD card, originally known as T-Flash or TransFlash, was introduced in 2005. It is the smallest memory card available and is widely used in mobile phones.",
      "date": "2005"
    },
    {
      "headline": "Introduction of SDHC",
      "text": "In 2006, the SDHC (Secure Digital High Capacity) format was introduced, allowing for storage capacities greater than 2 GB and up to 32 GB.",
      "date": "2006"
    },
    {
      "headline": "Introduction of SDXC",
      "text": "The SDXC (Secure Digital eXtended Capacity) format was introduced in 2009, supporting storage capacities up to 2 TB.",
      "date": "2009"
    },
    {
      "headline": "Introduction of UHS-I",
      "text": "In 2010, the UHS-I (Ultra High Speed) bus was introduced, providing faster data transfer speeds for SDHC and SDXC cards.",
      "date": "2010"
    },
    {
      "headline": "Introduction of UHS-II",
      "text": "The UHS-II bus was introduced in 2011, offering even faster data transfer speeds by adding a second row of pins.",
      "date": "2011"
    },
    {
      "headline": "Introduction of UHS-III",
      "text": "In 2017, the UHS-III bus was introduced, further increasing data transfer speeds for SD cards.",
      "date": "2017"
    },
    {
      "headline": "Introduction of SD Express",
      "text": "In 2018, the SD Express standard was introduced, incorporating PCIe and NVMe interfaces to significantly increase data transfer speeds.",
      "date": "2018"
    }
  ]
}

