      "headline": "Start of the First Punic War",
      "text": "The First Punic War began in 264 BC, marking the start of hostilities between Rome and Carthage over control of Sicily.",
      "date": "-0264"
    },
    {
      "headline": "Battle of Mylae",
      "text": "In 260 BC, the Roman fleet won its first major naval victory against Carthage at the Battle of Mylae.",
      "date": "-0260"
    },
    {
      "headline": "Battle of Ecnomus",
      "text": "In 256 BC, the Romans achieved a decisive naval victory at the Battle of Ecnomus, one of the largest naval battles in history.",
      "date": "-0256"
    },
    {
      "headline": "Battle of Cape Ecnomus",
      "text": "In 255 BC, the Romans suffered a defeat at the Battle of Cape Ecnomus, leading to the loss of their fleet.",
      "date": "-0255"
    },
    {
      "headline": "End of the First Punic War",
      "text": "The First Punic War ended in 241 BC with the Roman victory and the signing of a peace treaty, leading to Carthage ceding Sicily to Rome.",
      "date": "-0241"
    },
    {
      "headline": "Mercenary War",
      "text": "Following the First Punic War, the Mercenary War broke out in 241 BC when Carthaginian mercenaries revolted due to unpaid wages.",
      "date": "-0241"
    },
    {
      "headline": "Start of the Second Punic War",
      "text": "The Second Punic War began in 218 BC, initiated by Hannibal's attack on the Roman ally Saguntum in Spain.",
      "date": "-0218"
    },
    {
      "headline": "Battle of Cannae",
      "text": "In 216 BC, Hannibal achieved a major victory against Rome at the Battle of Cannae, one of the most significant battles of the Second Punic War.",
      "date": "-0216"
    },
    {
      "headline": "Battle of Zama",
      "text": "In 202 BC, the Romans, led by Scipio Africanus, defeated Hannibal at the Battle of Zama, effectively ending the Second Punic War.",
      "date": "-0202"
    },
    {
      "headline": "End of the Second Punic War",
      "text": "The Second Punic War concluded in 201 BC with the Treaty of Lutatius, which imposed harsh terms on Carthage.",
      "date": "-0201"
    },
    {
      "headline": "Start of the Third Punic War",
      "text": "The Third Punic War began in 149 BC as Rome sought to finally destroy Carthage.",
      "date": "-0149"
    },
    {
      "headline": "Destruction of Carthage",
      "text": "In 146 BC, the Third Punic War ended with the complete destruction of Carthage by Roman forces.",
      "date": "-0146"
    }
  ]
}

