    {
      "headline": "Initial Development of MS-DOS",
      "text": "In July 1980, IBM approached Microsoft to discuss an operating system for its upcoming IBM PC. Microsoft did not have an operating system at the time, so they acquired 86-DOS from Seattle Computer Products, which was then adapted to become MS-DOS.",
      "date": "1980-07"
    },
    {
      "headline": "Release of MS-DOS 1.0",
      "text": "MS-DOS 1.0 was released in August 1981 as the operating system for the IBM PC. It was a renamed version of 86-DOS, which Microsoft had acquired and modified.",
      "date": "1981-08"
    },
    {
      "headline": "Introduction of MS-DOS 2.0",
      "text": "MS-DOS 2.0 was released in March 1983, introducing support for hard disks, directories, and other features that significantly enhanced the operating system's capabilities.",
      "date": "1983-03"
    },
    {
      "headline": "Release of MS-DOS 3.0",
      "text": "In August 1984, MS-DOS 3.0 was released, adding support for high-density floppy disks and improved memory management.",
      "date": "1984-08"
    },
    {
      "headline": "MS-DOS 4.0 Launch",
      "text": "MS-DOS 4.0 was launched in July 1988, featuring a graphical shell and support for larger hard disks.",
      "date": "1988-07"
    },
    {
      "headline": "Release of MS-DOS 5.0",
      "text": "MS-DOS 5.0 was released in June 1991, introducing a full-screen text editor, improved memory management, and support for larger hard drives.",
      "date": "1991-06"
    },
    {
      "headline": "MS-DOS 6.0 Release",
      "text": "In March 1993, MS-DOS 6.0 was released, adding features like disk compression and disk defragmentation tools.",
      "date": "1993-03"
    },
    {
      "headline": "Introduction of MS-DOS 6.22",
      "text": "MS-DOS 6.22 was released in June 1994, which was the last standalone version of MS-DOS before it was integrated into Windows 95.",
      "date": "1994-06"
    },
    {
      "headline": "Integration into Windows 95",
      "text": "In August 1995, MS-DOS was integrated into Windows 95, marking the beginning of its decline as a standalone operating system.",
      "date": "1995-08"
    },
    {
      "headline": "End of MS-DOS as a Standalone Product",
      "text": "With the release of Windows ME in September 2000, MS-DOS was no longer provided as a standalone product, effectively marking the end of its development.",
      "date": "2000-09"
    }
  ]
}

