{
  "timeline": [
    {
      "headline": "First Use of the Term 'Corvette'",
      "text": "The term 'corvette' was first used in the 1670s to describe small warships that were smaller than frigates but larger than sloops.",
      "date": "1670"
    },
    {
      "headline": "Corvettes in the Age of Sail",
      "text": "During the Age of Sail, corvettes were typically three-masted ships with square rigging and were used for escort duties, reconnaissance, and delivering dispatches.",
      "date": "1700"
    },
    {
      "headline": "Corvettes in the Napoleonic Wars",
      "text": "Corvettes played a significant role during the Napoleonic Wars (1803-1815), serving as fast and maneuverable ships for the British and French navies.",
      "date": "1803"
    },
    {
      "headline": "Decline of Sail Corvettes",
      "text": "With the advent of steam power, the traditional sail-powered corvette began to decline in use by the mid-19th century.",
      "date": "1850"
    },
    {
      "headline": "Revival of Corvettes in World War II",
      "text": "Corvettes were revived during World War II as small, fast, and maneuverable escort vessels, particularly by the British Royal Navy, to protect convoys from submarines.",
      "date": "1939"
    },
    {
      "headline": "Flower-class Corvettes",
      "text": "The Flower-class corvettes were a class of 294 ships used by the Allies during World War II, known for their role in anti-submarine warfare.",
      "date": "1940"
    },
    {
      "headline": "Post-War Use of Corvettes",
      "text": "After World War II, corvettes continued to be used by navies around the world, often for patrol duties and as training vessels.",
      "date": "1945"
    },
    {
      "headline": "Modern Corvettes",
      "text": "In the 21st century, corvettes are used by many navies for coastal patrol, anti-submarine warfare, and as multi-role vessels equipped with modern technology.",
      "date": "2000"
    }
  ]
}

