    {
      "headline": "Emergence of the Olmec Civilization",
      "text": "The Olmec civilization emerged as the earliest known major Mesoamerican civilization, flourishing in the modern-day Mexican states of Veracruz and Tabasco. This period marks the beginning of the Olmec's cultural and societal development.",
      "date": "-1200"
    },
    {
      "headline": "Development of San Lorenzo Tenochtitlán",
      "text": "San Lorenzo Tenochtitlán became the first major center of the Olmec civilization. It was during this time that the Olmecs developed their distinctive art style, including colossal stone heads.",
      "date": "-1200"
    },
    {
      "headline": "Decline of San Lorenzo",
      "text": "Around the 10th century BCE, San Lorenzo began to decline, possibly due to environmental changes or human actions. This decline led to the movement of the Olmec center to La Venta.",
      "date": "-0900"
    },
    {
      "headline": "Rise of La Venta",
      "text": "La Venta became the new center of the Olmec civilization. It was during this period that the Olmecs reached their cultural zenith, constructing large earthen pyramids and ceremonial complexes.",
      "date": "-0900"
    },
    {
      "headline": "Construction of the Great Pyramid at La Venta",
      "text": "The Great Pyramid at La Venta, one of the largest and most significant Olmec structures, was constructed during this period, showcasing the architectural and cultural achievements of the Olmecs.",
      "date": "-0900"
    },
    {
      "headline": "Mysterious Disappearance of the Olmecs",
      "text": "The Olmec civilization mysteriously disappeared in the 4th century BCE. The reasons for their decline remain unclear, but it left the region sparsely populated until much later.",
      "date": "-0400"
    }
  ]
}

