{
  "timeline": [
    {
      "headline": "Development of Euclidean Geometry",
      "text": "Around 300 BCE, Euclid of Alexandria wrote 'The Elements', a comprehensive compilation of the knowledge of geometry of his time, which became the standard textbook for teaching mathematics, especially geometry, for many centuries.",
      "date": "-0300"
    },
    {
      "headline": "Introduction of Coordinate Geometry",
      "text": "In 1637, René Descartes published 'La Géométrie', which introduced the concept of using algebra to describe geometry, laying the foundation for analytic geometry.",
      "date": "1637"
    },
    {
      "headline": "Development of Non-Euclidean Geometry",
      "text": "In the early 19th century, mathematicians such as Carl Friedrich Gauss, János Bolyai, and Nikolai Lobachevsky independently developed non-Euclidean geometries, which challenged the traditional Euclidean view by altering the parallel postulate.",
      "date": "1820"
    },
    {
      "headline": "Foundation of Topology",
      "text": "In the late 19th century, mathematicians like Henri Poincaré began developing topology, a branch of geometry concerned with the properties of space that are preserved under continuous transformations.",
      "date": "1890"
    },
    {
      "headline": "Development of Differential Geometry",
      "text": "In the 19th century, differential geometry emerged as a field, combining calculus and geometry to study curves and surfaces. This was significantly advanced by the work of Carl Friedrich Gauss and Bernhard Riemann.",
      "date": "1850"
    },
    {
      "headline": "Introduction of Algebraic Geometry",
      "text": "In the 20th century, algebraic geometry, which studies geometries defined by polynomial equations, was further developed by mathematicians like Oscar Zariski and André Weil.",
      "date": "1930"
    },
    {
      "headline": "Advancements in Computational Geometry",
      "text": "In the late 20th century, computational geometry emerged as a field focusing on the development of algorithms to solve geometric problems, driven by the needs of computer graphics and computer-aided design.",
      "date": "1980"
    }
  ]
}

