{
  "timeline": [
    {
      "headline": "Origins of Bharatanatyam",
      "text": "Bharatanatyam is believed to have originated in Tamil Nadu, India, as a temple dance tradition. It is one of the oldest classical dance forms in India, with roots tracing back to ancient Tamil Nadu and the Natya Shastra, a Sanskrit Hindu text on the performing arts.",
      "date": "-0200"
    },
    {
      "headline": "Codification in the Natya Shastra",
      "text": "The Natya Shastra, attributed to the sage Bharata Muni, is a foundational treatise on Indian classical dance and drama. It is believed to have been composed between 200 BCE and 200 CE and provides the framework for Bharatanatyam.",
      "date": "-0200"
    },
    {
      "headline": "Development during the Chola Dynasty",
      "text": "During the Chola dynasty (9th to 13th centuries), Bharatanatyam was further developed and flourished in the temples of Tamil Nadu. The Cholas were great patrons of the arts, and the dance form was performed by Devadasis in temples.",
      "date": "0900"
    },
    {
      "headline": "Colonial Period and Decline",
      "text": "During the British colonial period in India, Bharatanatyam faced decline due to the suppression of temple practices and the Devadasi system. The dance form was stigmatized and associated with social issues.",
      "date": "1800"
    },
    {
      "headline": "Revival by Rukmini Devi Arundale",
      "text": "In the early 20th century, Rukmini Devi Arundale played a crucial role in the revival of Bharatanatyam. She redefined the dance form, removing its perceived stigma and presenting it as a respectable art form. She founded the Kalakshetra Foundation in 1936 to promote Bharatanatyam and other Indian arts.",
      "date": "1936"
    },
    {
      "headline": "Recognition by Sangeet Natak Akademi",
      "text": "Bharatanatyam was recognized as one of the classical dance forms of India by the Sangeet Natak Akademi, India's national academy for music, dance, and drama.",
      "date": "1950"
    }
  ]
}

