    {
      "headline": "Visit to the United States",
      "text": "In 1969, Fela Kuti visited the United States, where he was influenced by the Black Power movement.",
      "date": "1969"
    },
    {
      "headline": "Formation of the Kalakuta Republic",
      "text": "In 1970, Fela Kuti declared his compound in Lagos as the Kalakuta Republic, a commune and recording studio.",
      "date": "1970"
    },
    {
      "headline": "Release of 'Zombie'",
      "text": "In 1977, Fela Kuti released the album 'Zombie', which criticized the Nigerian military government.",
      "date": "1977"
    },
    {
      "headline": "Attack on the Kalakuta Republic",
      "text": "In 1977, the Nigerian military attacked the Kalakuta Republic, destroying the compound and injuring Fela Kuti and his followers.",
      "date": "1977"
    },
    {
      "headline": "Marriage to 27 Women",
      "text": "In 1978, Fela Kuti married 27 women in a single ceremony, many of whom were his dancers and singers.",
      "date": "1978"
    },
    {
      "headline": "Formation of the Movement of the People",
      "text": "In 1979, Fela Kuti formed his own political party, the Movement of the People (MOP), to contest elections.",
      "date": "1979"
    },
    {
      "headline": "Imprisonment",
      "text": "In 1984, Fela Kuti was arrested and sentenced to five years in prison on charges of currency smuggling, but was released after 20 months.",
      "date": "1984"
    },
    {
      "headline": "Release from Prison",
      "text": "Fela Kuti was released from prison in 1986 after serving 20 months of his sentence.",
      "date": "1986"
    },
    {
      "headline": "Death of Fela Kuti",
      "text": "Fela Kuti died on August 2, 1997, in Lagos, Nigeria, from complications related to AIDS.",
      "date": "1997-08-02"
    }
  ]
}

