    {
      "headline": "Formation of Einsatzgruppen",
      "text": "The Einsatzgruppen were formed in 1939 as paramilitary death squads under the direction of the SS, tasked with carrying out mass murders, primarily by shooting, in German-occupied Europe during World War II.",
      "date": "1939"
    },
    {
      "headline": "Invasion of Poland",
      "text": "Following the invasion of Poland in September 1939, the Einsatzgruppen began their operations by targeting the intelligentsia, cultural elite, and members of the Catholic priesthood in Poland.",
      "date": "1939-09"
    },
    {
      "headline": "Operation Barbarossa",
      "text": "During Operation Barbarossa, which began on June 22, 1941, the Einsatzgruppen expanded their operations into the Soviet Union, targeting Jews, Romani people, Soviet political commissars, and alleged partisans.",
      "date": "1941-06-22"
    },
    {
      "headline": "Babi Yar Massacre",
      "text": "One of the most infamous massacres carried out by the Einsatzgruppen occurred at Babi Yar, near Kyiv, where over 33,000 Jews were murdered over two days, starting on September 29, 1941.",
      "date": "1941-09-29"
    },
    {
      "headline": "Role in the Final Solution",
      "text": "The Einsatzgruppen played a crucial role in the implementation of the Final Solution, systematically murdering Jews across Eastern Europe as part of the Nazi plan for the genocide of the Jewish people.",
      "date": "1941"
    },
    {
      "headline": "Nuremberg Trials",
      "text": "After the war, key leaders of the Einsatzgruppen were prosecuted during the Nuremberg Trials, specifically in the Einsatzgruppen Trial, which took place from 1947 to 1948.",
      "date": "1947"
    }
  ]
}

