    {
      "headline": "Creation of the X-Men and the Avengers",
      "text": "In 1963, Kirby co-created the X-Men and the Avengers, further expanding the Marvel Universe.",
      "date": "1963"
    },
    {
      "headline": "Departure from Marvel Comics",
      "text": "In 1970, Jack Kirby left Marvel Comics and joined DC Comics, where he created the Fourth World saga.",
      "date": "1970"
    },
    {
      "headline": "Return to Marvel Comics",
      "text": "In 1975, Kirby returned to Marvel Comics, where he worked on titles such as Captain America and Black Panther.",
      "date": "1975"
    },
    {
      "headline": "Final Years and Death",
      "text": "Jack Kirby continued to work in comics until his death on February 6, 1994, in Thousand Oaks, California, USA.",
