      "headline": "2009 European Parliament Election",
      "text": "In the 2009 European Parliament election, the Party for Freedom won 4 out of the 25 Dutch seats, marking its first entry into the European Parliament.",
      "date": "2009"
    },
    {
      "headline": "2010 Dutch General Election",
      "text": "The Party for Freedom gained significant ground in the 2010 Dutch general election, winning 24 seats and becoming the third-largest party in the House of Representatives.",
      "date": "2010"
    },
    {
      "headline": "Support for the First Rutte Cabinet",
      "text": "Following the 2010 election, the Party for Freedom provided support to the minority First Rutte cabinet, a coalition between the VVD and the Christian Democratic Appeal (CDA), without being part of the government.",
      "date": "2010"
    },
    {
      "headline": "Withdrawal of Support for the First Rutte Cabinet",
      "text": "In April 2012, the Party for Freedom withdrew its support for the First Rutte cabinet, leading to the collapse of the government and triggering early elections.",
      "date": "2012-04"
    },
    {
      "headline": "2012 Dutch General Election",
      "text": "In the 2012 Dutch general election, the Party for Freedom won 15 seats, a decrease from the previous election.",
      "date": "2012"
    },
    {
      "headline": "2014 European Parliament Election",
      "text": "The Party for Freedom participated in the 2014 European Parliament election and won 4 seats, maintaining its presence in the European Parliament.",
      "date": "2014"
    },
    {
      "headline": "2017 Dutch General Election",
      "text": "In the 2017 Dutch general election, the Party for Freedom increased its number of seats to 20, becoming the second-largest party in the House of Representatives.",
      "date": "2017"
    },
    {
      "headline": "2019 European Parliament Election",
      "text": "In the 2019 European Parliament election, the Party for Freedom lost all its seats, failing to secure representation.",
      "date": "2019"
    },
    {
      "headline": "2021 Dutch General Election",
      "text": "The Party for Freedom won 17 seats in the 2021 Dutch general election, maintaining its position as one of the larger parties in the House of Representatives.",
      "date": "2021"
    }
  ]
}

