      "headline": "Roman Conquest",
      "text": "In 123 BCE, the Balearic Islands were conquered by the Romans, who incorporated them into the Roman Republic.",
      "date": "-0123"
    },
    {
      "headline": "Vandal and Byzantine Rule",
      "text": "In 455 CE, the Balearic Islands were conquered by the Vandals, and later, in 534 CE, they were annexed by the Byzantine Empire.",
      "date": "0455"
    },
    {
      "headline": "Muslim Conquest",
      "text": "In 902, the Balearic Islands were conquered by the Moors and became part of the Caliphate of Córdoba.",
      "date": "0902"
    },
    {
      "headline": "Christian Reconquest",
      "text": "In 1229, King James I of Aragon began the Christian reconquest of the Balearic Islands, starting with the conquest of Mallorca.",
      "date": "1229"
    },
    {
      "headline": "Incorporation into the Crown of Aragon",
      "text": "In 1235, the Balearic Islands were fully incorporated into the Crown of Aragon.",
      "date": "1235"
    },
    {
      "headline": "War of Spanish Succession",
      "text": "In 1715, following the War of Spanish Succession, the Balearic Islands were ceded to Spain under the Treaty of Utrecht.",
      "date": "1715"
    },
    {
      "headline": "Autonomous Community",
      "text": "In 1983, the Balearic Islands became an autonomous community of Spain, with Palma de Mallorca as its capital.",
      "date": "1983"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of the Praetorian Guard",
      "text": "The Praetorian Guard was established by Augustus in 27 BCE as an elite unit of the Imperial Roman army, serving as personal bodyguards to the Roman emperors.",
      "date": "-0027"
    },
    {
      "headline": "Reorganization by Tiberius",
      "text": "In 23 CE, Emperor Tiberius reorganized the Praetorian Guard, concentrating them in a single camp, the Castra Praetoria, on the outskirts of Rome.",
      "date": "0023"
    },
    {
      "headline": "Role in the Assassination of Caligula",
      "text": "In 41 CE, members of the Praetorian Guard were involved in the assassination of Emperor Caligula, demonstrating their significant political influence.",
      "date": "0041"
    },
    {
      "headline": "Elevation of Claudius to Emperor",
      "text": "Following Caligula's assassination in 41 CE, the Praetorian Guard declared Claudius as the new emperor, showcasing their power in imperial succession.",
      "date": "0041"
    },
    {
      "headline": "Involvement in the Year of the Four Emperors",
      "text": "In 69 CE, during the Year of the Four Emperors, the Praetorian Guard played a crucial role in the political turmoil, supporting different claimants to the throne.",
      "date": "0069"
    },
    {
      "headline": "Disbandment by Constantine the Great",
      "text": "In 312 CE, after defeating Maxentius at the Battle of the Milvian Bridge, Emperor Constantine the Great disbanded the Praetorian Guard, ending their centuries-long influence.",
      "date": "0312"
    }
  ]
}

