{
  "timeline": [
    {
      "headline": "Introduction of the Gold Standard",
      "text": "The gold standard was first implemented in the United Kingdom in 1821, establishing a monetary system where the standard economic unit of account is based on a fixed quantity of gold.",
      "date": "1821"
    },
    {
      "headline": "International Adoption of the Gold Standard",
      "text": "During the 1870s, the gold standard became the basis for the international monetary system as many countries adopted it.",
      "date": "1870"
    },
    {
      "headline": "Gold Standard Act in the United States",
      "text": "The United States officially adopted the gold standard with the passage of the Gold Standard Act on March 14, 1900.",
      "date": "1900-03-14"
    },
    {
      "headline": "Suspension During World War I",
      "text": "The gold standard was suspended during World War I as countries needed to print more money to finance the war, leading to a temporary abandonment of the system.",
      "date": "1914"
    },
    {
      "headline": "Return to the Gold Standard",
      "text": "After World War I, countries attempted to return to the gold standard during the 1920s, but it was fraught with economic difficulties.",
      "date": "1920"
    },
    {
      "headline": "Great Depression and the End of the Gold Standard",
      "text": "The Great Depression led to the abandonment of the gold standard by most countries. The United States left the gold standard in 1933.",
      "date": "1933"
    },
    {
      "headline": "Bretton Woods System",
      "text": "The Bretton Woods system was established in 1944, creating a new international monetary system where currencies were pegged to the US dollar, which was convertible to gold.",
      "date": "1944"
    },
    {
      "headline": "End of the Bretton Woods System",
      "text": "On August 15, 1971, the United States unilaterally terminated the convertibility of the US dollar to gold, effectively ending the Bretton Woods system.",
      "date": "1971-08-15"
    }
  ]
}

