{
  "timeline": [
    {
      "headline": "Assassination of Rajiv Gandhi",
      "text": "On 21 May 1991, former Prime Minister Rajiv Gandhi was assassinated by a suicide bomber affiliated with the Liberation Tigers of Tamil Eelam (LTTE) during an election campaign rally in Sriperumbudur, Tamil Nadu.",
      "date": "1991-05-21"
    },
    {
      "headline": "First Phase of Elections",
      "text": "The first phase of the Indian general elections was held on 20 May 1991. This phase was conducted amidst heightened security due to the assassination of Rajiv Gandhi.",
      "date": "1991-05-20"
    },
    {
      "headline": "Second Phase of Elections",
      "text": "The second phase of the Indian general elections took place on 12 June 1991.",
      "date": "1991-06-12"
    },
    {
      "headline": "Third Phase of Elections",
      "text": "The third and final phase of the Indian general elections was conducted on 15 June 1991.",
      "date": "1991-06-15"
    },
    {
      "headline": "Postponement of Elections in Punjab",
      "text": "Due to ongoing insurgency and violence, the elections in Punjab were postponed and eventually held on 19 February 1992.",
      "date": "1992-02-19"
    },
    {
      "headline": "Formation of the 10th Lok Sabha",
      "text": "Following the elections, the 10th Lok Sabha was formed. The Indian National Congress, led by P. V. Narasimha Rao, emerged as the largest party and formed the government.",
      "date": "1991"
    },
    {
      "headline": "P. V. Narasimha Rao Becomes Prime Minister",
      "text": "P. V. Narasimha Rao was sworn in as the Prime Minister of India, leading a Congress minority government, after the elections.",
      "date": "1991"
    }
  ]
}

