{
  "timeline": [
    {
      "headline": "Birth of Wendy Carlos",
      "text": "Wendy Carlos was born on November 14, 1939, in Pawtucket, Rhode Island, USA.",
      "date": "1939-11-14"
    },
    {
      "headline": "Education and Early Career",
      "text": "In the late 1950s, Wendy Carlos attended Brown University, where she studied music and physics. She later pursued a master's degree in music composition at Columbia University, graduating in 1965.",
      "date": "1965"
    },
    {
      "headline": "Release of 'Switched-On Bach'",
      "text": "In 1968, Wendy Carlos released 'Switched-On Bach', an album of Bach compositions performed on a Moog synthesizer. The album was a commercial success and won three Grammy Awards.",
      "date": "1968"
    },
    {
      "headline": "Collaboration with Stanley Kubrick",
      "text": "In 1971, Wendy Carlos collaborated with director Stanley Kubrick to compose the electronic score for the film 'A Clockwork Orange'.",
      "date": "1971"
    },
    {
      "headline": "Score for 'The Shining'",
      "text": "In 1980, Wendy Carlos composed the score for Stanley Kubrick's horror film 'The Shining'.",
      "date": "1980"
    },
    {
      "headline": "Score for 'Tron'",
      "text": "In 1982, Wendy Carlos composed the score for the Disney science fiction film 'Tron', which was one of the first films to use computer-generated imagery.",
      "date": "1982"
    },
    {
      "headline": "Release of 'Beauty in the Beast'",
      "text": "In 1986, Wendy Carlos released the album 'Beauty in the Beast', which explored alternate tunings and complex rhythms.",
      "date": "1986"
    },
    {
      "headline": "Release of 'Tales of Heaven and Hell'",
      "text": "In 1998, Wendy Carlos released 'Tales of Heaven and Hell', an album that included a variety of electronic compositions.",
      "date": "1998"
    }
  ]
}

