      "headline": "First French Settlement",
      "text": "The first French settlement on Saint Barthélemy was established in 1648 by colonists from Normandy and Brittany.",
      "date": "1648"
    },
    {
      "headline": "Swedish Control",
      "text": "In 1784, France ceded Saint Barthélemy to Sweden in exchange for trading rights in Gothenburg. The island was named Gustavia after the Swedish King Gustav III.",
      "date": "1784"
    },
    {
      "headline": "Return to French Control",
      "text": "Saint Barthélemy was sold back to France by Sweden in 1878 after a referendum where the island's population voted to return to French rule.",
      "date": "1878"
    },
    {
      "headline": "Overseas Collectivity Status",
      "text": "In 2007, Saint Barthélemy became an overseas collectivity of France, separating from Guadeloupe.",
      "date": "2007"
    }
  ]
}

