{
  "timeline": [
    {
      "headline": "Creation of the International Ice Hockey Federation (IIHF)",
      "text": "The International Ice Hockey Federation (IIHF) was founded in 1908, establishing the governing body for international ice hockey competitions.",
      "date": "1908"
    },
    {
      "headline": "First European Ice Hockey Championships",
      "text": "The first European Ice Hockey Championships, which served as a precursor to the World Championships, were held in 1910.",
      "date": "1910"
    },
    {
      "headline": "First Ice Hockey World Championship at the 1920 Summer Olympics",
      "text": "The first official Ice Hockey World Championship was held at the 1920 Summer Olympics in Antwerp, Belgium. This tournament is recognized as the inaugural World Championship.",
      "date": "1920"
    },
    {
      "headline": "Olympic Hockey Tournaments as World Championships",
      "text": "From 1920 to 1968, the Olympic hockey tournaments were also considered the World Championships for those years.",
      "date": "1920"
    },
    {
      "headline": "First Standalone Ice Hockey World Championship",
      "text": "The first standalone Ice Hockey World Championship, separate from the Olympics, was held in 1930.",
      "date": "1930"
    },
    {
      "headline": "World Championships during World War II",
      "text": "The Ice Hockey World Championships were not held from 1940 to 1946 due to World War II.",
      "date": "1940"
    },
    {
      "headline": "Resumption of World Championships Post-War",
      "text": "The Ice Hockey World Championships resumed in 1947 after a hiatus during World War II.",
      "date": "1947"
    },
    {
      "headline": "End of Olympic and World Championship Dual Status",
      "text": "In 1968, the practice of considering the Olympic hockey tournament as the World Championship ended, and the two events became separate.",
      "date": "1968"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of Odesa",
      "text": "Odesa was officially founded in 1794 by a decree of the Russian Empress Catherine the Great, on the site of a Tatar settlement known as Khadjibey.",
      "date": "1794"
    },
    {
      "headline": "Odesa becomes a Free Port",
      "text": "In 1819, Odesa was declared a free port, which significantly boosted its development as a major trading hub in the Russian Empire.",
      "date": "1819"
    },
    {
      "headline": "Odesa's Growth and Development",
      "text": "Throughout the 19th century, Odesa grew rapidly, becoming the fourth largest city of Imperial Russia and a major cultural and economic center.",
      "date": "1800s"
    },
    {
      "headline": "Odesa during the Russian Revolution",
      "text": "During the Russian Revolution of 1917, Odesa experienced significant political upheaval, changing hands multiple times between different factions.",
      "date": "1917"
    },
    {
      "headline": "Odesa in World War II",
      "text": "Odesa was occupied by Romanian and German troops from 1941 to 1944 during World War II, suffering significant damage and loss of life.",
      "date": "1941"
    },
    {
      "headline": "Liberation of Odesa",
      "text": "Odesa was liberated by the Soviet Army on April 10, 1944, marking the end of the occupation during World War II.",
      "date": "1944-04-10"
    },
