{
  "timeline": [
    {
      "headline": "Discovery of Statins",
      "text": "In 1976, Akira Endo, a Japanese biochemist, discovered the first statin, mevastatin, from the fungus Penicillium citrinum. This discovery marked the beginning of statin development.",
      "date": "1976"
    },
    {
      "headline": "Development of Lovastatin",
      "text": "In 1978, the pharmaceutical company Merck began developing lovastatin, the first statin to be marketed. It was derived from the fungus Aspergillus terreus.",
      "date": "1978"
    },
    {
      "headline": "FDA Approval of Lovastatin",
      "text": "On September 1, 1987, lovastatin was approved by the U.S. Food and Drug Administration (FDA) for medical use, becoming the first statin available to the public.",
      "date": "1987-09-01"
    },
    {
      "headline": "Introduction of Simvastatin and Pravastatin",
      "text": "In 1991, simvastatin and pravastatin were introduced to the market, expanding the options for cholesterol-lowering medications.",
      "date": "1991"
    },
    {
      "headline": "Introduction of Atorvastatin",
      "text": "In 1996, atorvastatin was introduced. It became one of the best-selling statins due to its effectiveness in lowering cholesterol levels.",
      "date": "1996"
    },
    {
      "headline": "Introduction of Rosuvastatin",
      "text": "In 2003, rosuvastatin was introduced to the market, offering another option for patients needing cholesterol management.",
      "date": "2003"
    },
    {
      "headline": "Patent Expiry and Generic Availability",
      "text": "In 2011, the patent for atorvastatin expired, leading to the availability of generic versions and significantly reducing costs for patients.",
      "date": "2011"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of Xi'an",
      "text": "Xi'an, originally known as Chang'an, was established as a city during the Western Zhou dynasty around 1046 BCE.",
      "date": "-1046"
    },
    {
      "headline": "Capital of the Qin Dynasty",
      "text": "In 221 BCE, Xi'an, then known as Xianyang, became the capital of the Qin dynasty, marking the first unification of China under Emperor Qin Shi Huang.",
      "date": "-0221"
    },
    {
      "headline": "Han Dynasty Capital",
      "text": "In 202 BCE, Xi'an became the capital of the Han dynasty, serving as a political, economic, and cultural center.",
      "date": "-0202"
    },
    {
      "headline": "Tang Dynasty Capital",
      "text": "During the Tang dynasty (618–907), Xi'an, then known as Chang'an, was the capital and one of the largest cities in the world.",
      "date": "0618"
    },
    {
      "headline": "Decline after Tang Dynasty",
      "text": "Following the fall of the Tang dynasty in 907, Xi'an's prominence declined as the capital was moved to other cities.",
      "date": "0907"
    },
    {
      "headline": "Ming Dynasty Rebuilding",
      "text": "In the late 14th century, during the Ming dynasty, the city walls of Xi'an were rebuilt, which still stand today.",
      "date": "1370"
    },
    {
      "headline": "Xi'an Incident",
      "text": "On December 12, 1936, the Xi'an Incident occurred, where Chiang Kai-shek was detained by his generals, leading to a temporary truce between the Nationalists and Communists.",
      "date": "1936-12-12"
    },
    {
      "headline": "Discovery of Terracotta Army",
      "text": "In 1974, the Terracotta Army was discovered near Xi'an, which became one of China's most famous archaeological sites.",
      "date": "1974"
    },
    {
      "headline": "Xi'an as a Modern Metropolis",
      "text": "By the 21st century, Xi'an had developed into a major cultural, industrial, and educational center in Western China.",
      "date": "2000"
    }
  ]
}

