    },
    {
      "headline": "Visit to China",
      "text": "In 1345, Ibn Battuta reached China, visiting cities such as Beijing and Guangzhou.",
      "date": "1345"
    },
    {
      "headline": "Return to Morocco",
      "text": "Ibn Battuta returned to Morocco in 1349 after traveling through Spain and North Africa.",
      "date": "1349"
    },
    {
      "headline": "Final Journey",
      "text": "In 1353, Ibn Battuta embarked on his final journey, traveling across the Sahara to the Kingdom of Mali in West Africa.",
      "date": "1353"
    },
    {
      "headline": "Completion of The Rihla",
      "text": "In 1355, Ibn Battuta completed his travelogue, The Rihla, which documented his extensive travels over three decades.",
      "date": "1355"
    },
    {
      "headline": "Death of Ibn Battuta",
      "text": "Ibn Battuta died in 1368 or 1369 in Morocco.",
      "date": "1368"
