{
  "timeline": [
    {
      "headline": "Francisco Goya Moves to Quinta del Sordo",
      "text": "In 1819, at the age of 72, Francisco Goya moved into a two-story house outside Madrid called Quinta del Sordo. The house had been named after the previous owner, who was deaf, and Goya himself was nearly deaf at the time due to an illness he suffered at age 46.",
      "date": "1819"
    },
    {
      "headline": "Creation of the Black Paintings",
      "text": "Between 1819 and 1823, Francisco Goya created the Black Paintings. These 14 paintings were painted directly onto the walls of his house, Quinta del Sordo. They are known for their intense and haunting themes, reflecting Goya's fear of insanity and bleak outlook on humanity.",
      "date": "1819"
    },
    {
      "headline": "Black Paintings Transferred to Canvas",
      "text": "The Black Paintings were later transferred from the walls of Quinta del Sordo to canvas by Baron Frédéric Émile d'Erlanger. This process involved 'hacking off' the murals from the walls.",
      "date": "1874"
    },
    {
      "headline": "Black Paintings in Museo del Prado",
      "text": "The Black Paintings are now housed in the Museo del Prado in Madrid, where they continue to be studied and admired for their powerful and enigmatic imagery.",
      "date": "Present"
    }
  ]
}

