    {
      "headline": "First Description of Ehlers–Danlos Syndromes",
      "text": "Ehlers–Danlos syndromes were first described in the early 20th century by Edvard Ehlers and Henri-Alexandre Danlos, who identified the characteristic symptoms of the disorders.",
      "date": "1900"
    },
    {
      "headline": "Recognition of EDS as a Group of Disorders",
      "text": "Throughout the 20th century, Ehlers–Danlos syndromes were recognized as a group of related genetic connective-tissue disorders, characterized by symptoms such as loose joints, stretchy skin, and abnormal scar formation.",
      "date": "1950"
    },
    {
      "headline": "Development of the Berlin Nosology",
      "text": "In 1988, the Berlin Nosology was developed to classify Ehlers–Danlos syndromes into different types based on clinical symptoms and genetic findings.",
      "date": "1988"
    },
    {
      "headline": "Villefranche Classification",
      "text": "In 1997, the Villefranche classification system was introduced, which categorized Ehlers–Danlos syndromes into six major types, providing a more standardized approach to diagnosis.",
      "date": "1997"
    },
    {
      "headline": "2017 International Classification Update",
      "text": "In 2017, the classification of Ehlers–Danlos syndromes was updated to include a total of 13 subtypes, incorporating several rarer forms of the disorder.",
      "date": "2017"
    }
  ]
}

