{
  "timeline": [
    {
      "headline": "Earliest Settlement",
      "text": "The area of Aleppo has been inhabited since around 5000 BCE, making it one of the oldest continuously inhabited cities in the world.",
      "date": "-5000"
    },
    {
      "headline": "Yamhad Kingdom",
      "text": "Around 1800 BCE, Aleppo became the capital of the Amorite kingdom of Yamhad, which was a major power in the region.",
      "date": "-1800"
    },
    {
      "headline": "Hittite Conquest",
      "text": "In the 16th century BCE, Aleppo was conquered by the Hittites, marking a significant change in its political landscape.",
      "date": "-1600"
    },
    {
      "headline": "Neo-Assyrian Empire",
      "text": "Aleppo came under the control of the Neo-Assyrian Empire in the 8th century BCE.",
      "date": "-0800"
    },
    {
      "headline": "Persian Rule",
      "text": "Aleppo was incorporated into the Achaemenid Empire after the conquests of Cyrus the Great in the 6th century BCE.",
      "date": "-0600"
    },
    {
      "headline": "Hellenistic Period",
      "text": "Following the conquests of Alexander the Great, Aleppo became part of the Seleucid Empire in the 4th century BCE.",
      "date": "-0300"
    },
    {
      "headline": "Roman Era",
      "text": "Aleppo was incorporated into the Roman Empire in 64 BCE by Pompey the Great.",
      "date": "-0064"
    },
    {
      "headline": "Byzantine Control",
      "text": "After the division of the Roman Empire, Aleppo became part of the Byzantine Empire.",
      "date": "0395"
    },
    {
      "headline": "Islamic Conquest",
      "text": "In 637, Aleppo was conquered by the Rashidun Caliphate during the early Islamic conquests.",
      "date": "0637"
    },
    {
      "headline": "Mamluk Rule",
      "text": "In 1260, Aleppo came under the control of the Mamluk Sultanate after the defeat of the Mongols.",
      "date": "1260"
    },
    {
      "headline": "Ottoman Empire",
      "text": "Aleppo became part of the Ottoman Empire in 1516 after the Battle of Marj Dabiq.",
      "date": "1516"
    },
    {
      "headline": "French Mandate",
      "text": "Following World War I, Aleppo was placed under French Mandate as part of the newly created state of Syria in 1920.",
      "date": "1920"
    },
    {
      "headline": "Independence of Syria",
      "text": "Syria, including Aleppo, gained independence from French control in 1946.",
      "date": "1946"
    },
    {
      "headline": "Syrian Civil War",
      "text": "Aleppo became a major battleground during the Syrian Civil War, with significant fighting occurring from 2012 to 2016.",
      "date": "2012"
    },
    {
      "headline": "Battle of Aleppo",
      "text": "The Battle of Aleppo concluded in December 2016 with the Syrian government regaining control of the city.",
      "date": "2016-12"
    }
  ]
}

