{
  "timeline": [
    {
      "headline": "First Use of Affirmative Action",
      "text": "The term 'affirmative action' was first used in the United States in Executive Order 10925, signed by President John F. Kennedy on March 6, 1961. The order required government contractors to 'take affirmative action to ensure that applicants are employed, and that employees are treated during employment, without regard to their race, creed, color, or national origin.'",
      "date": "1961-03-06"
    },
    {
      "headline": "Civil Rights Act of 1964",
      "text": "The Civil Rights Act of 1964 was a landmark piece of legislation in the United States that outlawed discrimination based on race, color, religion, sex, or national origin. It laid the groundwork for affirmative action policies by prohibiting unequal application of voter registration requirements and racial segregation in schools, employment, and public accommodations.",
      "date": "1964"
    },
    {
      "headline": "Executive Order 11246",
      "text": "On September 24, 1965, President Lyndon B. Johnson signed Executive Order 11246, which required government contractors to take affirmative action to ensure that equal opportunity is provided in all aspects of their employment. This order also established the Office of Federal Contract Compliance Programs (OFCCP) to enforce the order.",
      "date": "1965-09-24"
    },
    {
      "headline": "Regents of the University of California v. Bakke",
      "text": "In 1978, the U.S. Supreme Court case Regents of the University of California v. Bakke addressed affirmative action in college admissions. The Court ruled that race could be one of several factors in college admission policy but rejected the use of racial quotas.",
      "date": "1978"
    },
    {
      "headline": "Proposition 209 in California",
      "text": "In 1996, California voters approved Proposition 209, which amended the state constitution to prohibit state governmental institutions from considering race, sex, or ethnicity, specifically in the areas of public employment, public contracting, and public education.",
      "date": "1996"
    },
    {
      "headline": "Grutter v. Bollinger",
      "text": "In 2003, the U.S. Supreme Court upheld the affirmative action admissions policy of the University of Michigan Law School in Grutter v. Bollinger. The Court ruled that the use of race as a factor in admissions decisions was constitutional as it furthered a compelling interest in obtaining the educational benefits that flow from a diverse student body.",
      "date": "2003"
    },
    {
      "headline": "Fisher v. University of Texas",
      "text": "In 2013 and again in 2016, the U.S. Supreme Court heard Fisher v. University of Texas, a case challenging the university's affirmative action policy. In 2016, the Court upheld the university's policy, ruling that the use of race in admissions decisions was constitutional under the Equal Protection Clause.",
      "date": "2016"
    }
  ]
}

