{
  "timeline": [
    {
      "headline": "Babylonian Astronomy",
      "text": "Babylonian astronomers began systematically recording celestial events around 1200 BCE. They developed early forms of celestial calendars and star catalogs.",
      "date": "-1200"
    },
    {
      "headline": "Greek Astronomy",
      "text": "Around 600 BCE, Greek philosophers like Thales and Anaximander began to propose natural explanations for celestial phenomena, laying the groundwork for Western astronomy.",
      "date": "-0600"
    },
    {
      "headline": "Aristarchus Proposes Heliocentric Model",
      "text": "In the 3rd century BCE, Aristarchus of Samos proposed a heliocentric model of the solar system, suggesting that the Earth orbits the Sun.",
      "date": "-0270"
    },
    {
      "headline": "Ptolemaic System",
      "text": "In the 2nd century CE, Claudius Ptolemy developed the geocentric model of the universe, which placed Earth at the center. This model dominated Western astronomy for over a millennium.",
      "date": "0150"
    },
    {
      "headline": "Copernican Revolution",
      "text": "In 1543, Nicolaus Copernicus published 'De revolutionibus orbium coelestium', which proposed a heliocentric model of the universe, challenging the Ptolemaic system.",
      "date": "1543"
    },
    {
      "headline": "Galileo's Telescopic Observations",
      "text": "In 1609, Galileo Galilei used a telescope to observe celestial bodies, discovering moons orbiting Jupiter and the phases of Venus, providing evidence for the heliocentric model.",
      "date": "1609"
    },
    {
      "headline": "Kepler's Laws of Planetary Motion",
      "text": "Between 1609 and 1619, Johannes Kepler formulated his three laws of planetary motion, describing the elliptical orbits of planets around the Sun.",
      "date": "1609"
    },
    {
      "headline": "Newton's Law of Universal Gravitation",
      "text": "In 1687, Isaac Newton published 'Philosophiæ Naturalis Principia Mathematica', which included his law of universal gravitation, explaining the forces governing celestial bodies.",
      "date": "1687"
    },
    {
      "headline": "Discovery of Uranus",
      "text": "In 1781, William Herschel discovered Uranus, the first planet to be discovered with a telescope, expanding the known boundaries of the solar system.",
      "date": "1781"
    },
    {
      "headline": "Einstein's Theory of General Relativity",
      "text": "In 1915, Albert Einstein published his theory of general relativity, providing a new understanding of gravity and its effects on the fabric of space-time.",
      "date": "1915"
    },
    {
      "headline": "Discovery of Cosmic Microwave Background Radiation",
      "text": "In 1965, Arno Penzias and Robert Wilson discovered the cosmic microwave background radiation, providing strong evidence for the Big Bang theory.",
      "date": "1965"
    },
    {
      "headline": "Launch of the Hubble Space Telescope",
      "text": "In 1990, the Hubble Space Telescope was launched, providing unprecedented views of the universe and leading to numerous astronomical discoveries.",
      "date": "1990"
    },
    {
      "headline": "Discovery of Exoplanets",
      "text": "In the 1990s, astronomers began discovering exoplanets, planets orbiting stars outside our solar system, significantly expanding our understanding of planetary systems.",
      "date": "1992"
    },
    {
      "headline": "Detection of Gravitational Waves",
      "text": "In 2015, the LIGO observatory made the first direct detection of gravitational waves, confirming a major prediction of Einstein's general relativity.",
      "date": "2015"
    }
  ]
}

