    },
    {
      "headline": "Link to Variant Creutzfeldt–Jakob Disease (vCJD)",
      "text": "In 1996, scientists established a link between BSE in cattle and variant Creutzfeldt–Jakob disease (vCJD) in humans.",
      "date": "1996"
    },
    {
      "headline": "BSE Crisis in Europe",
      "text": "The BSE crisis spread to other European countries in the late 1990s, leading to widespread culling of cattle and bans on British beef exports.",
      "date": "1990s"
    },
    {
      "headline": "Global Measures to Combat BSE",
      "text": "In response to the BSE crisis, the World Health Organization and other international bodies implemented measures to control the spread of BSE, including banning certain animal feed practices.",
      "date": "2000s"
    },
    {
      "headline": "Decline in BSE Cases",
      "text": "By the early 2000s, the number of BSE cases had significantly declined due to stringent control measures.",
      "date": "2000s"
    },
    {
      "headline": "Total vCJD Cases Reported",
      "text": "As of 2018, a total of 231 cases of variant Creutzfeldt–Jakob disease (vCJD) had been reported globally.",
      "date": "2018"
    }
  ]
}

