{
  "timeline": [
    {
      "headline": "Establishment of the Soviet Union",
      "text": "On December 30, 1922, the Soviet Union was officially established as the first communist state, following the Russian Revolution of 1917 and the subsequent Russian Civil War.",
      "date": "1922-12-30"
    },
    {
      "headline": "Formation of the Comintern",
      "text": "The Communist International (Comintern) was founded in March 1919 to promote world communism. It played a significant role in the spread of Marxism-Leninism.",
      "date": "1919-03"
    },
    {
      "headline": "Bolshevization of the Comintern",
      "text": "In 1924, the Comintern underwent Bolshevization, aligning its policies closely with those of the Soviet Union and promoting Marxism-Leninism globally.",
      "date": "1924"
    },
    {
      "headline": "Establishment of the Eastern Bloc",
      "text": "Following World War II, several Eastern European countries became communist states under Soviet influence, forming the Eastern Bloc by 1949.",
      "date": "1949"
    },
    {
      "headline": "Formation of the Warsaw Pact",
      "text": "On May 14, 1955, the Warsaw Pact was established as a collective defense treaty among eight communist states of Central and Eastern Europe during the Cold War.",
      "date": "1955-05-14"
    },
    {
      "headline": "Cuban Revolution",
      "text": "On January 1, 1959, Fidel Castro's revolutionary forces overthrew the Batista regime in Cuba, leading to the establishment of a communist state.",
      "date": "1959-01-01"
    },
    {
      "headline": "Cultural Revolution in China",
      "text": "Initiated by Mao Zedong in 1966, the Cultural Revolution aimed to preserve Chinese communism by purging remnants of capitalist and traditional elements from Chinese society.",
      "date": "1966"
    },
    {
      "headline": "Revolutions of 1989",
      "text": "In 1989, a series of revolutions in Eastern Europe led to the fall of communist governments in countries such as Poland, East Germany, Czechoslovakia, and Romania.",
      "date": "1989"
    },
    {
      "headline": "Dissolution of the Soviet Union",
      "text": "On December 26, 1991, the Soviet Union was officially dissolved, marking the end of the world's first and largest communist state.",
      "date": "1991-12-26"
    },
    {
      "headline": "Communism in the 21st Century",
      "text": "As of the 21st century, communism remains the official ideology of the ruling parties in China, Cuba, Laos, Vietnam, and to a lesser extent, North Korea.",
      "date": "2000"
    }
  ]
}

