{
  "timeline": [
    {
      "headline": "Beginning of Luddite Movement",
      "text": "The Luddite movement began in Nottingham, England, in 1811. It was a response to the introduction of machinery in the textile industry, which threatened the jobs and livelihoods of skilled workers.",
      "date": "1811"
    },
    {
      "headline": "Spread of Luddite Riots",
      "text": "By early 1812, the Luddite riots had spread to Yorkshire, Lancashire, and other parts of England. The movement gained momentum as more workers joined in the destruction of machinery.",
      "date": "1812"
    },
    {
      "headline": "Government Response to Luddite Activities",
      "text": "In 1812, the British government responded to the Luddite activities by making machine-breaking a capital offense. This was part of a broader effort to suppress the movement and protect industrial interests.",
      "date": "1812"
    },
    {
      "headline": "Assassination of William Horsfall",
      "text": "On April 28, 1812, William Horsfall, a mill owner known for his opposition to the Luddites, was assassinated by a group of Luddites in West Yorkshire. This event marked a significant escalation in the conflict.",
      "date": "1812-04-28"
    },
    {
      "headline": "Trial and Execution of Luddites",
      "text": "In 1813, several Luddites were put on trial and executed for their involvement in the riots and machine-breaking. These trials were part of the government's crackdown on the movement.",
      "date": "1813"
    },
    {
      "headline": "Decline of the Luddite Movement",
      "text": "By 1816, the Luddite movement had largely declined due to the government's harsh reprisals and the increasing adoption of machinery in the textile industry.",
      "date": "1816"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Margaret Sanger",
      "text": "Margaret Sanger was born on September 14, 1879, in Corning, New York.",
      "date": "1879-09-14"
    },
    {
      "headline": "Marriage to William Sanger",
      "text": "In 1902, Margaret Sanger married architect William Sanger.",
      "date": "1902"
    },
    {
      "headline": "Publication of 'What Every Girl Should Know'",
      "text": "In 1912, Sanger began writing a column on sex education titled 'What Every Girl Should Know' for the socialist magazine The Call.",
      "date": "1912"
    },
    {
      "headline": "Publication of 'Family Limitation'",
      "text": "In 1914, Sanger published 'Family Limitation', a pamphlet that provided information on various contraceptive methods.",
      "date": "1914"
    },
    {
      "headline": "Founding of The Woman Rebel",
      "text": "In March 1914, Sanger launched The Woman Rebel, a monthly newsletter promoting contraception.",
      "date": "1914-03"
    },
    {
      "headline": "Opening of the First Birth Control Clinic",
      "text": "On October 16, 1916, Sanger opened the first birth control clinic in the United States in Brownsville, Brooklyn.",
      "date": "1916-10-16"
    },
    {
      "headline": "Founding of the American Birth Control League",
      "text": "In 1921, Sanger founded the American Birth Control League, which later became the Planned Parenthood Federation of America.",
      "date": "1921"
    },
    {
      "headline": "Marriage to J. Noah H. Slee",
      "text": "In 1922, Sanger married J. Noah H. Slee, an oil tycoon who supported her work.",
      "date": "1922"
    },
    {
      "headline": "International Birth Control Conference",
      "text": "In 1925, Sanger organized the Sixth International Neo-Malthusian and Birth Control Conference in New York City.",
      "date": "1925"
    },
    {
      "headline": "Founding of the Birth Control Clinical Research Bureau",
      "text": "In 1923, Sanger established the Birth Control Clinical Research Bureau in New York City to provide contraceptive services and gather data on birth control methods.",
      "date": "1923"
    },
    {
      "headline": "Retirement and Death",
      "text": "Margaret Sanger retired in the 1940s and passed away on September 6, 1966, in Tucson, Arizona.",
      "date": "1966-09-06"
    }
  ]
}

