    {
      "headline": "Naturalization as a U.S. Citizen",
      "text": "John Demjanjuk became a naturalized U.S. citizen on November 14, 1958.",
      "date": "1958-11-14"
    },
    {
      "headline": "First Denaturalization",
      "text": "In 1981, Demjanjuk was stripped of his U.S. citizenship after being accused of being 'Ivan the Terrible' of Treblinka.",
      "date": "1981"
    },
    {
      "headline": "Extradition to Israel",
      "text": "Demjanjuk was extradited to Israel in 1986 to stand trial for war crimes.",
      "date": "1986"
    },
    {
      "headline": "Conviction in Israel",
      "text": "On April 18, 1988, Demjanjuk was convicted in Israel of crimes against humanity and sentenced to death.",
      "date": "1988-04-18"
    },
    {
      "headline": "Acquittal by Israeli Supreme Court",
      "text": "On July 29, 1993, the Israeli Supreme Court overturned Demjanjuk's conviction, citing reasonable doubt about his identity as 'Ivan the Terrible'.",
      "date": "1993-07-29"
    },
    {
      "headline": "Return to the United States",
      "text": "Demjanjuk returned to the United States in 1993 after his acquittal in Israel.",
      "date": "1993"
    },
    {
      "headline": "Second Denaturalization",
      "text": "In 2002, Demjanjuk was again stripped of his U.S. citizenship after new evidence emerged of his service at Sobibor and other Nazi camps.",
      "date": "2002"
    },
    {
      "headline": "Extradition to Germany",
      "text": "In May 2009, Demjanjuk was extradited to Germany to face charges of accessory to murder at Sobibor.",
      "date": "2009-05"
    },
    {
      "headline": "Conviction in Germany",
      "text": "On May 12, 2011, Demjanjuk was convicted by a German court as an accessory to the murder of 28,060 Jews at Sobibor and sentenced to five years in prison.",
      "date": "2011-05-12"
    },
    {
      "headline": "Death of John Demjanjuk",
      "text": "John Demjanjuk died on March 17, 2012, in Bad Feilnbach, Germany, while awaiting appeal.",
      "date": "2012-03-17"
    }
  ]
}

