    {
      "headline": "Crash on Final Approach",
      "text": "On the morning of July 6, 2013, Asiana Airlines Flight 214 crashed on final approach into San Francisco International Airport. The Boeing 777-200ER struck a seawall short of the runway, causing the tail section to break off.",
      "date": "2013-07-06"
    },
    {
      "headline": "Casualties and Injuries",
      "text": "Of the 307 people on board, 3 died and 187 were injured, 49 of them seriously. Among the seriously injured were four flight attendants who were thrown onto the runway while still strapped in their seats.",
      "date": "2013-07-06"
    },
    {
      "headline": "First Fatal Crash of Boeing 777",
      "text": "The crash of Asiana Airlines Flight 214 marked the first fatal crash of a Boeing 777 since the aircraft type entered service in 1995.",
      "date": "2013-07-06"
    }
  ]
}

