    {
      "headline": "Incorporation as a City",
      "text": "Cambridge was incorporated as a city in 1846, transitioning from a town to a city government structure.",
      "date": "1846"
    },
    {
      "headline": "MIT Relocation",
      "text": "The Massachusetts Institute of Technology (MIT) moved from Boston to Cambridge in 1916, establishing itself as a leading institution in science and technology.",
