{
  "timeline": [
    {
      "headline": "Napoleon's Defeat and Bourbon Restoration",
      "text": "In 1815, following Napoleon's defeat at the Battle of Waterloo, the Bourbon monarchy was restored in France with Louis XVIII ascending to the throne.",
      "date": "1815"
    },
    {
      "headline": "Louis XVIII's Reign Begins",
      "text": "Louis XVIII began his reign in 1815, marking the start of the Bourbon Restoration. His rule aimed to balance the old monarchy with the new changes brought by the Revolution.",
      "date": "1815"
    },
    {
      "headline": "Charter of 1814",
      "text": "The Charter of 1814 was a constitutional document granted by Louis XVIII, establishing a constitutional monarchy and guaranteeing civil liberties while maintaining royal authority.",
      "date": "1814"
    },
    {
      "headline": "Death of Louis XVIII",
      "text": "Louis XVIII died on September 16, 1824, after a reign marked by efforts to stabilize France post-Revolution and Napoleonic Wars.",
      "date": "1824-09-16"
    },
    {
      "headline": "Charles X Ascends the Throne",
      "text": "Charles X, brother of Louis XVIII, became king on September 16, 1824, following the death of his brother.",
      "date": "1824-09-16"
    },
    {
      "headline": "Ultra-royalist Policies",
      "text": "Charles X pursued ultra-royalist policies, including compensation for nobles who lost lands during the Revolution, which led to growing public discontent.",
      "date": "1825"
    },
    {
      "headline": "July Ordinances",
      "text": "On July 25, 1830, Charles X issued the July Ordinances, which dissolved the Chamber of Deputies, restricted the press, and altered the electoral system, sparking widespread unrest.",
      "date": "1830-07-25"
    },
    {
      "headline": "July Revolution",
      "text": "The July Revolution, also known as the Three Glorious Days, occurred from July 27 to July 29, 1830, leading to the overthrow of Charles X and the end of the Bourbon Restoration.",
      "date": "1830-07-27"
    },
    {
      "headline": "End of Bourbon Restoration",
      "text": "The Bourbon Restoration officially ended on August 2, 1830, when Charles X abdicated the throne, leading to the establishment of the July Monarchy under Louis-Philippe.",
      "date": "1830-08-02"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Demonstration of Incandescent Light",
      "text": "In 1802, Humphry Davy demonstrated the first incandescent light by passing an electric current through a thin strip of platinum, chosen because the metal had an extremely high melting point.",
      "date": "1802"
    },
    {
      "headline": "First Practical Incandescent Lamp",
      "text": "In 1840, British scientist Warren de la Rue developed an efficient design by enclosing a coiled platinum filament in a vacuum tube.",
      "date": "1840"
    },
    {
      "headline": "First Commercially Viable Incandescent Light Bulb",
      "text": "In 1879, Thomas Edison developed a practical and longer-lasting incandescent light bulb using a carbon filament. He filed a patent for his electric lamp on November 4, 1879.",
      "date": "1879-11-04"
    },
    {
      "headline": "Patent for Improved Incandescent Light Bulb",
      "text": "On January 27, 1880, Thomas Edison received a patent for an improved incandescent light bulb with a high-resistance carbon filament.",
      "date": "1880-01-27"
    },
    {
      "headline": "Introduction of Tungsten Filament",
      "text": "In 1906, the General Electric Company patented a method of making filaments from tungsten, which has a higher melting point and longer lifespan than carbon or platinum.",
      "date": "1906"
    },
    {
      "headline": "Development of Gas-Filled Incandescent Lamps",
      "text": "In 1913, Irving Langmuir discovered that filling a bulb with an inert gas, such as nitrogen or argon, could improve efficiency and lifespan by reducing filament evaporation.",
      "date": "1913"
    },
    {
      "headline": "Introduction of Coiled-Coil Filament",
      "text": "In 1936, the coiled-coil filament was introduced, which further increased the efficiency and lifespan of incandescent bulbs.",
      "date": "1936"
    }
  ]
}

