  "timeline": [
    {
      "headline": "Treaty of Versailles",
      "text": "The Treaty of Versailles was signed on June 28, 1919, ending World War I. The treaty imposed heavy reparations and territorial losses on Germany, creating economic and political instability.",
      "date": "1919-06-28"
    },
    {
      "headline": "Rise of the Nazi Party",
      "text": "Adolf Hitler and the Nazi Party rose to power in Germany, culminating in Hitler becoming Chancellor on January 30, 1933. This marked the beginning of a totalitarian regime and aggressive expansionist policies.",
      "date": "1933-01-30"
    },
    {
      "headline": "Japanese Invasion of Manchuria",
      "text": "On September 18, 1931, Japan invaded Manchuria, marking the beginning of Japanese expansionism in Asia and leading to the establishment of the puppet state of Manchukuo.",
      "date": "1931-09-18"
    },
    {
      "headline": "Second Italo-Ethiopian War",
      "text": "Italy invaded Ethiopia on October 3, 1935, under the leadership of Benito Mussolini. This act of aggression was part of Italy's imperial ambitions and undermined the League of Nations.",
      "date": "1935-10-03"
    },
    {
      "headline": "Remilitarization of the Rhineland",
      "text": "On March 7, 1936, Germany remilitarized the Rhineland, violating the Treaty of Versailles and the Locarno Treaties. This bold move by Hitler went unchallenged by France and Britain.",
      "date": "1936-03-07"
    },
    {
      "headline": "Spanish Civil War",
      "text": "The Spanish Civil War began on July 17, 1936, as a military uprising against the Spanish Republic. It became a proxy war for the Axis and Allied powers, with Germany and Italy supporting the Nationalists.",
      "date": "1936-07-17"
    },
    {
      "headline": "Anschluss with Austria",
      "text": "On March 12, 1938, Germany annexed Austria in a union known as the Anschluss, further expanding its territory and violating the Treaty of Versailles.",
      "date": "1938-03-12"
    },
    {
      "headline": "Munich Agreement",
      "text": "The Munich Agreement was signed on September 30, 1938, allowing Germany to annex the Sudetenland region of Czechoslovakia. This act of appeasement failed to prevent further aggression.",
      "date": "1938-09-30"
    },
    {
      "headline": "Invasion of Czechoslovakia",
      "text": "On March 15, 1939, Germany invaded and occupied Czechoslovakia, further demonstrating its expansionist ambitions and undermining European stability.",
      "date": "1939-03-15"
    },
    {
      "headline": "Molotov-Ribbentrop Pact",
      "text": "On August 23, 1939, Germany and the Soviet Union signed the Molotov-Ribbentrop Pact, a non-aggression treaty that included secret protocols for the division of Eastern Europe.",
      "date": "1939-08-23"
    },
    {
      "headline": "Invasion of Poland",
      "text": "World War II began with the invasion of Poland by Nazi Germany on September 1, 1939. This act of aggression led Britain and France to declare war on Germany.",
      "date": "1939-09-01"
    }
  ]
}

