    {
      "headline": "Peak of Vijayanagara Empire",
      "text": "During the 14th and 15th centuries, Hampi reached its peak as the capital of the Vijayanagara Empire, known for its architectural grandeur and as a hub of trade and culture.",
      "date": "1400"
    },
    {
      "headline": "Battle of Talikota",
      "text": "In 1565, the Battle of Talikota led to the defeat of the Vijayanagara Empire by the Deccan Sultanates, resulting in the destruction and decline of Hampi.",
      "date": "1565"
    },
    {
      "headline": "Rediscovery and Archaeological Interest",
      "text": "In the 19th century, Hampi was rediscovered by European archaeologists and historians, sparking interest in its ruins and history.",
