{
  "timeline": [
    {
      "headline": "First Identified Outbreak",
      "text": "The first recognized outbreak of Legionnaires' disease occurred in July 1976 during an American Legion convention at the Bellevue-Stratford Hotel in Philadelphia, Pennsylvania. The outbreak resulted in 221 cases and 34 deaths.",
      "date": "1976-07"
    },
    {
      "headline": "Identification of Legionella Bacteria",
      "text": "In January 1977, the bacterium responsible for Legionnaires' disease was identified as Legionella pneumophila by scientists at the Centers for Disease Control and Prevention (CDC).",
      "date": "1977-01"
    },
    {
      "headline": "Naming of Legionnaires' Disease",
      "text": "The disease was named 'Legionnaires' disease' after the American Legion convention where the first major outbreak was identified.",
      "date": "1977"
    },
    {
      "headline": "Discovery of Legionella in Water Systems",
      "text": "In the late 1970s, it was discovered that Legionella bacteria could thrive in water systems, such as those in large buildings, leading to further understanding of how the disease spreads.",
      "date": "1970s"
    },
    {
      "headline": "Development of Diagnostic Tests",
      "text": "Throughout the 1980s, diagnostic tests for Legionnaires' disease were developed, including urinary antigen tests and culture techniques, improving the ability to diagnose the disease.",
      "date": "1980s"
    },
    {
      "headline": "Implementation of Prevention Guidelines",
      "text": "In the 1990s, guidelines for the prevention of Legionnaires' disease were implemented, focusing on maintaining and monitoring water systems to prevent the growth of Legionella bacteria.",
      "date": "1990s"
    },
    {
      "headline": "Recognition of Global Impact",
      "text": "By the early 2000s, Legionnaires' disease was recognized as a global health issue, with outbreaks reported in various countries, leading to increased international collaboration on prevention and control measures.",
      "date": "2000s"
    }
  ]
}

