    {
      "headline": "Capture of Cork",
      "text": "Pro-Treaty forces captured Cork on August 10, 1922, marking a significant victory.",
      "date": "1922-08-10"
    },
    {
      "headline": "End of Conventional Warfare",
      "text": "By the end of 1922, conventional warfare had largely ended, and the conflict shifted to guerrilla tactics.",
      "date": "1922"
