    "timeline": [
        {
            "headline": "Birth of Anthony of Padua",
            "text": "Anthony of Padua was born as Fernando Martins de Bulhões on 1195 in Lisbon, Portugal.",
            "date": "1195"
        },
        {
            "headline": "Joining the Canons Regular",
            "text": "In 1210, at the age of 15, Fernando joined the Canons Regular of the Order of the Holy Cross at the Abbey of Saint Vincent on the outskirts of Lisbon.",
            "date": "1210"
        },
        {
            "headline": "Transfer to the Abbey of Santa Cruz",
            "text": "In 1212, Fernando transferred to the Abbey of Santa Cruz in Coimbra, the then capital of Portugal, where he studied theology and Latin.",
            "date": "1212"
        },
        {
            "headline": "Joining the Franciscans",
            "text": "In 1220, inspired by the martyrdom of five Franciscan friars in Morocco, Fernando joined the Franciscan Order and took the name Anthony.",
            "date": "1220"
        },
        {
            "headline": "Mission to Morocco",
            "text": "In late 1220, Anthony set out for Morocco to preach to the Moors, but he fell seriously ill and was forced to return to Portugal.",
            "date": "1220"
        },
        {
            "headline": "Arrival in Italy",
            "text": "In 1221, after being shipwrecked on the coast of Sicily, Anthony arrived in Italy and attended the general chapter of the Franciscans in Assisi.",
            "date": "1221"
        },
        {
            "headline": "Teaching and Preaching in Italy",
            "text": "Anthony was assigned to a hermitage in Montepaolo, Italy, where he began his work as a preacher and teacher.",
            "date": "1222"
        },
        {
            "headline": "Preaching in Northern Italy and Southern France",
            "text": "From 1224 to 1227, Anthony traveled extensively, preaching in Northern Italy and Southern France, gaining a reputation as a powerful speaker.",
            "date": "1224"
        },
        {
            "headline": "Appointment as Provincial Superior",
            "text": "In 1227, Anthony was appointed as the Provincial Superior of the Franciscans in Northern Italy.",
            "date": "1227"
        },
        {
            "headline": "Return to Padua",
            "text": "In 1230, Anthony returned to Padua, where he continued his preaching and teaching.",
            "date": "1230"
        },
        {
            "headline": "Death of Anthony of Padua",
            "text": "Anthony of Padua died on June 13, 1231, at the age of 36, in Arcella, a suburb of Padua, Italy.",
            "date": "1231-06-13"
        },
        {
            "headline": "Canonization",
            "text": "Anthony of Padua was canonized by Pope Gregory IX on May 30, 1232, less than a year after his death.",
            "date": "1232-05-30"
        },
        {
            "headline": "Proclaimed Doctor of the Church",
            "text": "In 1946, Pope Pius XII proclaimed Anthony of Padua a Doctor of the Church, recognizing his contributions to theology and doctrine.",
            "date": "1946"
        }
    ]
}

