    },
    {
      "headline": "Colonial War",
      "text": "From 1961 to 1974, Portugal was involved in the Colonial War, fighting independence movements in its African colonies.",
      "date": "1961"
    },
    {
      "headline": "Salazar's Illness and Replacement",
      "text": "In 1968, Salazar suffered a stroke and was replaced by Marcelo Caetano as the head of the Estado Novo.",
      "date": "1968"
    },
    {
      "headline": "Carnation Revolution",
      "text": "On 1974-04-25, the Carnation Revolution took place, a military coup that overthrew the Estado Novo regime and led to the establishment of a democratic government in Portugal.",
