    {
      "headline": "Consolidation of the Kingdom of Denmark",
      "text": "The Kingdom of Denmark was already consolidated in the 8th century, with its rulers consistently referred to in Frankish sources as 'kings'.",
      "date": "-0700"
    },
    {
      "headline": "Reign of King Gudfred",
      "text": "Under the rule of King Gudfred in 804, the Kingdom of Denmark may have included all the major provinces of medieval Denmark.",
      "date": "0804"
    },
    {
      "headline": "Introduction of Christianity",
      "text": "Christianity was introduced to Denmark in the 10th century, significantly influencing the monarchy and its governance.",
      "date": "0900"
    },
    {
      "headline": "Reign of King Harald Bluetooth",
      "text": "King Harald Bluetooth, who reigned from around 958 to 986, is credited with uniting Denmark and converting the Danes to Christianity.",
      "date": "0958"
    },
    {
      "headline": "Reign of King Sweyn Forkbeard",
      "text": "King Sweyn Forkbeard, who reigned from 986 to 1014, was the first Danish king to also become King of England.",
      "date": "0986"
    },
    {
      "headline": "Reign of King Canute the Great",
      "text": "King Canute the Great, reigning from 1018 to 1035, ruled over a North Sea Empire that included Denmark, England, Norway, and parts of Sweden.",
      "date": "1018"
    },
    {
      "headline": "Establishment of the Kalmar Union",
      "text": "In 1397, the Kalmar Union was established, uniting the kingdoms of Denmark, Norway, and Sweden under a single monarch.",
      "date": "1397"
    },
    {
      "headline": "Reformation and Lutheran State Church",
      "text": "In 1536, Denmark officially became a Lutheran state, marking the end of Catholicism as the state religion.",
      "date": "1536"
    },
    {
      "headline": "Introduction of Absolute Monarchy",
      "text": "In 1660, Denmark transitioned to an absolute monarchy, centralizing power in the hands of the king.",
      "date": "1660"
    },
    {
      "headline": "Constitutional Monarchy Established",
      "text": "In 1849, Denmark adopted a new constitution, transitioning from absolute monarchy to constitutional monarchy.",
      "date": "1849"
    },
    {
      "headline": "Home Rule for Faroe Islands",
      "text": "In 1948, the Faroe Islands were granted home rule, becoming an autonomous territory within the Kingdom of Denmark.",
      "date": "1948"
    },
    {
      "headline": "Home Rule for Greenland",
      "text": "In 1979, Greenland was granted home rule, further expanding its autonomy within the Kingdom of Denmark.",
      "date": "1979"
    }
  ]
}

