{
  "timeline": [
    {
      "headline": "Formation of Wayanad District",
      "text": "Wayanad district was formed on 1 November 1980 as the 12th district in Kerala, by carving out areas from Kozhikode and Kannur districts.",
      "date": "1980-11-01"
    },
    {
      "headline": "Geographical Features",
      "text": "Wayanad is the only plateau in Kerala, forming a continuation of the Mysore Plateau, the southern portion of the Deccan Plateau. It is set high in the Western Ghats with altitudes ranging from 700 to 2,100 meters.",
      "date": "1980"
    },
    {
      "headline": "Highest Point in Wayanad",
      "text": "Vellari Mala, a 2,240 m (7,349 ft) high peak situated on the trijunction of Wayanad, Malappuram, and Kozhikode districts, is the highest point in Wayanad district.",
      "date": "1980"
    },
    {
      "headline": "Forested Area",
      "text": "An area of 885.92 km2 in Wayanad district is forested, contributing to its rich biodiversity and natural beauty.",
      "date": "1980"
    },
    {
      "headline": "Municipal Towns in Wayanad",
      "text": "Wayanad has three municipal towns—Kalpetta, Mananthavady, and Sulthan Bathery, which serve as important administrative and commercial centers.",
      "date": "1980"
    },
    {
      "headline": "Indigenous Tribes",
      "text": "Wayanad is home to many indigenous tribes, contributing to its cultural diversity and heritage.",
      "date": "1980"
    },
    {
      "headline": "Origin of Kabini River",
      "text": "The Kabini River, a tributary of the Kaveri River, originates in Wayanad, playing a crucial role in the district's ecology and agriculture.",
      "date": "1980"
    },
    {
      "headline": "Natural Gold Fields",
      "text": "Wayanad district, along with the Chaliyar valley in the neighbouring Nilambur in Malappuram district, is known for natural gold fields, which are also seen in other parts of the Nilgiri Biosphere Reserve.",
      "date": "1980"
    },
    {
      "headline": "Origin of Chaliyar River",
      "text": "The Chaliyar river, which is the fourth longest river of Kerala, originates on the Wayanad plateau, contributing to the district's water resources.",
      "date": "1980"
    },
    {
      "headline": "Edakkal Caves",
      "text": "The historically important Edakkal Caves are located in Wayanad district, known for their ancient petroglyphs and archaeological significance.",
      "date": "1980"
    }
  ]
}

