    {
      "headline": "Appointment as Abbot",
      "text": "Mendel was appointed as the abbot of St. Thomas' Abbey in 1868, which limited his time for scientific research.",
      "date": "1868"
    },
    {
      "headline": "Death of Gregor Mendel",
      "text": "Gregor Mendel died on January 6, 1884, in Brno, Austria-Hungary (now Czech Republic), largely unrecognized for his contributions to science during his lifetime.",
