    {
      "headline": "Islamic Conquest",
      "text": "In 711, the Moors conquered the Iberian Peninsula, including the area of present-day Granada.",
      "date": "0711"
    },
    {
      "headline": "Founding of the Taifa of Granada",
      "text": "In 1013, the Zirid dynasty established the Taifa of Granada, making it an independent Muslim kingdom.",
      "date": "1013"
    },
    {
      "headline": "Nasrid Dynasty Establishment",
      "text": "In 1238, Muhammad I founded the Nasrid dynasty, which ruled the Emirate of Granada.",
      "date": "1238"
    },
    {
      "headline": "Completion of the Alhambra",
      "text": "The Alhambra, a famous palace and fortress complex, was completed during the reign of the Nasrid dynasty in the mid-14th century.",
      "date": "1350"
    },
    {
      "headline": "Fall of Granada",
      "text": "On January 2, 1492, the Catholic Monarchs, Ferdinand and Isabella, captured Granada, marking the end of Muslim rule in Spain.",
      "date": "1492-01-02"
    },
    {
      "headline": "Granada War",
      "text": "The Granada War, a series of military campaigns between 1482 and 1492, led to the fall of the Emirate of Granada.",
      "date": "1482"
    },
    {
      "headline": "Granada Massacre",
      "text": "In 1066, a Muslim mob stormed the royal palace in Granada and killed more than 4,000 Jews, known as the Granada Massacre.",
      "date": "1066"
    },
    {
      "headline": "Granada Charter",
      "text": "In 1492, after the conquest, the Catholic Monarchs issued the Granada Charter, which granted certain rights to the Muslim population.",
      "date": "1492"
    },
    {
      "headline": "Expulsion of the Moriscos",
      "text": "In 1609, the Moriscos, Muslims who had converted to Christianity, were expelled from Granada as part of a wider expulsion from Spain.",
      "date": "1609"
    },
