    {
      "headline": "Creation of the Codex Gigas",
      "text": "The Codex Gigas was created in the early 13th century, around the year 1229, in the Benedictine monastery of Podlažice in Bohemia, which is now part of the Czech Republic. It is believed to have been written by a single scribe, possibly a monk, over a period of several years.",
      "date": "1229"
    },
    {
      "headline": "Legend of the Devil's Bible",
      "text": "According to legend, the Codex Gigas was created by a monk who made a pact with the Devil to complete the manuscript in a single night. This legend is associated with the full-page illustration of the Devil found within the manuscript.",
      "date": "1229"
    },
    {
      "headline": "Transfer to the Benedictine Monastery in Břevnov",
      "text": "In the 13th century, the Codex Gigas was transferred to the Benedictine monastery in Břevnov, near Prague, for safekeeping.",
      "date": "1230"
    },
    {
      "headline": "Acquisition by Emperor Rudolf II",
      "text": "In the late 16th century, the Codex Gigas was acquired by Holy Roman Emperor Rudolf II, who brought it to his castle in Prague.",
      "date": "1594"
    },
    {
      "headline": "Transfer to Sweden",
      "text": "During the Thirty Years' War, in 1648, Swedish forces took the Codex Gigas as war booty and brought it to Sweden, where it became part of the collection of Queen Christina of Sweden.",
      "date": "1648"
    },
    {
      "headline": "Housed in the National Library of Sweden",
      "text": "The Codex Gigas has been housed in the National Library of Sweden in Stockholm since 1649, where it remains to this day.",
      "date": "1649"
    }
  ]
}

