      "headline": "Discovery of the Photoelectric Effect",
      "text": "The photoelectric effect was first observed by Heinrich Hertz in 1887. He noticed that ultraviolet light could cause sparks to jump between two metal electrodes.",
      "date": "1887"
    },
    {
      "headline": "Wilhelm Hallwachs' Contribution",
      "text": "In 1888, Wilhelm Hallwachs discovered that a combination of ultraviolet light and a negatively charged plate could cause the plate to lose its charge.",
      "date": "1888"
    },
    {
      "headline": "Philipp Lenard's Experiments",
      "text": "Philipp Lenard conducted experiments in 1902 that showed the energy of photoelectrons was independent of the light intensity but dependent on the light frequency.",
      "date": "1902"
    },
    {
      "headline": "Albert Einstein's Explanation",
      "text": "In 1905, Albert Einstein published a paper explaining the photoelectric effect using the concept of light quanta, which later became known as photons. This work provided crucial support for the quantum theory of light.",
      "date": "1905"
    },
    {
      "headline": "Einstein Awarded Nobel Prize",
      "text": "Albert Einstein was awarded the Nobel Prize in Physics in 1921 for his explanation of the photoelectric effect, which was pivotal in establishing quantum theory.",
      "date": "1921"
    }
  ]
}

