{
  "timeline": [
    {
      "headline": "Launch of the Quit India Movement",
      "text": "The Quit India Movement was launched by Mahatma Gandhi at the Bombay session of the All India Congress Committee on 8 August 1942. Gandhi called for determined, but passive resistance to British rule.",
      "date": "1942-08-08"
    },
    {
      "headline": "Arrest of Indian Leaders",
      "text": "On 9 August 1942, the British government arrested major leaders of the Indian National Congress, including Mahatma Gandhi, Jawaharlal Nehru, and Sardar Vallabhbhai Patel, in an attempt to suppress the movement.",
      "date": "1942-08-09"
    },
    {
      "headline": "Mass Protests and Strikes",
      "text": "Following the arrest of leaders, mass protests and strikes erupted across India. The movement saw widespread acts of civil disobedience, including the destruction of communication and transport networks.",
      "date": "1942-08"
    },
    {
      "headline": "Repression by British Authorities",
      "text": "The British authorities responded to the Quit India Movement with severe repression, including mass detentions, censorship, and the use of force to quell protests. Thousands were arrested, and many were killed.",
      "date": "1942-08"
    },
