    {
      "headline": "Lituya Bay Earthquake",
      "text": "On July 9, 1958, at 22:15:58 PST, a strike-slip earthquake with a moment magnitude of 7.8 to 8.3 occurred on the Fairweather Fault in Alaska. The earthquake had a maximum Mercalli intensity of XI (Extreme).",
      "date": "1958-07-09"
    },
    {
      "headline": "Rockslide Triggered",
      "text": "The earthquake triggered a massive rockslide of 30 million cubic meters, approximately 90 million tons, into the narrow inlet of Lituya Bay.",
      "date": "1958-07-09"
    },
    {
      "headline": "Megatsunami Formation",
      "text": "The rockslide caused a sudden displacement of water, resulting in a megatsunami that washed out trees to a maximum elevation of 524 meters at the entrance of Gilbert Inlet. This event is recognized as the largest and most significant megatsunami in modern times.",
      "date": "1958-07-09"
    },
    {
      "headline": "Impact Heard",
      "text": "The impact of the rockslide and subsequent megatsunami was heard 80 kilometers (50 miles) away from Lituya Bay.",
      "date": "1958-07-09"
    },
    {
      "headline": "Re-evaluation of Large-Wave Events",
      "text": "The 1958 Lituya Bay megatsunami forced a re-evaluation of large-wave events and led to the recognition of impact events, rockfalls, and landslides as causes of very large waves.",
      "date": "1958"
    }
  ]
}

