{
  "timeline": [
    {
      "headline": "Boyle's Law",
      "text": "Boyle's Law, which describes the inversely proportional relationship between the pressure and volume of a gas at constant temperature, was formulated by Robert Boyle in 1662.",
      "date": "1662"
    },
    {
      "headline": "Charles's Law",
      "text": "Charles's Law, which states that the volume of a gas is directly proportional to its temperature at constant pressure, was discovered by Jacques Charles around 1787.",
      "date": "1787"
    },
    {
      "headline": "Gay-Lussac's Law",
      "text": "Gay-Lussac's Law, which relates the pressure of a gas to its temperature at constant volume, was formulated by Joseph Louis Gay-Lussac in 1808.",
      "date": "1808"
    },
    {
      "headline": "Avogadro's Law",
      "text": "Avogadro's Law, which states that equal volumes of gases, at the same temperature and pressure, contain an equal number of molecules, was hypothesized by Amedeo Avogadro in 1811.",
      "date": "1811"
    },
    {
      "headline": "Formulation of the Ideal Gas Law",
      "text": "The Ideal Gas Law was first stated by Benoît Paul Émile Clapeyron in 1834. It combines Boyle's Law, Charles's Law, Avogadro's Law, and Gay-Lussac's Law into one equation.",
      "date": "1834"
    }
  ]
}

{
  "timeline": [
