    {
      "headline": "First Opium War Begins",
      "text": "The First Opium War began in 1839 when the Chinese government, under the Qing dynasty, sought to enforce its ban on the opium trade. This led to conflict with British traders who were importing opium into China.",
      "date": "1839"
    },
    {
      "headline": "Battle of Kowloon",
      "text": "On September 4, 1839, the British Royal Navy engaged Chinese forces in the Battle of Kowloon, marking one of the first military confrontations of the First Opium War.",
      "date": "1839-09-04"
    },
    {
      "headline": "Treaty of Nanking",
      "text": "The Treaty of Nanking was signed on August 29, 1842, ending the First Opium War. It was the first of the 'unequal treaties' and ceded Hong Kong Island to the British, opened five ports to British trade, and granted extraterritorial rights to British citizens.",
      "date": "1842-08-29"
    },
    {
      "headline": "Second Opium War Begins",
      "text": "The Second Opium War, also known as the Arrow War, began in 1856 due to further disputes over trade and diplomatic relations between China and the British Empire, along with France.",
      "date": "1856"
    },
    {
      "headline": "Treaty of Tientsin",
      "text": "The Treaty of Tientsin was signed in June 1858, temporarily halting hostilities during the Second Opium War. It opened more Chinese ports to foreign trade, allowed for foreign legations in Beijing, and legalized the opium trade.",
      "date": "1858-06"
    },
    {
      "headline": "Convention of Peking",
      "text": "The Convention of Peking was signed in October 1860, marking the end of the Second Opium War. It resulted in further concessions to the British and French, including the cession of the Kowloon Peninsula to Britain.",
      "date": "1860-10"
    }
  ]
}

