{
  "timeline": [
    {
      "headline": "Enactment of the Sarbanes–Oxley Act",
      "text": "The Sarbanes–Oxley Act was enacted on July 30, 2002. It is a United States federal law that mandates certain practices in financial record keeping and reporting for corporations. The act is also known as the 'Public Company Accounting Reform and Investor Protection Act' and 'Corporate and Auditing Accountability, Responsibility, and Transparency Act'.",
      "date": "2002-07-30"
    },
    {
      "headline": "Introduction of the Sarbanes–Oxley Act",
      "text": "The Sarbanes–Oxley Act was introduced in response to a number of major corporate and accounting scandals, including those affecting Enron, Tyco International, and WorldCom. These scandals resulted in a decline in public trust in accounting and reporting practices.",
      "date": "2002"
    },
    {
      "headline": "Establishment of the Public Company Accounting Oversight Board (PCAOB)",
      "text": "One of the key provisions of the Sarbanes–Oxley Act was the establishment of the Public Company Accounting Oversight Board (PCAOB), which oversees the audits of public companies to protect investors and the public interest by promoting informative, accurate, and independent audit reports.",
      "date": "2002"
    },
    {
      "headline": "Implementation of Section 404",
      "text": "Section 404 of the Sarbanes–Oxley Act requires management and the external auditor to report on the adequacy of the company's internal control on financial reporting. This section has been one of the most challenging and costly aspects of the legislation for companies to implement.",
      "date": "2002"
    },
    {
      "headline": "Impact on Corporate Governance",
      "text": "The Sarbanes–Oxley Act significantly impacted corporate governance in the United States by enhancing standards for all U.S. public company boards, management, and public accounting firms. It aimed to increase transparency and accountability in corporate financial reporting.",
      "date": "2002"
    }
  ]
}

