{
  "timeline": [
    {
      "headline": "Ellis Island Opens as Immigration Station",
      "text": "On January 1, 1892, Ellis Island officially opened as the United States' first federal immigration station. Annie Moore, a 15-year-old from Ireland, was the first immigrant processed.",
      "date": "1892-01-01"
    },
    {
      "headline": "Ellis Island Fire",
      "text": "On June 15, 1897, a fire destroyed the immigration station on Ellis Island, along with many immigration records dating back to 1855.",
      "date": "1897-06-15"
    },
    {
      "headline": "Reopening of Ellis Island",
      "text": "Ellis Island reopened on December 17, 1900, with new fireproof buildings designed to handle the increasing number of immigrants.",
      "date": "1900-12-17"
    },
    {
      "headline": "Peak Year for Immigration",
      "text": "In 1907, Ellis Island processed a record number of immigrants, with over 1 million people arriving in that year alone.",
      "date": "1907"
    },
    {
      "headline": "Immigration Act of 1924",
      "text": "The Immigration Act of 1924 significantly reduced the number of immigrants allowed into the United States, leading to a decrease in the use of Ellis Island.",
      "date": "1924"
    },
    {
      "headline": "Ellis Island Closes as Immigration Station",
      "text": "On November 12, 1954, Ellis Island closed as an immigration processing station. The last person processed was a Norwegian merchant seaman named Arne Peterssen.",
      "date": "1954-11-12"
    },
    {
      "headline": "Part of Statue of Liberty National Monument",
      "text": "In 1965, President Lyndon B. Johnson declared Ellis Island part of the Statue of Liberty National Monument.",
      "date": "1965"
    },
    {
      "headline": "Ellis Island Immigration Museum Opens",
      "text": "On September 10, 1990, the Ellis Island Immigration Museum opened to the public, showcasing the history of the island and the immigrants who passed through it.",
      "date": "1990-09-10"
    },
    {
      "headline": "South Side of Ellis Island Opens for Tours",
      "text": "In 2014, the south side of Ellis Island, including the Ellis Island Immigrant Hospital, was opened to the public through guided tours.",
      "date": "2014"
    }
  ]
}

