{
  "timeline": [
    {
      "headline": "Early Use of Forensic Science",
      "text": "The earliest known use of forensic science dates back to the 700s when the Chinese used fingerprints to identify documents and clay sculptures.",
      "date": "-0700"
    },
    {
      "headline": "First Forensic Science Book",
      "text": "In 1248, the first forensic science book, 'Xi Yuan Lu' (The Washing Away of Wrongs), was published by Song Ci in China. It was a handbook for coroners.",
      "date": "1248"
    },
    {
      "headline": "Development of Toxicology",
      "text": "In 1814, Mathieu Orfila, a Spanish chemist, published the first scientific treatise on the detection of poisons and their effects on animals, establishing forensic toxicology as a scientific discipline.",
      "date": "1814"
    },
    {
      "headline": "First Use of Fingerprints in Criminal Cases",
      "text": "In 1892, Sir Francis Galton published 'Fingerprints', establishing the individuality and permanence of fingerprints, which led to their use in criminal cases.",
      "date": "1892"
    },
    {
      "headline": "First Crime Lab Established",
      "text": "In 1910, Edmond Locard established the first police crime laboratory in Lyon, France, pioneering the field of forensic science.",
      "date": "1910"
    },
