    {
      "headline": "Formation of the National Woman Suffrage Association",
      "text": "In 1869, Susan B. Anthony and Elizabeth Cady Stanton founded the National Woman Suffrage Association (NWSA) to advocate for women's voting rights.",
      "date": "1869"
    },
    {
      "headline": "Formation of the American Woman Suffrage Association",
      "text": "Also in 1869, Lucy Stone, Henry Blackwell, and others formed the American Woman Suffrage Association (AWSA), which focused on securing voting rights for women through state legislation.",
      "date": "1869"
    },
    {
      "headline": "Wyoming Grants Women's Suffrage",
      "text": "Wyoming became the first U.S. territory to grant women the right to vote on December 10, 1869.",
      "date": "1869-12-10"
    },
    {
      "headline": "Colorado Grants Women's Suffrage",
      "text": "Colorado became the first state to grant women the right to vote through a popular referendum on November 7, 1893.",
      "date": "1893-11-07"
    },
    {
      "headline": "Formation of the National American Woman Suffrage Association",
      "text": "In 1890, the NWSA and AWSA merged to form the National American Woman Suffrage Association (NAWSA), which became the leading organization advocating for women's suffrage in the United States.",
      "date": "1890"
    },
    {
      "headline": "Formation of the National Woman's Party",
      "text": "In 1916, Alice Paul and Lucy Burns founded the National Woman's Party (NWP), which used more militant tactics to push for women's suffrage.",
      "date": "1916"
    },
    {
      "headline": "New York Grants Women's Suffrage",
      "text": "On November 6, 1917, New York State granted women the right to vote, marking a significant victory for the suffrage movement.",
      "date": "1917-11-06"
    },
    {
      "headline": "Ratification of the 19th Amendment",
      "text": "The 19th Amendment to the United States Constitution, granting women the right to vote, was ratified on August 18, 1920, and officially adopted on August 26, 1920.",
      "date": "1920-08-18"
    }
  ]
}

