{
  "timeline": [
    {
      "headline": "Discovery of Nuclear Fission",
      "text": "In December 1938, German chemists Otto Hahn and Fritz Strassmann, along with physicists Lise Meitner and Otto Frisch, discovered nuclear fission. They found that when uranium atoms were bombarded with neutrons, they split into lighter elements, releasing a significant amount of energy.",
      "date": "1938-12"
    },
    {
      "headline": "First Explanation of Nuclear Fission",
      "text": "In January 1939, Lise Meitner and Otto Frisch provided the first theoretical explanation of nuclear fission. They described the process and coined the term 'fission' to describe the splitting of the atomic nucleus.",
      "date": "1939-01"
    },
    {
      "headline": "Publication of Nuclear Fission Discovery",
      "text": "In February 1939, the discovery of nuclear fission was published in the journal 'Nature' by Otto Hahn and Fritz Strassmann, with the theoretical explanation by Lise Meitner and Otto Frisch.",
      "date": "1939-02"
    },
    {
      "headline": "First Nuclear Fission Chain Reaction",
      "text": "On December 2, 1942, the first controlled nuclear fission chain reaction was achieved by Enrico Fermi and his team at the University of Chicago as part of the Manhattan Project. This experiment was conducted in a reactor known as Chicago Pile-1.",
      "date": "1942-12-02"
    },
    {
      "headline": "First Use of Nuclear Fission in Warfare",
      "text": "On August 6, 1945, the United States dropped an atomic bomb on Hiroshima, Japan, marking the first use of nuclear fission in warfare. The bomb, known as 'Little Boy', was based on the fission of uranium-235.",
      "date": "1945-08-06"
    },
    {
      "headline": "First Nuclear Power Plant",
      "text": "On June 27, 1954, the first nuclear power plant to generate electricity for a power grid was opened in Obninsk, USSR. This marked the first peaceful use of nuclear fission for energy production.",
      "date": "1954-06-27"
    },
    {
      "headline": "Nuclear Non-Proliferation Treaty",
      "text": "On July 1, 1968, the Nuclear Non-Proliferation Treaty (NPT) was opened for signature. The treaty aimed to prevent the spread of nuclear weapons and promote the peaceful use of nuclear energy.",
      "date": "1968-07-01"
    }
  ]
}

