{
  "timeline": [
    {
      "headline": "Start of Euromaidan Protests",
      "text": "On 21 November 2013, large protests began in Maidan Nezalezhnosti in Kyiv, Ukraine. These protests were sparked by President Viktor Yanukovych's decision not to sign the European Union–Ukraine Association Agreement, opting instead for closer ties with Russia.",
      "date": "2013-11-21"
    },
    {
      "headline": "Violent Dispersal of Protesters",
      "text": "On 30 November 2013, the Ukrainian government violently dispersed protesters in Maidan Nezalezhnosti, which led to further anger and increased the number of demonstrators.",
      "date": "2013-11-30"
    },
    {
      "headline": "Protests Intensify",
      "text": "Throughout December 2013, the protests intensified, with demonstrators calling for the resignation of President Yanukovych and the Azarov government, citing government corruption, abuse of power, and human rights violations.",
      "date": "2013-12"
    },
    {
      "headline": "Hrushevskoho Street Riots",
      "text": "From 19 January 2014, violent clashes between protesters and police erupted on Hrushevskoho Street in Kyiv, marking a significant escalation in the conflict.",
      "date": "2014-01-19"
    },
    {
      "headline": "Anti-Protest Laws Passed",
      "text": "On 16 January 2014, the Ukrainian parliament passed anti-protest laws, which were seen as draconian and further fueled the protests.",
      "date": "2014-01-16"
    },
    {
      "headline": "Deadly Clashes in Kyiv",
      "text": "From 18 to 20 February 2014, deadly clashes occurred in Kyiv, resulting in the deaths of dozens of protesters and police officers. This marked the peak of violence during the Euromaidan protests.",
      "date": "2014-02-18"
    },
    {
      "headline": "Yanukovych Flees Kyiv",
      "text": "On 22 February 2014, President Viktor Yanukovych fled Kyiv, and the Ukrainian parliament voted to remove him from office, leading to the establishment of a new interim government.",
      "date": "2014-02-22"
    },
    {
      "headline": "End of Euromaidan and Start of Revolution of Dignity",
      "text": "The Euromaidan protests culminated in the 2014 Revolution of Dignity, which led to significant political changes in Ukraine, including the establishment of a new government and a shift towards European integration.",
      "date": "2014-02"
    }
  ]
}

