{
  "timeline": [
    {
      "headline": "Release of 'Psycho'",
      "text": "The release of Alfred Hitchcock's 'Psycho' on June 16, 1960, is often credited with popularizing the slasher film genre. The film's shocking murder scenes and psychological tension set a new standard for horror films.",
      "date": "1960-06-16"
    },
    {
      "headline": "Release of 'Peeping Tom'",
      "text": "Released in 1960, 'Peeping Tom' directed by Michael Powell is another early example of the slasher film genre. It was controversial at the time for its depiction of voyeurism and violence.",
      "date": "1960"
    },
    {
      "headline": "Release of 'The Texas Chain Saw Massacre'",
      "text": "On October 11, 1974, 'The Texas Chain Saw Massacre' directed by Tobe Hooper was released. It became a seminal work in the slasher genre, known for its gritty realism and intense atmosphere.",
      "date": "1974-10-11"
    },
    {
      "headline": "Release of 'Black Christmas'",
      "text": "Released on December 20, 1974, 'Black Christmas' directed by Bob Clark is considered one of the earliest slasher films to feature a mysterious killer stalking a group of people, a trope that would become central to the genre.",
      "date": "1974-12-20"
    },
    {
      "headline": "Release of 'Halloween'",
      "text": "John Carpenter's 'Halloween', released on October 25, 1978, is one of the most influential slasher films. It introduced the character Michael Myers and set the template for many subsequent films in the genre.",
      "date": "1978-10-25"
    },
    {
      "headline": "Release of 'Friday the 13th'",
      "text": "On May 9, 1980, 'Friday the 13th' was released, further popularizing the slasher genre. The film introduced the iconic character Jason Voorhees, although he was not the primary antagonist until later sequels.",
      "date": "1980-05-09"
    },
    {
      "headline": "Release of 'A Nightmare on Elm Street'",
      "text": "Released on November 9, 1984, Wes Craven's 'A Nightmare on Elm Street' introduced the character Freddy Krueger and combined slasher elements with supernatural horror, revitalizing the genre.",
      "date": "1984-11-09"
    },
    {
      "headline": "Release of 'Scream'",
      "text": "On December 20, 1996, 'Scream' directed by Wes Craven was released. It revitalized the slasher genre by deconstructing its tropes and introducing a self-aware, satirical approach.",
      "date": "1996-12-20"
    },
    {
      "headline": "Release of 'I Know What You Did Last Summer'",
      "text": "Released on October 17, 1997, 'I Know What You Did Last Summer' is a post-'Scream' slasher film that contributed to the late 1990s revival of the genre.",
      "date": "1997-10-17"
    },
    {
      "headline": "Release of 'Halloween' (2018)",
      "text": "On October 19, 2018, a direct sequel to the original 'Halloween' was released, ignoring previous sequels and rebooting the franchise for a new generation.",
      "date": "2018-10-19"
    }
  ]
}

