      "date": "-08000"
    },
    {
      "headline": "Storegga Slide Tsunami",
      "text": "Around 8,200 years ago, the Storegga underwater landslide generated a tsunami that impacted Doggerland. The extent of the impact is controversial, but it contributed to the submergence of the region.",
      "date": "-06200"
    },
    {
      "headline": "Complete Submergence of Doggerland",
      "text": "By approximately 7,000 years ago, Doggerland was completely submerged beneath the southern North Sea.",
      "date": "-05000"
    }
  ]
}

