    },
    {
      "headline": "Introduction of Polar Route",
      "text": "In 1954, SAS became the first airline to fly the Copenhagen-Los Angeles route over the North Pole, introducing the polar route and significantly reducing flight time.",
      "date": "1954"
    },
    {
      "headline": "Merger of Parent Companies",
      "text": "In 1951, the three parent companies of SAS merged their European operations to form a single airline, further consolidating SAS's position in the aviation industry.",
      "date": "1951"
    },
    {
      "headline": "Introduction of Jet Aircraft",
      "text": "SAS introduced its first jet aircraft, the Sud Aviation Caravelle, into service in 1959, marking the beginning of the jet age for the airline.",
      "date": "1959"
    },
    {
      "headline": "Launch of EuroBonus Program",
      "text": "In 1992, SAS launched its frequent flyer program, EuroBonus, which became one of the most popular loyalty programs in Scandinavia.",
      "date": "1992"
    },
    {
      "headline": "Joining Star Alliance",
      "text": "SAS became a founding member of the Star Alliance on May 14, 1997, joining one of the world's largest global airline alliances.",
      "date": "1997-05-14"
    },
    {
      "headline": "Introduction of New Livery",
      "text": "In 2019, SAS unveiled a new livery design as part of its brand modernization efforts, reflecting a more modern and sustainable image.",
      "date": "2019"
