{
  "timeline": [
    {
      "headline": "First Description by Thomas Hodgkin",
      "text": "In 1832, English physician Thomas Hodgkin first described the condition now known as Hodgkin lymphoma. He identified it as a disease characterized by the presence of enlarged lymph nodes and other symptoms.",
      "date": "1832"
    },
    {
      "headline": "Identification of Reed–Sternberg Cells",
      "text": "In the late 19th century, Reed–Sternberg cells were identified as a key diagnostic feature of Hodgkin lymphoma. These are large, abnormal lymphocytes that can be seen under a microscope in the lymph nodes of affected individuals.",
      "date": "1890"
    },
    {
      "headline": "Development of Radiation Therapy",
      "text": "In the early 20th century, radiation therapy began to be used as a treatment for Hodgkin lymphoma. This marked a significant advancement in the management of the disease.",
      "date": "1900"
    },
    {
      "headline": "Introduction of Chemotherapy",
      "text": "In the mid-20th century, chemotherapy was introduced as a treatment for Hodgkin lymphoma, providing an additional therapeutic option alongside radiation therapy.",
      "date": "1950"
    },
    {
      "headline": "Development of Combination Chemotherapy",
      "text": "In the 1960s, combination chemotherapy regimens, such as MOPP (mechlorethamine, vincristine, procarbazine, and prednisone), were developed, significantly improving survival rates for Hodgkin lymphoma patients.",
      "date": "1960"
    },
    {
      "headline": "Introduction of ABVD Regimen",
      "text": "In the 1970s, the ABVD chemotherapy regimen (doxorubicin, bleomycin, vinblastine, and dacarbazine) was introduced, becoming a standard treatment for Hodgkin lymphoma due to its effectiveness and reduced side effects compared to previous regimens.",
      "date": "1970"
    },
    {
      "headline": "Advancements in Targeted Therapy",
      "text": "In the 21st century, targeted therapies, such as brentuximab vedotin, have been developed for Hodgkin lymphoma, offering new treatment options that specifically target cancer cells while sparing healthy tissue.",
      "date": "2000"
    }
  ]
}

