    },
    {
      "headline": "Introduction of the Hammond Organ",
      "text": "The Hammond organ, an electromechanical instrument, was invented by Laurens Hammond and John M. Hanert in 1935. It became popular in jazz, blues, and rock music.",
      "date": "1935"
    },
    {
      "headline": "Invention of the RCA Mark II Sound Synthesizer",
      "text": "The RCA Mark II Sound Synthesizer, considered the first programmable electronic synthesizer, was developed in 1957 at the Columbia-Princeton Electronic Music Center.",
      "date": "1957"
    },
    {
      "headline": "Introduction of the Moog Synthesizer",
      "text": "The Moog synthesizer, created by Robert Moog in 1964, was one of the first widely used electronic synthesizers and played a significant role in the development of electronic music.",
      "date": "1964"
    },
    {
      "headline": "Release of 'Switched-On Bach'",
      "text": "In 1968, Wendy Carlos released 'Switched-On Bach,' an album featuring music by Johann Sebastian Bach performed on a Moog synthesizer. It was a commercial success and brought electronic music to a wider audience.",
      "date": "1968"
    },
