    {
      "headline": "First Mention of Zion",
      "text": "Zion is first mentioned in the Hebrew Bible as a Jebusite fortress conquered by King David. This event is traditionally dated to around 1000 BCE.",
      "date": "-1000"
    },
    {
      "headline": "King David Establishes Zion as the City of David",
      "text": "After capturing the Jebusite fortress, King David establishes Zion as the City of David, making it the political and spiritual center of his kingdom. This is traditionally dated to around 1000 BCE.",
      "date": "-1000"
    },
    {
      "headline": "Solomon Builds the First Temple",
      "text": "King Solomon, David's son, builds the First Temple on Mount Zion, further solidifying its significance as a religious center. This is traditionally dated to around 957 BCE.",
      "date": "-0957"
    },
    {
      "headline": "Destruction of the First Temple",
      "text": "The First Temple is destroyed by the Babylonians under King Nebuchadnezzar II during the conquest of Jerusalem in 586 BCE.",
      "date": "-0586"
    },
    {
      "headline": "Rebuilding of the Second Temple",
      "text": "After the Babylonian Exile, the Second Temple is built on Mount Zion, completed in 516 BCE, marking the restoration of Jewish worship in Jerusalem.",
      "date": "-0516"
    },
    {
      "headline": "Destruction of the Second Temple",
      "text": "The Second Temple is destroyed by the Romans in 70 CE during the Siege of Jerusalem, a pivotal event in Jewish history.",
      "date": "0070"
    },
    {
      "headline": "Zion in Jewish Liturgy and Tradition",
      "text": "Throughout the centuries, Zion becomes a symbol of Jewish longing and hope, frequently mentioned in prayers and liturgy, especially during the Jewish diaspora.",
      "date": "Throughout centuries"
    },
    {
      "headline": "Modern Zionism Movement",
      "text": "In the late 19th century, the modern Zionist movement emerges, advocating for the return of the Jewish people to Zion and the establishment of a Jewish state.",
      "date": "Late 1800s"
    },
    {
      "headline": "Establishment of the State of Israel",
      "text": "On May 14, 1948, the State of Israel is established, fulfilling the Zionist vision of a Jewish homeland in the historic land of Zion.",
      "date": "1948-05-14"
    }
  ]
}

