{
  "timeline": [
    {
      "headline": "Initial Development of TCP/IP",
      "text": "In the early 1970s, the United States Department of Defense funded research through DARPA to develop a robust, fault-tolerant communication protocol for computer networks. This led to the creation of the Transmission Control Protocol (TCP) and the Internet Protocol (IP).",
      "date": "1970"
    },
    {
      "headline": "Publication of TCP Specification",
      "text": "In December 1974, Vint Cerf and Bob Kahn published a paper titled 'A Protocol for Packet Network Intercommunication', which laid out the design of TCP.",
      "date": "1974-12"
    },
    {
      "headline": "Separation of TCP and IP",
      "text": "In 1978, the original TCP was split into two distinct protocols: the Transmission Control Protocol (TCP) and the Internet Protocol (IP), forming the basis of the Internet protocol suite.",
      "date": "1978"
    },
    {
      "headline": "Adoption of TCP/IP by ARPANET",
      "text": "On January 1, 1983, ARPANET officially adopted TCP/IP as its standard networking protocol, marking a significant milestone in the development of the modern Internet.",
      "date": "1983-01-01"
    },
    {
      "headline": "Development of the Internet Protocol Suite",
      "text": "Throughout the 1980s, the Internet protocol suite continued to evolve, incorporating additional protocols such as the User Datagram Protocol (UDP) and others, which expanded its functionality and application.",
      "date": "1980"
    },
    {
      "headline": "Standardization of TCP/IP",
      "text": "In 1989, the Internet Engineering Task Force (IETF) began the formal standardization process for TCP/IP, leading to the publication of various RFCs (Request for Comments) that defined the protocols.",
      "date": "1989"
    },
    {
      "headline": "Widespread Adoption of TCP/IP",
      "text": "By the early 1990s, TCP/IP had become the dominant networking protocol suite, used by a wide range of networks beyond the original ARPANET, including commercial and academic networks.",
      "date": "1990"
    }
  ]
}

