{
  "timeline": [
    {
      "headline": "Development of the Standard Model Begins",
      "text": "The development of the Standard Model began in the latter half of the 20th century, with contributions from many scientists worldwide.",
      "date": "1950"
    },
    {
      "headline": "Quark Model Proposed",
      "text": "In 1964, Murray Gell-Mann and George Zweig independently proposed the quark model, which became a fundamental part of the Standard Model.",
      "date": "1964"
    },
    {
      "headline": "Electroweak Theory Developed",
      "text": "In 1967, Sheldon Glashow, Abdus Salam, and Steven Weinberg developed the electroweak theory, unifying the electromagnetic force and weak nuclear force.",
      "date": "1967"
    },
    {
      "headline": "Experimental Confirmation of Quarks",
      "text": "In the early 1970s, experiments at the Stanford Linear Accelerator Center provided evidence for the existence of quarks, confirming a key aspect of the Standard Model.",
      "date": "1970"
    },
    {
      "headline": "Standard Model Finalized",
      "text": "By the mid-1970s, the current formulation of the Standard Model was finalized, incorporating the electroweak theory and quantum chromodynamics.",
      "date": "1975"
    },
    {
      "headline": "Discovery of the W and Z Bosons",
      "text": "In 1983, the W and Z bosons were discovered at CERN, providing further confirmation of the electroweak theory.",
      "date": "1983"
    },
    {
      "headline": "Top Quark Discovered",
      "text": "In 1995, the top quark was discovered at Fermilab, completing the quark sector of the Standard Model.",
      "date": "1995"
    },
    {
      "headline": "Tau Neutrino Observed",
      "text": "In 2000, the tau neutrino was observed at Fermilab, confirming the existence of the third type of neutrino predicted by the Standard Model.",
      "date": "2000"
    },
    {
      "headline": "Higgs Boson Discovered",
      "text": "On July 4, 2012, the discovery of the Higgs boson was announced at CERN, providing the final piece of the Standard Model puzzle.",
      "date": "2012-07-04"
    }
  ]
}

