{
  "timeline": [
    {
      "headline": "Invention of Stereolithography",
      "text": "In 1984, Charles Hull invented stereolithography, a process that allows for the creation of three-dimensional objects using digital data. This was one of the first methods of 3D printing.",
      "date": "1984"
    },
    {
      "headline": "Patent for Stereolithography",
      "text": "On March 11, 1986, Charles Hull was granted a patent for stereolithography, which laid the groundwork for the development of 3D printing technology.",
      "date": "1986-03-11"
    },
    {
      "headline": "Founding of 3D Systems",
      "text": "In 1986, Charles Hull co-founded 3D Systems, one of the first companies to commercialize 3D printing technology.",
      "date": "1986"
    },
    {
      "headline": "Introduction of Fused Deposition Modeling (FDM)",
      "text": "In 1988, Scott Crump invented Fused Deposition Modeling (FDM), a 3D printing process that involves the extrusion of thermoplastic material to create objects layer by layer.",
      "date": "1988"
    },
    {
      "headline": "Patent for Fused Deposition Modeling",
      "text": "In 1992, Scott Crump was granted a patent for Fused Deposition Modeling (FDM), further advancing the field of 3D printing.",
      "date": "1992"
    },
    {
      "headline": "First Commercial 3D Printer",
      "text": "In 1992, 3D Systems produced the first commercial 3D printer, the SLA-1, which utilized stereolithography technology.",
      "date": "1992"
    },
    {
      "headline": "Introduction of Selective Laser Sintering (SLS)",
      "text": "In 1992, Selective Laser Sintering (SLS) was developed by Carl Deckard and Joe Beaman at the University of Texas at Austin, allowing for the creation of objects by fusing powdered material with a laser.",
      "date": "1992"
    },
    {
      "headline": "Expiration of Key 3D Printing Patents",
      "text": "In 2009, key patents for Fused Deposition Modeling (FDM) expired, leading to a significant decrease in the cost of 3D printers and a surge in their popularity.",
      "date": "2009"
    },
    {
      "headline": "Launch of Consumer 3D Printers",
      "text": "In the early 2010s, companies like MakerBot began producing affordable consumer 3D printers, making the technology accessible to hobbyists and small businesses.",
      "date": "2010"
    },
    {
      "headline": "3D Printing in Medicine",
      "text": "By the 2010s, 3D printing began to be used in the medical field for creating prosthetics, dental implants, and even bioprinting tissues and organs.",
      "date": "2010"
    },
    {
      "headline": "3D Printing in Aerospace",
      "text": "In the 2010s, the aerospace industry began using 3D printing to produce lightweight and complex parts for aircraft and spacecraft.",
      "date": "2010"
    },
    {
      "headline": "3D Printing in Construction",
      "text": "In the 2010s, 3D printing technology was adapted for use in construction, allowing for the creation of building components and even entire structures.",
      "date": "2010"
    }
  ]
}

