{
  "timeline": [
    {
      "headline": "Founding of Chabad",
      "text": "Chabad was founded in 1775 by Rabbi Shneur Zalman of Liadi in the town of Liozna, Belarus. He developed a unique approach to Hasidic philosophy that emphasized intellectual study and understanding.",
      "date": "1775"
    },
    {
      "headline": "Publication of Tanya",
      "text": "In 1797, Rabbi Shneur Zalman published the Tanya, the foundational work of Chabad philosophy, which outlines the movement's spiritual and philosophical teachings.",
      "date": "1797"
    },
    {
      "headline": "Rabbi Shneur Zalman's Arrest",
      "text": "In 1798, Rabbi Shneur Zalman was arrested by the Russian authorities, accused of supporting the Ottoman Empire. He was released after 53 days, which is celebrated by Chabad as Yud-Tes Kislev.",
      "date": "1798"
    },
    {
      "headline": "Leadership of Rabbi Dovber Schneuri",
      "text": "After the death of Rabbi Shneur Zalman in 1812, his son, Rabbi Dovber Schneuri, became the leader of Chabad and moved the center to the town of Lyubavichi, Russia.",
      "date": "1812"
    },
    {
      "headline": "Leadership of Rabbi Menachem Mendel Schneersohn",
      "text": "In 1831, Rabbi Menachem Mendel Schneersohn, known as the Tzemach Tzedek, became the third Rebbe of Chabad and led the movement until his death in 1866.",
      "date": "1831"
    },
    {
      "headline": "Leadership of Rabbi Shmuel Schneersohn",
      "text": "Rabbi Shmuel Schneersohn, known as the Rebbe Maharash, became the fourth Rebbe of Chabad in 1866 and led the movement until his death in 1882.",
      "date": "1866"
    },
    {
      "headline": "Leadership of Rabbi Sholom Dovber Schneersohn",
      "text": "In 1882, Rabbi Sholom Dovber Schneersohn, known as the Rebbe Rashab, became the fifth Rebbe of Chabad and led the movement until his death in 1920.",
      "date": "1882"
    },
    {
      "headline": "Leadership of Rabbi Yosef Yitzchak Schneersohn",
      "text": "Rabbi Yosef Yitzchak Schneersohn became the sixth Rebbe of Chabad in 1920. He faced persecution in Soviet Russia and later moved to the United States in 1940.",
      "date": "1920"
    },
    {
      "headline": "Leadership of Rabbi Menachem Mendel Schneerson",
      "text": "In 1950, Rabbi Menachem Mendel Schneerson became the seventh Rebbe of Chabad. Under his leadership, Chabad expanded globally, establishing centers and outreach programs worldwide.",
      "date": "1950"
    },
    {
      "headline": "Passing of Rabbi Menachem Mendel Schneerson",
      "text": "Rabbi Menachem Mendel Schneerson passed away on June 12, 1994. His leadership significantly influenced the growth and outreach of the Chabad movement.",
      "date": "1994-06-12"
    }
  ]
}

