{
  "timeline": [
    {
      "headline": "Construction of Vasa Begins",
      "text": "The construction of the Swedish warship Vasa began in 1626. It was commissioned by King Gustavus Adolphus of Sweden as part of a military expansion.",
      "date": "1626"
    },
    {
      "headline": "Vasa's Maiden Voyage",
      "text": "On 10 August 1628, Vasa set sail on her maiden voyage. Unfortunately, the ship sank after sailing roughly 1,300 meters (1,400 yards) into the voyage.",
      "date": "1628-08-10"
    },
    {
      "headline": "Salvage of Bronze Cannons",
      "text": "In the 17th century, most of Vasa's valuable bronze cannons were salvaged, and the ship fell into obscurity.",
      "date": "1600s"
    },
    {
      "headline": "Rediscovery of Vasa",
      "text": "Vasa was located again in the late 1950s in a busy shipping area in Stockholm harbor.",
      "date": "1950s"
    },
    {
      "headline": "Salvage of Vasa",
      "text": "The ship was salvaged with a largely intact hull in 1961, marking a significant moment in maritime archaeology.",
      "date": "1961"
    },
    {
      "headline": "Temporary Museum Wasavarvet",
      "text": "After being salvaged, Vasa was housed in a temporary museum called Wasavarvet until 1988.",
      "date": "1961-1988"
    },
    {
      "headline": "Vasa Museum Opening",
      "text": "In 1988, Vasa was moved permanently to the Vasa Museum in the Royal National City Park in Stockholm.",
      "date": "1988"
    },
    {
      "headline": "Vasa as a Tourist Attraction",
      "text": "Since her recovery, Vasa has become one of Sweden's most popular tourist attractions, seen by over 45 million visitors since 1961.",
      "date": "1961-present"
    }
  ]
}

