{
  "timeline": [
    {
      "headline": "Formation of the Duchy of Saxony",
      "text": "The Duchy of Saxony was established in the early Middle Ages, around the year 804, as a result of the Saxon Wars led by Charlemagne.",
      "date": "0804"
    },
    {
      "headline": "Division of Saxony",
      "text": "In 1180, the Duchy of Saxony was divided after the fall of Henry the Lion, with the western part becoming the Duchy of Westphalia and the eastern part remaining as the Duchy of Saxony.",
      "date": "1180"
    },
    {
      "headline": "Creation of the Electorate of Saxony",
      "text": "In 1356, the Golden Bull of 1356 established the Electorate of Saxony, granting the Saxon rulers the right to participate in the election of the Holy Roman Emperor.",
      "date": "1356"
    },
    {
      "headline": "Saxony becomes a Kingdom",
      "text": "In 1806, following the dissolution of the Holy Roman Empire, the Electorate of Saxony was elevated to the status of a kingdom by Napoleon.",
      "date": "1806"
    },
    {
      "headline": "Saxony joins the German Empire",
      "text": "In 1871, the Kingdom of Saxony became a part of the newly formed German Empire.",
      "date": "1871"
    },
    {
      "headline": "End of the Kingdom of Saxony",
      "text": "In 1918, following Germany's defeat in World War I, the monarchy was abolished, and Saxony became a republic within the Weimar Republic.",
      "date": "1918"
    },
    {
      "headline": "Saxony under Nazi rule",
      "text": "From 1933 to 1945, Saxony was under Nazi rule, during which it was reorganized into the Gau Saxony.",
      "date": "1933"
    },
    {
      "headline": "Saxony becomes part of East Germany",
      "text": "In 1949, Saxony became a part of the German Democratic Republic (East Germany) after World War II.",
      "date": "1949"
    },
    {
      "headline": "Re-establishment of the Free State of Saxony",
      "text": "In 1990, following the reunification of Germany, the Free State of Saxony was re-established as a federal state of Germany.",
      "date": "1990"
    }
  ]
}

{
