{
  "timeline": [
    {
      "headline": "Founding of the Theosophical Society",
      "text": "The Theosophical Society was founded in New York City on November 17, 1875, by Helena Blavatsky, Henry Steel Olcott, William Quan Judge, and others. The society aimed to promote the study of comparative religion, philosophy, and science.",
      "date": "1875-11-17"
    },
    {
      "headline": "Publication of 'Isis Unveiled'",
      "text": "In 1877, Helena Blavatsky published 'Isis Unveiled', a two-volume work that outlined the basic tenets of Theosophy and criticized the scientific and religious establishments of the time.",
      "date": "1877"
    },
    {
      "headline": "Relocation to India",
      "text": "In 1879, Helena Blavatsky and Henry Steel Olcott moved the headquarters of the Theosophical Society to India, establishing it in Adyar, Chennai. This move marked a significant expansion of the society's influence.",
      "date": "1879"
    },
    {
      "headline": "Publication of 'The Secret Doctrine'",
      "text": "In 1888, Helena Blavatsky published 'The Secret Doctrine', a comprehensive work that expanded on the ideas presented in 'Isis Unveiled' and introduced the concept of root races and cosmic evolution.",
      "date": "1888"
    },
    {
      "headline": "Death of Helena Blavatsky",
      "text": "Helena Blavatsky died on May 8, 1891, in London, England. Her death marked the end of an era for the Theosophical Society, but her writings continued to influence the movement.",
      "date": "1891-05-08"
    },
    {
      "headline": "Annie Besant becomes President of the Theosophical Society",
      "text": "In 1907, Annie Besant became the president of the Theosophical Society. Under her leadership, the society continued to grow and expand its influence globally.",
      "date": "1907"
    },
    {
      "headline": "Introduction of Jiddu Krishnamurti",
      "text": "In 1909, Jiddu Krishnamurti, a young Indian boy, was discovered by Charles Webster Leadbeater, a prominent Theosophist, and was proclaimed to be the future World Teacher. This event significantly impacted the Theosophical Society's direction.",
      "date": "1909"
    },
    {
      "headline": "Dissolution of the Order of the Star",
      "text": "In 1929, Jiddu Krishnamurti dissolved the Order of the Star, an organization created to support his role as the World Teacher, stating that truth is a pathless land and rejecting the notion of spiritual authority.",
      "date": "1929"
    }
  ]
}

