{
  "timeline": [
    {
      "headline": "Introduction of Fiat Money",
      "text": "Fiat money has been used in various forms throughout history, with early examples dating back to the 11th century in China. The Song Dynasty was the first to issue paper money, known as 'jiaozi'.",
      "date": "1020"
    },
    {
      "headline": "Fiat Money in Europe",
      "text": "In the 17th century, fiat money began to appear in Europe. The first European fiat money was issued in Sweden in 1661 by Stockholms Banco.",
      "date": "1661"
    },
    {
      "headline": "Fiat Money in the United States",
      "text": "The United States first issued fiat money during the American Civil War. The government issued 'greenbacks', which were not backed by gold or silver, to finance the war effort.",
      "date": "1862"
    },
    {
      "headline": "End of the Gold Standard",
      "text": "The Bretton Woods system, which established a gold standard for international currency exchange, ended in 1971. This marked the transition to fiat money for major world currencies.",
      "date": "1971"
    },
    {
      "headline": "Fiat Money as Global Standard",
      "text": "Since the end of the Bretton Woods system, fiat money has become the standard for most of the world's currencies, including the US dollar, Euro, and Japanese yen.",
      "date": "1971"
    }
  ]
}

