{
  "timeline": [
    {
      "headline": "Invention of the Electric Telegraph",
      "text": "The electric telegraph was developed in the early 19th century, with significant contributions from Samuel Morse and others, leading to its commercialization.",
      "date": "1837"
    },
    {
      "headline": "Invention of the Telephone",
      "text": "Alexander Graham Bell was awarded the first US patent for the invention of the telephone on March 7, 1876.",
      "date": "1876-03-07"
    },
    {
      "headline": "Development of Electrical Power Systems",
      "text": "The late 19th century saw the development of electrical power systems, including the first power station built by Thomas Edison in 1882 in New York City.",
      "date": "1882"
    },
    {
      "headline": "Formation of Electrical Engineering as a Discipline",
      "text": "Electrical engineering emerged as a distinct discipline in the latter half of the 19th century, driven by the commercialization of the telegraph, telephone, and electrical power.",
      "date": "1880"
    },
    {
      "headline": "Invention of the Radio",
      "text": "Guglielmo Marconi successfully demonstrated the first wireless telegraphy system in 1895, leading to the development of radio communication.",
      "date": "1895"
    },
    {
      "headline": "Introduction of Alternating Current (AC) Systems",
      "text": "Nikola Tesla and George Westinghouse developed and promoted alternating current (AC) systems in the late 19th century, which became the standard for electrical power distribution.",
      "date": "1890"
    },
    {
      "headline": "Establishment of the Institute of Radio Engineers",
      "text": "The Institute of Radio Engineers (IRE) was founded in 1912, which later merged with the American Institute of Electrical Engineers (AIEE) to form the IEEE.",
      "date": "1912"
    },
    {
      "headline": "Formation of the IEEE",
      "text": "The Institute of Electrical and Electronics Engineers (IEEE) was formed in 1963 from the merger of the AIEE and the IRE, becoming a leading professional association for electrical engineers.",
      "date": "1963"
    }
  ]
}

