{
  "timeline": [
    {
      "headline": "Discovery of CRISPR Sequences",
      "text": "In 1987, the first CRISPR sequences were discovered by Yoshizumi Ishino and colleagues at Osaka University in Japan. They found unusual repeated sequences in the genome of Escherichia coli.",
      "date": "1987"
    },
    {
      "headline": "Naming of CRISPR",
      "text": "In 2002, the acronym CRISPR (Clustered Regularly Interspaced Short Palindromic Repeats) was coined by Francisco Mojica and Ruud Jansen, who also identified the Cas genes associated with these sequences.",
      "date": "2002"
    },
    {
      "headline": "CRISPR-Cas System Function Identified",
      "text": "In 2005, three independent research groups, including Francisco Mojica, Ruud Jansen, and Alexander Bolotin, identified that CRISPR sequences matched sequences from bacteriophages, suggesting a role in microbial immunity.",
      "date": "2005"
    },
    {
      "headline": "CRISPR-Cas as an Adaptive Immune System",
      "text": "In 2007, a team led by Philippe Horvath and Rodolphe Barrangou at Danisco demonstrated that CRISPR-Cas systems provide adaptive immunity to bacteria against phages.",
      "date": "2007"
    },
    {
      "headline": "CRISPR-Cas9 as a Genome Editing Tool",
      "text": "In 2012, Jennifer Doudna and Emmanuelle Charpentier published a paper demonstrating that CRISPR-Cas9 could be used as a precise genome editing tool, revolutionizing genetic engineering.",
      "date": "2012"
    },
    {
      "headline": "First Use of CRISPR in Human Embryos",
      "text": "In 2015, researchers in China reported the first use of CRISPR-Cas9 to edit genes in human embryos, sparking ethical debates worldwide.",
      "date": "2015"
    },
    {
      "headline": "Nobel Prize in Chemistry",
      "text": "In 2020, Jennifer Doudna and Emmanuelle Charpentier were awarded the Nobel Prize in Chemistry for their development of the CRISPR-Cas9 genome editing method.",
      "date": "2020"
    }
  ]
}

