{
  "timeline": [
    {
      "headline": "Concept of Lebensraum Popularized",
      "text": "The concept of Lebensraum was first popularized around 1901. It became a geopolitical goal for Germany, emphasizing the need for territorial expansion to provide living space for the German people.",
      "date": "1901"
    },
    {
      "headline": "Lebensraum in World War I",
      "text": "During World War I (1914–1918), Lebensraum became a core element of the Septemberprogramm, which was Germany's plan for territorial expansion. The program aimed to secure land for Germany in Eastern Europe.",
      "date": "1914"
    },
    {
      "headline": "Nazi Party Adopts Lebensraum",
      "text": "The Nazi Party, led by Adolf Hitler, adopted the concept of Lebensraum as a central tenet of its ideology. It was used to justify the expansionist policies that would lead to World War II.",
      "date": "1920s"
    },
    {
      "headline": "Lebensraum as a Motivation for World War II",
      "text": "Lebensraum was a leading motivation for Nazi Germany to initiate World War II. The goal was to establish a Greater German Reich by expanding into Eastern Europe and beyond.",
      "date": "1939"
    },
    {
      "headline": "End of Lebensraum Policy",
      "text": "The policy of Lebensraum continued until the end of World War II in 1945, when Nazi Germany was defeated. The ideology was discredited and abandoned following the war.",
      "date": "1945"
    }
  ]
}

