{
  "timeline": [
    {
      "headline": "American Revolutionary War Conscription",
      "text": "During the American Revolutionary War (1775-1783), the Continental Congress recommended that the states provide 88 battalions of troops, and conscription was used by some states to meet these quotas.",
      "date": "1775"
    },
    {
      "headline": "American Civil War Conscription",
      "text": "The first national conscription law in the United States was enacted during the American Civil War in 1863. The Enrollment Act of 1863 required the enrollment of every male citizen and those immigrants who had filed for citizenship between ages 20 and 45.",
      "date": "1863"
    },
    {
      "headline": "World War I Conscription",
      "text": "The Selective Service Act of 1917 was passed by Congress on May 18, 1917, which authorized the federal government to raise a national army for the American entry into World War I through conscription.",
      "date": "1917-05-18"
    },
    {
      "headline": "World War II Conscription",
      "text": "The Selective Training and Service Act of 1940 was signed into law by President Franklin D. Roosevelt on September 16, 1940, creating the first peacetime draft in U.S. history.",
      "date": "1940-09-16"
    },
    {
      "headline": "Korean War Conscription",
      "text": "During the Korean War (1950-1953), the Selective Service System was used to draft men into the military. The draft continued to operate under the Selective Service Act of 1948.",
      "date": "1950"
    },
    {
      "headline": "Vietnam War Conscription",
      "text": "Conscription was used extensively during the Vietnam War (1955-1975), with the draft lottery system being introduced in 1969 to determine the order of call to military service.",
      "date": "1969"
    },
    {
      "headline": "End of Draft and Transition to All-Volunteer Force",
      "text": "The draft ended in 1973, and the United States transitioned to an all-volunteer military force. The Selective Service registration requirement was suspended in 1975.",
      "date": "1973"
    },
    {
      "headline": "Reinstatement of Selective Service Registration",
      "text": "In 1980, President Jimmy Carter reinstated the requirement for young men to register with the Selective Service System in response to the Soviet invasion of Afghanistan.",
      "date": "1980"
    }
  ]
}

