{
  "timeline": [
    {
      "headline": "Formation of Committee",
      "text": "In 1948, a group of educators, led by Benjamin Bloom, formed a committee to address the need for a common language to discuss educational goals.",
      "date": "1948"
    },
    {
      "headline": "Publication of Bloom's Taxonomy",
      "text": "In 1956, Bloom's Taxonomy was first introduced in the publication 'Taxonomy of Educational Objectives: The Classification of Educational Goals'. This framework categorized educational goals into three domains: cognitive, affective, and psychomotor.",
      "date": "1956"
    },
    {
      "headline": "Cognitive Domain",
      "text": "The cognitive domain of Bloom's Taxonomy, introduced in 1956, focuses on knowledge-based objectives and is structured into six levels: knowledge, comprehension, application, analysis, synthesis, and evaluation.",
      "date": "1956"
    },
    {
      "headline": "Affective Domain",
      "text": "The affective domain, also introduced in 1956, addresses emotional-based objectives and includes five levels: receiving, responding, valuing, organization, and characterization.",
      "date": "1956"
    },
    {
      "headline": "Psychomotor Domain",
      "text": "The psychomotor domain, which was less developed in the original 1956 taxonomy, focuses on action-based objectives and involves physical skills.",
      "date": "1956"
    },
    {
      "headline": "Revised Bloom's Taxonomy",
      "text": "In 2001, a revised version of Bloom's Taxonomy was published, which updated the cognitive domain to include six categories: remember, understand, apply, analyze, evaluate, and create.",
      "date": "2001"
    }
  ]
}

