{
  "timeline": [
    {
      "headline": "Brundtland Report Published",
      "text": "In 1987, the Brundtland Report, also known as 'Our Common Future', was published by the World Commission on Environment and Development. It introduced the concept of sustainable development and defined it as 'development that meets the needs of the present without compromising the ability of future generations to meet their own needs.'",
      "date": "1987"
    },
    {
      "headline": "Earth Summit in Rio de Janeiro",
      "text": "In 1992, the United Nations Conference on Environment and Development (UNCED), also known as the Earth Summit, was held in Rio de Janeiro. It resulted in the adoption of Agenda 21, a comprehensive plan of action to build a global partnership for sustainable development.",
      "date": "1992"
    },
    {
      "headline": "Kyoto Protocol Adopted",
      "text": "In 1997, the Kyoto Protocol was adopted in Kyoto, Japan. It was an international treaty that committed state parties to reduce greenhouse gas emissions, based on the premise that global warming exists and human-made CO2 emissions have caused it.",
      "date": "1997"
    },
    {
      "headline": "Millennium Development Goals Established",
      "text": "In 2000, the United Nations established the Millennium Development Goals (MDGs), which included goals related to sustainable development, such as ensuring environmental sustainability.",
      "date": "2000"
    },
    {
      "headline": "Paris Agreement Signed",
      "text": "In 2015, the Paris Agreement was signed by 196 countries at the 21st Conference of the Parties of the UNFCCC in Paris. It aimed to limit global warming to well below 2 degrees Celsius, with efforts to limit the temperature increase to 1.5 degrees Celsius.",
      "date": "2015"
    },
    {
      "headline": "United Nations Sustainable Development Goals (SDGs)",
      "text": "In 2015, the United Nations adopted the Sustainable Development Goals (SDGs), a set of 17 goals to end poverty, protect the planet, and ensure prosperity for all as part of a new sustainable development agenda.",
      "date": "2015"
    }
  ]
}

