{
  "timeline": [
    {
      "headline": "Emergence of Zionism",
      "text": "In the late 19th century, the Zionist movement began advocating for the establishment of a Jewish homeland in Palestine, then part of the Ottoman Empire.",
      "date": "1890"
    },
    {
      "headline": "Balfour Declaration",
      "text": "On November 2, 1917, the British government issued the Balfour Declaration, expressing support for the establishment of a 'national home for the Jewish people' in Palestine.",
      "date": "1917-11-02"
    },
    {
      "headline": "British Mandate for Palestine",
      "text": "In 1920, following World War I, the League of Nations granted Britain the mandate to govern Palestine, which included the implementation of the Balfour Declaration.",
      "date": "1920"
    },
    {
      "headline": "Arab Revolt",
      "text": "From 1936 to 1939, the Arab Revolt took place in Palestine, as Arab inhabitants protested against British colonial rule and mass Jewish immigration.",
      "date": "1936"
    },
    {
      "headline": "UN Partition Plan",
      "text": "On November 29, 1947, the United Nations approved a plan to partition Palestine into separate Jewish and Arab states, with Jerusalem as an international city.",
      "date": "1947-11-29"
    },
    {
      "headline": "Creation of Israel",
      "text": "On May 14, 1948, the State of Israel was declared, leading to the first Arab-Israeli war as neighboring Arab states invaded.",
      "date": "1948-05-14"
    },
    {
      "headline": "1948 Arab-Israeli War",
      "text": "The 1948 Arab-Israeli War, also known as the War of Independence for Israelis and the Nakba for Palestinians, resulted in significant territorial changes and the displacement of hundreds of thousands of Palestinians.",
      "date": "1948"
    },
    {
      "headline": "Six-Day War",
      "text": "From June 5 to June 10, 1967, the Six-Day War occurred, during which Israel captured the Gaza Strip, the Sinai Peninsula, the West Bank, East Jerusalem, and the Golan Heights.",
      "date": "1967-06"
    },
    {
      "headline": "Yom Kippur War",
      "text": "On October 6, 1973, Egypt and Syria launched a surprise attack on Israel on Yom Kippur, leading to a war that lasted until October 25, 1973.",
      "date": "1973-10-06"
    },
    {
      "headline": "Camp David Accords",
      "text": "In September 1978, the Camp David Accords were signed, leading to a peace treaty between Egypt and Israel and the return of the Sinai Peninsula to Egypt.",
      "date": "1978-09"
    },
    {
      "headline": "First Intifada",
      "text": "The First Intifada, a Palestinian uprising against Israeli occupation in the West Bank and Gaza Strip, began in December 1987 and lasted until 1993.",
      "date": "1987-12"
    },
    {
      "headline": "Oslo Accords",
      "text": "On September 13, 1993, the Oslo Accords were signed, marking the first face-to-face agreement between the government of Israel and the Palestine Liberation Organization (PLO).",
      "date": "1993-09-13"
    },
    {
      "headline": "Second Intifada",
      "text": "The Second Intifada, a period of intensified Israeli-Palestinian violence, began in September 2000 and lasted until 2005.",
      "date": "2000-09"
    },
    {
      "headline": "Gaza Disengagement",
      "text": "In August 2005, Israel unilaterally disengaged from the Gaza Strip, evacuating all Israeli settlements and military presence.",
      "date": "2005-08"
    },
    {
      "headline": "Hamas Takes Control of Gaza",
      "text": "In June 2007, Hamas took control of the Gaza Strip following a conflict with the Fatah-led Palestinian Authority.",
      "date": "2007-06"
    },
    {
      "headline": "Operation Protective Edge",
      "text": "In July 2014, Israel launched Operation Protective Edge in response to Hamas rocket fire, leading to a 50-day conflict in the Gaza Strip.",
      "date": "2014-07"
    }
  ]
}

