{
  "timeline": [
    {
      "headline": "Establishment of Chełmno Extermination Camp",
      "text": "Chełmno was the first extermination camp established by Nazi Germany. It began operations on December 8, 1941, in occupied Poland, where victims were murdered in gas vans.",
      "date": "1941-12-08"
    },
    {
      "headline": "Operation of Belzec Extermination Camp",
      "text": "Belzec was the second extermination camp to begin operations. It started functioning in March 1942, and was located in occupied Poland. It was part of Operation Reinhard, the plan to murder Polish Jews.",
      "date": "1942-03"
    },
    {
      "headline": "Operation of Sobibor Extermination Camp",
      "text": "Sobibor began operations in May 1942 as part of Operation Reinhard. It was located in occupied Poland and was used to systematically murder Jews primarily by gassing.",
      "date": "1942-05"
    },
    {
      "headline": "Operation of Treblinka Extermination Camp",
      "text": "Treblinka became operational in July 1942. It was one of the most notorious extermination camps, where hundreds of thousands of Jews were murdered.",
      "date": "1942-07"
    },
    {
      "headline": "Operation of Auschwitz-Birkenau Extermination Camp",
      "text": "Auschwitz-Birkenau, part of the Auschwitz complex, began its role as an extermination camp in 1942. It became the largest of the Nazi death camps, where over a million people were murdered.",
      "date": "1942"
    },
    {
      "headline": "Operation of Majdanek Extermination Camp",
      "text": "Majdanek, initially a labor camp, began functioning as an extermination camp in 1942. It was located near Lublin, Poland, and was used for mass murder primarily through gassing.",
      "date": "1942"
    },
    {
      "headline": "End of Operation Reinhard",
      "text": "Operation Reinhard, the plan to murder Polish Jews in the extermination camps of Belzec, Sobibor, and Treblinka, officially ended in November 1943, after the majority of the targeted population had been killed.",
      "date": "1943-11"
    },
    {
      "headline": "Liberation of Majdanek",
      "text": "Majdanek was the first major concentration camp to be liberated by Allied forces. The Soviet Army liberated the camp on July 22, 1944.",
      "date": "1944-07-22"
    },
    {
      "headline": "Liberation of Auschwitz-Birkenau",
      "text": "The Soviet Army liberated Auschwitz-Birkenau on January 27, 1945. The camp became a symbol of the Holocaust and the atrocities committed by the Nazis.",
      "date": "1945-01-27"
    }
  ]
}

