    {
      "headline": "Design of the Flag",
      "text": "The design of the flag was conceptualized by Emilio Aguinaldo, the leader of the Philippine Revolution against Spanish colonial rule. The flag features a horizontal bicolor of royal blue and crimson red, with a white equilateral triangle at the hoist. In the center of the triangle is a golden-yellow sun with eight primary rays, representing the original eight provinces that rebelled against Spanish rule during the 1896 Philippine Revolution.",
      "date": "1897"
    },
    {
      "headline": "First Display of the Flag",
      "text": "The Philippine flag was first displayed during the proclamation of Philippine independence from Spain on June 12, 1898, in Kawit, Cavite. This marked the official adoption of the flag as a symbol of the newly declared independent nation.",
      "date": "1898-06-12"
    },
    {
      "headline": "Flag Ban During American Occupation",
      "text": "Following the Philippine-American War, the display of the Philippine flag was banned by the United States colonial government from 1907 until 1919, as part of efforts to suppress Filipino nationalism.",
      "date": "1907"
    },
    {
      "headline": "Lifting of the Flag Ban",
      "text": "The ban on the display of the Philippine flag was lifted on October 30, 1919, allowing Filipinos to once again openly display their national symbol.",
      "date": "1919-10-30"
    },
    {
      "headline": "Official Adoption of the Flag",
      "text": "The flag was officially adopted as the national flag of the Philippines on March 26, 1920, by the Philippine Legislature, solidifying its status as a symbol of the nation's identity and sovereignty.",
      "date": "1920-03-26"
    },
    {
      "headline": "World War II and the Flag",
      "text": "During World War II, the flag was used by the Japanese-occupied Philippine government, but it was also a symbol of resistance and hope for liberation among Filipinos.",
      "date": "1941"
    },
    {
      "headline": "Restoration of Independence",
      "text": "On July 4, 1946, the Philippines gained full independence from the United States, and the flag was raised to symbolize the country's sovereignty.",
      "date": "1946-07-04"
    },
    {
      "headline": "Modification of the Flag's Colors",
      "text": "In 1998, the shade of blue on the flag was changed from navy blue to royal blue, following Republic Act No. 8491, also known as the Flag and Heraldic Code of the Philippines.",
      "date": "1998"
    }
  ]
}

