      "headline": "Birth of Muhammad Ali",
      "text": "Muhammad Ali was born in Kavala, in present-day Greece, in 1769.",
      "date": "1769"
    },
    {
      "headline": "Arrival in Egypt",
      "text": "Muhammad Ali arrived in Egypt as part of an Ottoman force sent to drive out the French in 1801.",
      "date": "1801"
    },
    {
      "headline": "Rise to Power",
      "text": "Muhammad Ali became the Wāli (governor) of Egypt in 1805 after being appointed by the Ottoman Sultan.",
      "date": "1805"
    },
    {
      "headline": "Massacre of the Mamluks",
      "text": "In 1811, Muhammad Ali orchestrated the massacre of the Mamluks, consolidating his power in Egypt.",
      "date": "1811"
    },
    {
      "headline": "Conquest of Sudan",
      "text": "Muhammad Ali began his conquest of Sudan in 1820, expanding his control southward.",
      "date": "1820"
    },
    {
      "headline": "Greek War of Independence",
      "text": "Muhammad Ali's forces participated in the Greek War of Independence, notably in the Battle of Navarino in 1827.",
      "date": "1827"
    },
    {
      "headline": "Battle of Navarino",
      "text": "The Egyptian fleet was destroyed by the combined British, French, and Russian fleets at the Battle of Navarino in 1827.",
      "date": "1827"
    },
    {
      "headline": "First Egyptian-Ottoman War",
      "text": "Muhammad Ali's forces invaded Syria in 1831, leading to the First Egyptian-Ottoman War.",
      "date": "1831"
    },
    {
      "headline": "Battle of Konya",
      "text": "Muhammad Ali's son, Ibrahim Pasha, defeated the Ottoman forces at the Battle of Konya in 1832.",
      "date": "1832"
    },
    {
      "headline": "Treaty of Kütahya",
      "text": "In 1833, the Treaty of Kütahya was signed, granting Muhammad Ali control over Syria and Adana.",
      "date": "1833"
    },
    {
      "headline": "Second Egyptian-Ottoman War",
      "text": "The Second Egyptian-Ottoman War began in 1839, as Muhammad Ali sought to expand his territory.",
      "date": "1839"
    },
    {
      "headline": "Convention of London",
      "text": "In 1840, the Convention of London forced Muhammad Ali to withdraw from most of his conquests, leaving him with hereditary rule over Egypt and Sudan.",
      "date": "1840"
    },
    {
      "headline": "Abdication",
      "text": "Muhammad Ali officially abdicated in favor of his son Ibrahim Pasha in 1848 due to ill health.",
      "date": "1848"
    },
    {
      "headline": "Death of Muhammad Ali",
      "text": "Muhammad Ali died on August 2, 1849, in Alexandria, Egypt.",
      "date": "1849-08-02"
    }
  ]
}

