      "headline": "Sumerian Origin of Weekdays",
      "text": "The concept of naming days after celestial bodies and deities originated with the Sumerians, who associated each day with one of the seven classical planets known in ancient astronomy.",
      "date": "-03000"
    },
    {
      "headline": "Babylonian Adoption",
      "text": "The Babylonians adopted the Sumerian system of naming days after celestial bodies and deities, further developing the concept of a seven-day week.",
      "date": "-01800"
    },
    {
      "headline": "Hellenistic Astronomy Influence",
      "text": "During the Hellenistic period, the Greeks adopted the seven-day week from the Babylonians, naming the days after the seven classical planets, which were associated with Greek deities.",
      "date": "-0300"
    },
    {
      "headline": "Roman Empire Adoption",
      "text": "The Roman Empire adopted the seven-day week from the Hellenistic Greeks, naming the days after Roman deities corresponding to the classical planets.",
      "date": "0001"
    },
    {
      "headline": "Early Christian Adoption",
      "text": "Early Christianity adopted the seven-day week from the Hebrew calendar, which was based on the creation story in the Book of Genesis, and gradually replaced the Roman internundinum.",
      "date": "0300"
    },
    {
      "headline": "Spread of the Seven-Day Week",
      "text": "The seven-day week spread throughout Europe and other parts of the world, influenced by the Roman Empire and the spread of Christianity.",
      "date": "0400"
    }
  ]
}

