  "timeline": [
    {
      "headline": "Origins of Afroasiatic Languages",
      "text": "The Afroasiatic language family is believed to have originated in the African continent, with its earliest forms possibly dating back to the Neolithic period. The exact date of origin is debated, but it is estimated to be around 10,000 years ago.",
      "date": "-08000"
    },
    {
      "headline": "Development of Egyptian Branch",
      "text": "The Egyptian branch of the Afroasiatic languages developed in the Nile Valley. The earliest known form of Egyptian is Old Egyptian, which was used during the Early Dynastic Period of Egypt, around 3000 BCE.",
      "date": "-03000"
    },
    {
      "headline": "Emergence of Semitic Languages",
      "text": "The Semitic branch of the Afroasiatic languages emerged in the Middle East. Akkadian, one of the earliest Semitic languages, was used in Mesopotamia around 2500 BCE.",
      "date": "-02500"
    },
    {
      "headline": "Berber Languages in North Africa",
      "text": "The Berber languages, part of the Afroasiatic family, have been spoken in North Africa since ancient times. Evidence of Berber languages dates back to the first millennium BCE.",
      "date": "-01000"
    },
    {
      "headline": "Chadic Languages in Central Africa",
      "text": "The Chadic branch of the Afroasiatic languages developed in Central Africa. These languages are primarily spoken in the Lake Chad Basin, with evidence of their use dating back to ancient times.",
      "date": "-01000"
    },
    {
      "headline": "Cushitic Languages in the Horn of Africa",
      "text": "The Cushitic languages, another branch of the Afroasiatic family, are indigenous to the Horn of Africa. They have been spoken in this region for thousands of years.",
      "date": "-01000"
    },
    {
      "headline": "Omotic Languages in Southwestern Ethiopia",
      "text": "The Omotic languages, considered a branch of the Afroasiatic family, are primarily spoken in southwestern Ethiopia. They have been present in this region for several millennia.",
      "date": "-01000"
    },
    {
      "headline": "Spread of Afroasiatic Languages",
      "text": "Over the centuries, Afroasiatic languages spread across West Asia, North Africa, the Horn of Africa, and parts of the Sahara and Sahel, becoming one of the largest language families in the world.",
      "date": "0000"
    }
  ]
}

