{
  "timeline": [
    {
      "headline": "Development of Electroconvulsive Therapy",
      "text": "In 1938, Italian neurologist Ugo Cerletti and his colleague Lucio Bini developed the first method of electroconvulsive therapy (ECT) for the treatment of severe mental disorders.",
      "date": "1938"
    },
    {
      "headline": "First Human ECT Treatment",
      "text": "On April 11, 1938, the first electroconvulsive therapy treatment was administered to a human patient in Rome, Italy.",
      "date": "1938-04-11"
    },
    {
      "headline": "Introduction of ECT in the United States",
      "text": "In 1940, electroconvulsive therapy was introduced to the United States and quickly gained popularity as a treatment for various psychiatric conditions.",
      "date": "1940"
    },
    {
      "headline": "Peak Usage of ECT",
      "text": "During the 1940s and 1950s, ECT became a widely used treatment for mental disorders, particularly for severe depression and schizophrenia.",
      "date": "1940-1959"
    },
    {
      "headline": "Decline in ECT Usage",
      "text": "In the 1960s and 1970s, the use of ECT declined due to the development of psychiatric medications and growing public concern over the treatment's side effects.",
      "date": "1960-1979"
    },
    {
      "headline": "Resurgence of ECT",
      "text": "In the 1980s and 1990s, ECT experienced a resurgence as research demonstrated its effectiveness, particularly for treatment-resistant depression.",
      "date": "1980-1999"
    },
    {
      "headline": "Modern ECT Practices",
      "text": "Today, ECT is considered a safe and effective treatment for certain psychiatric disorders, with improved techniques and anesthesia reducing side effects.",
      "date": "2000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of Delhi Metro Rail Corporation",
      "text": "The Delhi Metro Rail Corporation (DMRC) was founded on May 3, 1995, to oversee the construction and operation of the Delhi Metro.",
      "date": "1995-05-03"
    },
    {
      "headline": "Construction Begins",
      "text": "Construction of the Delhi Metro began on October 1, 1998, marking the start of a new era in public transportation for Delhi.",
      "date": "1998-10-01"
    },
    {
      "headline": "Inauguration of First Line",
      "text": "The first line of the Delhi Metro, the Red Line, was inaugurated on December 24, 2002, by then Prime Minister Atal Bihari Vajpayee. This line initially ran from Shahdara to Tis Hazari.",
      "date": "2002-12-24"
    },
    {
      "headline": "Completion of Phase I",
      "text": "Phase I of the Delhi Metro was completed on November 11, 2006, with a total of 65 kilometers of track laid across three lines.",
      "date": "2006-11-11"
    },
    {
      "headline": "Completion of Phase II",
      "text": "Phase II was completed on August 27, 2011, adding 125 kilometers of track and extending the network to the National Capital Region.",
      "date": "2011-08-27"
    },
    {
      "headline": "Introduction of Airport Express Line",
      "text": "The Airport Express Line, connecting New Delhi Railway Station to Indira Gandhi International Airport, was inaugurated on February 23, 2011.",
      "date": "2011-02-23"
    },
    {
      "headline": "Completion of Phase III",
      "text": "Phase III was completed on March 8, 2019, expanding the network by an additional 160 kilometers and introducing new lines and extensions.",
      "date": "2019-03-08"
    },
    {
      "headline": "Delhi Metro Achieves 350 km Milestone",
      "text": "By 2020, the Delhi Metro network reached a total length of 350 kilometers, making it the largest metro network in India.",
