  "timeline": [
    {
      "headline": "Birth of Fritz Haber",
      "text": "Fritz Haber was born on December 9, 1868, in Breslau, Prussia (now Wrocław, Poland).",
      "date": "1868-12-09"
    },
    {
      "headline": "Haber's Education",
      "text": "Haber studied chemistry at the University of Heidelberg, the University of Berlin, and the Technical University of Charlottenburg (now the Technical University of Berlin) from 1886 to 1891.",
      "date": "1886"
    },
    {
      "headline": "Haber's Doctorate",
      "text": "In 1891, Fritz Haber received his doctorate in chemistry from the University of Berlin.",
      "date": "1891"
    },
    {
      "headline": "Haber's Academic Career",
      "text": "Haber began his academic career at the University of Karlsruhe in 1894, where he worked on various chemical processes.",
      "date": "1894"
    },
    {
      "headline": "Development of the Haber Process",
      "text": "In 1909, Fritz Haber successfully developed the Haber process, which allowed for the synthesis of ammonia from nitrogen and hydrogen gases.",
      "date": "1909"
    },
    {
      "headline": "Nobel Prize in Chemistry",
      "text": "Fritz Haber was awarded the Nobel Prize in Chemistry in 1918 for his invention of the Haber process.",
      "date": "1918"
    },
    {
      "headline": "Proposal of the Born–Haber Cycle",
      "text": "In 1919, Haber, along with Max Born, proposed the Born–Haber cycle, a method for evaluating the lattice energy of an ionic solid.",
      "date": "1919"
    },
    {
      "headline": "Haber's Role in Chemical Warfare",
      "text": "During World War I, Haber played a significant role in the development and deployment of chemical warfare, including chlorine gas.",
      "date": "1915"
    },
    {
      "headline": "Emigration from Germany",
      "text": "In 1933, due to the rise of the Nazi regime and its policies against Jews, Haber emigrated from Germany.",
      "date": "1933"
    },
    {
      "headline": "Death of Fritz Haber",
      "text": "Fritz Haber died on January 29, 1934, in Basel, Switzerland.",
      "date": "1934-01-29"
    }
  ]
}

