      "headline": "Discovery of Heparin",
      "text": "Heparin was discovered in 1916 by Jay McLean, a second-year medical student, while working in the laboratory of William Henry Howell at Johns Hopkins University.",
      "date": "1916"
    },
    {
      "headline": "First Clinical Use",
      "text": "Heparin was first used clinically in the late 1930s. It was initially used as an anticoagulant in blood transfusions.",
      "date": "1930"
    },
    {
      "headline": "Commercial Production",
      "text": "In 1936, the pharmaceutical company Connaught Laboratories began the commercial production of heparin.",
      "date": "1936"
    },
    {
      "headline": "Approval for Medical Use",
      "text": "Heparin was approved for medical use in the United States in 1937.",
      "date": "1937"
    },
    {
      "headline": "Development of Low Molecular Weight Heparins",
      "text": "In the 1980s, low molecular weight heparins (LMWH) were developed, offering more predictable pharmacokinetics and a reduced risk of bleeding compared to unfractionated heparin.",
      "date": "1980"
    },
    {
      "headline": "Contamination Crisis",
      "text": "In 2008, a contamination crisis occurred when batches of heparin were found to be contaminated with oversulfated chondroitin sulfate, leading to adverse reactions and deaths.",
      "date": "2008"
    }
  ]
}

