{
  "timeline": [
    {
      "headline": "Establishment of Nalanda Mahavihara",
      "text": "Nalanda Mahavihara was established around 427 CE in the ancient kingdom of Magadha, near the city of Rajagriha. It became one of the greatest centers of learning in the ancient world.",
      "date": "0427"
    },
    {
      "headline": "Patronage by Gupta Empire",
      "text": "During the 5th and 6th centuries CE, Nalanda received significant patronage from the Gupta Empire, which helped it flourish as a center of learning and culture. This period is often referred to as the 'Golden Age of India'.",
      "date": "0500"
    },
    {
      "headline": "Visit by Xuanzang",
      "text": "The Chinese Buddhist monk Xuanzang visited Nalanda in 637 CE and studied there for several years. He documented the university's operations and its extensive library.",
      "date": "0637"
    },
    {
      "headline": "Visit by Yijing",
      "text": "Another Chinese monk, Yijing, visited Nalanda in 673 CE and spent about ten years studying and translating Buddhist texts.",
      "date": "0673"
    },
    {
      "headline": "Decline and Destruction",
      "text": "Nalanda began to decline after the 12th century due to the invasions by Muslim rulers. It was finally destroyed by Bakhtiyar Khilji in 1193 CE.",
      "date": "1193"
    },
    {
      "headline": "Rediscovery and Excavation",
      "text": "The site of Nalanda was rediscovered in the 19th century by the Archaeological Survey of India, and excavations began in the early 20th century.",
      "date": "1900"
    }
  ]
}

