    {
      "headline": "Publication of 'Hugh Selwyn Mauberley'",
      "text": "In 1920, Pound published 'Hugh Selwyn Mauberley', a poem that is considered one of his most significant works.",
      "date": "1920"
    },
    {
      "headline": "Publication of 'The Cantos'",
      "text": "Ezra Pound began publishing 'The Cantos', his most ambitious work, in 1917, with the final sections published in 1969. The epic poem spans over 800 pages.",
      "date": "1917"
    },
    {
      "headline": "Involvement with Fascist Italy",
      "text": "During World War II, Pound became involved with Fascist Italy and made radio broadcasts supporting Mussolini's regime.",
      "date": "1940"
    },
    {
      "headline": "Arrest and Detention",
      "text": "In 1945, Pound was arrested by American forces in Italy for treason and was detained at a U.S. Army Disciplinary Training Center near Pisa.",
      "date": "1945"
    },
    {
      "headline": "Confinement at St. Elizabeths Hospital",
      "text": "In 1946, Pound was declared unfit to stand trial and was committed to St. Elizabeths Hospital in Washington, D.C., where he remained until 1958.",
      "date": "1946"
    },
    {
      "headline": "Release from St. Elizabeths Hospital",
      "text": "Ezra Pound was released from St. Elizabeths Hospital in 1958 and returned to Italy.",
      "date": "1958"
    },
    {
      "headline": "Death of Ezra Pound",
      "text": "Ezra Pound died on November 1, 1972, in Venice, Italy.",
      "date": "1972-11-01"
    }
  ]
}

