    {
      "headline": "First Permanent Photograph",
      "text": "In 1826 or 1827, Joseph Nicéphore Niépce created the first permanent photograph using a process called heliography. The photograph was taken from the window of his estate in France.",
      "date": "1826"
    },
    {
      "headline": "Daguerreotype Process Announced",
      "text": "On January 7, 1839, Louis Daguerre announced the daguerreotype process, the first publicly available photographic process, which became widely used.",
      "date": "1839-01-07"
    },
    {
      "headline": "Calotype Process Patented",
      "text": "In 1841, William Henry Fox Talbot patented the calotype process, which used paper coated with silver iodide to create a negative image.",
      "date": "1841"
    },
    {
      "headline": "Introduction of Collodion Process",
      "text": "In 1851, Frederick Scott Archer introduced the collodion process, which allowed for sharper images and shorter exposure times compared to previous methods.",
      "date": "1851"
    },
    {
      "headline": "Invention of Dry Plate Photography",
      "text": "In 1871, Richard Leach Maddox invented the dry plate process, which used gelatin emulsion and allowed for more convenient and faster photography.",
      "date": "1871"
    },
    {
      "headline": "Kodak Camera Released",
      "text": "In 1888, George Eastman released the Kodak camera, which was pre-loaded with film and made photography accessible to the general public.",
      "date": "1888"
    },
    {
      "headline": "Introduction of 35mm Film",
      "text": "In 1913, 35mm film was introduced, becoming the standard for still photography and motion pictures.",
      "date": "1913"
    },
    {
      "headline": "Polaroid Instant Camera Invented",
      "text": "In 1948, Edwin Land introduced the first Polaroid instant camera, which allowed photographers to see their images within minutes.",
      "date": "1948"
    },
    {
      "headline": "Digital Photography Emerges",
      "text": "In 1975, Steven Sasson, an engineer at Eastman Kodak, developed the first digital camera, marking the beginning of digital photography.",
      "date": "1975"
    },
    {
      "headline": "First Commercial Digital Camera Released",
      "text": "In 1991, Kodak released the first commercially available digital camera, the Kodak DCS, which was aimed at professional photographers.",
      "date": "1991"
    },
    {
      "headline": "Introduction of Camera Phones",
      "text": "In 2000, the first camera phone, the Sharp J-SH04, was released in Japan, revolutionizing the way people capture and share images.",
      "date": "2000"
    }
  ]
}

