{
  "timeline": [
    {
      "headline": "Drafting of the Fourth Amendment",
      "text": "The Fourth Amendment was drafted as part of the United States Bill of Rights, which was proposed by James Madison in response to calls from several states for greater constitutional protection for individual liberties.",
      "date": "1789"
    },
    {
      "headline": "Ratification of the Fourth Amendment",
      "text": "The Fourth Amendment was ratified on December 15, 1791, as part of the Bill of Rights. It prohibits unreasonable searches and seizures and sets requirements for issuing warrants.",
      "date": "1791-12-15"
    },
    {
      "headline": "Katz v. United States",
      "text": "In 1967, the Supreme Court case Katz v. United States expanded the Fourth Amendment protections to include electronic wiretaps, establishing the principle that the amendment protects people, not just places.",
      "date": "1967"
    },
    {
      "headline": "Terry v. Ohio",
      "text": "In 1968, the Supreme Court decided Terry v. Ohio, which established the 'stop and frisk' rule, allowing police to stop and search a person if they have reasonable suspicion that the person has committed, is committing, or is about to commit a crime.",
      "date": "1968"
    },
    {
      "headline": "United States v. Jones",
      "text": "In 2012, the Supreme Court ruled in United States v. Jones that attaching a GPS device to a vehicle and using it to monitor the vehicle's movements constitutes a search under the Fourth Amendment.",
      "date": "2012"
    },
    {
      "headline": "Riley v. California",
      "text": "In 2014, the Supreme Court ruled in Riley v. California that the warrantless search and seizure of digital contents of a cell phone during an arrest is unconstitutional.",
      "date": "2014"
    }
  ]
}

