{
  "timeline": [
    {
      "headline": "Emergence of Anabaptism",
      "text": "Anabaptism emerged as part of the Radical Reformation in the early 16th century, challenging the practices of the Catholic Church and advocating for believer's baptism.",
      "date": "1520"
    },
    {
      "headline": "First Anabaptist Baptism",
      "text": "On January 21, 1525, the first Anabaptist baptism took place in Zurich, Switzerland, when Conrad Grebel baptized George Blaurock, marking the formal beginning of the Anabaptist movement.",
      "date": "1525-01-21"
    },
    {
      "headline": "Persecution of Anabaptists",
      "text": "Throughout the 1520s and 1530s, Anabaptists faced severe persecution from both Protestant and Catholic authorities, leading to the execution of many Anabaptist leaders.",
      "date": "1525"
    },
    {
      "headline": "Schleitheim Confession",
      "text": "In 1527, the Schleitheim Confession was adopted by Swiss Anabaptists, outlining key beliefs and practices, including adult baptism, nonviolence, and separation from the world.",
      "date": "1527"
    },
    {
      "headline": "Munster Rebellion",
      "text": "In 1534-1535, the Munster Rebellion occurred when radical Anabaptists took control of the city of Munster, Germany, leading to a violent siege and the eventual defeat of the Anabaptists.",
      "date": "1534"
    },
    {
      "headline": "Menno Simons' Leadership",
      "text": "Menno Simons, a former Catholic priest, became a prominent Anabaptist leader in the 1530s, helping to organize and consolidate the movement, which later became known as the Mennonites.",
      "date": "1536"
    },
    {
      "headline": "Establishment of Hutterites",
      "text": "In the mid-16th century, the Hutterites, a communal branch of Anabaptism, were established in Moravia under the leadership of Jakob Hutter.",
      "date": "1560"
    },
    {
      "headline": "Migration to North America",
      "text": "In the late 17th and 18th centuries, many Anabaptists, including Mennonites and Amish, migrated to North America to escape persecution and seek religious freedom.",
      "date": "1683"
    }
  ]
}

{
