    },
    {
      "headline": "20th-Century Folk Revival",
      "text": "The 20th-century folk revival saw a renewed interest in traditional folk music, leading to the evolution of a contemporary genre that drew from traditional roots.",
      "date": "1900"
    },
    {
      "headline": "Folk Music and World Music",
      "text": "Some types of folk music began to be referred to as world music, highlighting the global influence and diversity of traditional music styles.",
      "date": "1900"
