      "headline": "Birth of Jack Johnson",
      "text": "John Arthur Johnson was born on March 31, 1878, in Galveston, Texas.",
      "date": "1878-03-31"
    },
    {
      "headline": "Professional Boxing Debut",
      "text": "Jack Johnson made his professional boxing debut on November 1, 1898, in Galveston, Texas.",
      "date": "1898-11-01"
    },
    {
      "headline": "Wins World Colored Heavyweight Championship",
      "text": "On February 3, 1903, Jack Johnson won the World Colored Heavyweight Championship by defeating Ed Martin.",
      "date": "1903-02-03"
    },
    {
      "headline": "Becomes World Heavyweight Champion",
      "text": "Jack Johnson became the first black world heavyweight boxing champion on December 26, 1908, by defeating Tommy Burns in Sydney, Australia.",
      "date": "1908-12-26"
    },
    {
      "headline": "Fight of the Century",
      "text": "On July 4, 1910, Jack Johnson fought James J. Jeffries in Reno, Nevada, in what was dubbed the 'Fight of the Century'. Johnson defeated Jeffries, leading to race riots across the United States.",
      "date": "1910-07-04"
    },
    {
      "headline": "Mann Act Conviction",
      "text": "In 1913, Jack Johnson was convicted under the Mann Act for transporting a white woman across state lines for 'immoral purposes', a charge widely seen as racially motivated.",
      "date": "1913"
    },
    {
      "headline": "Exile in Europe",
      "text": "Following his conviction, Jack Johnson fled the United States and lived in exile in Europe and South America from 1913 to 1920.",
      "date": "1913"
    },
    {
      "headline": "Loses World Heavyweight Title",
      "text": "On April 5, 1915, Jack Johnson lost the World Heavyweight Title to Jess Willard in Havana, Cuba.",
      "date": "1915-04-05"
    },
    {
      "headline": "Returns to the United States",
      "text": "Jack Johnson returned to the United States in 1920 and surrendered to federal agents. He served a year in prison.",
      "date": "1920"
    },
    {
      "headline": "Death of Jack Johnson",
      "text": "Jack Johnson died in a car crash on June 10, 1946, near Raleigh, North Carolina.",
      "date": "1946-06-10"
    }
  ]
}

