      "date": "1388"
    },
    {
      "headline": "First Psychotic Episode",
      "text": "Charles VI experienced his first major psychotic episode in August 1392, during a military expedition in Brittany.",
      "date": "1392-08"
    },
    {
      "headline": "Treaty of Leulinghem",
      "text": "In 1396, Charles VI signed the Treaty of Leulinghem, establishing a truce with England during the Hundred Years' War.",
      "date": "1396"
    },
    {
      "headline": "Marriage of Isabella of Valois",
      "text": "In 1396, Charles VI's daughter, Isabella of Valois, married Richard II of England as part of a peace agreement.",
      "date": "1396"
    },
    {
      "headline": "Cabochien Revolt",
      "text": "In 1413, Paris experienced the Cabochien Revolt, a violent uprising influenced by Charles VI's mental instability and political tensions.",
      "date": "1413"
    },
    {
      "headline": "Treaty of Troyes",
      "text": "On May 21, 1420, Charles VI signed the Treaty of Troyes, disinheriting his son and recognizing Henry V of England as his heir.",
      "date": "1420-05-21"
    },
    {
      "headline": "Death of Charles VI",
      "text": "Charles VI died on October 21, 1422, in Paris, France, after a long period of mental illness.",
      "date": "1422-10-21"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Launch of HMS Dreadnought",
      "text": "HMS Dreadnought was launched on February 10, 1906. It was the first battleship of its kind, featuring an 'all-big-gun' armament scheme and steam turbine propulsion.",
      "date": "1906-02-10"
    },
    {
      "headline": "Completion of HMS Dreadnought",
      "text": "HMS Dreadnought was completed and commissioned into the Royal Navy on December 3, 1906. Its revolutionary design rendered all previous battleships obsolete.",
      "date": "1906-12-03"
    },
    {
      "headline": "Naval Arms Race Intensifies",
      "text": "Following the launch of HMS Dreadnought, a naval arms race intensified, particularly between the United Kingdom and Germany, as nations rushed to build their own dreadnoughts.",
      "date": "1906"
    },
    {
      "headline": "Introduction of Super-Dreadnoughts",
      "text": "Within five years of HMS Dreadnought's launch, new battleships known as 'super-dreadnoughts' were introduced. These ships were larger and more powerful, featuring improved armament, armour, and propulsion.",
      "date": "1911"
    },
    {
      "headline": "World War I Begins",
      "text": "World War I began in 1914, and dreadnoughts played a significant role in naval battles during the conflict.",
      "date": "1914"
    },
    {
      "headline": "Washington Naval Treaty",
      "text": "After World War I, the Washington Naval Treaty was signed in 1922, leading to the scrapping of many original dreadnoughts to prevent a renewed arms race.",
      "date": "1922"
    },
    {
      "headline": "World War II and Super-Dreadnoughts",
      "text": "Many of the newer super-dreadnoughts continued to serve throughout World War II, playing crucial roles in various naval engagements.",
      "date": "1939"
    }
  ]
}

