{
  "timeline": [
    {
      "headline": "Martin Luther Writes the Ninety-five Theses",
      "text": "On October 31, 1517, Martin Luther, a professor of moral theology at the University of Wittenberg, Germany, wrote the Ninety-five Theses. This document criticized the Roman Catholic Church's sale of indulgences and questioned the authority of the Pope.",
      "date": "1517-10-31"
    },
    {
      "headline": "Luther Sends Theses to Archbishop",
      "text": "In late 1517, Martin Luther sent a copy of the Ninety-five Theses to Albert of Brandenburg, the Archbishop of Mainz, along with a letter protesting the sale of indulgences.",
      "date": "1517"
    },
    {
      "headline": "Theses Spread Across Europe",
      "text": "By early 1518, the Ninety-five Theses had been translated from Latin into German and spread across Europe, sparking widespread debate and discussion.",
      "date": "1518"
    },
    {
      "headline": "Luther Summoned to Rome",
      "text": "In 1518, Martin Luther was summoned to Rome to answer charges of heresy due to his criticisms outlined in the Ninety-five Theses.",
      "date": "1518"
    },
    {
      "headline": "Luther Debates Johann Eck",
      "text": "In July 1519, Martin Luther engaged in a public debate with Johann Eck in Leipzig, where he further defended his views expressed in the Ninety-five Theses.",
      "date": "1519-07"
    },
    {
      "headline": "Pope Leo X Condemns Luther's Teachings",
      "text": "On June 15, 1520, Pope Leo X issued the papal bull Exsurge Domine, condemning Martin Luther's teachings and threatening him with excommunication.",
      "date": "1520-06-15"
    },
    {
      "headline": "Luther Excommunicated",
      "text": "On January 3, 1521, Martin Luther was officially excommunicated from the Roman Catholic Church by Pope Leo X.",
      "date": "1521-01-03"
    },
    {
      "headline": "Diet of Worms",
      "text": "In April 1521, Martin Luther appeared before the Diet of Worms, where he refused to recant his writings, including the Ninety-five Theses.",
      "date": "1521-04"
    }
  ]
}

