{
  "timeline": [
    {
      "headline": "Founding of the College of William & Mary",
      "text": "The College of William & Mary was founded in 1693 under a royal charter issued by King William III and Queen Mary II. It is the second-oldest institution of higher education in the United States.",
      "date": "1693"
    },
    {
      "headline": "First Building Constructed",
      "text": "The construction of the Wren Building, the oldest college building still in use in the United States, began in 1695 and was completed in 1700.",
      "date": "1700"
    },
    {
      "headline": "Charter Granted",
      "text": "The college received its official charter from King William III and Queen Mary II, which allowed it to confer degrees and established it as a legal entity.",
      "date": "1693"
    },
    {
      "headline": "First President",
      "text": "Reverend James Blair became the first president of the College of William & Mary, serving from 1693 to 1743.",
      "date": "1693"
    },
    {
      "headline": "Fire and Reconstruction",
      "text": "The Wren Building was destroyed by fire in 1705 and was subsequently rebuilt.",
      "date": "1705"
    },
    {
      "headline": "Introduction of the Honor Code",
      "text": "The College of William & Mary introduced the Honor Code in 1779, which is one of the oldest honor codes in the United States.",
      "date": "1779"
    },
    {
      "headline": "Thomas Jefferson's Enrollment",
      "text": "Thomas Jefferson, who later became the third President of the United States, enrolled at the College of William & Mary in 1760.",
      "date": "1760"
    },
    {
      "headline": "Closure During the Civil War",
      "text": "The college closed during the American Civil War from 1861 to 1865 and was used as a hospital and barracks.",
      "date": "1861"
    },
    {
      "headline": "Reopening After the Civil War",
      "text": "The College of William & Mary reopened in 1869 after being closed during the Civil War.",
      "date": "1869"
    },
    {
      "headline": "Becoming a Public Institution",
      "text": "In 1906, the College of William & Mary became a public institution, receiving funding from the Commonwealth of Virginia.",
      "date": "1906"
    },
    {
      "headline": "First Female Students",
      "text": "The college admitted its first female students in 1918, becoming coeducational.",
      "date": "1918"
    },
    {
      "headline": "Designation as a Public Ivy",
      "text": "In 1985, the College of William & Mary was designated as one of the original eight 'Public Ivies' by Richard Moll in his book 'Public Ivies: A Guide to America's Best Public Undergraduate Colleges and Universities'.",
      "date": "1985"
    }
  ]
}

