    {
      "headline": "Reign of Caligula",
      "text": "Caligula became emperor in AD 37 and ruled until AD 41. His reign was noted for its extravagance and eventual descent into tyranny, leading to his assassination.",
      "date": "0037"
    },
    {
      "headline": "Reign of Claudius",
      "text": "Claudius ruled from AD 41 to AD 54, expanding the Roman Empire through the conquest of Britain and implementing significant administrative reforms.",
      "date": "0041"
    },
    {
      "headline": "Reign of Nero",
      "text": "Nero ruled from AD 54 to AD 68. His reign ended with his suicide, which led to a brief period of civil war known as the Year of the Four Emperors.",
      "date": "0054"
    },
    {
      "headline": "Year of the Four Emperors",
      "text": "In AD 69, a year of civil war ensued following Nero's death, resulting in the rise of Vespasian as emperor and the establishment of the Flavian dynasty.",
      "date": "0069"
    },
    {
      "headline": "Reign of Vespasian",
      "text": "Vespasian ruled from AD 69 to AD 79, restoring stability to the empire and initiating the construction of the Colosseum.",
      "date": "0069"
    },
    {
      "headline": "Reign of Titus",
      "text": "Titus ruled from AD 79 to AD 81, overseeing the completion of the Colosseum and dealing with the aftermath of the eruption of Mount Vesuvius.",
      "date": "0079"
    },
    {
      "headline": "Reign of Domitian",
      "text": "Domitian ruled from AD 81 to AD 96, strengthening the empire's defenses and expanding its borders, though his autocratic rule led to his assassination.",
      "date": "0081"
    },
    {
      "headline": "Reign of Nerva",
      "text": "Nerva ruled from AD 96 to AD 98, beginning the era of the 'Five Good Emperors' and implementing policies to restore trust in the imperial office.",
      "date": "0096"
    },
    {
      "headline": "Reign of Trajan",
      "text": "Trajan ruled from AD 98 to AD 117, expanding the empire to its greatest territorial extent and initiating extensive public building programs.",
      "date": "0098"
    },
    {
      "headline": "Reign of Hadrian",
      "text": "Hadrian ruled from AD 117 to AD 138, consolidating the empire's borders and commissioning the construction of Hadrian's Wall in Britain.",
      "date": "0117"
    },
    {
      "headline": "Reign of Antoninus Pius",
      "text": "Antoninus Pius ruled from AD 138 to AD 161, overseeing a period of peace and prosperity within the empire.",
      "date": "0138"
    },
    {
      "headline": "Reign of Marcus Aurelius",
      "text": "Marcus Aurelius ruled from AD 161 to AD 180, known for his philosophical writings and his efforts to defend the empire against various invasions.",
      "date": "0161"
    },
    {
      "headline": "End of Pax Romana",
      "text": "The Pax Romana is traditionally considered to have ended with the death of Marcus Aurelius in AD 180, marking the conclusion of the era of the 'Five Good Emperors'.",
      "date": "0180"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "PostgreSQL Project Initiation",
      "text": "The PostgreSQL project began as a successor to the Ingres database, developed at the University of California, Berkeley. The project was initiated by Michael Stonebraker in 1986.",
      "date": "1986"
    },
    {
      "headline": "Postgres Release",
      "text": "The first version of Postgres was released in 1989. It was designed to add the ability to define types and fully support complex objects.",
      "date": "1989"
    },
    {
      "headline": "Postgres95 Release",
      "text": "In 1995, Postgres95 was released, which was a reimplementation of the Postgres code base to use SQL as the query language instead of the original QUEL query language.",
      "date": "1995"
    },
    {
      "headline": "Renaming to PostgreSQL",
      "text": "In 1996, the project was renamed to PostgreSQL to reflect its support for SQL.",
      "date": "1996"
    },
    {
      "headline": "PostgreSQL 6.0 Release",
      "text": "PostgreSQL 6.0 was released in January 1997, marking the first release under the PostgreSQL name.",
      "date": "1997-01"
    },
    {
      "headline": "Introduction of MVCC",
      "text": "In 2000, PostgreSQL 7.0 introduced Multi-Version Concurrency Control (MVCC), which improved performance by allowing readers to access data without blocking writers.",
      "date": "2000"
    },
    {
      "headline": "PostgreSQL 8.0 Release",
      "text": "PostgreSQL 8.0 was released in January 2005, introducing native Windows support, which significantly broadened its user base.",
      "date": "2005-01"
    },
    {
      "headline": "PostgreSQL 9.0 Release",
      "text": "Released in September 2010, PostgreSQL 9.0 introduced streaming replication and hot standby, enhancing its capabilities for high availability.",
      "date": "2010-09"
    },
    {
      "headline": "PostgreSQL 10 Release",
      "text": "PostgreSQL 10 was released in October 2017, featuring logical replication and declarative table partitioning.",
      "date": "2017-10"
    },
    {
      "headline": "PostgreSQL 13 Release",
      "text": "Released in September 2020, PostgreSQL 13 included improvements in indexing and partitioning, among other enhancements.",
      "date": "2020-09"
    }
  ]
}

