{
  "timeline": [
    {
      "headline": "Start of the Second Congo War",
      "text": "The Second Congo War began on 2 August 1998 when Congolese president Laurent-Désiré Kabila turned against his former allies from Rwanda and Uganda, who had helped him seize power.",
      "date": "1998-08-02"
    },
    {
      "headline": "Rwandan and Ugandan Involvement",
      "text": "In August 1998, Rwanda and Uganda sent troops into the Democratic Republic of the Congo to support rebel groups against President Laurent-Désiré Kabila.",
      "date": "1998-08"
    },
    {
      "headline": "Zimbabwe, Angola, and Namibia Support Kabila",
      "text": "In late 1998, Zimbabwe, Angola, and Namibia sent troops to support President Laurent-Désiré Kabila's government against the rebels and their foreign backers.",
      "date": "1998"
    },
    {
      "headline": "Lusaka Ceasefire Agreement",
      "text": "On 10 July 1999, the Lusaka Ceasefire Agreement was signed by the DRC, Angola, Namibia, Zimbabwe, Rwanda, and Uganda, aiming to end hostilities.",
      "date": "1999-07-10"
    },
    {
      "headline": "Deployment of MONUC",
      "text": "In November 1999, the United Nations Organization Mission in the Democratic Republic of the Congo (MONUC) was deployed to monitor the ceasefire and facilitate peace efforts.",
      "date": "1999-11"
    },
    {
      "headline": "Assassination of Laurent-Désiré Kabila",
      "text": "On 16 January 2001, President Laurent-Désiré Kabila was assassinated. His son, Joseph Kabila, succeeded him as president.",
      "date": "2001-01-16"
    },
    {
      "headline": "Sun City Agreement",
      "text": "In April 2002, the Sun City Agreement was signed, establishing a transitional government and setting the stage for peace and democratic elections.",
      "date": "2002-04"
    },
    {
      "headline": "Pretoria Accord",
      "text": "On 30 July 2002, the Pretoria Accord was signed between the DRC and Rwanda, leading to the withdrawal of Rwandan troops from the DRC.",
      "date": "2002-07-30"
    },
    {
      "headline": "Luanda Agreement",
      "text": "On 6 September 2002, the Luanda Agreement was signed between the DRC and Uganda, leading to the withdrawal of Ugandan troops from the DRC.",
      "date": "2002-09-06"
    },
    {
      "headline": "End of the Second Congo War",
      "text": "The Second Congo War officially ended in July 2003 with the establishment of a transitional government in the DRC.",
      "date": "2003-07"
    }
  ]
}

