{
  "timeline": [
    {
      "headline": "Ancient Bengal",
      "text": "Bengal was part of the Vanga Kingdom, one of the ancient kingdoms of the Indian subcontinent. The region was known for its maritime trade and cultural exchanges with Southeast Asia.",
      "date": "-1000"
    },
    {
      "headline": "Maurya Empire",
      "text": "Bengal became part of the Maurya Empire under Emperor Ashoka, who ruled from 268 to 232 BCE. The region was influenced by Buddhism during this period.",
      "date": "-0268"
    },
    {
      "headline": "Gupta Empire",
      "text": "Bengal was incorporated into the Gupta Empire, which is often referred to as the Golden Age of India due to significant advancements in science, art, and culture.",
      "date": "0320"
    },
    {
      "headline": "Pala Empire",
      "text": "The Pala Empire, founded by Gopala in the 8th century, was a major power in Bengal. It was known for its patronage of Buddhism and the establishment of universities like Nalanda and Vikramashila.",
      "date": "0750"
    },
    {
      "headline": "Sena Dynasty",
      "text": "The Sena dynasty replaced the Pala Empire in the 11th century. They were known for their Hindu revivalism and the construction of temples.",
      "date": "1070"
    },
    {
      "headline": "Islamic Rule",
      "text": "Bengal came under Islamic rule with the establishment of the Bengal Sultanate in the 14th century. This period saw the spread of Islam and the development of a syncretic culture.",
      "date": "1342"
    },
    {
      "headline": "Mughal Empire",
