{
  "timeline": [
    {
      "headline": "Emergence of the Counterculture",
      "text": "The counterculture of the 1960s began to emerge in the early 1960s, characterized by a rejection of the conventional social norms of the 1950s.",
      "date": "1960"
    },
    {
      "headline": "Civil Rights Movement Progress",
      "text": "The civil rights movement in the United States made significant progress, including the passage of the Civil Rights Act of 1964, which outlawed discrimination based on race, color, religion, sex, or national origin.",
      "date": "1964"
    },
    {
      "headline": "Voting Rights Act of 1965",
      "text": "The Voting Rights Act of 1965 was signed into law, prohibiting racial discrimination in voting, which was a significant milestone for the civil rights movement and influenced the counterculture.",
      "date": "1965-08-06"
    },
    {
      "headline": "Intensification of the Vietnam War",
      "text": "The Vietnam War intensified in 1965, leading to widespread protests and becoming a central issue for the counterculture movement.",
      "date": "1965"
    },
    {
      "headline": "Summer of Love",
      "text": "The Summer of Love took place in 1967, centered in San Francisco's Haight-Ashbury neighborhood, symbolizing the height of the hippie movement and counterculture.",
      "date": "1967"
    },
    {
      "headline": "Woodstock Festival",
      "text": "The Woodstock Music & Art Fair was held in August 1969, attracting an audience of over 400,000 and becoming a defining moment of the counterculture era.",
      "date": "1969-08-15"
    },
    {
      "headline": "Stonewall Riots",
      "text": "The Stonewall Riots occurred in June 1969 in New York City, marking a pivotal event in the fight for LGBTQ+ rights and aligning with the counterculture's push for social change.",
      "date": "1969-06-28"
    },
    {
      "headline": "End of the Vietnam War",
      "text": "The Vietnam War officially ended in 1975, but the counterculture's influence on anti-war sentiment and activism had already peaked by the early 1970s.",
      "date": "1975"
    }
  ]
}

