{
  "timeline": [
    {
      "headline": "Estimated Composition of the Book of Job",
      "text": "Scholars generally agree that the Book of Job was written between the 7th and 4th centuries BCE. It is part of the Ketuvim ('Writings') section of the Hebrew Bible and the first of the Poetic Books in the Old Testament of the Christian Bible.",
      "date": "-0700"
    },
    {
      "headline": "Setting of the Book of Job",
      "text": "The Book of Job is set in a time when Job, a wealthy and God-fearing man, lives a comfortable life with a large family. This setting provides the backdrop for the exploration of the problem of evil and theodicy.",
      "date": "-0700"
    },
    {
      "headline": "God's Challenge to Satan",
      "text": "In the narrative, God asks Satan for his opinion of Job's piety. Satan suggests that Job would turn away from God if he were rendered penniless, without his family, and materially uncomfortable. God allows Satan to test Job's faith.",
      "date": "-0700"
    },
    {
      "headline": "Job's Trials and Tribulations",
      "text": "Job faces severe trials, losing his wealth, family, and health. Despite these hardships, Job maintains his faith and integrity, defending himself against his unsympathetic friends who suggest his suffering is due to his own wrongdoing.",
      "date": "-0700"
    },
    {
      "headline": "God's Response and Restoration",
      "text": "God admonishes Job's friends for their lack of understanding and reaffirms His sovereignty over nature. Ultimately, God restores Job's fortunes, granting him even greater prosperity than before.",
      "date": "-0700"
    }
  ]
}

{
  "timeline": [
