{
  "timeline": [
    {
      "headline": "Birth of Amin al-Husseini",
      "text": "Mohammed Amin al-Husseini was born in Jerusalem, then part of the Ottoman Empire, in 1897.",
      "date": "1897"
    },
    {
      "headline": "Education in Cairo",
      "text": "In 1912, Amin al-Husseini attended Al-Azhar University in Cairo, Egypt, where he studied Islamic law.",
      "date": "1912"
    },
    {
      "headline": "World War I Service",
      "text": "During World War I, al-Husseini served in the Ottoman army, but later deserted and joined the Arab nationalist movement.",
      "date": "1914"
    },
    {
      "headline": "Involvement in the Nebi Musa Riots",
      "text": "In April 1920, Amin al-Husseini was involved in the Nebi Musa riots in Jerusalem, which led to his conviction in absentia by the British authorities.",
      "date": "1920-04"
    },
    {
      "headline": "Appointment as Grand Mufti of Jerusalem",
      "text": "In 1921, Amin al-Husseini was appointed as the Grand Mufti of Jerusalem by the British High Commissioner, a position he held for many years.",
      "date": "1921"
    },
    {
      "headline": "President of the Supreme Muslim Council",
      "text": "In 1922, al-Husseini became the President of the Supreme Muslim Council, giving him significant influence over Muslim religious and political matters in Palestine.",
      "date": "1922"
    },
    {
      "headline": "Role in the 1936-1939 Arab Revolt",
      "text": "Amin al-Husseini played a leading role in the Arab Revolt against British rule and Jewish immigration in Palestine from 1936 to 1939.",
      "date": "1936"
    },
    {
      "headline": "Exile and Alliance with Axis Powers",
      "text": "In 1937, al-Husseini fled Palestine to avoid arrest by the British and later collaborated with Axis powers during World War II.",
      "date": "1937"
    },
    {
      "headline": "Meeting with Adolf Hitler",
      "text": "On November 28, 1941, Amin al-Husseini met with Adolf Hitler in Berlin, seeking support for Arab independence and opposition to Jewish immigration.",
      "date": "1941-11-28"
    },
    {
      "headline": "Post-War Activities",
      "text": "After World War II, al-Husseini continued to be involved in Arab nationalist activities and opposed the establishment of the State of Israel.",
      "date": "1945"
    },
    {
      "headline": "Death of Amin al-Husseini",
      "text": "Amin al-Husseini died in Beirut, Lebanon, on July 4, 1974.",
      "date": "1974-07-04"
    }
  ]
}

