{
  "timeline": [
    {
      "headline": "Neolithic Settlement",
      "text": "Orkney is known for its significant Neolithic sites, including the settlement of Skara Brae, which dates back to around 3180 BCE.",
      "date": "-3180"
    },
    {
      "headline": "Norse Settlement",
      "text": "The Norse began to settle in Orkney around the late 8th century, establishing it as a significant Norse territory.",
      "date": "0799"
    },
    {
      "headline": "Earl of Orkney",
      "text": "In 875, Harald Fairhair, King of Norway, annexed Orkney and Shetland, establishing the Earldom of Orkney.",
      "date": "0875"
    },
    {
      "headline": "Treaty of Perth",
      "text": "In 1266, the Treaty of Perth was signed, ceding the Hebrides and the Isle of Man to Scotland, but Orkney remained under Norwegian control.",
      "date": "1266"
    },
    {
      "headline": "Pledge to Scotland",
      "text": "In 1468, Orkney was pledged to Scotland by Christian I of Denmark and Norway as part of the dowry for his daughter Margaret's marriage to James III of Scotland.",
      "date": "1468"
    },
    {
      "headline": "Annexation by Scotland",
      "text": "In 1472, Orkney was annexed by the Kingdom of Scotland after the dowry was not paid.",
      "date": "1472"
    },
    {
      "headline": "Battle of Summerdale",
      "text": "In 1529, the Battle of Summerdale took place on Orkney, marking the last battle fought on Scottish soil between rival factions.",
      "date": "1529"
    },
    {
      "headline": "Orkney and Shetland Act",
      "text": "In 1707, the Orkney and Shetland Act was passed, confirming the islands' status as part of Scotland.",
      "date": "1707"
    },
    {
      "headline": "World War II Naval Base",
      "text": "During World War II, Scapa Flow in Orkney was used as a major naval base by the British Royal Navy.",
      "date": "1939"
    },
    {
      "headline": "Orkney Islands Council",
      "text": "In 1975, the Orkney Islands Council was established, providing local government for the islands.",
      "date": "1975"
    }
