      "headline": "Surrender of Japan",
      "text": "Japan formally surrendered to the Allies on September 2, 1945, marking the end of World War II. This event initiated the occupation of Japan.",
      "date": "1945-09-02"
    },
    {
      "headline": "Start of Allied Occupation",
      "text": "The Allied occupation of Japan began in September 1945, led by the United States with support from the British Commonwealth. General Douglas MacArthur was appointed as the Supreme Commander for the Allied Powers.",
      "date": "1945-09"
    },
    {
      "headline": "Establishment of the Far Eastern Commission",
      "text": "The Far Eastern Commission was established in 1946 to oversee the occupation and reconstruction of Japan.",
      "date": "1946"
    },
    {
      "headline": "New Constitution Promulgated",
      "text": "On November 3, 1946, a new constitution was promulgated in Japan, which came into effect on May 3, 1947. This constitution introduced democratic reforms and renounced war.",
      "date": "1946-11-03"
    },
    {
      "headline": "Constitution Comes into Effect",
      "text": "The new Japanese constitution came into effect on May 3, 1947, establishing a parliamentary system and guaranteeing civil liberties.",
      "date": "1947-05-03"
    },
    {
      "headline": "General Matthew Ridgway Succeeds MacArthur",
      "text": "In 1951, General Matthew Ridgway succeeded General Douglas MacArthur as the Supreme Commander for the Allied Powers.",
      "date": "1951"
    },
    {
      "headline": "Treaty of San Francisco",
      "text": "The Treaty of San Francisco was signed on September 8, 1951, officially ending the state of war between Japan and the Allied Powers. It came into effect on April 28, 1952.",
      "date": "1951-09-08"
    },
    {
      "headline": "End of Occupation",
      "text": "The occupation of Japan officially ended on April 28, 1952, when the Treaty of San Francisco came into effect, restoring Japan's sovereignty.",
      "date": "1952-04-28"
    }
  ]
}

