{
  "timeline": [
    {
      "headline": "Introduction of Reservation System",
      "text": "The reservation system in India was introduced during the British rule to address the social and educational backwardness of certain communities.",
      "date": "1933"
    },
    {
      "headline": "Constitution of India Enacted",
      "text": "The Constitution of India, which came into effect on January 26, 1950, included provisions for reservation in education and employment for Scheduled Castes (SCs) and Scheduled Tribes (STs).",
      "date": "1950-01-26"
    },
    {
      "headline": "First Backward Classes Commission",
      "text": "The First Backward Classes Commission, headed by Kaka Kalelkar, was established in 1953 to determine the criteria for identifying socially and educationally backward classes.",
      "date": "1953"
    },
    {
      "headline": "Mandal Commission Established",
      "text": "The Mandal Commission was established in 1979 to identify the socially or educationally backward classes of India and recommend measures for their advancement.",
      "date": "1979"
    },
    {
      "headline": "Mandal Commission Report",
      "text": "In 1980, the Mandal Commission submitted its report recommending 27% reservation for Other Backward Classes (OBCs) in government jobs and educational institutions.",
      "date": "1980"
    },
    {
      "headline": "Implementation of Mandal Commission Recommendations",
      "text": "In 1990, Prime Minister V.P. Singh announced the implementation of the Mandal Commission's recommendations, leading to widespread protests and debates.",
      "date": "1990"
    },
    {
      "headline": "Supreme Court Verdict on Reservation",
      "text": "In 1992, the Supreme Court of India upheld the implementation of the Mandal Commission recommendations but capped the total reservation at 50% in the Indra Sawhney case.",
      "date": "1992"
    },
    {
      "headline": "Introduction of Reservation in Private Sector",
      "text": "In the early 2000s, discussions began regarding the extension of reservation policies to the private sector, though no formal legislation was enacted.",
      "date": "2000"
    },
    {
      "headline": "93rd Constitutional Amendment",
      "text": "In 2006, the 93rd Constitutional Amendment was passed, allowing the government to make special provisions for the advancement of any socially and educationally backward classes or Scheduled Castes and Scheduled Tribes in educational institutions, including private ones.",
      "date": "2006"
    },
    {
      "headline": "Introduction of Economically Weaker Sections (EWS) Quota",
      "text": "In 2019, the Indian government introduced a 10% reservation for Economically Weaker Sections (EWS) in the general category, applicable to educational institutions and government jobs.",
      "date": "2019"
    }
  ]
}

