    },
    {
      "headline": "Recognition by Eastern Roman Emperor",
      "text": "In 477, Odoacer was recognized by the Eastern Roman Emperor Zeno as the ruler of Italy, although he ruled as a patrician under the nominal authority of the Eastern Empire.",
      "date": "0477"
    },
    {
      "headline": "Conflict with Theodoric the Great",
      "text": "In 489, Theodoric the Great, king of the Ostrogoths, invaded Italy under orders from the Eastern Roman Emperor Zeno, leading to a conflict with Odoacer.",
      "date": "0489"
    },
    {
      "headline": "Battle of Isonzo",
      "text": "In August 489, Odoacer was defeated by Theodoric at the Battle of Isonzo.",
      "date": "0489-08"
    },
    {
      "headline": "Battle of Verona",
      "text": "In September 489, Odoacer was again defeated by Theodoric at the Battle of Verona.",
      "date": "0489-09"
    },
    {
      "headline": "Siege of Ravenna",
      "text": "From 490 to 493, Odoacer was besieged in Ravenna by Theodoric's forces.",
      "date": "0490"
    },
    {
      "headline": "Odoacer's Death",
      "text": "Odoacer was killed by Theodoric the Great on March 15, 493, after a banquet held to celebrate a treaty between the two leaders.",
      "date": "0493-03-15"
    }
  ]
}

