{
  "timeline": [
    {
      "headline": "Start of the Progressive Era",
      "text": "The Progressive Era began in the 1890s as a response to the problems caused by rapid industrialization, urbanization, and political corruption in the United States.",
      "date": "1890"
    },
    {
      "headline": "Sherman Antitrust Act",
      "text": "In 1890, the Sherman Antitrust Act was passed to combat anti-competitive practices, reduce monopolies, and preserve economic fairness.",
      "date": "1890"
    },
    {
      "headline": "Founding of the National Consumers League",
      "text": "In 1899, the National Consumers League was founded to promote fair labor standards and protect workers' rights.",
      "date": "1899"
    },
    {
      "headline": "Publication of 'The Jungle'",
      "text": "In 1906, Upton Sinclair published 'The Jungle,' exposing the unsanitary conditions in the meatpacking industry, leading to public outcry and reform.",
      "date": "1906"
    },
    {
      "headline": "Pure Food and Drug Act",
      "text": "The Pure Food and Drug Act was enacted in 1906 to regulate the labeling and safety of food and pharmaceuticals.",
      "date": "1906"
    },
    {
      "headline": "Establishment of the Federal Reserve System",
      "text": "In 1913, the Federal Reserve System was established to provide the country with a safer, more flexible, and stable monetary and financial system.",
      "date": "1913"
    },
    {
      "headline": "Ratification of the 16th Amendment",
      "text": "The 16th Amendment, allowing Congress to levy an income tax, was ratified in 1913 as part of the Progressive Era reforms.",
      "date": "1913"
    },
    {
      "headline": "Ratification of the 17th Amendment",
      "text": "In 1913, the 17th Amendment was ratified, establishing the direct election of United States Senators by popular vote.",
      "date": "1913"
    },
    {
      "headline": "Ratification of the 18th Amendment",
      "text": "The 18th Amendment, establishing the prohibition of alcohol, was ratified in 1919, reflecting the Progressive Era's moral reform efforts.",
      "date": "1919"
    },
    {
      "headline": "Ratification of the 19th Amendment",
      "text": "In 1920, the 19th Amendment was ratified, granting women the right to vote and marking a significant victory for the women's suffrage movement.",
      "date": "1920"
    },
    {
      "headline": "End of the Progressive Era",
      "text": "The Progressive Era is generally considered to have ended in the 1920s, as the focus shifted to other national issues and the onset of the Great Depression.",
      "date": "1920"
    }
  ]
}

