{
  "timeline": [
    {
      "headline": "Birth of Selim I",
      "text": "Selim I was born in 1470 in Amasya, Ottoman Empire.",
      "date": "1470"
    },
    {
      "headline": "Ascension to the Throne",
      "text": "Selim I became the Sultan of the Ottoman Empire on April 24, 1512, after overthrowing his father, Bayezid II.",
      "date": "1512-04-24"
    },
    {
      "headline": "Battle of Chaldiran",
      "text": "On August 23, 1514, Selim I defeated the Safavid Empire at the Battle of Chaldiran, securing eastern Anatolia and northern Iraq for the Ottoman Empire.",
      "date": "1514-08-23"
    },
    {
      "headline": "Conquest of the Mamluk Sultanate",
      "text": "Between 1516 and 1517, Selim I conquered the Mamluk Sultanate, including the Levant, Hejaz, Tihamah, and Egypt, significantly expanding the Ottoman Empire.",
      "date": "1516"
    },
    {
      "headline": "Battle of Marj Dabiq",
      "text": "On August 24, 1516, Selim I defeated the Mamluks at the Battle of Marj Dabiq, leading to the Ottoman control of Syria.",
      "date": "1516-08-24"
    },
    {
      "headline": "Battle of Ridaniya",
      "text": "On January 22, 1517, Selim I defeated the Mamluks at the Battle of Ridaniya, leading to the capture of Cairo and the end of the Mamluk Sultanate.",
      "date": "1517-01-22"
    },
    {
      "headline": "Death of Selim I",
      "text": "Selim I died on September 22, 1520, in Çorlu, Ottoman Empire. His reign saw the Ottoman Empire grow by seventy percent.",
      "date": "1520-09-22"
    }
  ]
}

{
  "timeline": [
    {
