    },
    {
      "headline": "Public Announcement of Dolly's Cloning",
      "text": "Dolly's existence was announced to the public on February 22, 1997. Her cloning was a significant scientific breakthrough, proving that a cloned organism could be produced from a mature cell.",
      "date": "1997-02-22"
    },
    {
      "headline": "Dolly Gives Birth",
      "text": "In April 1998, Dolly gave birth to her first lamb, named Bonnie. This demonstrated that cloned animals could reproduce naturally.",
      "date": "1998-04"
