{
  "timeline": [
    {
      "headline": "First Recorded Trade Union",
      "text": "The first recorded trade union was the General Union of Trades, also known as the Philanthropic Society, formed in 1818 in the United Kingdom.",
      "date": "1818"
    },
    {
      "headline": "Combination Act Repealed",
      "text": "In 1824, the British Parliament repealed the Combination Act, which had prohibited trade unions and collective bargaining.",
      "date": "1824"
    },
    {
      "headline": "Tolpuddle Martyrs",
      "text": "In 1834, six agricultural laborers from Tolpuddle, Dorset, England, were arrested and transported to Australia for forming a trade union, becoming known as the Tolpuddle Martyrs.",
      "date": "1834"
    },
    {
      "headline": "Formation of the American Federation of Labor",
      "text": "The American Federation of Labor (AFL) was founded in 1886, becoming one of the first federations of labor unions in the United States.",
      "date": "1886"
    },
    {
      "headline": "International Labour Organization Established",
      "text": "The International Labour Organization (ILO) was established in 1919 as part of the Treaty of Versailles, aiming to promote social justice and set international labor standards.",
      "date": "1919"
    },
    {
      "headline": "National Labor Relations Act",
      "text": "In 1935, the National Labor Relations Act, also known as the Wagner Act, was enacted in the United States, guaranteeing the rights of private sector employees to organize into trade unions.",
      "date": "1935"
    },
    {
      "headline": "Formation of the Congress of Industrial Organizations",
      "text": "The Congress of Industrial Organizations (CIO) was formed in 1935 in the United States, focusing on organizing industrial workers.",
      "date": "1935"
    },
    {
      "headline": "Merger of AFL and CIO",
      "text": "In 1955, the American Federation of Labor and the Congress of Industrial Organizations merged to form the AFL-CIO, a major federation of unions in the United States.",
      "date": "1955"
    },
    {
      "headline": "Solidarity Movement in Poland",
      "text": "In 1980, the Solidarity movement, a trade union and social movement, was founded in Poland, playing a major role in the end of Communist rule in the country.",
      "date": "1980"
    }
  ]
}

