{
  "timeline": [
    {
      "headline": "Unification of Denmark",
      "text": "The Kingdom of Denmark was unified in the 10th century under King Gorm the Old and his son Harald Bluetooth, who is credited with consolidating the kingdom and converting the Danes to Christianity.",
      "date": "0936"
    },
    {
      "headline": "Kalmar Union",
      "text": "In 1397, the Kalmar Union was formed, uniting Denmark, Norway, and Sweden under a single monarch. This union lasted until 1523 when Sweden left the union.",
      "date": "1397"
    },
    {
      "headline": "Treaty of Kiel",
      "text": "On January 14, 1814, the Treaty of Kiel was signed, ceding Norway from Denmark to Sweden, but Denmark retained control over Greenland, Iceland, and the Faroe Islands.",
      "date": "1814-01-14"
    },
    {
      "headline": "Constitution of Denmark",
      "text": "On June 5, 1849, Denmark became a constitutional monarchy with the signing of the Danish Constitution, which established a parliamentary system.",
      "date": "1849-06-05"
    },
    {
      "headline": "Home Rule for Faroe Islands",
      "text": "On March 23, 1948, the Faroe Islands were granted home rule, allowing them greater autonomy within the Kingdom of Denmark.",
      "date": "1948-03-23"
    },
    {
      "headline": "Greenland Home Rule",
      "text": "On May 1, 1979, Greenland was granted home rule, providing it with a greater degree of self-government within the Kingdom of Denmark.",
      "date": "1979-05-01"
    },
    {
      "headline": "Greenland Self-Government Act",
      "text": "On June 21, 2009, the Greenland Self-Government Act came into effect, further expanding Greenland's autonomy and recognizing Greenlanders as a distinct people under international law.",
      "date": "2009-06-21"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of Phi Beta Kappa",
      "text": "Phi Beta Kappa was founded on December 5, 1776, at the College of William & Mary in Virginia. It is the oldest academic honor society in the United States.",
      "date": "1776-12-05"
    },
    {
      "headline": "First Expansion",
      "text": "In 1779, the society expanded to include chapters at Yale University and Harvard University, marking its first expansion beyond the College of William & Mary.",
      "date": "1779"
    },
    {
      "headline": "Adoption of Greek Letters",
      "text": "Phi Beta Kappa adopted Greek letters as its name, which was a novel idea at the time. The letters ΦΒΚ stand for 'Philosophia Biou Kybernētēs', which means 'Love of learning is the guide of life.'",
      "date": "1776"
    },
    {
      "headline": "Introduction of Secret Rituals",
      "text": "Initially, Phi Beta Kappa included secret rituals and a handshake, which were later abandoned as the society evolved.",
      "date": "1776"
    },
    {
      "headline": "Transition to Honor Society",
      "text": "By the 1830s, Phi Beta Kappa had transitioned from a secret society to an academic honor society focused on recognizing academic excellence.",
      "date": "1830"
    },
    {
      "headline": "First Woman Inducted",
      "text": "In 1875, the first woman was inducted into Phi Beta Kappa, marking a significant step towards gender inclusivity.",
      "date": "1875"
    },
    {
      "headline": "First African American Inducted",
      "text": "In 1874, the first African American, George Washington Henderson, was inducted into Phi Beta Kappa at the University of Vermont.",
      "date": "1874"
    },
    {
      "headline": "Phi Beta Kappa Key",
      "text": "The Phi Beta Kappa key, a symbol of membership, was first introduced in the 19th century and remains a recognizable emblem of the society.",
      "date": "1800s"
    },
    {
      "headline": "Centennial Celebration",
      "text": "In 1876, Phi Beta Kappa celebrated its centennial anniversary, marking 100 years since its founding.",
      "date": "1876"
    },
    {
      "headline": "Establishment of National Office",
      "text": "In 1883, Phi Beta Kappa established a national office to better coordinate its activities and manage its growing number of chapters.",
      "date": "1883"
    },
    {
      "headline": "200th Anniversary",
      "text": "In 1976, Phi Beta Kappa celebrated its 200th anniversary, commemorating two centuries of promoting excellence in the liberal arts and sciences.",
