{
  "timeline": [
    {
      "headline": "First Castles Built",
      "text": "The first castles were built in the 9th and 10th centuries, primarily in Europe, as a response to the need for defense against invasions and local conflicts.",
      "date": "0900"
    },
    {
      "headline": "Development of Motte-and-Bailey Castles",
      "text": "Around the 10th century, the motte-and-bailey design became popular. This type of castle featured a wooden or stone keep situated on a raised earthwork called a motte, accompanied by an enclosed courtyard or bailey.",
      "date": "1000"
    },
    {
      "headline": "Introduction of Stone Keep Castles",
      "text": "In the 11th century, stone keep castles began to replace wooden structures, offering greater durability and defense. The Tower of London, begun in 1078, is a famous example.",
      "date": "1078"
    },
    {
      "headline": "Crusader Castles",
      "text": "During the 12th and 13th centuries, the Crusades led to the construction of many castles in the Middle East, such as Krak des Chevaliers, to secure territories and protect pilgrims.",
      "date": "1100"
    },
    {
      "headline": "Advent of Concentric Castles",
      "text": "In the 13th century, concentric castles, with multiple layers of defensive walls, became prominent. These offered improved defense and were exemplified by castles like Caerphilly Castle in Wales.",
      "date": "1200"
    },
    {
      "headline": "Decline of Castle Building",
      "text": "By the 15th century, the development of gunpowder and artillery made traditional castle defenses less effective, leading to a decline in castle building.",
      "date": "1400"
    },
    {
      "headline": "Transition to Fortified Manor Houses",
      "text": "In the late Middle Ages, the focus shifted from building castles to constructing fortified manor houses, which offered comfort and some level of defense.",
      "date": "1500"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Arrival of Enslaved Africans",
      "text": "During the late 17th century, enslaved Africans were brought to the coastal regions of the Carolinas and Georgia to work on rice plantations. Their knowledge of rice cultivation was crucial to the success of these plantations.",
      "date": "1600"
    },
    {
      "headline": "Development of Gullah Culture",
      "text": "Throughout the 18th century, the Gullah people developed a distinct culture that blended African traditions with new influences from their environment in the Sea Islands and coastal regions.",
      "date": "1700"
    },
    {
      "headline": "American Civil War and Emancipation",
      "text": "The American Civil War (1861-1865) and the subsequent emancipation of enslaved people had a significant impact on the Gullah community, leading to changes in their social and economic conditions.",
      "date": "1861"
    },
    {
      "headline": "Preservation Efforts Begin",
      "text": "In the late 20th century, efforts to preserve Gullah culture and language began to gain momentum, with increased recognition of their unique cultural heritage.",
      "date": "1900"
    },
    {
      "headline": "Gullah/Geechee Cultural Heritage Corridor Established",
      "text": "In 2006, the U.S. Congress designated the Gullah/Geechee Cultural Heritage Corridor to recognize and preserve the cultural and historical contributions of the Gullah people.",
      "date": "2006"
    }
  ]
}

