{
  "timeline": [
    {
      "headline": "First Darknet Market - Silk Road",
      "text": "Silk Road, the first modern darknet market, was launched in February 2011. It operated as a hidden service on the Tor network, allowing users to browse it anonymously and securely without potential traffic monitoring.",
      "date": "2011-02"
    },
    {
      "headline": "Silk Road Shutdown",
      "text": "On October 2, 2013, the FBI shut down the Silk Road website and arrested its alleged operator, Ross Ulbricht, under charges of being the site's pseudonymous founder 'Dread Pirate Roberts'.",
      "date": "2013-10-02"
    },
    {
      "headline": "Launch of Silk Road 2.0",
      "text": "Silk Road 2.0 was launched in November 2013 by former administrators of Silk Road. It aimed to continue the legacy of the original Silk Road.",
      "date": "2013-11"
    },
    {
      "headline": "Silk Road 2.0 Shutdown",
      "text": "On November 6, 2014, Silk Road 2.0 was shut down by the FBI and Europol as part of Operation Onymous, and its alleged operator, Blake Benthall, was arrested.",
      "date": "2014-11-06"
    },
    {
      "headline": "Operation Onymous",
      "text": "In November 2014, Operation Onymous was a joint international law enforcement operation that resulted in the seizure of over 400 websites, including several darknet markets.",
      "date": "2014-11"
    },
    {
      "headline": "Gareth Owen's Study",
      "text": "In December 2014, a study by Gareth Owen from the University of Portsmouth suggested that the second most popular sites on Tor were darknet markets, highlighting their prevalence and significance.",
      "date": "2014-12"
    },
    {
      "headline": "AlphaBay Market Launch",
      "text": "AlphaBay, one of the largest darknet markets, was launched in December 2014. It quickly grew to become one of the most popular platforms for illicit trade.",
      "date": "2014-12"
    },
    {
      "headline": "AlphaBay Shutdown",
      "text": "On July 4, 2017, AlphaBay was shut down by law enforcement as part of a coordinated international operation. Its founder, Alexandre Cazes, was arrested in Thailand.",
      "date": "2017-07-04"
    },
    {
      "headline": "Dream Market Closure",
      "text": "Dream Market, another prominent darknet market, announced its closure in March 2019, citing security concerns and law enforcement pressure.",
      "date": "2019-03"
    }
  ]
}

