    {
      "headline": "Ancient Foundation",
      "text": "Prayagraj, historically known as Prayag, is believed to have been founded by the Hindu god Brahma. It is considered one of the oldest cities in India, with its history dating back to ancient times.",
      "date": "-1500"
    },
    {
      "headline": "Mughal Era - Renaming to Allahabad",
      "text": "In 1583, the Mughal Emperor Akbar renamed the city to Allahabad, meaning 'City of God'. He also built a fort on the banks of the confluence of the Ganges, Yamuna, and the mythical Sarasvati rivers.",
      "date": "1583"
    },
    {
      "headline": "British Colonial Period",
      "text": "During the British colonial period, Allahabad became a prominent city for administration and education. The city played a significant role in the Indian independence movement.",
      "date": "1858"
    },
    {
      "headline": "Allahabad High Court Establishment",
      "text": "The Allahabad High Court was established in 1869, making the city the judicial capital of Uttar Pradesh.",
      "date": "1869"
    },
    {
      "headline": "Indian Independence Movement",
      "text": "Allahabad was a major center for the Indian independence movement. The city hosted several important sessions of the Indian National Congress and was home to many prominent leaders.",
      "date": "1920"
    },
    {
      "headline": "Post-Independence Development",
      "text": "After India's independence in 1947, Allahabad continued to develop as an important administrative and educational center in Uttar Pradesh.",
      "date": "1947"
    },
    {
      "headline": "Renaming to Prayagraj",
      "text": "In 2018, the city was officially renamed from Allahabad to Prayagraj, reflecting its ancient heritage and religious significance.",
      "date": "2018"
    }
  ]
}

