    },
    {
      "headline": "Expansion to Foreign Recipients",
      "text": "The Legion of Merit was expanded to include foreign recipients, allowing it to be awarded to military and political figures of foreign governments for their outstanding services and achievements.",
      "date": "1943"
    },
    {
      "headline": "Distinctive Design of the Legion of Merit",
      "text": "The design of the Legion of Merit is distinctive, featuring a five-pointed white star with a red border, and a blue circle in the center with 13 white stars. It is suspended from a ribbon of purple with white edges.",
      "date": "1942"
    },
    {
      "headline": "Categories of the Legion of Merit",
      "text": "The Legion of Merit is awarded in four degrees: Chief Commander, Commander, Officer, and Legionnaire. The Chief Commander degree is typically awarded to heads of state or government.",
      "date": "1942"
    }
  ]
}

