{
  "timeline": [
    {
      "headline": "Emergence of Runic Alphabets",
      "text": "The runic alphabets, used by Germanic peoples, began to emerge around the 2nd century CE. These alphabets were used to write various Germanic languages before the adoption of the Latin alphabet.",
      "date": "0200"
    },
    {
      "headline": "Oldest Runic Inscriptions",
      "text": "The oldest known runic inscriptions date back to around 150-200 CE. These early inscriptions were found on artifacts such as combs, brooches, and weapons.",
      "date": "0200"
    },
    {
      "headline": "Development of the Elder Futhark",
      "text": "The Elder Futhark, the oldest form of the runic alphabets, was used from approximately 150-800 CE. It consisted of 24 runes and was used across the Germanic world.",
      "date": "0150"
    },
    {
      "headline": "Introduction of the Younger Futhark",
      "text": "Around 800 CE, the Younger Futhark emerged in Scandinavia. This runic alphabet had only 16 characters and was used during the Viking Age.",
      "date": "0800"
    },
    {
      "headline": "Development of the Anglo-Saxon Futhorc",
      "text": "The Anglo-Saxon Futhorc, a variant of the runic alphabet, developed in England around the 5th century CE. It expanded the Elder Futhark to include additional runes to accommodate Old English sounds.",
      "date": "0500"
    },
    {
      "headline": "Runes in the Christian Era",
      "text": "Despite the spread of Christianity and the Latin alphabet, runes continued to be used for specialized purposes, such as inscriptions on monuments and in magical contexts, up until the Middle Ages.",
      "date": "1000"
    },
    {
      "headline": "Runes in Modern Times",
      "text": "In modern times, runes have been revived in various forms, including as symbols in neo-paganism and in popular culture. They are studied for their historical and linguistic significance.",
      "date": "1900"
    }
  ]
}

