    },
    {
      "headline": "Akkadian Influence and Bilingualism",
      "text": "Around 2000 BCE, Sumerian began to be influenced by Akkadian, leading to a period of bilingualism in Mesopotamia.",
      "date": "-2000"
    },
    {
      "headline": "Sumerian as a Classical Language",
      "text": "By 1800 BCE, Sumerian ceased to be a spoken language and was used primarily as a classical and liturgical language.",
      "date": "-1800"
    },
    {
      "headline": "Sumerian in Scribal Education",
      "text": "Throughout the 2nd millennium BCE, Sumerian was taught in scribal schools and used for scholarly purposes.",
      "date": "-1700"
    },
    {
      "headline": "Decline of Sumerian Language",
      "text": "By 1000 BCE, the use of Sumerian had significantly declined, with Akkadian and later Aramaic becoming more dominant.",
      "date": "-1000"
    }
  ]
}

