{
  "timeline": [
    {
      "headline": "Black Monday Stock Market Crash",
      "text": "On October 19, 1987, global stock markets experienced a severe and largely unexpected crash. The Dow Jones Industrial Average fell by 22.6%, marking the largest one-day percentage decline in history. This event became known as Black Monday.",
      "date": "1987-10-19"
    },
    {
      "headline": "Global Impact of Black Monday",
      "text": "The crash affected stock markets around the world. In Hong Kong, the market fell by 45.8% over the course of October. In the United Kingdom, the FTSE 100 Index fell by 10.8% on Black Monday and by 26.4% by the end of the month.",
      "date": "1987-10"
    },
    {
      "headline": "Economic Concerns Post-Crash",
      "text": "The severity of the crash sparked fears of extended economic instability or even a reprise of the Great Depression. However, the markets recovered relatively quickly, and the economic impact was not as severe as initially feared.",
      "date": "1987-10"
    },
    {
      "headline": "Regulatory and Market Reforms",
      "text": "In response to Black Monday, regulatory bodies and stock exchanges implemented measures to prevent a similar event in the future. These included the introduction of circuit breakers and other mechanisms to halt trading during extreme volatility.",
      "date": "1987"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Early 20th Century Simplification Efforts",
      "text": "In the early 20th century, various scholars and reformers in China began advocating for the simplification of Chinese characters to increase literacy rates.",
      "date": "1900"
    },
    {
      "headline": "First Official Simplification",
      "text": "In 1935, the government of the Republic of China introduced the first official list of simplified characters, but it was later rescinded in 1936.",
      "date": "1935"
    },
    {
      "headline": "Establishment of the People's Republic of China",
      "text": "The People's Republic of China was established in 1949, and the new government prioritized increasing literacy among the population.",
      "date": "1949"
    },
    {
      "headline": "First Round of Simplified Characters",
      "text": "In 1956, the People's Republic of China released the first official list of simplified Chinese characters, which included 515 characters and 54 radicals.",
      "date": "1956"
    },
    {
      "headline": "Second Round of Simplified Characters",
      "text": "In 1964, a second round of simplifications was introduced, resulting in the publication of the 'Complete List of Simplified Characters' which included 2,238 simplified characters.",
      "date": "1964"
    },
    {
      "headline": "Promotion of Simplified Characters",
      "text": "Throughout the 1960s and 1970s, the Chinese government actively promoted the use of simplified characters in education and media.",
      "date": "1960"
    },
    {
      "headline": "Simplified Characters in Singapore",
      "text": "In 1969, Singapore adopted simplified Chinese characters for use in education and official documents.",
      "date": "1969"
    },
    {
      "headline": "Reaffirmation of Simplified Characters",
      "text": "In 1986, the Chinese government reaffirmed the use of simplified characters by publishing the 'Table of General Standard Chinese Characters', which included 7,000 characters.",
      "date": "1986"
    },
    {
      "headline": "Current Use of Simplified Characters",
      "text": "Today, simplified Chinese characters are the standard writing system in mainland China and Singapore, while traditional characters remain in use in Hong Kong, Macau, and Taiwan.",
      "date": "2023"
    }
  ]
}

