{
  "timeline": [
    {
      "headline": "Outbreak of the Second Punic War",
      "text": "The Second Punic War began in 218 BCE when Hannibal, the Carthaginian general, attacked the Roman ally Saguntum in Iberia, prompting Rome to declare war on Carthage.",
      "date": "-0218"
    },
    {
      "headline": "Battle of the Trebia",
      "text": "In December 218 BCE, Hannibal defeated the Roman forces at the Battle of the Trebia, marking his first major victory in Italy.",
      "date": "-0218-12"
    },
    {
      "headline": "Battle of Lake Trasimene",
      "text": "On June 21, 217 BCE, Hannibal ambushed and destroyed a Roman army at the Battle of Lake Trasimene, one of the largest ambushes in military history.",
      "date": "-0217-06-21"
    },
    {
      "headline": "Battle of Cannae",
      "text": "On August 2, 216 BCE, Hannibal achieved a significant victory at the Battle of Cannae, where his forces encircled and annihilated a larger Roman army.",
      "date": "-0216-08-02"
    },
    {
      "headline": "Roman Recovery and Fabian Strategy",
      "text": "Following the disaster at Cannae, Rome adopted the Fabian strategy, avoiding direct confrontation with Hannibal and focusing on attrition warfare.",
      "date": "-0216"
    },
    {
      "headline": "Battle of the Metaurus",
      "text": "In 207 BCE, the Romans defeated and killed Hasdrubal Barca, Hannibal's brother, at the Battle of the Metaurus, preventing him from reinforcing Hannibal in Italy.",
      "date": "-0207"
    },
    {
      "headline": "Scipio's Campaign in Iberia",
      "text": "From 210 to 206 BCE, Roman general Scipio Africanus led successful campaigns in Iberia, capturing Carthago Nova and defeating Carthaginian forces, securing Roman control over the region.",
      "date": "-0210"
    },
    {
      "headline": "Battle of Zama",
      "text": "On October 19, 202 BCE, the Romans under Scipio Africanus defeated Hannibal at the Battle of Zama in North Africa, effectively ending the Second Punic War.",
      "date": "-0202-10-19"
    },
    {
      "headline": "End of the Second Punic War",
      "text": "The Second Punic War officially ended in 201 BCE with the signing of a peace treaty, which imposed harsh terms on Carthage, including the loss of its fleet and overseas territories.",
      "date": "-0201"
    }
  ]
}

