{
  "timeline": [
    {
      "headline": "Ancient Settlement",
      "text": "Campania has been inhabited since the Neolithic period. The region was settled by various ancient peoples, including the Oscans, Greeks, and Etruscans.",
      "date": "-04000"
    },
    {
      "headline": "Greek Colonization",
      "text": "In the 8th century BCE, Greek settlers established colonies in Campania, including the city of Cumae, which became a major cultural and commercial center.",
      "date": "-0800"
    },
    {
      "headline": "Samnite Wars",
      "text": "During the 4th century BCE, Campania was involved in the Samnite Wars, a series of conflicts between the Roman Republic and the Samnites, an Italic tribe.",
      "date": "-0343"
    },
    {
      "headline": "Roman Conquest",
      "text": "By the end of the Samnite Wars in 290 BCE, Campania was fully integrated into the Roman Republic.",
      "date": "-0290"
    },
    {
      "headline": "Eruption of Mount Vesuvius",
      "text": "On August 24, 79 CE, Mount Vesuvius erupted, leading to the destruction of the cities of Pompeii and Herculaneum.",
      "date": "0079-08-24"
    },
    {
      "headline": "Fall of the Western Roman Empire",
      "text": "In 476 CE, the Western Roman Empire fell, leading to a period of instability and the eventual control of Campania by the Ostrogoths.",
      "date": "0476"
    },
    {
      "headline": "Byzantine and Lombard Rule",
      "text": "During the 6th and 7th centuries, Campania was contested between the Byzantine Empire and the Lombards, with the latter eventually establishing control over much of the region.",
      "date": "0600"
    },
    {
      "headline": "Norman Conquest",
      "text": "In the 11th century, the Normans conquered Campania, integrating it into the Kingdom of Sicily.",
      "date": "1059"
    },
    {
      "headline": "Kingdom of Naples",
      "text": "In 1282, Campania became part of the Kingdom of Naples, following the Sicilian Vespers and the division of the Kingdom of Sicily.",
      "date": "1282"
    },
    {
      "headline": "Unification of Italy",
      "text": "In 1861, Campania became part of the newly unified Kingdom of Italy.",
      "date": "1861"
    },
    {
      "headline": "World War II",
      "text": "During World War II, Campania was a significant battleground, including the Allied invasion of Salerno in 1943.",
      "date": "1943"
    },
    {
      "headline": "Establishment of Campania Region",
      "text": "In 1970, Campania was officially established as an administrative region of Italy.",
      "date": "1970"
    },
    {
      "headline": "UNESCO World Heritage Sites",
      "text": "Campania is home to 10 UNESCO World Heritage Sites, including Pompeii, Herculaneum, and the Amalfi Coast.",
      "date": "1997"
    }
  ]
}

