    {
      "headline": "Invention of Ethernet",
      "text": "Ethernet was invented by Robert Metcalfe and others at Xerox PARC in 1973. It was designed to connect multiple computers over a network.",
      "date": "1973"
    },
    {
      "headline": "Ethernet Paper Published",
      "text": "In 1976, Robert Metcalfe and David Boggs published a seminal paper titled 'Ethernet: Distributed Packet Switching for Local Computer Networks'.",
      "date": "1976"
    },
    {
      "headline": "Commercial Introduction of Ethernet",
      "text": "Ethernet was commercially introduced in 1980 by Digital Equipment Corporation, Intel, and Xerox (DIX).",
      "date": "1980"
    },
    {
      "headline": "Standardization of Ethernet",
      "text": "Ethernet was first standardized as IEEE 802.3 in 1983, establishing it as a widely accepted networking technology.",
      "date": "1983"
    },
    {
      "headline": "Introduction of Fast Ethernet",
      "text": "Fast Ethernet, offering speeds of 100 Mbit/s, was introduced in 1995, significantly increasing the speed of Ethernet networks.",
      "date": "1995"
    },
    {
      "headline": "Gigabit Ethernet Standardized",
      "text": "In 1999, Gigabit Ethernet was standardized, providing data transfer rates of 1 Gbit/s.",
      "date": "1999"
    },
    {
      "headline": "10 Gigabit Ethernet Standardized",
      "text": "The IEEE 802.3ae standard for 10 Gigabit Ethernet was ratified in 2002, further increasing Ethernet speeds.",
      "date": "2002"
    },
    {
      "headline": "Introduction of 40 and 100 Gigabit Ethernet",
      "text": "In 2010, the IEEE 802.3ba standard was ratified, introducing 40 and 100 Gigabit Ethernet for high-speed data transmission.",
      "date": "2010"
    },
    {
      "headline": "Ethernet Alliance Formed",
      "text": "The Ethernet Alliance was formed in 2005 to promote and support Ethernet technology.",
      "date": "2005"
    },
    {
      "headline": "25 Gigabit Ethernet Standardized",
      "text": "In 2016, the IEEE 802.3by standard for 25 Gigabit Ethernet was ratified, offering a new option for high-speed networking.",
      "date": "2016"
    },
    {
      "headline": "400 Gigabit Ethernet Standardized",
      "text": "The IEEE 802.3bs standard for 400 Gigabit Ethernet was ratified in 2017, marking a significant milestone in Ethernet technology.",
      "date": "2017"
    }
  ]
}

