{
  "timeline": [
    {
      "headline": "Start of the Great Chicago Fire",
      "text": "The Great Chicago Fire began on the evening of October 8, 1871, in a neighborhood southwest of the city center. The fire started in or around a small barn belonging to the O'Leary family.",
      "date": "1871-10-08"
    },
    {
      "headline": "Fire Spreads Rapidly",
      "text": "Due to a long period of hot, dry, and windy conditions, and the wooden construction prevalent in the city, the fire spread rapidly. It leapt the south branch of the Chicago River and destroyed much of central Chicago.",
      "date": "1871-10-08"
    },
    {
      "headline": "Destruction of Central Chicago",
      "text": "On October 9, 1871, the fire continued to spread, crossing the main stem of the Chicago River and consuming the Near North Side. The fire destroyed roughly 3.3 square miles of the city, including over 17,000 structures.",
      "date": "1871-10-09"
    },
    {
      "headline": "End of the Great Chicago Fire",
      "text": "The fire finally burned out on October 10, 1871, after rain helped to extinguish the flames. The fire left more than 100,000 residents homeless and killed approximately 300 people.",
      "date": "1871-10-10"
    },
    {
      "headline": "Rebuilding of Chicago",
      "text": "In the aftermath of the fire, Chicago began a period of rebuilding. The city adopted stricter fire codes and building regulations, leading to a more modern and fire-resistant cityscape.",
      "date": "1871"
    }
  ]
}

