{
  "timeline": [
    {
      "headline": "First Voyage Begins",
      "text": "Christopher Columbus set sail on his first voyage across the Atlantic Ocean on August 3, 1492, with three ships: the Niña, the Pinta, and the Santa María.",
      "date": "1492-08-03"
    },
    {
      "headline": "Landfall in the New World",
      "text": "On October 12, 1492, Columbus made landfall in the Bahamas, on an island he named San Salvador, marking the discovery of the New World.",
      "date": "1492-10-12"
    },
    {
      "headline": "Exploration of Cuba",
      "text": "Columbus reached Cuba on October 28, 1492, during his first voyage, believing it to be part of Asia.",
      "date": "1492-10-28"
    },
    {
      "headline": "Santa María Shipwreck",
      "text": "On December 25, 1492, the Santa María ran aground off the coast of Hispaniola, leading to the establishment of the settlement La Navidad.",
      "date": "1492-12-25"
    },
    {
      "headline": "Return to Spain",
      "text": "Columbus returned to Spain on March 15, 1493, after completing his first voyage to the New World.",
      "date": "1493-03-15"
    },
    {
      "headline": "Second Voyage Begins",
      "text": "Columbus embarked on his second voyage on September 24, 1493, with a fleet of 17 ships, aiming to establish permanent colonies in the New World.",
      "date": "1493-09-24"
    },
    {
      "headline": "Founding of La Isabela",
      "text": "In January 1494, Columbus established the settlement of La Isabela on the island of Hispaniola, the first European town in the Americas.",
      "date": "1494-01"
    },
    {
      "headline": "Third Voyage Begins",
      "text": "Columbus set out on his third voyage on May 30, 1498, with the goal of finding a new route to Asia and exploring further south.",
      "date": "1498-05-30"
    },
    {
      "headline": "Discovery of South America",
      "text": "On August 1, 1498, Columbus reached the mainland of South America, landing on the Paria Peninsula in present-day Venezuela.",
      "date": "1498-08-01"
    },
    {
      "headline": "Fourth Voyage Begins",
      "text": "Columbus embarked on his fourth and final voyage on May 11, 1502, with the intention of finding a westward passage to the Indian Ocean.",
      "date": "1502-05-11"
    },
    {
      "headline": "Exploration of Central America",
      "text": "During his fourth voyage, Columbus explored the coasts of Central America, including present-day Honduras, Nicaragua, Costa Rica, and Panama, from 1502 to 1504.",
      "date": "1502"
    },
    {
      "headline": "Return from Fourth Voyage",
      "text": "Columbus returned to Spain on November 7, 1504, after completing his fourth voyage, marking the end of his explorations.",
      "date": "1504-11-07"
    }
  ]
}

