    {
      "headline": "Establishment of the Rhodes Scholarship",
      "text": "The Rhodes Scholarship was established in 1902 under the will of Cecil John Rhodes, a British mining magnate and politician in southern Africa. The scholarship aimed to promote unity among English-speaking nations and instill a sense of civic-minded leadership and moral fortitude in future leaders.",
      "date": "1902"
    },
    {
      "headline": "First Rhodes Scholars",
      "text": "The first cohort of Rhodes Scholars took up residence at the University of Oxford in 1903. The initial group included students from the United States, Germany, and the British colonies.",
      "date": "1903"
    },
    {
      "headline": "Expansion to Commonwealth Countries",
      "text": "Over the years, the Rhodes Scholarship expanded to include students from Commonwealth countries, reflecting the changing political landscape and the growing importance of global education.",
      "date": "1920s"
    },
    {
      "headline": "Inclusion of Women",
      "text": "In 1977, the Rhodes Trust amended its criteria to allow women to apply for the scholarship, marking a significant step towards gender equality in higher education.",
      "date": "1977"
    },
    {
      "headline": "Global Expansion",
      "text": "The Rhodes Scholarship continued to expand globally, with new scholarships established for students from countries in Africa, Asia, and the Middle East, furthering its mission to foster international understanding and peace.",
      "date": "2000s"
    },
    {
      "headline": "Rhodes Scholarships for China",
      "text": "In 2015, the Rhodes Trust announced the establishment of Rhodes Scholarships for China, marking the first time students from China could apply for the prestigious award.",
      "date": "2015"
    },
    {
      "headline": "Rhodes Scholarships for West Africa",
      "text": "In 2018, the Rhodes Trust launched scholarships specifically for students from West Africa, further expanding its reach and commitment to diverse global representation.",
      "date": "2018"
    }
  ]
}

