    {
      "headline": "Formation of the 1900 Galveston Hurricane",
      "text": "The hurricane formed as a tropical storm in the central Atlantic Ocean on August 27, 1900.",
      "date": "1900-08-27"
    },
    {
      "headline": "Hurricane Reaches Cuba",
      "text": "The storm reached Cuba on September 3, 1900, where it was observed as a hurricane.",
      "date": "1900-09-03"
    },
    {
      "headline": "Landfall in Galveston, Texas",
      "text": "On September 8, 1900, the hurricane made landfall in Galveston, Texas, with devastating effects. The storm surge inundated the coastline and the island city with 8 to 12 feet of water.",
      "date": "1900-09-08"
    },
    {
      "headline": "Destruction in Galveston",
      "text": "The hurricane destroyed about 7,000 buildings in Galveston, including 3,636 homes. Every dwelling in the city suffered some degree of damage.",
      "date": "1900-09-08"
    },
    {
      "headline": "Casualties and Homelessness",
      "text": "The hurricane resulted in between 6,000 and 12,000 fatalities, with the most cited number being 8,000. Approximately 10,000 people in Galveston were left homeless.",
      "date": "1900-09-08"
    },
    {
      "headline": "Impact on Galveston's Economy",
      "text": "The disaster ended the Golden Era of Galveston, as the hurricane alarmed potential investors, who turned to Houston instead.",
      "date": "1900-09-08"
    },
    {
      "headline": "Engineering Response",
      "text": "In response to the storm, three engineers designed and oversaw plans to raise the Gulf of Mexico shoreline of Galveston Island by 17 feet and erect a 10-mile seawall.",
      "date": "1900"
    }
  ]
}

