{
  "timeline": [
    {
      "headline": "Founding of Rome",
      "text": "According to Roman tradition, the city of Rome was founded in 753 BC by Romulus, who became its first king.",
      "date": "-0753"
    },
    {
      "headline": "Reign of Romulus",
      "text": "Romulus is traditionally considered the first King of Rome, ruling from 753 BC until his death in 716 BC.",
      "date": "-0753"
    },
    {
      "headline": "Reign of Numa Pompilius",
      "text": "Numa Pompilius, the second king of Rome, ruled from 715 BC to 673 BC. He is credited with establishing many of Rome's religious and legal institutions.",
      "date": "-0715"
    },
    {
      "headline": "Reign of Tullus Hostilius",
      "text": "Tullus Hostilius, the third king of Rome, ruled from 673 BC to 642 BC. He is known for his military exploits and the destruction of Alba Longa.",
      "date": "-0673"
    },
    {
      "headline": "Reign of Ancus Marcius",
      "text": "Ancus Marcius, the fourth king of Rome, ruled from 642 BC to 617 BC. He is credited with expanding Rome's territory and building the first bridge over the Tiber River.",
      "date": "-0642"
    },
    {
      "headline": "Reign of Lucius Tarquinius Priscus",
      "text": "Lucius Tarquinius Priscus, the fifth king of Rome, ruled from 616 BC to 579 BC. He is known for his public works and military conquests.",
      "date": "-0616"
    },
    {
      "headline": "Reign of Servius Tullius",
      "text": "Servius Tullius, the sixth king of Rome, ruled from 578 BC to 535 BC. He is credited with implementing important social and political reforms, including the Servian Constitution.",
      "date": "-0578"
    },
    {
      "headline": "Reign of Lucius Tarquinius Superbus",
      "text": "Lucius Tarquinius Superbus, the seventh and last king of Rome, ruled from 535 BC until his overthrow in 509 BC. His tyrannical reign led to the establishment of the Roman Republic.",
      "date": "-0535"
    },
    {
      "headline": "Establishment of the Roman Republic",
      "text": "In 509 BC, the Roman Kingdom came to an end with the overthrow of Lucius Tarquinius Superbus, leading to the establishment of the Roman Republic.",
      "date": "-0509"
    }
  ]
}

