      "text": "In 615, Uthman married Ruqayyah, the daughter of the Prophet Muhammad, strengthening his ties to the Prophet.",
      "date": "0615"
    },
    {
      "headline": "Migration to Abyssinia",
      "text": "Uthman and his wife Ruqayyah migrated to Abyssinia in 615 to escape persecution in Mecca, marking the first migration in Islamic history.",
      "date": "0615"
    },
    {
      "headline": "Return to Mecca",
      "text": "Uthman and Ruqayyah returned to Mecca in 619 after the situation for Muslims improved.",
      "date": "0619"
    },
    {
      "headline": "Migration to Medina",
      "text": "In 622, Uthman migrated to Medina with other Muslims during the Hijra, a pivotal event in Islamic history.",
      "date": "0622"
    },
    {
      "headline": "Death of Ruqayyah",
      "text": "Ruqayyah, Uthman's wife, died in 624, shortly after the Battle of Badr.",
      "date": "0624"
    },
    {
      "headline": "Marriage to Umm Kulthum bint Muhammad",
      "text": "Uthman married Umm Kulthum, another daughter of the Prophet Muhammad, in 625 after the death of Ruqayyah.",
      "date": "0625"
    },
    {
      "headline": "Becomes the Third Caliph",
      "text": "In 644, Uthman was elected as the third caliph of the Islamic community after the death of Caliph Umar.",
      "date": "0644"
    },
    {
      "headline": "Compilation of the Quran",
      "text": "Uthman ordered the compilation of the Quran into a standardized version around 650, which remains the version used today.",
      "date": "0650"
    },
    {
      "headline": "Assassination of Uthman",
      "text": "Uthman was assassinated in 656 in Medina during a period of civil unrest, marking the end of his caliphate.",
      "date": "0656"
    }
  ]
}

