{
  "timeline": [
    {
      "headline": "Invention of the Leyden Jar",
      "text": "The Leyden jar, invented in 1745-1746, was the first device capable of storing an electric charge. It was a type of capacitor rather than a battery, but it laid the groundwork for future developments in electrical storage.",
      "date": "1745"
    },
    {
      "headline": "Voltaic Pile Invented",
      "text": "In 1800, Alessandro Volta invented the voltaic pile, the first true battery. It consisted of a stack of alternating discs of zinc and copper, separated by pieces of cardboard soaked in saltwater.",
      "date": "1800"
    },
    {
      "headline": "Daniell Cell Developed",
      "text": "In 1836, John Frederic Daniell developed the Daniell cell, which provided a more reliable and longer-lasting source of electrical power than the voltaic pile.",
      "date": "1836"
    },
    {
      "headline": "Grove Cell Introduced",
      "text": "In 1839, William Robert Grove introduced the Grove cell, which used a platinum cathode and a zinc anode, providing a higher voltage than the Daniell cell.",
      "date": "1839"
    },
    {
      "headline": "Invention of the Lead-Acid Battery",
      "text": "In 1859, Gaston Planté invented the lead-acid battery, the first rechargeable battery. It is still used today in many applications, including car batteries.",
      "date": "1859"
    },
    {
      "headline": "Development of the Nickel-Cadmium Battery",
      "text": "In 1899, Waldemar Jungner invented the nickel-cadmium battery, which offered a higher energy density and was rechargeable.",
      "date": "1899"
    },
    {
      "headline": "Introduction of the Alkaline Battery",
      "text": "In 1959, Lewis Urry developed the alkaline battery, which provided a longer life and higher energy density than the zinc-carbon batteries commonly used at the time.",
      "date": "1959"
    },
    {
      "headline": "Commercialization of the Lithium-Ion Battery",
      "text": "In 1991, Sony and Asahi Kasei released the first commercial lithium-ion battery, which revolutionized portable electronics with its high energy density and rechargeability.",
      "date": "1991"
    }
  ]
}

