{
    "timeline": [
        {
            "headline": "First European sighting",
            "text": "The first European to reach the Cape of Good Hope was the Portuguese explorer Bartolomeu Dias in 1488. He originally named it the 'Cape of Storms'.",
            "date": "1488"
        },
        {
            "headline": "Renaming to Cape of Good Hope",
            "text": "King John II of Portugal renamed the Cape of Storms to the Cape of Good Hope because of the optimism it inspired for opening a sea route to India and the East.",
            "date": "1488"
        },
        {
            "headline": "Dutch settlement established",
            "text": "In 1652, the Dutch East India Company established a supply station at the Cape of Good Hope under the leadership of Jan van Riebeeck.",
            "date": "1652"
        },
        {
            "headline": "British occupation",
            "text": "The British occupied the Cape of Good Hope in 1795 during the Napoleonic Wars to prevent it from falling into French hands.",
            "date": "1795"
        },
        {
            "headline": "Return to Dutch control",
            "text": "The Cape was returned to Dutch control in 1803 under the Treaty of Amiens.",
            "date": "1803"
        },
        {
            "headline": "Second British occupation",
            "text": "The British re-occupied the Cape of Good Hope in 1806 after the Battle of Blaauwberg.",
            "date": "1806"
        },
        {
            "headline": "Cape Colony established",
            "text": "The Cape Colony was formally established as a British colony in 1814 following the Anglo-Dutch Treaty.",
            "date": "1814"
        },
        {
            "headline": "Union of South Africa",
            "text": "In 1910, the Cape of Good Hope became part of the Union of South Africa, a self-governing dominion of the British Empire.",
            "date": "1910"
        }
    ]
}

