    },
    {
      "headline": "Jiangxi Soviet",
      "text": "In 1931, Mao established the Jiangxi Soviet, a self-governing communist region in Jiangxi Province, which became a testing ground for Mao's revolutionary ideas.",
      "date": "1931"
    },
    {
      "headline": "Long March",
      "text": "The Long March, a strategic retreat by the Red Army, began in October 1934 and ended in October 1935. It was a turning point for Mao's leadership within the CCP.",
      "date": "1934-10"
    },
    {
      "headline": "Yan'an Period",
      "text": "From 1935 to 1947, the CCP, under Mao's leadership, was based in Yan'an. During this time, Mao developed his revolutionary theories and solidified his control over the party.",
      "date": "1935"
    },
    {
      "headline": "Founding of the People's Republic of China",
      "text": "On October 1, 1949, Mao Zedong proclaimed the founding of the People's Republic of China in Beijing, marking the victory of the communist revolution.",
      "date": "1949-10-01"
    },
    {
      "headline": "Great Leap Forward",
      "text": "Launched in 1958, the Great Leap Forward was an economic and social campaign led by Mao to rapidly transform China into a socialist society through rapid industrialization and collectivization.",
      "date": "1958"
    },
    {
      "headline": "Cultural Revolution",
      "text": "The Cultural Revolution, initiated by Mao in 1966, was a sociopolitical movement aimed at preserving Chinese communism by purging remnants of capitalist and traditional elements from Chinese society.",
      "date": "1966"
    },
    {
      "headline": "Death of Mao Zedong",
      "text": "Mao Zedong died on September 9, 1976, in Beijing, China, marking the end of an era in Chinese politics and the beginning of a shift away from his policies.",
      "date": "1976-09-09"
    }
  ]
}

