  "timeline": [
    {
      "headline": "Emergence of Yahwism",
      "text": "Yahwism began to emerge as a distinct religious tradition during the Iron Age, around the 12th century BCE, in the ancient kingdoms of Israel and Judah. Yahweh was worshipped as the national god.",
      "date": "-1200"
    },
    {
      "headline": "Yahweh as National God",
      "text": "By the 9th century BCE, Yahweh was recognized as the national god of the kingdoms of Israel and Judah, often depicted as a warrior god who led the armies of Israel.",
      "date": "-0900"
    },
    {
      "headline": "Integration of Asherah",
      "text": "During the 8th and 7th centuries BCE, some evidence suggests that Asherah was worshipped alongside Yahweh, possibly as his consort, although this is debated among scholars.",
      "date": "-0800"
    },
    {
      "headline": "Reforms of King Hezekiah",
      "text": "In the late 8th century BCE, King Hezekiah of Judah implemented religious reforms that centralized worship in Jerusalem and sought to eliminate the worship of other deities besides Yahweh.",
      "date": "-0728"
    },
    {
      "headline": "Reforms of King Josiah",
      "text": "In the late 7th century BCE, King Josiah of Judah furthered religious reforms, promoting exclusive worship of Yahweh and destroying altars to other gods.",
      "date": "-0622"
    },
    {
      "headline": "Babylonian Exile",
      "text": "In 586 BCE, the Babylonian conquest of Jerusalem led to the destruction of the First Temple and the exile of many Judeans, which had a profound impact on Yahwism and its development.",
      "date": "-0586"
    },
    {
      "headline": "Post-Exilic Period",
      "text": "After the Babylonian Exile, Yahwism evolved into a more monotheistic religion, with a stronger emphasis on the exclusive worship of Yahweh, laying the foundations for Judaism.",
      "date": "-0538"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Beginning of the Carboniferous Period",
      "text": "The Carboniferous Period began approximately 358.9 million years ago, marking the end of the Devonian Period.",
      "date": "-358900000"
    },
    {
      "headline": "Mississippian Subperiod",
      "text": "The Mississippian is the earlier subperiod of the Carboniferous, spanning from approximately 358.9 million years ago to 323.2 million years ago. It is characterized by the development of extensive shallow marine habitats and the dominance of crinoids and other marine life.",
      "date": "-358900000"
    },
    {
      "headline": "Development of Extensive Coal Swamps",
      "text": "During the Carboniferous, particularly in the Pennsylvanian subperiod, extensive coal swamps developed, leading to the formation of vast coal deposits. These swamps were dominated by lycophyte trees, horsetails, and ferns.",
      "date": "-323200000"
    },
    {
      "headline": "Pennsylvanian Subperiod",
      "text": "The Pennsylvanian is the later subperiod of the Carboniferous, spanning from approximately 323.2 million years ago to 298.9 million years ago. It is noted for the diversification of amphibians and the first appearance of reptiles.",
      "date": "-323200000"
    },
    {
      "headline": "Diversification of Amphibians",
      "text": "Amphibians diversified significantly during the Carboniferous, taking advantage of the humid climate and abundant resources in the coal swamps.",
      "date": "-320000000"
    },
    {
      "headline": "Appearance of Reptiles",
      "text": "Reptiles first appeared during the Carboniferous, marking an important evolutionary step as they were able to lay eggs on land, unlike their amphibian ancestors.",
      "date": "-315000000"
    },
    {
      "headline": "End of the Carboniferous Period",
      "text": "The Carboniferous Period ended approximately 298.9 million years ago, transitioning into the Permian Period.",
      "date": "-298900000"
    }
  ]
}

