{
  "timeline": [
    {
      "headline": "Tang Dynasty: Early Muslim Influence",
      "text": "During the Tang Dynasty (618-907), Arab and Persian traders and diplomats began to settle in China, bringing Islam with them. This period marks the initial Muslim influence in China, which would later contribute to the formation of the Hui identity.",
      "date": "0618"
    },
    {
      "headline": "Song and Yuan Dynasties: Formation of Hui Identity",
      "text": "During the Song (960-1279) and Yuan (1271-1368) Dynasties, the Hui identity began to form as Muslim communities grew in China. The Yuan Dynasty, in particular, saw an increase in Muslim immigration and integration, with many Muslims serving in administrative roles.",
      "date": "0960"
    },
    {
      "headline": "Ming Dynasty: Hui Cultural Flourishing",
      "text": "The Ming Dynasty (1368-1644) was a period of cultural flourishing for the Hui people. They became more integrated into Chinese society while maintaining their Islamic faith, contributing to various aspects of Chinese culture and economy.",
      "date": "1368"
    },
    {
      "headline": "Qing Dynasty: Hui Rebellions",
      "text": "During the Qing Dynasty (1644-1912), several Hui rebellions occurred, including the Panthay Rebellion (1856-1873) and the Dungan Revolt (1862-1877), as a response to ethnic and religious tensions.",
      "date": "1856"
    },
    {
      "headline": "Republic of China: Hui National Identity",
      "text": "In the early 20th century, during the Republic of China era (1912-1949), the Hui people began to assert a distinct national identity, participating in the political and social changes of the time.",
      "date": "1912"
    },
    {
      "headline": "People's Republic of China: Recognition as an Ethnic Minority",
      "text": "After the establishment of the People's Republic of China in 1949, the Hui were officially recognized as one of the 56 ethnic groups in China. This recognition helped preserve their cultural and religious practices.",
      "date": "1949"
    },
    {
      "headline": "2010 Census: Hui Population",
      "text": "According to the 2010 census, there were approximately 10.5 million Hui people living in China, making them one of the largest Muslim ethnic groups in the country.",
      "date": "2010"
    }
  ]
}

