{
  "timeline": [
    {
      "headline": "Establishment of the Australian Labor Party",
      "text": "The Australian Labor Party (ALP) was established on 8 May 1901 at Parliament House, Melbourne, during the meeting of the first Federal Parliament.",
      "date": "1901-05-08"
    },
    {
      "headline": "First Federal Government",
      "text": "The ALP formed its first federal government in 1904 under the leadership of Chris Watson, becoming the first Labour party to form a national government in the world.",
      "date": "1904"
    },
    {
      "headline": "Andrew Fisher's Government",
      "text": "Andrew Fisher led the ALP to form a majority government in 1910, implementing significant reforms such as the establishment of the Commonwealth Bank and the introduction of maternity allowances.",
      "date": "1910"
    },
    {
      "headline": "Split over Conscription",
      "text": "In 1916, the ALP split over the issue of conscription during World War I, leading to the formation of the Nationalist Party by Prime Minister Billy Hughes.",
      "date": "1916"
    },
    {
      "headline": "Scullin Government",
      "text": "James Scullin led the ALP to victory in the 1929 federal election, but his government struggled with the effects of the Great Depression.",
      "date": "1929"
    },
    {
      "headline": "Curtin's Leadership during WWII",
      "text": "John Curtin became Prime Minister in 1941, leading Australia through much of World War II and strengthening ties with the United States.",
      "date": "1941"
    },
    {
      "headline": "Chifley Government and Post-war Reconstruction",
      "text": "Ben Chifley succeeded Curtin and focused on post-war reconstruction, including the establishment of the Snowy Mountains Scheme and the introduction of the Australian National University.",
      "date": "1945"
    },
    {
      "headline": "Split of 1955",
      "text": "The ALP experienced a major split in 1955, leading to the formation of the Democratic Labor Party, which significantly weakened the ALP's electoral prospects.",
      "date": "1955"
    },
    {
      "headline": "Whitlam Government",
      "text": "Gough Whitlam led the ALP to victory in 1972, implementing widespread reforms in healthcare, education, and foreign policy before being dismissed in 1975.",
      "date": "1972"
    },
    {
      "headline": "Hawke and Keating Governments",
      "text": "Bob Hawke became Prime Minister in 1983, followed by Paul Keating in 1991, with both leaders implementing economic reforms and social policies that modernized Australia.",
      "date": "1983"
