{
  "timeline": [
    {
      "headline": "Christian Doppler Describes the Doppler Effect",
      "text": "In 1842, Austrian physicist Christian Doppler first described the phenomenon now known as the Doppler effect. He proposed that the observed frequency of a wave depends on the relative speed of the source and the observer.",
      "date": "1842"
    },
    {
      "headline": "Doppler's Paper on the Effect",
      "text": "Christian Doppler published his paper titled 'Über das farbige Licht der Doppelsterne und einiger anderer Gestirne des Himmels' ('On the coloured light of the binary stars and some other stars of the heavens') in 1842, where he explained the effect.",
      "date": "1842"
    },
    {
      "headline": "First Experimental Confirmation",
      "text": "In 1845, the Doppler effect was first experimentally confirmed by the Dutch scientist Christoph Hendrik Diederik Buys Ballot. He used a group of musicians playing a single note on a train to demonstrate the change in pitch as the train moved.",
      "date": "1845"
    },
    {
      "headline": "Application in Astronomy",
      "text": "By the late 19th century, astronomers began using the Doppler effect to measure the velocity of stars and galaxies moving towards or away from Earth. This application has become a fundamental tool in astrophysics.",
      "date": "1890"
    },
    {
      "headline": "Development of Radar Technology",
      "text": "During the 20th century, the Doppler effect was utilized in the development of radar technology, which uses the change in frequency of radio waves to determine the speed of objects.",
      "date": "1900"
    },
    {
      "headline": "Doppler Effect in Medical Imaging",
      "text": "In the 1950s, the Doppler effect began to be used in medical imaging, particularly in Doppler ultrasound, which measures blood flow and heart movement.",
      "date": "1950"
    }
  ]
}

