    {
      "headline": "French Establishment in Pondicherry",
      "text": "In 1674, the French East India Company set up a trading center at Pondicherry, which became the chief French settlement in India.",
      "date": "1674"
    },
    {
      "headline": "French Acquisition of Karaikal",
      "text": "In 1739, the French acquired Karaikal, further expanding their territories in India.",
      "date": "1739"
    },
    {
      "headline": "French Acquisition of Mahé",
      "text": "In 1721, Mahé was acquired by the French, adding to their Indian territories.",
      "date": "1721"
    },
    {
      "headline": "French Acquisition of Yanaon",
      "text": "In 1751, Yanaon came under French control, completing the set of territories that would later form Puducherry.",
      "date": "1751"
    },
    {
      "headline": "Treaty of Paris",
      "text": "In 1814, the Treaty of Paris restored the French territories in India, including Pondicherry, Karaikal, Mahé, and Yanaon, after they were temporarily lost during the Napoleonic Wars.",
      "date": "1814"
    },
    {
      "headline": "De facto Transfer to India",
      "text": "On 1 November 1954, the de facto transfer of the French settlements to the Indian Union took place.",
      "date": "1954-11-01"
    },
    {
      "headline": "De jure Transfer to India",
      "text": "The de jure transfer of the French territories to India was completed on 16 August 1962, when the French Parliament ratified the treaty with India.",
      "date": "1962-08-16"
    },
    {
      "headline": "Formation of Union Territory",
      "text": "On 1 July 1963, the territories of Pondicherry, Karaikal, Mahé, and Yanaon were organized to form the Union Territory of Puducherry.",
      "date": "1963-07-01"
    },
    {
      "headline": "Name Change to Puducherry",
      "text": "On 1 October 2006, the official name of the territory was changed from Pondicherry to Puducherry.",
      "date": "2006-10-01"
    }
  ]
}

