    {
      "headline": "Expansion to Scotland",
      "text": "The Orange Order expanded to Scotland in 1798, establishing its presence among the Scottish Protestant community.",
      "date": "1798"
    },
    {
      "headline": "Expansion to England",
      "text": "The Orange Order expanded to England in the early 19th century, further spreading its influence among Protestant communities.",
      "date": "1800"
    },
    {
      "headline": "Formation of the Grand Orange Lodge of Ireland",
      "text": "The Grand Orange Lodge of Ireland was formed in 1798 to oversee the activities of the Orange Order in Ireland.",
      "date": "1798"
    },
    {
      "headline": "Establishment in Canada",
      "text": "The Orange Order was established in Canada in 1830, where it became a significant social and political force.",
      "date": "1830"
    },
    {
      "headline": "Formation of the Grand Orange Lodge of Scotland",
      "text": "The Grand Orange Lodge of Scotland was formed in 1798, marking the formal organization of the Order in Scotland.",
