    {
      "headline": "Formation of the Grand Orange Lodge of England",
      "text": "The Grand Orange Lodge of England was formed in 1876 to coordinate the activities of the Order in England.",
      "date": "1876"
    },
    {
      "headline": "Peak Membership",
      "text": "The Orange Order reached its peak membership in the late 19th and early 20th centuries, with significant influence in Ireland, Canada, and other parts of the British Empire.",
      "date": "1900"
    },
    {
      "headline": "Decline in Membership",
      "text": "The Orange Order experienced a decline in membership and influence throughout the 20th century, particularly in the Republic of Ireland and Canada.",
