    {
      "headline": "Anglo-Irish Treaty Signed",
      "text": "The Anglo-Irish Treaty was signed on December 6, 1921, between representatives of the British government and Irish republicans, leading to the establishment of the Irish Free State.",
      "date": "1921-12-06"
    },
    {
      "headline": "Establishment of the Irish Free State",
      "text": "The Irish Free State was officially established on December 6, 1922, as a self-governing dominion within the British Commonwealth, following the ratification of the Anglo-Irish Treaty.",
      "date": "1922-12-06"
    },
    {
      "headline": "Irish Civil War",
      "text": "The Irish Civil War broke out in June 1922 and lasted until May 1923, fought between pro-treaty forces (supporters of the Anglo-Irish Treaty) and anti-treaty forces (opponents of the treaty).",
      "date": "1922-06"
    },
    {
      "headline": "End of the Irish Civil War",
      "text": "The Irish Civil War ended in May 1923 with the defeat of the anti-treaty forces, solidifying the position of the Irish Free State.",
      "date": "1923-05"
    },
    {
      "headline": "Constitution of the Irish Free State",
      "text": "The Constitution of the Irish Free State came into effect on December 6, 1922, establishing the legal framework for the new state.",
      "date": "1922-12-06"
    },
    {
      "headline": "Abolition of the Oath of Allegiance",
      "text": "In 1932, the Irish Free State abolished the Oath of Allegiance to the British monarch, which had been a contentious issue since the state's establishment.",
      "date": "1932"
    },
    {
      "headline": "Bunreacht na hÉireann Adopted",
      "text": "On December 29, 1937, the new constitution, Bunreacht na hÉireann, was adopted, replacing the Constitution of the Irish Free State and effectively ending the Irish Free State, as the state was renamed Ireland (Éire).",
      "date": "1937-12-29"
    }
  ]
}

