    {
      "headline": "Temporary Provisions Effective",
      "text": "In 1948, the Temporary Provisions Effective During the Period of National Mobilization for Suppression of the Communist Rebellion were enacted, which extended the terms of the first Legislative Yuan members indefinitely.",
      "date": "1948"
    },
    {
      "headline": "First Direct Elections",
      "text": "The first direct elections for the Legislative Yuan in Taiwan were held in 1992, marking a significant step in Taiwan's democratization process.",
      "date": "1992"
    },
    {
      "headline": "Constitutional Amendments",
      "text": "In 2005, constitutional amendments were passed to reduce the number of seats in the Legislative Yuan from 225 to 113 and to change the electoral system to a parallel voting system.",
      "date": "2005"
    },
    {
      "headline": "Implementation of New Electoral System",
      "text": "The new electoral system and the reduced number of seats were implemented in the 2008 legislative elections.",
      "date": "2008"
