{
  "timeline": [
    {
      "headline": "Discovery of Mustard Gas as a Treatment",
      "text": "In the 1940s, researchers discovered that mustard gas, a chemical warfare agent, could be used to treat cancer. This discovery marked the beginning of chemotherapy as a cancer treatment.",
      "date": "1940"
    },
    {
      "headline": "First Use of Nitrogen Mustard",
      "text": "In 1942, nitrogen mustard was first used to treat a patient with non-Hodgkin's lymphoma, marking the first successful use of chemotherapy in cancer treatment.",
      "date": "1942"
    },
    {
      "headline": "Development of Methotrexate",
      "text": "In 1948, methotrexate was developed and became one of the first chemotherapy drugs to cure a solid tumor, specifically choriocarcinoma.",
      "date": "1948"
    },
    {
      "headline": "Introduction of Combination Chemotherapy",
      "text": "In the 1950s, the concept of combination chemotherapy was introduced, using multiple drugs to treat cancer, which improved treatment outcomes.",
      "date": "1950"
    },
    {
      "headline": "Discovery of Cisplatin",
      "text": "In 1965, cisplatin was discovered and later became one of the most effective chemotherapy drugs, particularly for testicular and ovarian cancers.",
      "date": "1965"
    },
    {
      "headline": "FDA Approval of Doxorubicin",
      "text": "In 1974, the FDA approved doxorubicin, a chemotherapy drug that became widely used for treating various types of cancer.",
      "date": "1974"
    },
    {
      "headline": "Introduction of Targeted Therapy",
      "text": "In the late 1990s, targeted therapy emerged as a new approach in chemotherapy, focusing on specific molecular targets associated with cancer.",
      "date": "1990"
    },
    {
      "headline": "Approval of Imatinib",
      "text": "In 2001, the FDA approved imatinib, a targeted therapy drug that revolutionized the treatment of chronic myeloid leukemia (CML).",
      "date": "2001"
    },
    {
      "headline": "Development of Immunotherapy",
      "text": "In the 2010s, immunotherapy became a significant advancement in cancer treatment, often used in conjunction with chemotherapy.",
      "date": "2010"
    }
  ]
}

