{
  "timeline": [
    {
      "headline": "Age of Enlightenment",
      "text": "The Age of Enlightenment, which began in the late 17th century, laid the intellectual groundwork for progressivism. Enlightenment thinkers believed in the power of reason and science to improve society.",
      "date": "1685"
    },
    {
      "headline": "American Progressive Era",
      "text": "The Progressive Era in the United States spanned from the 1890s to the 1920s. It was a period of widespread social activism and political reform across the United States, addressing issues such as industrialization, urbanization, immigration, and political corruption.",
      "date": "1890"
    },
    {
      "headline": "Publication of 'The Jungle'",
      "text": "In 1906, Upton Sinclair published 'The Jungle', a novel that exposed the harsh conditions and exploited lives of immigrants in the United States in Chicago and similar industrialized cities. This book led to public outcry and reforms in the food industry.",
      "date": "1906"
    },
    {
      "headline": "Establishment of the Federal Reserve System",
      "text": "In 1913, the Federal Reserve System was established in the United States as a result of progressive reforms to stabilize the economy and prevent financial crises.",
      "date": "1913"
    },
    {
      "headline": "Women's Suffrage in the United States",
      "text": "The 19th Amendment to the United States Constitution was ratified on August 18, 1920, granting American women the right to vote, a significant achievement of the Progressive Era.",
      "date": "1920-08-18"
    },
    {
      "headline": "New Deal Reforms",
      "text": "During the 1930s, President Franklin D. Roosevelt implemented the New Deal, a series of programs, public work projects, financial reforms, and regulations, in response to the Great Depression. These were influenced by progressive ideas.",
      "date": "1933"
    },
    {
      "headline": "Civil Rights Movement",
      "text": "The Civil Rights Movement, which peaked in the 1950s and 1960s, was influenced by progressive ideals. It sought to end racial segregation and discrimination against African Americans in the United States.",
      "date": "1950"
    },
    {
      "headline": "Environmental Protection Agency Established",
      "text": "In 1970, the United States established the Environmental Protection Agency (EPA) to address environmental issues, reflecting progressive concerns about pollution and conservation.",
      "date": "1970"
    },
    {
      "headline": "Affordable Care Act",
      "text": "The Affordable Care Act, signed into law by President Barack Obama on March 23, 2010, aimed to increase health insurance quality and affordability, lower the uninsured rate, and reduce the costs of healthcare, reflecting progressive health care reform goals.",
      "date": "2010-03-23"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of Rogers' Rangers",
      "text": "In 1756, during the French and Indian War, Robert Rogers formed a company of colonial militia known as Rogers' Rangers. They were known for their unconventional warfare tactics and were the precursor to modern Rangers.",
      "date": "1756"
    },
    {
      "headline": "Rangers in the American Revolutionary War",
      "text": "During the American Revolutionary War, Ranger units such as the Corps of Rangers led by Thomas Knowlton and Francis Marion's brigade were instrumental in various battles and skirmishes.",
      "date": "1775"
    },
    {
      "headline": "Formation of Merrill's Marauders",
      "text": "In 1943, during World War II, the 5307th Composite Unit (Provisional), also known as Merrill's Marauders, was formed. They conducted long-range penetration missions behind Japanese lines in Burma.",
      "date": "1943"
    },
    {
      "headline": "Establishment of the 75th Ranger Regiment",
      "text": "In 1974, the 75th Ranger Regiment was established as a permanent Ranger unit in the United States Army, consisting of three battalions.",
      "date": "1974"
    },
    {
      "headline": "Operation Urgent Fury",
      "text": "In October 1983, the 1st and 2nd Ranger Battalions participated in Operation Urgent Fury, the invasion of Grenada, to rescue American students and restore order.",
      "date": "1983-10"
    },
    {
      "headline": "Operation Just Cause",
      "text": "In December 1989, Rangers took part in Operation Just Cause, the invasion of Panama, to capture Manuel Noriega and restore democratic governance.",
      "date": "1989-12"
    },
    {
      "headline": "Operation Gothic Serpent",
      "text": "In 1993, Rangers were involved in Operation Gothic Serpent in Somalia, which included the Battle of Mogadishu, famously depicted in the book and film 'Black Hawk Down'.",
      "date": "1993"
    },
    {
      "headline": "Global War on Terror",
      "text": "Since 2001, Rangers have been continuously deployed in support of the Global War on Terror, participating in operations in Afghanistan and Iraq.",
      "date": "2001"
    }
  ]
}

