{
  "timeline": [
    {
      "headline": "Formation of the Seven Council Fires",
      "text": "The Sioux, or Oceti Sakowin, meaning 'Seven Council Fires', is a confederation of seven Sioux tribes. The formation of this confederation is a significant cultural and political event in Sioux history, representing the unity and cooperation among the Dakota, Nakota, and Lakota divisions.",
      "date": "-1600"
    },
    {
      "headline": "Introduction of Horses",
      "text": "The Sioux acquired horses in the early 18th century, which transformed their way of life. Horses allowed the Sioux to become more mobile, enhancing their ability to hunt buffalo and engage in warfare.",
      "date": "1700"
    },
    {
      "headline": "Treaty of Fort Laramie",
      "text": "In 1851, the Treaty of Fort Laramie was signed between the United States and several Native American tribes, including the Sioux. This treaty aimed to establish peace and define territorial boundaries.",
      "date": "1851"
    },
    {
      "headline": "Great Sioux War",
      "text": "The Great Sioux War of 1876-1877 was a series of battles and negotiations between the United States and the Sioux tribes, primarily over control of the Black Hills, which were sacred to the Sioux.",
      "date": "1876"
    },
    {
      "headline": "Battle of Little Bighorn",
      "text": "On June 25-26, 1876, the Sioux, along with their allies, defeated the 7th Cavalry Regiment of the United States Army at the Battle of Little Bighorn, also known as Custer's Last Stand.",
      "date": "1876-06-25"
    },
    {
      "headline": "Wounded Knee Massacre",
      "text": "On December 29, 1890, the Wounded Knee Massacre occurred, where U.S. Army forces killed hundreds of Sioux, including women and children, at Wounded Knee Creek in South Dakota.",
      "date": "1890-12-29"
    },
    {
      "headline": "Indian Reorganization Act",
      "text": "In 1934, the Indian Reorganization Act was passed, which aimed to reverse the assimilationist policies of the U.S. government and restore some degree of self-governance to Native American tribes, including the Sioux.",
      "date": "1934"
    },
    {
      "headline": "Occupation of Wounded Knee",
      "text": "In 1973, members of the American Indian Movement and local Oglala Lakota occupied the town of Wounded Knee, South Dakota, for 71 days to protest against U.S. government policies and corruption within the tribal government.",
      "date": "1973"
    }
  ]
}

