{
  "timeline": [
    {
      "headline": "Birth of Eugene V. Debs",
      "text": "Eugene Victor Debs was born on November 5, 1855, in Terre Haute, Indiana.",
      "date": "1855-11-05"
    },
    {
      "headline": "Joined Brotherhood of Locomotive Firemen",
      "text": "In 1875, Debs joined the Brotherhood of Locomotive Firemen, marking the beginning of his involvement in labor movements.",
      "date": "1875"
    },
    {
      "headline": "Elected to Indiana General Assembly",
      "text": "In 1884, Debs was elected as a Democrat to the Indiana General Assembly, serving one term.",
      "date": "1884"
    },
    {
      "headline": "Co-founded the American Railway Union",
      "text": "In 1893, Debs co-founded the American Railway Union (ARU), one of the first industrial unions in the United States.",
      "date": "1893"
    },
    {
      "headline": "Pullman Strike",
      "text": "In 1894, Debs led the ARU in the Pullman Strike, a nationwide railroad strike that significantly impacted the labor movement.",
      "date": "1894"
    },
    {
      "headline": "Imprisonment for Role in Pullman Strike",
      "text": "Debs was imprisoned for six months in 1895 for his role in the Pullman Strike, during which he read extensively and became a committed socialist.",
      "date": "1895"
    },
    {
      "headline": "Co-founded the Social Democracy of America",
      "text": "In 1897, Debs co-founded the Social Democracy of America, a precursor to the Socialist Party of America.",
      "date": "1897"
    },
    {
      "headline": "Ran for President as a Socialist",
      "text": "In 1900, Debs ran for President of the United States as a candidate for the Socialist Party, the first of his five presidential campaigns.",
      "date": "1900"
    },
    {
      "headline": "Co-founded the Industrial Workers of the World",
      "text": "In 1905, Debs was one of the founding members of the Industrial Workers of the World (IWW), a radical labor union.",
      "date": "1905"
    },
    {
      "headline": "Ran for President from Prison",
      "text": "In 1920, Debs ran for President while imprisoned, receiving nearly a million votes. He was serving a ten-year sentence for speaking against World War I.",
      "date": "1920"
    },
    {
      "headline": "Release from Prison",
      "text": "Debs was released from prison on December 25, 1921, after his sentence was commuted by President Warren G. Harding.",
      "date": "1921-12-25"
    },
    {
      "headline": "Death of Eugene V. Debs",
      "text": "Eugene V. Debs died on October 20, 1926, in Elmhurst, Illinois.",
      "date": "1926-10-20"
    }
  ]
}

