{
  "timeline": [
    {
      "headline": "Start of the Bosnian War",
      "text": "The Bosnian War began in April 1992 following the breakup of Yugoslavia, leading to ethnic tensions and conflict in Bosnia and Herzegovina.",
      "date": "1992-04"
    },
    {
      "headline": "Ethnic Cleansing Campaign",
      "text": "Throughout the Bosnian War, from 1992 to 1995, the Army of Republika Srpska (VRS) engaged in a campaign of ethnic cleansing against Bosniak and Bosnian Croat populations in areas under their control.",
      "date": "1992"
    },
    {
      "headline": "Srebrenica Declared a Safe Area",
      "text": "In April 1993, the United Nations declared Srebrenica a 'safe area' under UN protection, intended to be free from armed attack or any other hostile act.",
      "date": "1993-04"
    },
    {
      "headline": "Srebrenica Massacre",
      "text": "In July 1995, the Srebrenica massacre occurred when more than 8,000 Bosniak men and boys were killed by units of the Army of Republika Srpska under the command of General Ratko Mladić.",
      "date": "1995-07"
    },
    {
      "headline": "Mass Expulsion from Srebrenica",
      "text": "Alongside the massacre in July 1995, there was a mass expulsion of 25,000 to 30,000 Bosniak civilians from Srebrenica by VRS forces.",
      "date": "1995-07"
    },
    {
      "headline": "End of the Bosnian War",
      "text": "The Bosnian War ended with the signing of the Dayton Agreement in December 1995, which brought peace to the region and established the framework for Bosnia and Herzegovina's current political structure.",
      "date": "1995-12"
    },
    {
      "headline": "International Criminal Tribunal for the Former Yugoslavia (ICTY)",
      "text": "In 1993, the ICTY was established by the United Nations to prosecute serious crimes committed during the Yugoslav Wars, including those related to the Bosnian genocide.",
      "date": "1993"
    },
    {
      "headline": "Ratko Mladić Convicted",
      "text": "In November 2017, Ratko Mladić was convicted by the ICTY of genocide, war crimes, and crimes against humanity for his role in the Bosnian genocide, including the Srebrenica massacre.",
      "date": "2017-11"
    }
  ]
}

