{
  "timeline": [
    {
      "headline": "Outbreak of the Eighty Years' War",
      "text": "The Eighty Years' War began in 1568 when the Dutch provinces revolted against the Spanish rule of King Philip II, driven by religious, political, and economic grievances.",
      "date": "1568"
    },
    {
      "headline": "Battle of Heiligerlee",
      "text": "On May 23, 1568, the Battle of Heiligerlee marked the first significant military engagement of the Eighty Years' War, resulting in a victory for the Dutch rebels.",
      "date": "1568-05-23"
    },
    {
      "headline": "Capture of Brielle",
      "text": "On April 1, 1572, the Sea Beggars captured the town of Brielle, an event that significantly boosted the morale of the Dutch rebels and encouraged further uprisings.",
      "date": "1572-04-01"
    },
    {
      "headline": "Pacification of Ghent",
      "text": "In 1576, the Pacification of Ghent was signed, uniting the northern and southern provinces of the Netherlands in opposition to Spanish rule.",
      "date": "1576"
    },
    {
      "headline": "Union of Utrecht",
      "text": "On January 23, 1579, the Union of Utrecht was signed, forming a defensive alliance of the northern provinces against Spanish rule, laying the foundation for the Dutch Republic.",
      "date": "1579-01-23"
    },
    {
      "headline": "Act of Abjuration",
      "text": "On July 26, 1581, the Act of Abjuration was declared, formally rejecting the rule of King Philip II and proclaiming the independence of the northern provinces.",
      "date": "1581-07-26"
    },
    {
      "headline": "Assassination of William of Orange",
      "text": "William of Orange, a key leader of the Dutch Revolt, was assassinated on July 10, 1584, in Delft, dealing a significant blow to the rebel cause.",
      "date": "1584-07-10"
    },
    {
      "headline": "Spanish Armada",
      "text": "In 1588, the Spanish Armada was launched by King Philip II to invade England, but its defeat weakened Spanish influence and indirectly aided the Dutch cause.",
      "date": "1588"
    },
    {
      "headline": "Twelve Years' Truce",
      "text": "The Twelve Years' Truce was signed in 1609, temporarily halting hostilities between the Dutch Republic and Spain, and allowing the Dutch to consolidate their independence.",
      "date": "1609"
    },
    {
      "headline": "Resumption of War",
      "text": "Hostilities resumed in 1621 after the expiration of the Twelve Years' Truce, as Spain attempted to regain control over the Dutch territories.",
      "date": "1621"
    },
    {
      "headline": "Peace of Münster",
      "text": "The Peace of Münster was signed on January 30, 1648, as part of the Treaty of Westphalia, officially ending the Eighty Years' War and recognizing the independence of the Dutch Republic.",
      "date": "1648-01-30"
    }
  ]
}

