{
  "timeline": [
    {
      "headline": "Initial Definition of the Metre",
      "text": "In 1793, the metre was initially defined in France as one ten-millionth of the distance from the equator to the North Pole along a meridian through Paris.",
      "date": "1793"
    },
    {
      "headline": "Platinum Metre Bar",
      "text": "In 1799, the metre was redefined as the length of a prototype metre bar made of platinum.",
      "date": "1799"
    },
    {
      "headline": "International Prototype Metre",
      "text": "In 1889, the first General Conference on Weights and Measures (CGPM) defined the metre as the distance between two lines on a standard bar of an alloy of platinum with 10% iridium, measured at the melting point of ice.",
      "date": "1889"
    },
    {
      "headline": "Redefinition Using Krypton-86",
      "text": "In 1960, the metre was redefined in terms of the wavelength of light emitted by the krypton-86 isotope, specifically 1,650,763.73 wavelengths of the orange-red emission line in the electromagnetic spectrum of the krypton-86 atom in a vacuum.",
      "date": "1960"
    },
    {
      "headline": "Redefinition Using Speed of Light",
      "text": "In 1983, the metre was redefined by the 17th CGPM as the distance light travels in a vacuum in 1/299,792,458 of a second, effectively fixing the speed of light in a vacuum at exactly 299,792,458 metres per second.",
      "date": "1983"
    },
    {
      "headline": "Current Definition",
      "text": "Since 2019, the metre has been defined as the length of the path travelled by light in vacuum during a time interval of 1/299,792,458 of a second, where the second is defined by a hyperfine transition frequency of caesium.",
      "date": "2019"
    }
  ]
}

