      "headline": "Establishment of the Kingdom of Greece",
      "text": "The Kingdom of Greece was established in 1832 as the successor state to the First Hellenic Republic. It was internationally recognized by the Treaty of Constantinople, securing its full independence from the Ottoman Empire after nearly four centuries.",
      "date": "1832"
    },
    {
      "headline": "Reign of King Otto",
      "text": "King Otto of Bavaria was chosen as the first king of the newly established Kingdom of Greece. His reign began in 1832 and lasted until he was deposed in 1862.",
      "date": "1832"
    },
    {
      "headline": "Deposition of King Otto",
      "text": "King Otto was deposed in 1862 due to his unpopularity and inability to effectively govern, leading to his exile.",
      "date": "1862"
    },
    {
      "headline": "Reign of King George I",
      "text": "King George I ascended to the throne in 1863, following the deposition of King Otto. His reign marked a period of modernization and territorial expansion for Greece.",
      "date": "1863"
    },
    {
      "headline": "Annexation of Thessaly and parts of Epirus",
      "text": "In 1881, Greece annexed Thessaly and parts of Epirus, expanding its territory as part of the Treaty of Berlin agreements.",
      "date": "1881"
    },
    {
      "headline": "Greco-Turkish War",
      "text": "The Greco-Turkish War of 1897 resulted in a defeat for Greece and a subsequent loss of territory, although the Great Powers intervened to prevent significant territorial losses.",
      "date": "1897"
    },
    {
      "headline": "Balkan Wars",
      "text": "During the Balkan Wars of 1912-1913, Greece expanded its territory significantly, including the acquisition of Macedonia, Epirus, and the Aegean Islands.",
      "date": "1912"
    },
    {
      "headline": "World War I and National Schism",
      "text": "Greece was divided during World War I due to the National Schism between supporters of King Constantine I and Prime Minister Eleftherios Venizelos, leading to political instability.",
      "date": "1914"
    },
    {
      "headline": "Asia Minor Catastrophe",
      "text": "In 1922, Greece suffered a major defeat in the Greco-Turkish War, leading to the Asia Minor Catastrophe and the subsequent population exchange between Greece and Turkey.",
      "date": "1922"
    },
    {
      "headline": "Abolition of the Monarchy",
      "text": "The monarchy was abolished in 1924, leading to the establishment of the Second Hellenic Republic.",
      "date": "1924"
    },
    {
      "headline": "Restoration of the Monarchy",
      "text": "The monarchy was restored in 1935 following a military coup, marking the end of the Second Hellenic Republic.",
      "date": "1935"
    },
    {
      "headline": "End of the Kingdom of Greece",
      "text": "The Kingdom of Greece officially ended in 1973 when the monarchy was abolished following a referendum, leading to the establishment of the Hellenic Republic.",
      "date": "1973"
    }
  ]
}

