    {
      "headline": "Intel adopts x86-64",
      "text": "In 2004, Intel announced it would adopt the x86-64 architecture, initially referring to it as IA-32e and later as Intel 64.",
      "date": "2004"
    },
    {
      "headline": "Introduction of Intel's first x86-64 processors",
      "text": "In 2004, Intel released its first x86-64 processors, starting with the Nocona core for the Xeon processor line.",
      "date": "2004"
    },
