      "headline": "Microsoft Windows XP Professional x64 Edition",
      "text": "In April 2005, Microsoft released Windows XP Professional x64 Edition, supporting the x86-64 architecture.",
      "date": "2005-04"
    },
    {
      "headline": "Release of Windows Server 2003 x64 Editions",
      "text": "In 2005, Microsoft released Windows Server 2003 x64 Editions, providing support for x86-64 architecture.",
      "date": "2005"
    },
    {
      "headline": "Apple transitions to x86-64",
      "text": "In 2006, Apple announced its transition to Intel processors, adopting the x86-64 architecture for its Mac computers.",
      "date": "2006"
    },
    {
      "headline": "Introduction of AMD's Ryzen processors",
      "text": "In 2017, AMD introduced the Ryzen processor line, continuing to use the x86-64 architecture.",
      "date": "2017"
    }
  ]
}

