{
  "timeline": [
    {
      "headline": "Birth of Shaka",
      "text": "Shaka was born in 1787, the illegitimate son of Senzangakhona, chief of the Zulu clan, and Nandi, of the Langeni clan.",
      "date": "1787"
    },
    {
      "headline": "Shaka's Early Life",
      "text": "During his early years, Shaka lived with his mother Nandi in her Langeni clan after being rejected by his father's family. He later joined the Mthethwa chiefdom under Dingiswayo.",
      "date": "1790"
    },
    {
      "headline": "Shaka Joins Mthethwa",
      "text": "In the early 1800s, Shaka joined the Mthethwa military under the leadership of Dingiswayo, where he began to rise through the ranks due to his military prowess.",
      "date": "1800"
    },
    {
      "headline": "Shaka Becomes Zulu Chief",
      "text": "In 1816, after the death of his father Senzangakhona, Shaka became the chief of the Zulu clan with the support of Dingiswayo.",
      "date": "1816"
    },
    {
      "headline": "Shaka's Military Reforms",
      "text": "Shaka implemented wide-reaching military reforms, including the introduction of the iklwa (a short stabbing spear) and the buffalo horn formation, transforming the Zulu army into a formidable force.",
      "date": "1817"
    },
    {
      "headline": "Expansion of the Zulu Kingdom",
      "text": "Under Shaka's leadership, the Zulu Kingdom expanded significantly, incorporating numerous neighboring tribes and becoming a dominant power in the region.",
      "date": "1818"
    },
    {
      "headline": "Death of Dingiswayo",
      "text": "In 1818, Dingiswayo, the leader of the Mthethwa and Shaka's mentor, was killed by Zwide, the chief of the Ndwandwe. Shaka avenged his death by defeating Zwide and consolidating power.",
      "date": "1818"
    },
    {
      "headline": "Battle of Gqokli Hill",
      "text": "In 1818, Shaka defeated Zwide's Ndwandwe forces at the Battle of Gqokli Hill, solidifying his control over the region.",
      "date": "1818"
    },
    {
      "headline": "Shaka's Assassination",
      "text": "On September 22, 1828, Shaka was assassinated by his half-brothers Dingane and Mhlangana, with the assistance of his bodyguard Mbopa, at Dukuza.",
      "date": "1828-09-22"
    }
  ]
}

