{
  "timeline": [
    {
      "headline": "Creation of the SEC",
      "text": "The U.S. Securities and Exchange Commission (SEC) was created by the Securities Exchange Act of 1934, following the Wall Street Crash of 1929, to restore investor confidence in the capital markets by providing investors and the markets with more reliable information and clear rules of honest dealing.",
      "date": "1934"
    },
    {
      "headline": "First Chairman of the SEC",
      "text": "Joseph P. Kennedy, Sr. was appointed as the first chairman of the SEC in 1934, serving until 1935. His appointment was part of the effort to establish the SEC as a credible and effective regulatory body.",
      "date": "1934"
    },
    {
      "headline": "Securities Act of 1933",
      "text": "The Securities Act of 1933 was enacted prior to the establishment of the SEC, requiring that investors receive financial and other significant information concerning securities being offered for public sale, and prohibiting deceit, misrepresentations, and other fraud in the sale of securities.",
      "date": "1933"
    },
    {
      "headline": "Securities Exchange Act of 1934",
      "text": "The Securities Exchange Act of 1934 was enacted to govern securities transactions on the secondary market, after issue, ensuring greater financial transparency and accuracy and less fraud or manipulation.",
      "date": "1934"
    },
    {
      "headline": "Public Utility Holding Company Act of 1935",
      "text": "The Public Utility Holding Company Act of 1935 was passed to facilitate the regulation of electric utilities by either limiting their operations to a single state or forcing divestitures to simplify their structures.",
      "date": "1935"
    },
    {
      "headline": "Investment Company Act of 1940",
      "text": "The Investment Company Act of 1940 was enacted to regulate the organization of investment companies and the activities they engage in, primarily focusing on mutual funds.",
      "date": "1940"
    },
    {
      "headline": "Investment Advisers Act of 1940",
      "text": "The Investment Advisers Act of 1940 was established to regulate the actions and activities of investment advisers, requiring them to register with the SEC and adhere to regulations designed to protect investors.",
      "date": "1940"
    },
    {
      "headline": "Sarbanes-Oxley Act of 2002",
      "text": "In response to major corporate and accounting scandals, the Sarbanes-Oxley Act of 2002 was enacted to protect investors from fraudulent financial reporting by corporations, enhancing the SEC's role in overseeing corporate governance.",
      "date": "2002"
    },
    {
      "headline": "Dodd-Frank Act of 2010",
      "text": "The Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 was passed to promote the financial stability of the United States by improving accountability and transparency in the financial system, and to protect consumers from abusive financial services practices.",
      "date": "2010"
    }
  ]
}

