{
  "timeline": [
    {
      "headline": "Dred Scott Files Lawsuit",
      "text": "In 1846, Dred Scott, an enslaved African American man, filed a lawsuit in Missouri for his freedom, claiming that his residence in free territories made him a free man.",
      "date": "1846"
    },
    {
      "headline": "Missouri Supreme Court Decision",
      "text": "In 1852, the Missouri Supreme Court reversed a lower court's decision that had declared Dred Scott free, ruling that he remained a slave.",
      "date": "1852"
    },
    {
      "headline": "Dred Scott v. Sandford Case Begins",
      "text": "In 1853, Dred Scott filed a federal lawsuit against John F.A. Sandford, his owner's brother, which eventually reached the U.S. Supreme Court.",
      "date": "1853"
    },
    {
      "headline": "Supreme Court Decision",
      "text": "On March 6, 1857, the U.S. Supreme Court delivered its decision in Dred Scott v. Sandford, ruling that African Americans, whether enslaved or free, could not be American citizens and therefore had no standing to sue in federal court.",
      "date": "1857-03-06"
    },
    {
      "headline": "Impact on American Civil War",
      "text": "The Dred Scott decision intensified national divisions over slavery and is considered a contributing factor to the outbreak of the American Civil War in 1861.",
      "date": "1861"
    },
    {
      "headline": "Dred Scott Gains Freedom",
      "text": "In May 1857, shortly after the Supreme Court decision, Dred Scott and his family were freed by their owners, the Blow family, who had originally sold Scott.",
      "date": "1857-05"
    },
    {
      "headline": "Death of Dred Scott",
      "text": "Dred Scott died of tuberculosis on September 17, 1858, in St. Louis, Missouri.",
      "date": "1858-09-17"
    }
  ]
}

