    {
      "headline": "French Occupation",
      "text": "In 1795, under the Treaty of Basel, Spain ceded Santo Domingo to France, marking the beginning of French occupation.",
      "date": "1795"
    },
    {
      "headline": "Return to Spanish Rule",
      "text": "Santo Domingo returned to Spanish rule in 1809 after the Spanish reconquest.",
      "date": "1809"
    },
    {
      "headline": "Independence from Haiti",
      "text": "On February 27, 1844, Santo Domingo became the capital of the newly independent Dominican Republic after gaining independence from Haiti.",
      "date": "1844-02-27"
    },
    {
      "headline": "U.S. Occupation",
      "text": "The United States occupied Santo Domingo from 1916 to 1924.",
      "date": "1916"
    },
    {
      "headline": "Renaming to Ciudad Trujillo",
      "text": "In 1936, the city was renamed Ciudad Trujillo in honor of the dictator Rafael Trujillo.",
      "date": "1936"
