{
  "timeline": [
    {
      "headline": "Birth of Ernest Rutherford",
      "text": "Ernest Rutherford was born on August 30, 1871, in Brightwater, New Zealand.",
      "date": "1871-08-30"
    },
    {
      "headline": "Education at Canterbury College",
      "text": "In 1890, Rutherford began his studies at Canterbury College, University of New Zealand, where he earned a Bachelor of Arts, Master of Arts, and Bachelor of Science.",
      "date": "1890"
    },
    {
      "headline": "Move to Cambridge University",
      "text": "In 1895, Rutherford moved to England to study at the Cavendish Laboratory, University of Cambridge, under J.J. Thomson.",
      "date": "1895"
    },
    {
      "headline": "Appointment at McGill University",
      "text": "In 1898, Rutherford was appointed to a professorship at McGill University in Montreal, Canada.",
      "date": "1898"
    },
    {
      "headline": "Discovery of the concept of radioactive half-life",
      "text": "In 1900, Rutherford discovered the concept of radioactive half-life and differentiated alpha and beta radiation.",
      "date": "1900"
    },
    {
      "headline": "Nobel Prize in Chemistry",
      "text": "In 1908, Rutherford was awarded the Nobel Prize in Chemistry for his investigations into the disintegration of the elements and the chemistry of radioactive substances.",
      "date": "1908"
    },
    {
      "headline": "Gold foil experiment",
      "text": "In 1909, Rutherford conducted the gold foil experiment, leading to the discovery of the atomic nucleus.",
      "date": "1909"
    },
    {
      "headline": "Return to England",
      "text": "In 1907, Rutherford returned to England to become the Langworthy Professor of Physics at the University of Manchester.",
      "date": "1907"
    },
    {
      "headline": "Rutherford model of the atom",
      "text": "In 1911, Rutherford proposed the Rutherford model of the atom, describing a small, dense nucleus surrounded by orbiting electrons.",
      "date": "1911"
    },
    {
      "headline": "Director of the Cavendish Laboratory",
      "text": "In 1919, Rutherford became the Director of the Cavendish Laboratory at the University of Cambridge.",
      "date": "1919"
    },
    {
      "headline": "First artificial nuclear reaction",
      "text": "In 1917, Rutherford achieved the first artificial nuclear reaction by converting nitrogen into oxygen.",
      "date": "1917"
    },
    {
      "headline": "Creation of the element 'rutherfordium'",
      "text": "In 1997, the element with atomic number 104 was named 'rutherfordium' in his honor.",
      "date": "1997"
    },
    {
      "headline": "Death of Ernest Rutherford",
      "text": "Ernest Rutherford died on October 19, 1937, in Cambridge, England.",
      "date": "1937-10-19"
    }
  ]
}

