{
  "timeline": [
    {
      "headline": "Discovery of Cathode Rays",
      "text": "In the late 19th century, scientists discovered cathode rays, which are streams of electrons observed in vacuum tubes. This discovery laid the foundation for the development of the cathode-ray tube.",
      "date": "1800"
    },
    {
      "headline": "Invention of the Cathode-Ray Tube",
      "text": "The cathode-ray tube was invented by German physicist Karl Ferdinand Braun in 1897. He developed the first CRT with a fluorescent screen, which was used to display electrical waveforms.",
      "date": "1897"
    },
    {
      "headline": "Development of the Oscilloscope",
      "text": "In the early 20th century, CRTs were used in oscilloscopes, which are instruments that graphically display varying signal voltages, typically as a two-dimensional plot of one or more signals as a function of time.",
      "date": "1920"
    },
    {
      "headline": "Introduction of CRT Television",
      "text": "The first commercially made CRT television sets were produced in the 1930s. These early televisions used CRT technology to display moving images.",
      "date": "1930"
    },
    {
      "headline": "Widespread Use in Television",
      "text": "By the 1950s, CRTs became the standard technology for television displays, providing the main method for viewing broadcast television.",
      "date": "1950"
    },
    {
      "headline": "CRTs in Computer Monitors",
      "text": "In the 1970s and 1980s, CRTs were widely adopted for use in computer monitors, allowing for the display of digital raster graphics.",
      "date": "1970"
    },
    {
      "headline": "Decline of CRT Technology",
      "text": "Starting in the late 1990s and early 2000s, CRT technology began to decline with the advent of flat-panel display technologies such as LCD, LED, and plasma screens, which offered lighter and thinner alternatives.",
      "date": "2000"
    },
    {
      "headline": "End of CRT Production",
      "text": "By the 2010s, most major electronics manufacturers had ceased production of CRTs, marking the end of an era for this technology.",
      "date": "2010"
    }
  ]
}

