{
  "timeline": [
    {
      "headline": "Beginnings of Cubism",
      "text": "Cubism began in Paris in the early 20th century, with its roots traced back to 1907 when Pablo Picasso painted 'Les Demoiselles d'Avignon'. This painting is considered a precursor to the Cubist movement.",
      "date": "1907"
    },
    {
      "headline": "First Phase: Analytic Cubism",
      "text": "Between 1908 and 1912, the first phase of Cubism, known as Analytic Cubism, developed. Artists like Pablo Picasso and Georges Braque fragmented objects into geometric shapes and used monochromatic color palettes.",
      "date": "1908"
    },
    {
      "headline": "Introduction of the Term 'Cubism'",
      "text": "The term 'Cubism' was first used in 1908 by the critic Louis Vauxcelles after seeing Braque's landscapes in the exhibition at the Kahnweiler Gallery.",
      "date": "1908"
    },
    {
      "headline": "Second Phase: Synthetic Cubism",
      "text": "From 1912 onwards, Synthetic Cubism emerged, characterized by simpler shapes, brighter colors, and the introduction of mixed media and collage elements.",
      "date": "1912"
    },
    {
      "headline": "Salon Cubists",
      "text": "In 1911, a group of artists known as the Salon Cubists, including Jean Metzinger, Albert Gleizes, and Fernand Léger, exhibited their works at the Salon des Indépendants and the Salon d'Automne, further popularizing Cubism.",
      "date": "1911"
    },
    {
      "headline": "Publication of 'Du Cubisme'",
      "text": "In 1912, Jean Metzinger and Albert Gleizes published 'Du Cubisme', the first major theoretical text on Cubism, explaining the movement's principles and aesthetics.",
      "date": "1912"
    },
    {
      "headline": "Impact on Other Art Forms",
      "text": "Throughout the 1910s and 1920s, Cubism influenced various art forms, including music, ballet, literature, and architecture, marking its significance as a revolutionary movement.",
      "date": "1910"
    },
    {
      "headline": "Cubism's Influence on Architecture",
      "text": "Cubism influenced architecture during the 1920s, notably seen in the works of architects like Le Corbusier, who incorporated geometric forms and abstract concepts.",
      "date": "1920"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of John Money",
      "text": "John William Money was born on July 8, 1921, in Morrinsville, New Zealand.",
      "date": "1921-07-08"
    },
    {
      "headline": "Education and Early Career",
      "text": "John Money completed his undergraduate studies at Victoria University of Wellington in New Zealand, where he earned a bachelor's degree in psychology in 1944.",
      "date": "1944"
    },
    {
      "headline": "Move to the United States",
      "text": "In 1947, John Money moved to the United States to pursue further studies.",
      "date": "1947"
    },
    {
      "headline": "Doctorate in Psychology",
      "text": "John Money received his Ph.D. in psychology from Harvard University in 1952.",
      "date": "1952"
    },
    {
      "headline": "Joining Johns Hopkins University",
      "text": "In 1951, John Money joined the faculty at Johns Hopkins University, where he would conduct much of his influential research.",
      "date": "1951"
    },
    {
      "headline": "Introduction of Gender Identity Theory",
      "text": "In the 1950s and 1960s, John Money introduced the concept of gender identity and argued that it was malleable in early childhood.",
      "date": "1950"
    },
    {
      "headline": "Publication of 'Man & Woman, Boy & Girl'",
      "text": "In 1972, John Money published 'Man & Woman, Boy & Girl', a book that further explored his theories on gender identity and sexual differentiation.",
      "date": "1972"
    },
    {
      "headline": "Controversy over the John/Joan Case",
      "text": "In the late 1990s, controversy arose over John Money's involvement in the John/Joan case, where he advised gender reassignment for a boy whose circumcision was botched. The case later became a significant point of criticism against Money's theories.",
      "date": "1997"
    },
    {
      "headline": "Death of John Money",
      "text": "John Money passed away on July 7, 2006, in Towson, Maryland, United States.",
      "date": "2006-07-07"
    }
  ]
}

