{
  "timeline": [
    {
      "headline": "Outbreak of World War I",
      "text": "The Western Front was established following the outbreak of World War I in August 1914. The Imperial German Army invaded Luxembourg and Belgium, marking the beginning of the Western Front.",
      "date": "1914-08"
    },
    {
      "headline": "Battle of the Marne",
      "text": "The German advance was halted with the Battle of the Marne, which took place from September 6 to September 12, 1914. This battle effectively ended the German offensive that had threatened Paris.",
      "date": "1914-09-06"
    },
    {
      "headline": "Race to the Sea",
      "text": "Following the Battle of the Marne, both sides engaged in the 'Race to the Sea' from September to October 1914, attempting to outflank each other, which resulted in the establishment of a continuous line of trenches from the North Sea to the Swiss frontier.",
      "date": "1914-09"
    },
    {
      "headline": "Trench Warfare Begins",
      "text": "By the end of 1914, both sides had dug in along a meandering line of fortified trenches, stretching from the North Sea to the Swiss frontier with France. This marked the beginning of trench warfare on the Western Front.",
      "date": "1914"
    },
    {
      "headline": "Battle of Verdun",
      "text": "The Battle of Verdun was one of the largest and longest battles on the Western Front, lasting from February 21 to December 18, 1916. It resulted in heavy casualties on both sides.",
      "date": "1916-02-21"
    },
    {
      "headline": "Battle of the Somme",
      "text": "The Battle of the Somme was a major battle on the Western Front, taking place from July 1 to November 18, 1916. It was one of the bloodiest battles in human history.",
      "date": "1916-07-01"
    },
    {
      "headline": "German Spring Offensive",
      "text": "In early 1918, the German Army launched the Spring Offensive, a series of attacks along the Western Front, aiming to defeat the Allies before American forces could fully deploy.",
      "date": "1918-03"
    },
    {
      "headline": "Allied Hundred Days Offensive",
      "text": "The Allied Hundred Days Offensive began on August 8, 1918, and marked a series of successful Allied attacks that eventually led to the end of World War I.",
      "date": "1918-08-08"
    },
    {
      "headline": "Armistice of Compiègne",
      "text": "The Armistice of Compiègne was signed on November 11, 1918, ending fighting on the Western Front and marking the end of World War I.",
      "date": "1918-11-11"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Establishment of the Library of Congress",
      "text": "The Library of Congress was established on April 24, 1800, when President John Adams signed an act of Congress providing for the transfer of the seat of government from Philadelphia to the new capital city of Washington. The legislation appropriated $5,000 \"for the purchase of such books as may be necessary for the use of Congress.\"",
      "date": "1800-04-24"
    },
    {
      "headline": "First Library Collection",
      "text": "In 1801, the first books were ordered for the Library of Congress. The initial collection consisted of 740 books and three maps.",
      "date": "1801"
    },
    {
      "headline": "Destruction of the Library",
      "text": "On August 24, 1814, during the War of 1812, the British burned the Capitol building, and the Library of Congress's collection of 3,000 volumes was destroyed.",
      "date": "1814-08-24"
    },
    {
      "headline": "Thomas Jefferson's Library",
      "text": "In 1815, former President Thomas Jefferson sold his personal library of 6,487 books to the Library of Congress to replace the collection destroyed by the British.",
      "date": "1815"
    },
    {
      "headline": "Expansion of the Library",
      "text": "In 1851, a fire destroyed two-thirds of the Library's 55,000 volumes, including two-thirds of Jefferson's original collection. This led to a significant expansion and rebuilding effort.",
      "date": "1851"
    },
    {
      "headline": "Opening of the Thomas Jefferson Building",
      "text": "The Thomas Jefferson Building, the first purpose-built Library of Congress building, opened to the public on November 1, 1897.",
      "date": "1897-11-01"
    },
    {
      "headline": "Creation of the Copyright Office",
      "text": "In 1897, the Library of Congress was given responsibility for administering the United States Copyright Office, further solidifying its role as a national library.",
      "date": "1897"
    },
    {
      "headline": "Acquisition of the Gutenberg Bible",
      "text": "In 1930, the Library of Congress acquired one of the few surviving copies of the Gutenberg Bible, a significant addition to its collection.",
      "date": "1930"
    },
    {
      "headline": "Opening of the John Adams Building",
      "text": "The John Adams Building, the second Library of Congress building, was opened in 1939 to accommodate the growing collections.",
      "date": "1939"
    },
    {
      "headline": "Opening of the James Madison Memorial Building",
      "text": "The James Madison Memorial Building, the third Library of Congress building, was completed in 1980, providing additional space for the Library's expanding collections and services.",
      "date": "1980"
    }
  ]
}

