{
  "timeline": [
    {
      "headline": "First Mention of Hanover",
      "text": "Hanover was first mentioned in historical records in 1150 as a small village on the high bank of the River Leine.",
      "date": "1150"
    },
    {
      "headline": "Hanover Becomes a City",
      "text": "In 1241, Hanover was granted city status, marking its development as a significant settlement.",
      "date": "1241"
    },
    {
      "headline": "Hanover Joins the Hanseatic League",
      "text": "In 1386, Hanover became a member of the Hanseatic League, a powerful economic and defensive alliance of merchant guilds and market towns in Northwestern and Central Europe.",
      "date": "1386"
    },
    {
      "headline": "Hanover Becomes a Principality",
      "text": "In 1636, Hanover became the capital of the Principality of Calenberg, a subdivision of the Duchy of Brunswick-Lüneburg.",
      "date": "1636"
    },
    {
      "headline": "Electorate of Hanover Established",
      "text": "In 1692, the Electorate of Hanover was established, elevating the region's political status within the Holy Roman Empire.",
      "date": "1692"
    },
    {
      "headline": "Hanoverian Succession to the British Throne",
      "text": "In 1714, George I of Hanover became King of Great Britain, initiating the personal union between Britain and Hanover.",
      "date": "1714"
    },
    {
      "headline": "Hanover Occupied by Napoleon",
      "text": "In 1803, Hanover was occupied by French troops under Napoleon, disrupting the personal union with Britain.",
      "date": "1803"
    },
    {
      "headline": "Kingdom of Hanover Established",
      "text": "In 1814, following the defeat of Napoleon, the Congress of Vienna elevated Hanover to a kingdom.",
      "date": "1814"
    },
    {
      "headline": "Annexation by Prussia",
      "text": "In 1866, after the Austro-Prussian War, Hanover was annexed by Prussia and became a province.",
      "date": "1866"
    },
    {
      "headline": "Hanover Becomes Part of Lower Saxony",
      "text": "In 1946, after World War II, Hanover became part of the newly formed state of Lower Saxony in West Germany.",
      "date": "1946"
    },
    {
      "headline": "Expo 2000",
      "text": "In 2000, Hanover hosted the Expo 2000, the first world exposition held in Germany, attracting millions of visitors.",
      "date": "2000"
    }
  ]
}

