      "headline": "Founding of Harbin",
      "text": "Harbin was originally a small village in the Manchu region. It began to develop significantly in the late 19th century when the Russians built the Chinese Eastern Railway in the area.",
      "date": "1898"
    },
    {
      "headline": "Russian Influence",
      "text": "In 1898, Harbin became a major center for Russian immigrants and influence due to the construction of the Chinese Eastern Railway by Russia.",
      "date": "1898"
    },
    {
      "headline": "Harbin as a Refuge for White Russians",
      "text": "Following the Russian Revolution in 1917, Harbin became a refuge for White Russians fleeing the Bolsheviks.",
      "date": "1917"
    },
    {
      "headline": "Japanese Occupation",
      "text": "Harbin was occupied by Japanese forces during the Second Sino-Japanese War, starting in 1932, and became part of the puppet state of Manchukuo.",
      "date": "1932"
    },
    {
      "headline": "Soviet Liberation",
      "text": "In 1945, Harbin was liberated by Soviet forces at the end of World War II.",
      "date": "1945"
    },
    {
      "headline": "Incorporation into the People's Republic of China",
      "text": "After the establishment of the People's Republic of China in 1949, Harbin was incorporated into the new state and became the capital of Heilongjiang Province.",
      "date": "1949"
    },
    {
      "headline": "Harbin Ice Festival",
      "text": "The Harbin International Ice and Snow Sculpture Festival was first held in 1985, becoming an annual event and one of the largest ice festivals in the world.",
      "date": "1985"
    },
    {
      "headline": "Population Growth",
      "text": "According to the 2020 census, Harbin's metropolitan population reached over 10 million, making it one of the 100 largest urban areas in the world.",
      "date": "2020"
    }
  ]
}

