    },
    {
      "headline": "Zagreus as Orphic Dionysus",
      "text": "Zagreus is identified with an Orphic Dionysus, a son of Zeus and Persephone, who was dismembered by the Titans and reborn, reflecting themes of death and rebirth.",
      "date": "-0400"
    },
    {
      "headline": "Zagreus' Parentage",
      "text": "Timothy Gantz postulates that Zagreus, originally the son of Hades and Persephone, later merged with the Orphic Dionysus, the son of Zeus and Persephone, illustrating the fluidity of mythological identities.",
      "date": "-0300"
    }
  ]
}

