    },
    {
      "headline": "Easter Rising Participation",
      "text": "Éamon de Valera participated in the Easter Rising, a rebellion against British rule in Ireland, which took place from April 24 to April 29, 1916.",
      "date": "1916-04-24"
    },
    {
      "headline": "Imprisonment and Release",
      "text": "Following the Easter Rising, de Valera was imprisoned but was released in June 1917.",
      "date": "1917-06"
    },
    {
      "headline": "Elected President of Sinn Féin",
      "text": "In October 1917, Éamon de Valera was elected President of Sinn Féin, a political party advocating for Irish independence.",
      "date": "1917-10"
    },
    {
      "headline": "Elected President of Dáil Éireann",
      "text": "Éamon de Valera was elected President of Dáil Éireann, the revolutionary parliament of the Irish Republic, in April 1919.",
      "date": "1919-04"
    },
    {
      "headline": "Anglo-Irish Treaty Opposition",
      "text": "In 1921, Éamon de Valera opposed the Anglo-Irish Treaty, which led to the partition of Ireland and the establishment of the Irish Free State.",
      "date": "1921"
    },
    {
      "headline": "Formation of Fianna Fáil",
      "text": "In 1926, Éamon de Valera founded Fianna Fáil, a new political party in Ireland.",
      "date": "1926"
    },
    {
      "headline": "Becomes President of the Executive Council",
      "text": "Éamon de Valera became President of the Executive Council of the Irish Free State on March 9, 1932.",
      "date": "1932-03-09"
    },
    {
      "headline": "Introduction of the 1937 Constitution",
      "text": "Éamon de Valera played a leading role in introducing the 1937 Constitution of Ireland, which came into effect on December 29, 1937.",
      "date": "1937-12-29"
    },
    {
      "headline": "Becomes Taoiseach",
      "text": "Éamon de Valera served as Taoiseach, the head of government in Ireland, from 1937 to 1948, and again from 1951 to 1954, and from 1957 to 1959.",
      "date": "1937"
    },
    {
      "headline": "Elected President of Ireland",
      "text": "Éamon de Valera was elected as the President of Ireland in 1959 and served until 1973.",
      "date": "1959"
    },
    {
      "headline": "Retirement from Politics",
      "text": "Éamon de Valera retired from politics in 1973 after serving two terms as President of Ireland.",
      "date": "1973"
    },
    {
      "headline": "Death of Éamon de Valera",
      "text": "Éamon de Valera passed away on August 29, 1975, in Dublin, Ireland.",
      "date": "1975-08-29"
    }
  ]
}

