{
  "timeline": [
    {
      "headline": "Establishment of the Zhou Dynasty",
      "text": "The Zhou dynasty was established around 1046 BC, marking the beginning of the longest-lasting dynasty in Chinese history. This date is supported by the Xia–Shang–Zhou Chronology Project and David Pankenier.",
      "date": "-1046"
    },
    {
      "headline": "Battle of Muye",
      "text": "In 1046 BC, the Zhou dynasty, under King Wu, defeated the Shang dynasty at the Battle of Muye, leading to the fall of the Shang and the establishment of Zhou rule.",
      "date": "-1046"
    },
    {
      "headline": "Reign of King Wu of Zhou",
      "text": "King Wu of Zhou reigned from 1046 BC until his death in 1043 BC. He was the first king of the Zhou dynasty and played a crucial role in its establishment.",
      "date": "-1046"
    },
    {
      "headline": "Reign of King Cheng of Zhou",
      "text": "King Cheng of Zhou reigned from 1042 BC to 1021 BC. He was the second king of the Zhou dynasty and consolidated the dynasty's power.",
      "date": "-1042"
    },
    {
      "headline": "Western Zhou Period",
      "text": "The Western Zhou period lasted from 1046 BC to 771 BC. During this time, the Zhou dynasty had military control over ancient China and established a feudal system.",
      "date": "-1046"
    },
    {
      "headline": "Eastern Zhou Period",
      "text": "The Eastern Zhou period began in 770 BC and lasted until 256 BC. This period was marked by the decline of Zhou royal power and the rise of regional states.",
      "date": "-0770"
    },
    {
      "headline": "Spring and Autumn Period",
      "text": "The Spring and Autumn period, part of the Eastern Zhou, lasted from 770 BC to 476 BC. It was characterized by the fragmentation of power and the rise of influential regional leaders.",
      "date": "-0770"
    },
    {
      "headline": "Warring States Period",
      "text": "The Warring States period, also part of the Eastern Zhou, lasted from 475 BC to 221 BC. It was marked by intense warfare among the states and the eventual rise of the Qin state.",
      "date": "-0475"
    },
    {
      "headline": "End of the Zhou Dynasty",
      "text": "The Zhou dynasty came to an end in 256 BC when the last Zhou king was deposed by the Qin state, marking the end of the dynasty's rule.",
      "date": "-0256"
    }
  ]
}

