    {
      "headline": "ILOVEYOU Worm Released",
      "text": "On 2000-05-05, the ILOVEYOU computer worm began spreading rapidly across the globe. It was sent as an email with the subject line 'ILOVEYOU' and an attachment named 'LOVE-LETTER-FOR-YOU.TXT.vbs'.",
      "date": "2000-05-05"
    },
    {
      "headline": "Global Impact of ILOVEYOU",
      "text": "Within days of its release on 2000-05-05, the ILOVEYOU worm infected over ten million Windows personal computers worldwide, causing widespread disruption.",
      "date": "2000-05-05"
    },
    {
      "headline": "Technical Mechanism of ILOVEYOU",
      "text": "The worm exploited the fact that Windows computers often hid file extensions, leading users to believe the attachment was a harmless text file. Upon opening, the Visual Basic script was activated, overwriting random files and spreading to contacts in the user's address book.",
      "date": "2000-05-05"
    },
    {
      "headline": "Response to ILOVEYOU",
      "text": "Following the outbreak on 2000-05-05, companies and governments around the world took measures to contain the worm, including shutting down email systems and implementing stricter email security protocols.",
      "date": "2000-05-05"
    },
    {
      "headline": "Identification of the Creator",
      "text": "In May 2000, authorities identified Onel de Guzman, a student from the Philippines, as a suspect in the creation of the ILOVEYOU worm. However, due to the lack of specific cybercrime laws in the Philippines at the time, he was not prosecuted.",
      "date": "2000-05"
    }
  ]
}

