{
  "timeline": [
    {
      "headline": "Origins of Opera",
      "text": "Opera originated in Italy at the end of the 16th century, with Jacopo Peri's lost 'Dafne' produced in Florence in 1598.",
      "date": "1598"
    },
    {
      "headline": "First Surviving Opera",
      "text": "The first opera for which music has survived is 'Euridice' by Jacopo Peri, which premiered in Florence in 1600.",
      "date": "1600"
    },
    {
      "headline": "Monteverdi's 'L'Orfeo'",
      "text": "Claudio Monteverdi's 'L'Orfeo', premiered in Mantua in 1607, is one of the earliest operas still regularly performed today.",
      "date": "1607"
    },
    {
      "headline": "Establishment of Public Opera Houses",
      "text": "The first public opera house, Teatro San Cassiano, opened in Venice in 1637, making opera accessible to a wider audience.",
      "date": "1637"
    },
    {
      "headline": "French Opera Development",
      "text": "Jean-Baptiste Lully established French opera with 'Cadmus et Hermione' in 1673, incorporating ballet and French classical drama.",
      "date": "1673"
    },
    {
      "headline": "Birth of Opera Seria",
      "text": "Opera seria, a noble and serious style of Italian opera, was developed in the early 18th century, with composers like Alessandro Scarlatti.",
      "date": "1700"
    },
    {
      "headline": "Handel's Influence in England",
      "text": "George Frideric Handel became a dominant figure in English opera with works like 'Rinaldo' in 1711.",
      "date": "1711"
    },
    {
      "headline": "Mozart's Contribution",
      "text": "Wolfgang Amadeus Mozart's operas, including 'The Marriage of Figaro' (1786), 'Don Giovanni' (1787), and 'The Magic Flute' (1791), are central to the opera repertoire.",
      "date": "1786"
    },
    {
      "headline": "Bel Canto Era",
      "text": "The early 19th century saw the rise of the bel canto style, with composers like Rossini, Bellini, and Donizetti.",
      "date": "1800"
    },
    {
      "headline": "Verdi's Dominance",
      "text": "Giuseppe Verdi became a leading opera composer with works like 'Rigoletto' (1851), 'Il trovatore' (1853), and 'La traviata' (1853).",
      "date": "1851"
    },
    {
      "headline": "Wagner's Innovations",
      "text": "Richard Wagner revolutionized opera with his concept of Gesamtkunstwerk and works like 'The Ring Cycle' (completed in 1874).",
      "date": "1874"
    },
    {
      "headline": "Puccini's Masterpieces",
      "text": "Giacomo Puccini became famous for operas such as 'La Bohème' (1896), 'Tosca' (1900), and 'Madama Butterfly' (1904).",
      "date": "1896"
    },
    {
      "headline": "20th Century and Beyond",
      "text": "The 20th century saw diverse developments in opera, with composers like Richard Strauss, Benjamin Britten, and Philip Glass expanding the form.",
      "date": "1900"
    }
  ]
}

