{
  "timeline": [
    {
      "headline": "Birth of Chandra Shekhar Azad",
      "text": "Chandra Shekhar Azad was born on 23 July 1906 in Bardarka village, Unnao district, United Provinces. His parents were Sitaram Tiwari and Jagrani Devi.",
      "date": "1906-07-23"
    },
    {
      "headline": "Jallianwala Bagh Massacre Influence",
      "text": "The Jallianwala Bagh massacre in 1919 deeply influenced Chandra Shekhar Azad, leading him to join the Indian independence movement.",
      "date": "1919"
    },
    {
      "headline": "Joining the Non-Cooperation Movement",
      "text": "In 1921, Chandra Shekhar Azad joined the Non-Cooperation Movement led by Mahatma Gandhi, marking his entry into active politics.",
      "date": "1921"
    },
    {
      "headline": "Arrest and Pseudonym 'Azad'",
      "text": "Chandra Shekhar was arrested for his involvement in revolutionary activities and, upon being asked his name, he famously declared 'Azad' (meaning free) in 1921.",
      "date": "1921"
    },
    {
      "headline": "Reorganization of Hindustan Republican Association",
      "text": "After the execution of Ram Prasad Bismil and others in 1927, Azad reorganized the Hindustan Republican Association (HRA) into the Hindustan Socialist Republican Association (HSRA).",
      "date": "1928"
    },
    {
      "headline": "Kakori Train Robbery",
      "text": "Azad was involved in the Kakori Train Robbery on 9 August 1925, a significant event in the Indian independence movement.",
      "date": "1925-08-09"
    },
    {
      "headline": "Death of Chandra Shekhar Azad",
      "text": "Chandra Shekhar Azad died on 27 February 1931 in Alfred Park, Allahabad, during a shootout with the police. He shot himself to avoid capture.",
      "date": "1931-02-27"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Early Settlement",
      "text": "The Tajiks are believed to have settled in Central Asia as early as the 4th century BCE, with their ancestors being part of the Eastern Iranian tribes.",
      "date": "-0400"
    },
    {
      "headline": "Samanid Empire",
      "text": "The Samanid Empire (819–999 CE) was a Persian empire that is considered the first Tajik state. It played a significant role in the revival of Persian culture and language.",
      "date": "0819"
    },
    {
      "headline": "Ghaznavid Dynasty",
      "text": "The Ghaznavid Dynasty (977–1186 CE) was a Persianate Muslim dynasty of Turkic mamluk origin, which ruled large parts of Persia and the Indian subcontinent. The Tajiks were an integral part of this empire.",
      "date": "0977"
    },
    {
      "headline": "Mongol Invasion",
      "text": "The Mongol invasion of Central Asia in the 13th century led to significant changes in the region, impacting the Tajik population and culture.",
      "date": "1220"
    },
    {
      "headline": "Timurid Empire",
      "text": "The Timurid Empire (1370–1507 CE) was a Persianate empire that emerged after the Mongol invasions, with the Tajiks contributing to its cultural and scientific achievements.",
      "date": "1370"
    },
    {
      "headline": "Russian Empire Expansion",
      "text": "In the 19th century, the Russian Empire expanded into Central Asia, incorporating Tajik territories into its domain.",
      "date": "1860"
    },
    {
      "headline": "Soviet Era",
      "text": "During the Soviet era (1917–1991), Tajikistan became a Soviet Socialist Republic, and the Tajik identity was shaped by Soviet policies.",
      "date": "1917"
    },
    {
      "headline": "Independence of Tajikistan",
      "text": "Tajikistan declared independence from the Soviet Union on September 9, 1991, becoming a sovereign nation.",
      "date": "1991-09-09"
    },
    {
      "headline": "Tajik Civil War",
      "text": "The Tajik Civil War (1992–1997) was a conflict that erupted shortly after independence, involving various factions and resulting in significant loss of life and displacement.",
      "date": "1992"
    },
    {
      "headline": "Peace Agreement",
      "text": "The Tajik Civil War ended with a peace agreement in 1997, leading to a period of reconstruction and political stabilization.",
      "date": "1997"
    }
  ]
}

