    {
      "headline": "Founding of St. Augustine",
      "text": "St. Augustine was founded on September 8, 1565, by Spanish admiral Pedro Menéndez de Avilés, making it the oldest continuously inhabited European-established settlement in the contiguous United States.",
      "date": "1565-09-08"
    },
    {
      "headline": "Attack by Sir Francis Drake",
      "text": "In 1586, English privateer Sir Francis Drake attacked and burned St. Augustine during his expedition against Spanish settlements in the Americas.",
      "date": "1586"
    },
    {
      "headline": "Construction of Castillo de San Marcos",
      "text": "Construction of the Castillo de San Marcos, a masonry fort, began in 1672 to protect the city from pirate raids and other threats.",
      "date": "1672"
    },
    {
      "headline": "Completion of Castillo de San Marcos",
      "text": "The Castillo de San Marcos was completed in 1695, providing a strong defensive structure for the city.",
      "date": "1695"
    },
    {
      "headline": "Transfer to British Control",
      "text": "In 1763, as part of the Treaty of Paris, Spain ceded Florida to Britain, and St. Augustine came under British control.",
      "date": "1763"
    },
    {
      "headline": "Return to Spanish Control",
      "text": "In 1783, the Treaty of Paris ended the American Revolutionary War, and Florida was returned to Spanish control.",
      "date": "1783"
    },
    {
      "headline": "Acquisition by the United States",
      "text": "In 1821, Florida was ceded to the United States by Spain as part of the Adams-Onís Treaty.",
      "date": "1821"
    },
    {
      "headline": "Civil Rights Movement",
      "text": "In the 1960s, St. Augustine was a significant site for civil rights demonstrations, including efforts led by Dr. Martin Luther King Jr. and the Southern Christian Leadership Conference.",
      "date": "1960s"
    }
  ]
}

