{
  "timeline": [
    {
      "headline": "Proto-Slavic Language Development",
      "text": "Proto-Slavic, the common ancestor of all Slavic languages, began to develop during the Early Middle Ages. It is thought to have descended from the earlier Proto-Balto-Slavic language.",
      "date": "0500"
    },
    {
      "headline": "Slavic Migration and Expansion",
      "text": "Between the 5th and 10th centuries, Slavic tribes migrated and expanded across Eastern Europe, leading to the diversification of the Proto-Slavic language into distinct Slavic languages.",
      "date": "0500-1000"
    },
    {
      "headline": "Old Church Slavonic",
      "text": "Old Church Slavonic, the first literary Slavic language, was developed by Saints Cyril and Methodius in the 9th century for the purpose of translating the Bible and other texts for the Slavic peoples.",
      "date": "0863"
    },
    {
      "headline": "Division into East, West, and South Slavic Languages",
      "text": "By the 10th century, the Slavic languages had diverged into three main branches: East Slavic, West Slavic, and South Slavic.",
      "date": "1000"
    },
    {
      "headline": "Development of Cyrillic and Glagolitic Alphabets",
      "text": "The Cyrillic and Glagolitic alphabets were developed in the 9th and 10th centuries to write Slavic languages, with Cyrillic eventually becoming the dominant script for many Slavic languages.",
      "date": "0900-1000"
    },
    {
      "headline": "Influence of the Mongol Invasion",
      "text": "The Mongol invasion of Eastern Europe in the 13th century had a significant impact on the development of the East Slavic languages, particularly Russian.",
      "date": "1200-1300"
    },
    {
      "headline": "Standardization of Slavic Languages",
      "text": "From the 18th century onwards, various Slavic languages underwent processes of standardization, often influenced by national movements and the establishment of nation-states.",
      "date": "1700"
    }
  ]
}

