    {
      "headline": "Origin of the Term 'Gospel'",
      "text": "The term 'gospel' originally meant the Christian message itself. It was used in this sense before the 2nd century.",
      "date": "-0100"
    },
    {
      "headline": "Use of 'Gospel' for Written Accounts",
      "text": "In the 2nd century, the term 'gospel' came to be used for the books that reported the Christian message. These books are episodic narratives of the words and deeds of Jesus, culminating in his trial and death and concluding with reports of his post-resurrection appearances.",
      "date": "0100"
    },
    {
      "headline": "Formation of the Canonical Gospels",
      "text": "The four canonical gospels—Matthew, Mark, Luke, and John—were written between approximately 66-110 AD. These texts became the primary sources for the life and teachings of Jesus.",
      "date": "0066"
    },
    {
      "headline": "Recognition of the Four Canonical Gospels",
      "text": "By the late 2nd century, the four gospels of Matthew, Mark, Luke, and John were widely recognized by the early Christian community as authoritative and were included in the New Testament canon.",
      "date": "0180"
    },
    {
      "headline": "Council of Nicaea",
      "text": "In 325 AD, the First Council of Nicaea affirmed the canonical status of the four gospels as part of the Christian biblical canon.",
      "date": "0325"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Battle of Badr",
      "text": "The Battle of Badr took place on March 13, 624. It was a key battle in the early days of Islam and a turning point in Muhammad's struggle with his opponents among the Quraysh in Mecca.",
      "date": "0624-03-13"
    },
    {
      "headline": "Conquest of Mecca",
      "text": "The Conquest of Mecca occurred in January 630. Muhammad and his followers captured Mecca from the Quraysh, marking a significant expansion of Muslim control.",
      "date": "0630-01"
    },
    {
      "headline": "Battle of Yarmouk",
      "text": "The Battle of Yarmouk was fought between the Rashidun Caliphate and the Byzantine Empire from August 15 to August 20, 636. It was a decisive victory for the Muslims and marked the end of Byzantine rule in Syria.",
      "date": "0636-08-15"
    },
    {
      "headline": "Battle of Qadisiyyah",
      "text": "The Battle of Qadisiyyah took place in 636. It was a pivotal battle between the Rashidun Caliphate and the Sassanian Empire, leading to the Muslim conquest of Persia.",
      "date": "0636"
    },
    {
      "headline": "Siege of Jerusalem",
      "text": "The Siege of Jerusalem occurred in 637. The city was captured by the Rashidun Caliphate, marking a significant expansion of Muslim territory.",
      "date": "0637"
    },
    {
      "headline": "Battle of Nihawand",
      "text": "The Battle of Nihawand was fought in 642. It was a decisive battle that led to the collapse of the Sassanian Empire and the expansion of Muslim rule into Persia.",
      "date": "0642"
    },
    {
      "headline": "Conquest of Egypt",
      "text": "The Muslim conquest of Egypt began in 639 and was completed in 646. It marked the end of Byzantine rule in Egypt and the establishment of Muslim control.",
      "date": "0646"
    },
    {
      "headline": "Battle of the Camel",
      "text": "The Battle of the Camel took place on November 7, 656. It was a civil war battle fought between forces loyal to Ali and those allied with Aisha, Talha, and Zubair.",
      "date": "0656-11-07"
    },
    {
      "headline": "Battle of Siffin",
      "text": "The Battle of Siffin was fought from July 26 to July 28, 657, between the forces of Ali and Muawiya. It was part of the First Fitna, the first Muslim civil war.",
      "date": "0657-07-26"
    },
    {
      "headline": "Battle of Karbala",
      "text": "The Battle of Karbala occurred on October 10, 680. It was a significant event in Islamic history, leading to the martyrdom of Husayn ibn Ali and shaping Shia Islam.",
      "date": "0680-10-10"
    },
    {
      "headline": "Conquest of the Iberian Peninsula",
      "text": "The Muslim conquest of the Iberian Peninsula began in 711 and was largely completed by 718. It marked the expansion of Muslim rule into Europe.",
      "date": "0711"
    }
  ]
}

