{
  "timeline": [
    {
      "headline": "Beginning of the Vedic Period",
      "text": "The Vedic period began around the end of the urban Indus Valley Civilisation, marking the transition to the late Bronze Age and early Iron Age in the northern Indian subcontinent. This period is characterized by the composition of the Vedic literature, including the Vedas.",
      "date": "-1500"
    },
    {
      "headline": "Composition of the Rigveda",
      "text": "The Rigveda, the oldest of the Vedas, was composed during the early Vedic period. It is a collection of hymns dedicated to various deities and is considered one of the oldest religious texts in the world.",
      "date": "-1500"
    },
    {
      "headline": "Development of the Kuru Kingdom",
      "text": "The Kuru Kingdom emerged as a significant political and cultural center during the Vedic period. It played a crucial role in the development of Brahmanical ideology and the codification of Vedic rituals.",
      "date": "-1200"
    },
    {
      "headline": "Composition of the Sama Veda, Yajur Veda, and Atharva Veda",
      "text": "The Sama Veda, Yajur Veda, and Atharva Veda were composed following the Rigveda. These texts expanded on the religious and philosophical ideas of the Vedic tradition.",
      "date": "-1000"
    },
    {
      "headline": "Later Vedic Period",
      "text": "The later Vedic period saw the expansion of Vedic culture into the Indo-Gangetic Plain. This era was marked by the composition of the Brahmanas and Aranyakas, which provided commentary on the Vedas.",
      "date": "-1000"
    },
    {
      "headline": "Emergence of the Mahajanapadas",
      "text": "By around 600 BCE, the Vedic period transitioned into the era of the Mahajanapadas, marked by the rise of large kingdoms and republics in the Indo-Gangetic Plain, leading to a second urbanization.",
      "date": "-0600"
    }
  ]
}

