    {
      "headline": "War of the Seventh Coalition Begins",
      "text": "The War of the Seventh Coalition began as European powers formed a coalition to oppose Napoleon's return to power.",
      "date": "1815"
    },
    {
      "headline": "Battle of Ligny",
      "text": "On June 16, 1815, Napoleon defeated the Prussian army under Field Marshal Blücher at the Battle of Ligny.",
      "date": "1815-06-16"
    },
    {
      "headline": "Battle of Quatre Bras",
      "text": "On June 16, 1815, the Battle of Quatre Bras was fought between the Duke of Wellington's Anglo-allied army and the left wing of the French Army under Marshal Ney.",
      "date": "1815-06-16"
    },
    {
      "headline": "Battle of Waterloo",
      "text": "The Battle of Waterloo took place on June 18, 1815, where Napoleon was defeated by the Duke of Wellington and Prussian forces led by Blücher.",
      "date": "1815-06-18"
    },
    {
      "headline": "Napoleon Abdicates",
      "text": "Napoleon abdicated for the second time on June 22, 1815, after his defeat at Waterloo.",
      "date": "1815-06-22"
    },
    {
      "headline": "Second Restoration of King Louis XVIII",
      "text": "King Louis XVIII was restored to the French throne on July 8, 1815, marking the end of the Hundred Days.",
      "date": "1815-07-08"
    }
  ]
}

