      "text": "Allen Welsh Dulles was born on April 7, 1893, in Watertown, New York.",
      "date": "1893-04-07"
    },
    {
      "headline": "Graduation from Princeton University",
      "text": "In 1914, Allen Dulles graduated from Princeton University.",
      "date": "1914"
