      "headline": "Director of the Office of Strategic Services (OSS)",
      "text": "During World War II, Dulles served as the Director of the Office of Strategic Services (OSS) station in Bern, Switzerland, from 1942 to 1945.",
      "date": "1942"
    },
    {
      "headline": "Became Deputy Director of Central Intelligence",
      "text": "In 1951, Dulles was appointed as the Deputy Director of Central Intelligence.",
      "date": "1951"
    },
    {
      "headline": "Appointed Director of Central Intelligence",
      "text": "On February 26, 1953, Allen Dulles was appointed as the Director of Central Intelligence, becoming the first civilian to hold the position.",
      "date": "1953-02-26"
    },
    {
      "headline": "Oversaw the 1953 Iranian coup d'état",
      "text": "In August 1953, Dulles oversaw the CIA's involvement in the Iranian coup d'état, which led to the overthrow of Prime Minister Mohammad Mossadegh.",
      "date": "1953-08"
    },
    {
      "headline": "Oversaw the 1954 Guatemalan coup d'état",
      "text": "In 1954, Dulles oversaw the CIA's operation to overthrow Guatemalan President Jacobo Árbenz.",
      "date": "1954"
    },
    {
      "headline": "Initiated the Lockheed U-2 aircraft program",
      "text": "Dulles played a key role in the development and deployment of the Lockheed U-2 spy plane program, which began in 1955.",
      "date": "1955"
    },
    {
      "headline": "Launched Project MKUltra",
      "text": "In 1953, Dulles authorized Project MKUltra, a covert CIA program focused on mind control and chemical interrogation.",
      "date": "1953"
    },
    {
      "headline": "Bay of Pigs Invasion",
      "text": "In April 1961, Dulles oversaw the Bay of Pigs Invasion, an unsuccessful attempt to overthrow Cuban leader Fidel Castro.",
      "date": "1961-04"
    },
    {
      "headline": "Dismissal by President Kennedy",
      "text": "Following the failure of the Bay of Pigs Invasion, President John F. Kennedy dismissed Dulles as Director of Central Intelligence in November 1961.",
      "date": "1961-11"
    },
    {
      "headline": "Death of Allen Dulles",
      "text": "Allen Dulles died on January 29, 1969, in Washington, D.C.",
      "date": "1969-01-29"
    }
  ]
}

