      "headline": "Butler Act Enacted",
      "text": "In March 1925, the Butler Act was enacted in Tennessee, making it illegal for teachers in state-funded schools to teach human evolution.",
      "date": "1925-03"
    },
    {
      "headline": "Scopes Trial Begins",
      "text": "The Scopes Trial, formally known as The State of Tennessee v. John Thomas Scopes, began on July 10, 1925, in Dayton, Tennessee. John T. Scopes, a high school teacher, was accused of violating the Butler Act.",
      "date": "1925-07-10"
    },
    {
      "headline": "William Jennings Bryan Joins Prosecution",
      "text": "William Jennings Bryan, a three-time presidential candidate and a known opponent of Darwinism, joined the prosecution team during the trial.",
      "date": "1925-07"
    },
    {
      "headline": "Clarence Darrow Defends Scopes",
      "text": "Famed defense attorney Clarence Darrow represented John T. Scopes, arguing against the constitutionality of the Butler Act.",
      "date": "1925-07"
    },
    {
      "headline": "Scopes Found Guilty",
      "text": "On July 21, 1925, John T. Scopes was found guilty of teaching evolution and was fined $100.",
      "date": "1925-07-21"
    },
    {
      "headline": "Tennessee Supreme Court Overturns Conviction",
      "text": "In 1927, the Tennessee Supreme Court overturned Scopes' conviction on a technicality, while upholding the constitutionality of the Butler Act.",
      "date": "1927"
    },
    {
      "headline": "Butler Act Repealed",
      "text": "The Butler Act was eventually repealed in 1967, allowing the teaching of evolution in Tennessee schools.",
      "date": "1967"
    }
  ]
}

