{
  "timeline": [
    {
      "headline": "Discovery of Hepatitis C Virus",
      "text": "In 1989, the hepatitis C virus (HCV) was discovered by a team of scientists led by Michael Houghton at Chiron Corporation. This discovery was a significant breakthrough in understanding the cause of non-A, non-B hepatitis.",
      "date": "1989"
    },
    {
      "headline": "Development of Hepatitis C Diagnostic Test",
      "text": "Following the discovery of the hepatitis C virus, a diagnostic test was developed in 1990 to detect antibodies to the virus in the blood. This test allowed for more accurate diagnosis and screening of blood supplies.",
      "date": "1990"
    },
    {
      "headline": "Approval of Interferon Therapy",
      "text": "In 1991, the first treatment for hepatitis C, interferon alfa-2b, was approved by the U.S. Food and Drug Administration (FDA). This marked the beginning of medical treatment options for hepatitis C.",
      "date": "1991"
    },
    {
      "headline": "Combination Therapy with Ribavirin",
      "text": "In 1998, the FDA approved the use of ribavirin in combination with interferon for the treatment of hepatitis C. This combination therapy improved treatment outcomes significantly.",
      "date": "1998"
    },
    {
      "headline": "Introduction of Pegylated Interferon",
      "text": "In 2001, pegylated interferon was introduced, which allowed for less frequent dosing and improved efficacy in the treatment of hepatitis C.",
      "date": "2001"
    },
    {
      "headline": "Approval of Direct-Acting Antivirals",
      "text": "In 2011, the first direct-acting antivirals (DAAs), boceprevir and telaprevir, were approved by the FDA. These drugs targeted the hepatitis C virus more directly and improved cure rates.",
      "date": "2011"
    },
    {
      "headline": "Introduction of Sofosbuvir",
      "text": "In 2013, sofosbuvir, a breakthrough DAA, was approved. It offered a shorter, more effective, and better-tolerated treatment regimen for hepatitis C.",
      "date": "2013"
    },
    {
      "headline": "Approval of Harvoni",
      "text": "In 2014, Harvoni, a combination of sofosbuvir and ledipasvir, was approved. It was the first all-oral, interferon-free treatment for hepatitis C, significantly simplifying the treatment process.",
      "date": "2014"
    },
    {
      "headline": "WHO Global Health Sector Strategy on Viral Hepatitis",
      "text": "In 2016, the World Health Organization (WHO) adopted the Global Health Sector Strategy on Viral Hepatitis, aiming to eliminate hepatitis C as a public health threat by 2030.",
      "date": "2016"
    }
  ]
}

