{
  "timeline": [
    {
      "headline": "Earliest Known Reference",
      "text": "The earliest known reference to a game similar to Tic-tac-toe is found in the Roman Empire, around the first century BCE. The game was called 'terni lapilli' and was played with pebbles on a grid.",
      "date": "-0001"
    },
    {
      "headline": "Modern Tic-tac-toe",
      "text": "The modern version of Tic-tac-toe, as we know it today, began to be played in the 19th century. The game became popular as a simple pastime.",
      "date": "1800"
    },
    {
      "headline": "First Computer Implementation",
      "text": "In 1952, the first computer implementation of Tic-tac-toe was created by A.S. Douglas as part of his Ph.D. thesis on human-computer interaction at the University of Cambridge. The game was called OXO and ran on the EDSAC computer.",
      "date": "1952"
    },
    {
      "headline": "Tic-tac-toe as a Solved Game",
      "text": "Tic-tac-toe was mathematically solved in the 1970s, meaning that the outcome of the game can be predicted if both players play optimally. The game will always result in a draw if neither player makes a mistake.",
      "date": "1970"
    }
  ]
}

