    {
      "headline": "Resignation from Cardinalate",
      "text": "In 1498, Cesare Borgia resigned from the cardinalate to pursue a military and political career.",
      "date": "1498"
    },
    {
      "headline": "Marriage to Charlotte of Albret",
      "text": "Cesare Borgia married Charlotte of Albret, a French noblewoman, on May 10, 1499.",
      "date": "1499-05-10"
    },
    {
      "headline": "Conquest of Romagna",
      "text": "In 1499-1500, Cesare Borgia led military campaigns to conquer the Romagna region, expanding his power in Italy.",
      "date": "1499"
    },
    {
      "headline": "Duke of Valentinois",
      "text": "Cesare Borgia was granted the title of Duke of Valentinois by King Louis XII of France in 1499.",
      "date": "1499"
    },
    {
      "headline": "Capture of Urbino",
      "text": "In 1502, Cesare Borgia captured the Duchy of Urbino, further consolidating his power in central Italy.",
      "date": "1502"
    },
    {
      "headline": "Fall from Power",
      "text": "Following the death of his father, Pope Alexander VI, in 1503, Cesare Borgia's power began to decline.",
      "date": "1503"
    },
    {
      "headline": "Imprisonment in Spain",
      "text": "In 1504, Cesare Borgia was imprisoned in Spain after being captured by the forces of Gonzalo Fernández de Córdoba.",
      "date": "1504"
    },
    {
      "headline": "Escape from Prison",
      "text": "Cesare Borgia escaped from prison in Spain in 1506 and sought refuge with his brother-in-law, King John III of Navarre.",
      "date": "1506"
    },
    {
      "headline": "Death of Cesare Borgia",
      "text": "Cesare Borgia died on March 12, 1507, during a military campaign in Navarre, Spain.",
      "date": "1507-03-12"
    }
  ]
}

