{
  "timeline": [
    {
      "headline": "Outbreak of the Great Northern War",
      "text": "The Great Northern War began in 1700 when a coalition of Denmark-Norway, Saxony-Poland-Lithuania, and Russia declared war on the Swedish Empire.",
      "date": "1700"
    },
    {
      "headline": "Battle of Narva",
      "text": "On November 30, 1700, Charles XII of Sweden defeated the Russian army at the Battle of Narva, marking an early Swedish victory in the war.",
      "date": "1700-11-30"
    },
    {
      "headline": "Treaty of Travendal",
      "text": "In August 1700, Denmark-Norway was forced to exit the war after the Treaty of Travendal, following a Swedish invasion.",
      "date": "1700-08"
    },
    {
      "headline": "Battle of Kliszów",
      "text": "On July 19, 1702, Charles XII of Sweden defeated the Polish-Lithuanian-Saxon army at the Battle of Kliszów.",
      "date": "1702-07-19"
    },
    {
      "headline": "Battle of Fraustadt",
      "text": "On February 13, 1706, Swedish forces achieved a decisive victory over the Saxon and Russian armies at the Battle of Fraustadt.",
      "date": "1706-02-13"
    },
    {
      "headline": "Treaty of Altranstädt",
      "text": "In 1706, Augustus II of Saxony-Poland-Lithuania was forced to sign the Treaty of Altranstädt, exiting the war temporarily.",
      "date": "1706"
    },
    {
      "headline": "Battle of Poltava",
      "text": "On June 28, 1709, the Swedish army was decisively defeated by Russian forces at the Battle of Poltava, marking a turning point in the war.",
