    {
      "headline": "Monroe Doctrine Declared",
      "text": "On December 2, 1823, President James Monroe declared the Monroe Doctrine during his annual message to Congress. The doctrine stated that any intervention by external powers in the politics of the Americas is a potentially hostile act against the United States.",
      "date": "1823-12-02"
    },
    {
      "headline": "Roosevelt Corollary",
      "text": "In 1904, President Theodore Roosevelt added the Roosevelt Corollary to the Monroe Doctrine, asserting the right of the United States to intervene in Latin America to stabilize the economic affairs of small states if they were unable to pay their international debts.",
      "date": "1904"
    },
    {
      "headline": "Good Neighbor Policy",
      "text": "In 1933, President Franklin D. Roosevelt implemented the Good Neighbor Policy, which marked a departure from the Monroe Doctrine's interventionist stance, promoting non-intervention and cooperation with Latin American countries.",
      "date": "1933"
    },
    {
      "headline": "Cuban Missile Crisis",
      "text": "In 1962, during the Cuban Missile Crisis, the Monroe Doctrine was invoked by President John F. Kennedy to justify the U.S. blockade of Cuba in response to the Soviet Union's installation of nuclear missiles on the island.",
      "date": "1962"
    },
    {
      "headline": "Reagan Doctrine",
      "text": "In the 1980s, President Ronald Reagan's foreign policy, known as the Reagan Doctrine, was seen as an extension of the Monroe Doctrine. It aimed to provide support to anti-communist insurgencies in Latin America and elsewhere.",
      "date": "1980"
    }
  ]
}

