{
  "timeline": [
    {
      "headline": "Beginning of the Dirty War",
      "text": "The Dirty War began in 1974, during the presidency of Isabel Perón, when the Argentine government initiated a campaign against political dissidents.",
      "date": "1974"
    },
    {
      "headline": "Military Coup",
      "text": "On March 24, 1976, a military coup overthrew President Isabel Perón, establishing a military junta that intensified the Dirty War.",
      "date": "1976-03-24"
    },
    {
      "headline": "Operation Condor",
      "text": "In 1976, Argentina joined Operation Condor, a campaign of political repression and state terror involving intelligence operations and assassination of opponents, coordinated among South American dictatorships.",
      "date": "1976"
    },
    {
      "headline": "Peak of Repression",
      "text": "The period between 1976 and 1978 marked the peak of the Dirty War, with widespread human rights abuses, including kidnappings, torture, and forced disappearances.",
      "date": "1976"
    },
    {
      "headline": "World Cup 1978",
      "text": "In 1978, Argentina hosted and won the FIFA World Cup, which the military junta used as a propaganda tool to improve its international image despite ongoing human rights violations.",
      "date": "1978"
    },
    {
      "headline": "Falklands War",
      "text": "In April 1982, Argentina invaded the Falkland Islands, leading to a war with the United Kingdom. The defeat in June 1982 weakened the military junta's hold on power.",
      "date": "1982-04"
    },
    {
      "headline": "End of the Dirty War",
      "text": "The Dirty War officially ended in 1983 with the return to democratic rule in Argentina, following the election of Raúl Alfonsín as President.",
      "date": "1983"
    },
    {
      "headline": "Trial of the Juntas",
      "text": "In 1985, the Trial of the Juntas was held, where key figures of the military dictatorship were prosecuted for human rights abuses committed during the Dirty War.",
      "date": "1985"
    }
  ]
}

