    {
      "headline": "End of the Ashikaga Shogunate",
      "text": "In 1573, the Ashikaga Shogunate came to an end when Oda Nobunaga deposed the last shogun, Ashikaga Yoshiaki.",
      "date": "1573"
    },
    {
      "headline": "Establishment of the Tokugawa Shogunate",
      "text": "In 1603, Tokugawa Ieyasu established the Tokugawa Shogunate, which marked the beginning of the Edo period, a time of relative peace and stability in Japan.",
      "date": "1603"
    },
    {
      "headline": "Sakoku Edict",
      "text": "In 1639, the Tokugawa Shogunate issued the Sakoku Edict, enforcing a policy of national isolation that lasted for over two centuries.",
      "date": "1639"
    },
    {
      "headline": "End of the Tokugawa Shogunate",
      "text": "In 1868, the Tokugawa Shogunate was dissolved during the Meiji Restoration, which restored imperial rule and marked the end of the shogunate system in Japan.",
      "date": "1868"
    }
  ]
}

