{
  "timeline": [
    {
      "headline": "First Mention of Galicia",
      "text": "The region of Galicia is first mentioned in historical records in the 9th century as part of the Slavic state of Great Moravia.",
      "date": "0900"
    },
    {
      "headline": "Incorporation into Poland",
      "text": "In 1349, Galicia was incorporated into the Kingdom of Poland by King Casimir III the Great.",
      "date": "1349"
    },
    {
      "headline": "Part of the Polish–Lithuanian Commonwealth",
      "text": "In 1569, Galicia became part of the Polish–Lithuanian Commonwealth following the Union of Lublin.",
      "date": "1569"
    },
    {
      "headline": "First Partition of Poland",
      "text": "In 1772, during the First Partition of Poland, Galicia was annexed by the Habsburg Monarchy and became part of the Austrian Empire.",
      "date": "1772"
    },
    {
      "headline": "Galicia and Lodomeria",
      "text": "In 1773, the region was officially named the Kingdom of Galicia and Lodomeria under Austrian rule.",
      "date": "1773"
    },
    {
      "headline": "Austrian Reforms",
      "text": "In the late 18th and early 19th centuries, the Austrian government implemented various reforms in Galicia, including the abolition of serfdom in 1848.",
      "date": "1848"
    },
    {
      "headline": "Galician Autonomy",
      "text": "In 1867, Galicia gained a degree of autonomy within the Austro-Hungarian Empire, with its own provincial parliament.",
      "date": "1867"
    },
    {
      "headline": "World War I and the Collapse of Austria-Hungary",
      "text": "In 1918, following the end of World War I and the collapse of the Austro-Hungarian Empire, Galicia became a contested region between Poland and Ukraine.",
      "date": "1918"
    },
    {
      "headline": "Incorporation into the Second Polish Republic",
      "text": "In 1923, the League of Nations recognized Galicia as part of the Second Polish Republic.",
      "date": "1923"
    },
    {
      "headline": "World War II and Soviet Annexation",
      "text": "In 1939, following the Molotov-Ribbentrop Pact, the Soviet Union annexed eastern Galicia. After World War II, the region was divided between Poland and the Soviet Union.",
      "date": "1939"
    },
    {
      "headline": "Post-War Division",
      "text": "In 1945, the borders were finalized, with western Galicia remaining in Poland and eastern Galicia becoming part of the Ukrainian SSR within the Soviet Union.",
      "date": "1945"
    }
  ]
}

