{
  "timeline": [
    {
      "headline": "Departure from England",
      "text": "On September 16, 1620, the Pilgrims departed from Plymouth, England, aboard the Mayflower, seeking religious freedom and a new life in North America.",
      "date": "1620-09-16"
    },
    {
      "headline": "Arrival at Cape Cod",
      "text": "On November 11, 1620, the Mayflower arrived at Cape Cod, Massachusetts, after a 66-day voyage across the Atlantic Ocean.",
      "date": "1620-11-11"
    },
    {
      "headline": "Signing of the Mayflower Compact",
      "text": "On November 21, 1620, the male passengers of the Mayflower signed the Mayflower Compact, establishing a basic form of self-government and agreeing to abide by the community's rules.",
      "date": "1620-11-21"
    },
    {
      "headline": "Founding of Plymouth Colony",
      "text": "In December 1620, the Pilgrims established Plymouth Colony in present-day Plymouth, Massachusetts, marking the beginning of permanent European settlement in New England.",
      "date": "1620-12"
    },
    {
      "headline": "First Winter and the 'Starving Time'",
      "text": "During the winter of 1620-1621, the Pilgrims faced severe hardships, including disease and starvation, which resulted in the deaths of nearly half of the original settlers.",
      "date": "1620-12"
    },
    {
      "headline": "First Thanksgiving",
      "text": "In the autumn of 1621, the Pilgrims celebrated their first successful harvest with a three-day feast, which is now remembered as the First Thanksgiving, attended by both Pilgrims and Native Americans.",
      "date": "1621"
    },
    {
      "headline": "Establishment of a Treaty with the Wampanoag",
      "text": "In March 1621, the Pilgrims established a peace treaty with the Wampanoag leader Massasoit, which helped ensure the colony's survival.",
      "date": "1621-03"
    },
    {
      "headline": "Arrival of the Fortune",
      "text": "In November 1621, the ship Fortune arrived at Plymouth Colony, bringing additional settlers and supplies.",
      "date": "1621-11"
    },
    {
      "headline": "First General Court",
      "text": "In 1623, the Pilgrims held their first General Court, an early form of democratic government where colonists could participate in decision-making.",
      "date": "1623"
    },
    {
      "headline": "Division of Land",
      "text": "In 1623, the Pilgrims divided land among the settlers, allowing families to farm their own plots, which increased productivity and improved food security.",
      "date": "1623"
    },
    {
      "headline": "Pequot War",
      "text": "In 1637, the Pilgrims participated in the Pequot War, a conflict between New England settlers and the Pequot tribe, which resulted in the tribe's defeat.",
      "date": "1637"
    },
    {
      "headline": "Plymouth Colony Merges with Massachusetts Bay Colony",
      "text": "In 1691, Plymouth Colony was merged with the Massachusetts Bay Colony to form the Province of Massachusetts Bay, ending its status as a separate colony.",
      "date": "1691"
    }
  ]
}

