      "headline": "Founding of Indraprastha",
      "text": "The Pandavas founded the city of Indraprastha after the Kuru Kingdom was split to avoid succession disputes with their cousins, the Kauravas.",
      "date": "-0285"
    },
    {
      "headline": "Game of Dice and Exile",
      "text": "Yudhishtira lost the Pandavas' kingdom to Duryodhana in a game of dice. As a result, the Pandavas were exiled for 13 years, including one year in disguise.",
      "date": "-0280"
    },
    {
      "headline": "End of Exile",
      "text": "The Pandavas completed their 13-year exile and requested the return of their kingdom from the Kauravas, who refused.",
      "date": "-0267"
    },
    {
      "headline": "Kurukshetra War",
      "text": "The Pandavas waged the Kurukshetra War against the Kauravas. With the help of Krishna, they emerged victorious, but the war resulted in massive loss of life.",
      "date": "-0265"
    },
    {
      "headline": "Reign of Yudhishtira",
      "text": "After the Kurukshetra War, Yudhishtira was crowned king and ruled the kingdom, bringing prosperity and peace.",
      "date": "-0264"
    },
    {
      "headline": "The Pandavas' Final Journey",
      "text": "The Pandavas, along with Draupadi, embarked on their final journey to the Himalayas, renouncing their kingdom and worldly possessions.",
      "date": "-0250"
    }
  ]
}

