{
  "timeline": [
    {
      "headline": "Beginning of the Beaver Wars",
      "text": "The Beaver Wars began in the early 17th century as the Iroquois sought to expand their territory and control the fur trade. The conflicts were primarily against the Huron, Algonquins, and their French allies.",
      "date": "1600"
    },
    {
      "headline": "Iroquois Expansion",
      "text": "Throughout the 1640s, the Iroquois Confederacy expanded its territory by attacking and dispersing the Huron Confederacy, which was allied with the French. This expansion was driven by the desire to control the fur trade.",
      "date": "1640"
    },
    {
      "headline": "Destruction of the Huron Confederacy",
      "text": "In 1649, the Iroquois launched a series of attacks that led to the destruction of the Huron Confederacy. Many Huron were killed, assimilated, or fled to other regions.",
      "date": "1649"
    },
    {
      "headline": "Defeat of the Erie Nation",
      "text": "In 1654, the Iroquois defeated the Erie Nation, further expanding their control over the Great Lakes region.",
      "date": "1654"
    },
    {
      "headline": "Neutral Nation Conquered",
      "text": "By 1656, the Iroquois had conquered the Neutral Nation, further solidifying their dominance in the region.",
      "date": "1656"
    },
    {
      "headline": "Conflict with the Susquehannock",
      "text": "In the 1660s, the Iroquois engaged in conflicts with the Susquehannock, eventually leading to their defeat and dispersal.",
      "date": "1660"
    },
    {
      "headline": "Peace Treaty with the French",
      "text": "In 1667, the Iroquois signed a peace treaty with the French, temporarily halting hostilities between the two groups.",
      "date": "1667"
    },
    {
      "headline": "Renewed Conflict and Expansion",
      "text": "In the 1670s, the Iroquois resumed their expansionist campaigns, attacking various Algonquian tribes and continuing to exert control over the fur trade.",
      "date": "1670"
    },
    {
      "headline": "Great Peace of Montreal",
      "text": "In 1701, the Great Peace of Montreal was signed, ending the Beaver Wars. The treaty involved the Iroquois, French, and various Native American tribes, establishing peace and trade agreements.",
      "date": "1701"
    }
  ]
}

